def block_data():
    """
C     Hydrogenic oscillator strentghs

    BLOCK DATA -> block_data()。对应 tlusty208.f 行 69–108。
    仅初始化 COMMON/OSCHYD/ 的 OSH(20,20)。
    """
    # DATA ((OSH(I,J),I=1,20),J=1,16)、((OSH(I,J),I=1,20),J=17,20)
    # 下列每行是 OSH 的一列（J 固定，I=1..20，列主序；n*0. 已展开为列表乘积）
    _osh_cols = [
        [0.0] * 20,                                                            # J=1
        [0.4162] + [0.0] * 19,                                                 # J=2
        [7.910e-2, 0.6407] + [0.0] * 18,                                       # J=3
        [2.899e-2, 0.1193, 0.8421] + [0.0] * 17,                               # J=4
        [1.394e-2, 4.467e-2, 0.1506, 1.038] + [0.0] * 16,                      # J=5
        [7.799e-3, 2.209e-2, 5.584e-2, 0.1793, 1.231] + [0.0] * 15,            # J=6
        [4.814e-3, 1.270e-2, 2.768e-2, 6.549e-2, 0.2069, 1.424] + [0.0] * 14,  # J=7
        [3.183e-3, 8.036e-3, 1.604e-2, 3.23e-2, 7.448e-2, 0.234, 1.616] + [0.0] * 13,   # J=8
        [2.216e-3, 5.429e-3, 1.023e-2, 1.87e-2, 3.645e-2, 8.315e-2, 0.2609, 1.807] + [0.0] * 12,  # J=9
        [1.605e-3, 3.851e-3, 6.98e-3, 1.196e-2, 2.104e-2, 4.038e-2, 9.163e-2, 0.2876, 1.999] + [0.0] * 11,  # J=10
        [1.201e-3, 2.835e-3, 4.996e-3, 8.187e-3, 1.344e-2, 2.32e-2, 4.416e-2, 0.1, 0.3143, 2.19] + [0.0] * 10,  # J=11
        [9.214e-4, 2.151e-3, 3.711e-3, 5.886e-3, 9.209e-3, 1.479e-2, 2.525e-2, 4.787e-2, 0.1083, 0.3408, 2.381] + [0.0] * 9,  # J=12
        [7.227e-4, 1.672e-3, 2.839e-3, 4.393e-3, 6.631e-3, 1.012e-2, 1.605e-2, 2.724e-2, 5.152e-2, 0.1166, 0.3673, 2.572] + [0.0] * 8,  # J=13
        [5.744e-4, 1.326e-3, 2.224e-3, 3.375e-3, 4.959e-3, 7.289e-3, 1.097e-2, 1.726e-2, 2.918e-2, 5.513e-2, 0.1248, 0.3938, 2.763] + [0.0] * 7,  # J=14
        [4.686e-4, 1.07e-3, 1.776e-3, 2.656e-3, 3.821e-3, 5.455e-3, 7.891e-3, 1.177e-2, 1.843e-2, 3.109e-2, 5.872e-2, 0.133, 0.4202, 2.954] + [0.0] * 6,  # J=15
        [3.856e-4, 8.764e-4, 1.443e-3, 2.131e-3, 3.014e-3, 4.207e-3, 5.905e-3, 8.456e-3, 1.254e-2, 1.958e-2, 3.298e-2, 6.228e-2, 0.1412, 0.4467, 3.145] + [0.0] * 5,  # J=16
        [3.211e-4, 7.270e-4, 1.188e-3, 1.739e-3, 2.425e-3, 3.324e-3, 4.556e-3, 6.323e-3, 8.995e-3, .01328, .0207, .03486, .06584, .1494, 0.4731, 3.336] + [0.0] * 4,  # J=17
        [2.702e-4, 6.099e-4, 9.916e-4, 1.439e-3, 1.984e-3, 2.679e-3, 3.602e-3, 4.877e-3, 6.719e-3, 9.515e-3, 0.01402, .02182, .03672, .06938, .1575, .4995, 3.527] + [0.0] * 3,  # J=18
        [2.296e-4, 5.167e-4, 8.361e-4, 1.204e-3, 1.646e-3, 2.196e-3, 2.905e-3, 3.856e-3, 5.180e-3, 7.099e-3, .01002, .01474, .02292, .03858, .07292, .1657, .5259, 3.718] + [0.0] * 2,  # J=19
        [1.967e-4, 4.416e-4, 7.118e-4, 1.019e-3, 1.382e-3, 1.825e-3, 2.383e-3, 3.112e-3, 4.094e-3, 5.468e-3, 7.468e-3, .01052, .01545, .02402, .04043, .07644, 0.1738, .5523, 3.909, 0.0],  # J=20
    ]
    # _osh_cols[j-1][i-1] = OSH(I,J)，转置后写入 C.OSH（1 基，索引 0 不用）
    C.OSH[1:21, 1:21] = np.array(_osh_cols).T


# ======================================================================

def start():
    """
C     General input and initialization procedure

    SUBROUTINE START。对应 tlusty208.f 行 115–132。
    """
    # common/hediff/ hcmass,radstr -> C.hcmass, C.radstr
    # read(1,*,end=10,err=10) idisk
    # TODO(port): 单元 1 在原文中未 OPEN（gfortran 会隐式打开文件 fort.1）；
    # 文件缺失或读失败均落到标号 10（即跳过）。
    try:
        open_unit(1, "fort.1", "r")
        C.IDISK = _ld_int(1)
        _ld_end(1)
    except (EOFError, OSError, KeyError, ValueError):
        pass                          # -> 标号 10
    #  10 continue
    initia()
    if C.hcmass > 0.0:
        hedif()
    C.NN0 = C.NN
    comset()
    prdini()
    return


