    C.cconml = 16.0
    if mltype == 2:
        C.aconml = 1.0
        C.bconml = 2.0
        C.cconml = 16.0
    C.nungam = 0
    C.nunbal = 0
    if C.iquasi > 0:
        getlal()
    #
    if C.ND > MDEPTH:
        quit("nd.gt.mdepth", C.ND, MDEPTH)
    if C.NDGREY > MDEPTH:
        quit("ndgrey.gt.mdepth", C.NDGREY, MDEPTH)
    if C.NLAMBD > MLAMBD:
        quit("nlambd.gt.mlambd", C.NLAMBD, MLAMBD)
    if C.IACC <= 2:
        quit("Ng too early", C.IACC, C.IACC)
    if C.NMU > MMU:
        quit("nmu.gt.mmu", C.NMU, MMU)
    return


