def nstout():
    """
C     Diagnostic print of the input flags and parameters

    SUBROUTINE NSTOUT。对应 tlusty208.f 行 2034–2156。
    """
    # TODO(port): 原文 ICHC 为本子程序未初始化局部量（LCHC 为假时打印值未定义，
    # 实际为 0）；注意与 NSTPAR 中读入的关键字 ICHC 不是同一存储
    ichc = 0
    if C.LCHC:
        ichc = 1
    #  602 FORMAT(/' VALUES OF SOME KEYWORD PARAMETERS:'/
    #     *        ' =================================='//
    #     *       'ISPLIN=',I6,2X,'IRTE  =',I6,2X,'IBC   =',I6,2X,
    #     *       'ILMCOR=',I6,2X,'ILPSCT=',I6,2X/
    #     *       'ILASCT=',I6,2X,'DJMAX =',F6.3,2X,'NTRALI=',I6,2X,'IPSLTE=',I6,2X/
    #     *       'ICOMPT=',I6/
    #     *       'IZSCAL=',I6,2X,'IBCHE =',I6,2X,'IVISC =',I6,2X/
    #     *       'IFALI =',I6,2X,'IFPOPR=',I6,2X,'JALI  =',I6,2X,'IFRALI=',I6,2X/
    #     *       'IFPREC=',I6,2X,'IELCOR=',I6,2X,'ICHC  =',I6,2X,
