def alisk1():
    """
    C     Simplified routine ALIST1 for Kantorovich iteration
    C
    C     Evaluation of all nexcessary ALI parameters + radiative rates

    对应 tlusty208.f 行 7675–7836。
    DIMENSION RBNU(MDEPTH)
    无哑元。
    """
    rbnu = np.zeros(MDEPTH + 1)  # DIMENSION RBNU(MDEPTH)，1 基索引
    # C     DIMENSION EHKL(MFREQL)   （原代码注释掉，保留）

    #     zero the rates and other quantities (subr. NULL)

    for id in range(1, C.ND + 1):
        C.FCOOLI[id] = 0.0
        C.FLFIX[id] = 0.0
        C.FPRD[id] = 0.0
        C.FLRD[id] = 0.0
        C.PRADT[id] = 0.0
        C.PRADA[id] = 0.0
        for itr in range(1, C.NTRANS + 1):
            C.RRU[itr, id] = 0.0
            C.RRD[itr, id] = 0.0
    C.PRD0 = 0.0

    lross = C.NDRE <= 0 and C.ITER == 1 or C.LFIN
    if C.HMIX0 > 0.0:
        lross = True
    if lross:
        for id in range(1, C.ND + 1):
            C.ABROSD[id] = 0.0
            C.SUMDPL[id] = 0.0

    for ij in range(1, C.NFREQ + 1):  # DO 100 IJ=1,NFREQ
        if C.IJX[ij] == -1:
            continue  # GO TO 100
        fr = C.FREQ[ij]
        w0 = C.W0E[ij]
        opacf1(ij)
        if C.IJEX[ij] > 0:
            ije = C.IJEX[ij]
            for id in range(1, C.ND + 1):
                C.ABSOEX[ije, id] = C.ABSO1[id]
                C.EMISEX[ije, id] = C.EMIS1[id]
                C.SCATEX[ije, id] = C.SCAT1[id]
        rtefr1(ij)
        alifrk(ij)
        if lross:
            rosstd(ij)
        if C.IOPTAB < 0:
            continue  # go to 100

        #        ---------------------
        #        Continuum transitions
        #        ---------------------

        for id in range(1, C.ND + 1):
            rbnu[id] = ((C.RAD1[id] + C.BNUE[ij])
                        * math.exp(-C.HKT1[id] * fr))
            for ibft in range(1, C.NTRANC + 1):  # DO 10
                itr = C.ITRBF[ibft]
                sg = cross(ibft, ij)  # CROSS 为函数（tlusty208.f:35158）
                if sg <= 0.0:
                    continue  # GO TO 10
                ii = C.ILOW[itr]
                jj = C.IUP[itr]
                if C.IPZERO[ii, id] != 0 or C.IPZERO[jj, id] != 0:
                    continue  # GO TO 10
                jc = C.ITRA[jj, ii]  # 原代码计算后未再使用，保留直译
                icdw = C.MCDW[itr]
                imer = C.IMRG[ii]
                if C.ifwop[ii] >= 0:
                    if icdw >= 1:
                        sg = sg * C.DWF1[icdw, id]
                else:
                    sg = C.SGMG[imer, id]
                sgw0 = sg * w0
                C.RRU[itr, id] = C.RRU[itr, id] + sgw0 * C.RAD1[id]
                C.RRD[itr, id] = C.RRD[itr, id] + sgw0 * rbnu[id]
            # 10 CONTINUE

        #        ----------------
        #        Line transitions
        #        ----------------

        if C.IJLIN[ij] > 0:

            #        the "primary" line at the given frequency

            itr = C.IJLIN[ij]
            for id in range(1, C.ND + 1):
                sgw0 = C.PRFLIN[id, ij] * w0
                C.RRU[itr, id] = C.RRU[itr, id] + sgw0 * C.RAD1[id]
                C.RRD[itr, id] = C.RRD[itr, id] + sgw0 * rbnu[id]

        if C.NLINES[ij] <= 0:
            continue  # GO TO 100

        #        the "overlapping" lines at the given frequency

        for ilint in range(1, C.NLINES[ij] + 1):  # DO 90
            itr = C.ITRLIN[ilint, ij]
            if C.LINEXP[itr]:
                continue  # goto 90
            ij0 = C.IFR0[itr]
            for ijt in range(ij0, C.IFR1[itr] + 1):
                if C.FREQ[ijt] <= fr:
                    ij0 = ijt
                    break  # GO TO 70
            # 70
            ij1 = ij0 - 1
            a1 = (fr - C.FREQ[ij0]) / (C.FREQ[ij1] - C.FREQ[ij0]) * w0
            a2 = w0 - a1
            for id in range(1, C.ND + 1):
                sgw0 = a1 * C.PRFLIN[id, ij1] + a2 * C.PRFLIN[id, ij0]
                C.RRU[itr, id] = C.RRU[itr, id] + sgw0 * C.RAD1[id]
                C.RRD[itr, id] = C.RRD[itr, id] + sgw0 * rbnu[id]
        # 90 CONTINUE
    # 100 CONTINUE

    #     multiply some quantities by frequency-independent constants

    for id in range(1, C.ND + 1):
        C.FCOOL[id] = C.REINT[id] * C.FCOOLI[id] - C.REDIF[id] * C.FLFIX[id]
        if C.CRSW[id] != UN:
            for itr in range(1, C.NTRANS + 1):
                C.RRU[itr, id] = C.RRU[itr, id] * C.CRSW[id]
                C.RRD[itr, id] = C.RRD[itr, id] * C.CRSW[id]

    #     radiation pressure

    prdx = 1.0
    # TODO(port): Fortran 中 PRDR 在 PRADA(ID)<=0 时不赋值即被引用
    # （值为未定义）；此处先置 0.0 以保证 Python 语义确定
    prdr = 0.0
    for id in range(1, C.ND + 1):
        C.PRADT[id] = C.PRADT[id] * PCK
        C.PRADA[id] = C.PRADA[id] * PCK
        if C.PRADA[id] > 0.0:
            prdr = C.PRADT[id] / C.PRADA[id]
        if prdr < prdx:
            prdx = prdr
    C.PRD0 = C.PRD0 / C.DENS1[1] * C.DM[1] * PCK
    if C.LFIN:
        #  1100 FORMAT(' PRAD MIN RATIO ',F10.6,I4)
        write_line(10, ' PRAD MIN RATIO %10.6f%4d' % (prdx, C.ITER))

    #     Rosseland mean opacity

    if lross:
        for id in range(1, C.ND + 1):
            C.ABROSD[id] = C.SUMDPL[id] / (C.ABROSD[id] * C.DENS[id])
    return


def alisk2():
    """
    C     Simplified routine ALISET for Kantorovich iteration
    C
    C     Evaluation of all nexcessary ALI parameters + radiative rates
    C     (the routine is analogous to RATES)

    对应 tlusty208.f 行 7843–8046。
    DIMENSION RBNU(MDEPTH)
    无哑元。
    """
    rbnu = np.zeros(MDEPTH + 1)  # DIMENSION RBNU(MDEPTH)，1 基索引
    # C     DIMENSION EHKL(MFREQL)   （原代码注释掉，保留）

    #     zero the rates and other quantities

    for id in range(1, C.ND + 1):
        C.FCOOLI[id] = 0.0
        C.FLFIX[id] = 0.0
        C.FLEXP[id] = 0.0
        C.FPRD[id] = 0.0
        C.FLRD[id] = 0.0
        C.PRADT[id] = 0.0
        C.PRADA[id] = 0.0
        for itr in range(1, C.NTRANS + 1):
            C.RRU[itr, id] = 0.0
            C.RRD[itr, id] = 0.0
    C.PRD0 = 0.0

    lross = C.NDRE <= 0 and C.ITER == 1 or C.LFIN
    if C.HMIX0 > 0.0:
        lross = True
    if lross:
        for id in range(1, C.ND + 1):
            C.ABROSD[id] = 0.0
            C.SUMDPL[id] = 0.0

    for ij in range(1, C.NFREQ + 1):  # DO 100 IJ=1,NFREQ
        if C.IJX[ij] == -1:
            continue  # GO TO 100
        fr = C.FREQ[ij]
        w0 = C.W0E[ij]
        opacf1(ij)
        rtefr1(ij)
        alifrk(ij)
        if lross:
            rosstd(ij)
        if C.IOPTAB < 0:
            continue  # go to 100
        if C.IJEX[ij] > 0:
            ije = C.IJEX[ij]
            for id in range(1, C.ND + 1):
                C.ABSOEX[ije, id] = C.ABSO1[id]
                C.EMISEX[ije, id] = C.EMIS1[id]
                C.SCATEX[ije, id] = C.SCAT1[id]

        #        ---------------------
        #        Continuum transitions
        #        ---------------------

        for id in range(1, C.ND + 1):
            rbnu[id] = ((C.RAD1[id] + C.BNUE[ij])
                        * math.exp(-C.HKT1[id] * fr))
            for ibft in range(1, C.NTRANC + 1):  # DO 10
                itr = C.ITRBF[ibft]
                sg = cross(ibft, ij)  # CROSS 为函数（tlusty208.f:35158）
                if sg <= 0.0:
                    continue  # GO TO 10
                ii = C.ILOW[itr]
                jj = C.IUP[itr]
                if C.IPZERO[ii, id] != 0 or C.IPZERO[jj, id] != 0:
                    continue  # GO TO 10
                jc = C.ITRA[jj, ii]  # 原代码计算后未再使用，保留直译
                if C.ifwop[ii] >= 0:
                    icdw = C.MCDW[itr]
                    if icdw >= 1:
                        sg = sg * C.DWF1[icdw, id]
                else:
                    imer = C.IMRG[ii]
                    sg = C.SGMG[imer, id]
                sgw0 = sg * w0
                C.RRU[itr, id] = C.RRU[itr, id] + sgw0 * C.RAD1[id]
                C.RRD[itr, id] = C.RRD[itr, id] + sgw0 * rbnu[id]
            # 10 CONTINUE

        #        ----------------
        #        Line transitions
        #        ----------------

        if C.ISPODF == 0:
            if C.IJLIN[ij] > 0:

                #        the "primary" line at the given frequency

                itr = C.IJLIN[ij]
                ii = C.ILOW[itr]
                jj = C.IUP[itr]
                for id in range(1, C.ND + 1):  # DO 50
                    if C.IPZERO[ii, id] != 0 or C.IPZERO[jj, id] != 0:
                        continue  # GO TO 50
                    sgw0 = C.PRFLIN[id, ij] * w0
                    C.RRU[itr, id] = C.RRU[itr, id] + sgw0 * C.RAD1[id]
                    C.RRD[itr, id] = C.RRD[itr, id] + sgw0 * rbnu[id]
                # 50 CONTINUE

            if C.NLINES[ij] > 0:  # IF(NLINES(IJ).LE.0) GO TO 100 的否定
                #        the "overlapping" lines at the given frequency
                for ilint in range(1, C.NLINES[ij] + 1):  # DO 90
                    itr = C.ITRLIN[ilint, ij]
                    if C.LINEXP[itr]:
                        continue  # go to 90
                    ii = C.ILOW[itr]
                    jj = C.IUP[itr]
                    ij0 = C.IFR0[itr]
                    for ijt in range(ij0, C.IFR1[itr] + 1):
                        if C.FREQ[ijt] <= fr:
                            ij0 = ijt
                            break  # GO TO 70
                    # 70
                    ij1 = ij0 - 1
                    a1 = ((fr - C.FREQ[ij0])
                          / (C.FREQ[ij1] - C.FREQ[ij0]) * w0)
                    a2 = w0 - a1
                    for id in range(1, C.ND + 1):  # DO 80
                        if C.IPZERO[ii, id] != 0 or C.IPZERO[jj, id] != 0:
                            continue  # GO TO 80
                        sgw0 = (a1 * C.PRFLIN[id, ij1]
                                + a2 * C.PRFLIN[id, ij0])
                        C.RRU[itr, id] = C.RRU[itr, id] + sgw0 * C.RAD1[id]
                        C.RRD[itr, id] = C.RRD[itr, id] + sgw0 * rbnu[id]
                    # 80 CONTINUE
                # 90 CONTINUE

        else:
            #        Opacity sampling option
            if C.NLINES[ij] > 0:  # IF(NLINES(IJ).LE.0) GO TO 100 的否定
                for ilint in range(1, C.NLINES[ij] + 1):  # DO 190
                    itr = C.ITRLIN[ilint, ij]
                    kj = ij - C.IFR0[itr] + C.KFR0[itr]
                    indxpa = abs(C.INDEXP[itr])
                    ii = C.ILOW[itr]
                    jj = C.IUP[itr]
                    if indxpa != 3 and indxpa != 4:
                        for id in range(1, C.ND + 1):  # DO 150
                            if (C.IPZERO[ii, id] != 0
                                    or C.IPZERO[jj, id] != 0):
                                continue  # GO TO 150
                            sgw0 = C.PRFLIN[id, kj] * w0
                            C.RRU[itr, id] = (C.RRU[itr, id]
                                              + sgw0 * C.RAD1[id])
                            C.RRD[itr, id] = (C.RRD[itr, id]
                                              + sgw0 * rbnu[id])
                        # 150 CONTINUE
                    else:
                        for id in range(1, C.ND + 1):  # DO 160
                            if (C.IPZERO[ii, id] != 0
                                    or C.IPZERO[jj, id] != 0):
                                continue  # GO TO 160
                            kjd = C.JIDI[id]
                            sg = math.exp(C.XJID[id] * C.SIGFE[kjd, kj]
                                          + (UN - C.XJID[id])
                                          * C.SIGFE[kjd + 1, kj])
                            sgw0 = sg * w0
                            C.RRU[itr, id] = (C.RRU[itr, id]
                                              + sgw0 * C.RAD1[id])
                            C.RRD[itr, id] = (C.RRD[itr, id]
                                              + sgw0 * rbnu[id])
                        # 160 CONTINUE
                # 190 CONTINUE
    # 100 CONTINUE

    #     multiply some quantities by frequency-independent constants

    for id in range(1, C.ND + 1):
        # 原代码 8016 行作 "FCO OL(ID)"（标识符中夹空格，Fortran 忽略空格
        # 即 FCOOL），按 FCOOL 直译
        C.FCOOL[id] = C.REINT[id] * C.FCOOLI[id] - C.REDIF[id] * C.FLFIX[id]
        if C.CRSW[id] != UN:
            for itr in range(1, C.NTRANS + 1):
                C.RRU[itr, id] = C.RRU[itr, id] * C.CRSW[id]
                C.RRD[itr, id] = C.RRD[itr, id] * C.CRSW[id]

    #     radiation pressure

    prdx = 1.0
    # TODO(port): Fortran 中 PRDR 在 PRADA(ID)<=0 时不赋值即被引用
    # （值为未定义）；此处先置 0.0 以保证 Python 语义确定
    prdr = 0.0
    for id in range(1, C.ND + 1):
        C.PRADT[id] = C.PRADT[id] * PCK
        C.PRADA[id] = C.PRADA[id] * PCK
        if C.PRADA[id] > 0.0:
            prdr = C.PRADT[id] / C.PRADA[id]
        if prdr < prdx:
            prdx = prdr
    C.PRD0 = C.PRD0 / C.DENS1[1] * C.DM[1] * PCK
    if C.LFIN:
        #  1100 FORMAT(' PRAD MIN RATIO ',F10.6,I4)
        write_line(10, ' PRAD MIN RATIO %10.6f%4d' % (prdx, C.ITER))

    #     Rosseland mean opacity

    if lross:
        for id in range(1, C.ND + 1):
            C.ABROSD[id] = C.SUMDPL[id] / (C.ABROSD[id] * C.DENS[id])
    return


def dopgam(itr, id, t, dop, agam):
    """
    C     Doppler width and the Voigt damping parameter for the line ITR
    C
    C     Input:
    C      ITR   - index of transition
    C      ID    - depth index
    C      T     - temperature
    C     Output:
    C      DOP   - Doppler width
    C      AGAM  - total damping parameter (in units of Doppler widths;
    C              ie. = gam/4pi/DOP, where gam is the "physical" damping
    C              parameter expresed in circular frequencies)
    C
    C     Damping parameter is calculated only for transitions with
    C     |IPROF(ITR)| = 1 (ie. those for which either Voigt or some non-
    C     standard profile is assumed)
    C     Determination of AGAM:
    C     is controlled by input parameters transmitted by COMMON/VOIPAR:
    C
    C      GAMAR(IP)        - for > 0  - has the meaning of natural damping
    C                                    parameter (=Einstein coefficient for
    C                                    spontaneous emission)
    C                             = 0  - classical natural damping assumed
    C                             < 0  - damping is given by a non-standard,
    C                                    user supplied procedure GAMSP
    C      STARK1(IP)       -     = 0  - Stark broadening neglected
    C                             < 0  - scaled classical expression
    C                                    (ie gam = -STARK1 * classical Stark)
    C                             > 0  - Stark broadening given by
    C                                    n(el)*[STARK1*T**STARK2 + STARK3]
    C      STRAK2, STARK3   -   see above
    C      VDWH(IP)         -   .le.0  - Van der Waals broadening neglected
    C                             > 0  - scaled classical expression
    C
    C      the corresponding index IP is given by ITRA(IUP(ITR),ILOW(ITR))

    对应 tlusty208.f 行 8052–8171。
    PARAMETER (BOL2=2.76108D-16, CIN=UN/2.997925D10)
    PARAMETER (R02=2.5,R12=45.,OP4=0.4,VW0=4.5E-9)
    子程序体给标量哑元 DOP、AGAM 赋值 → 按约定 return 全部标量哑元
    (itr, id, t, dop, agam)。
    """
    BOL2 = 2.76108e-16        # PARAMETER (BOL2=2.76108D-16, ...)
    CIN = UN / 2.997925e10    # PARAMETER (..., CIN=UN/2.997925D10)
    R02 = 2.5                 # PARAMETER (R02=2.5,R12=45.,OP4=0.4,VW0=4.5E-9)
    R12 = 45.0
    OP4 = 0.4
    VW0 = 4.5e-9

    j = C.IUP[itr]
    iat = C.IATM[j]
    fr = C.FR0[itr]
    ie = C.IEL[j]
    am = BOL2 / C.AMASS[iat] * t
    agam = 0.0

    #     Doppler width

    dop = fr * CIN * math.sqrt(am + C.VTURBS[id] * C.VTURBS[id])

    #     -----------------
    #     damping parameter - only for IPROF = 1

    if abs(C.IPROF[itr]) != 1:
        return itr, id, t, dop, agam  # RETURN（提前返回，AGAM=0）
    ip = C.ITRA[j, C.ILOW[itr]]
    ane = C.ELEC[id]

    #     Natural (radiation) broadening

    if C.GAMAR[ip] > 0.0:
        agam = C.GAMAR[ip]
    elif C.GAMAR[ip] == 0.0:
        agam = 2.47342e-22 * fr * fr
    else:
        #     Non-standard expression - for the total damping parameter,
        #     not only for radiation damping
        # GAMSP(tlusty208.f:8177) 给标量哑元 AGAM 赋值 →
        # 按约定返回全部标量哑元 (itr, t, ane, agam)，调用点解包接收
        itr, t, ane, agam = gamsp(itr, t, ane, agam)

    #     Stark broadening

    z = float(C.IZ[ie])
    anff = z * z * EH / C.ENION[j]
    if C.STARK1[ip] == 0.0:
        agam = agam + 1.0e-8 * anff ** 2.5 * ane
    elif C.STARK1[ip] > 0.0:
        agam = agam + ane * (C.STARK1[ip] * t ** C.STARK2[ip]
                             + C.STARK3[ip])

    #     Van der Waals broadening

    if C.IELH > 0:
        ah = C.POPUL[C.NFIRST[C.IELH], id]
    else:
        ah = C.DENS[id] / C.WMM[id] / C.YTOT[id]
    if C.IELHE1 != 0:
        ahe = ah * C.ABUND[C.IATHE, id]
    else:
        ahe = ah * C.ABNDD[2, id]
    vdwc = (t * 1.0e-4) ** 0.3 * (ah + 0.42 * ahe)
    if C.VDWH[ip] >= 0.0:
        if iat < 21:
            r2 = R02 * (anff / z) ** 2
        elif iat < 45:
            r2 = (R12 - float(iat)) / z
        else:
            r2 = 0.5
        gw0 = vdwc * VW0 * r2 ** OP4
        agam = agam + gw0
    elif C.VDWH[ip] < 0.0:
        gw0 = vdwc * math.exp(2.3025851 * C.VDWH[ip])
        agam = agam + gw0

    #     Total damping parameter in units of Doppler widths

    agam = agam / dop / 12.566370614
    return itr, id, t, dop, agam


