def topbas(freq, freq0, typlv):
    """
    Procedure calculates the photo-ionisation cross section SIGMA in
    [cm^2] at frequency FREQ. FREQ0 is the threshold frequency from
    level I of ion KI. Threshold cross-sections will be of the order
    of the numerical value of 10^-18.
    Opacity-Project (OP) interpolation fit formula

    对应 tlusty208.f 行 10692–10742
    """
    # PARAMETER (E10=2.3025851)
    E10 = 2.3025851
    # PARAMETER (MMAXOP=200, MOP=15) —— Fortran 局部 PARAMETER；MMAXOP 仅用于
    # /TOPB/ 数组维度（commons.py 已按 15/200 分配），此处只需 MOP
    MOP = 15         # maximum number of fit points per level
    xfit = np.zeros(MOP + 1)  # XFIT(MOP)：local array containing x     for OP data
    sfit = np.zeros(MOP + 1)  # SFIT(MOP)：local array containing sigma for OP data

    topbas_ = 0.0

    # Read OP data if not yet done
    if not C.LOPREA:
        opdata()
    x = math.log10(freq / freq0)
    for iop in range(1, C.NTOTOP + 1):
        if feq(C.IDLVOP[iop], typlv):   # IDLVOP(IOP).EQ.TYPLV（字符串比较忽略尾部空格）
            # level has been detected in OP-data file
            if C.NOP[iop] <= 0:
                # GO TO 20 —— Level is not found, or no data for this level, in RBF.DAT
                # 100 FORMAT ('SIGMA.......: OP DATA NOT AVAILABLE FOR LEVEL ',A10)
                write_line(61, 'SIGMA.......: OP DATA NOT AVAILABLE FOR LEVEL '
                           + '{:<10}'.format(typlv))
                return topbas_   # 标号 20 的 RETURN，TOPBAS 仍为 0
            for ifit in range(1, C.NOP[iop] + 1):
                xfit[ifit] = C.XOP[ifit, iop]
                sfit[ifit] = C.SOP[ifit, iop]
            sigm = ylintp(x, xfit, sfit, C.NOP[iop], MOP)
            sigm = 1.0e-18 * math.exp(E10 * sigm)
            topbas_ = sigm
            # GO TO 10 → RETURN
            return topbas_
    # 标号 10 RETURN（循环结束未匹配到该能级）
    return topbas_


def opdata():
    """
    Procedure reads photo-ionization cross sections fit coefficients
    based on Opacity-Project (OP) data from file RBF.DAT
    Data, as stored, requires linear interpolation.

    Meaning of global variables:
       NTOTOP    = total number of levels in Opacity Project data
       IDLVOP() = level identifyer of current level
       NOP()     = number of fit points for current level
       XOP(,)    = x     = alog10(nu/nu0)       of fit point
       SOP(,)    = sigma = alog10(sigma/10^-18) of fit point

    对应 tlusty208.f 行 10748–10813
    """
    # /TOPB/ 各量直接写 C.XXX（commons.py 懒分配），无需 global
    open_unit(40, 'RBF.DAT', 'r')   # OPEN (UNIT=40,FILE='RBF.DAT',STATUS='OLD')
    # Skip header
    for iread in range(1, 21 + 1):
        read_line(40)               # READ (40,*)
    iop = 0
    #   = initialize sequential level index op Opacity Project data
    # Read number of elements in file
    # TODO(port): Fortran 表式（list-directed）READ 允许多记录/多值混排，
    # 这里按“每行一条记录”直译解析（RBF.DAT 为逐行书写）。
    neop = int(read_line(40).split()[0])          # READ (40,*) NEOP
    for ieop in range(1, neop + 1):
        # Skip element name header
        for iread in range(1, 3 + 1):
            read_line(40)                         # READ (40,*)
        # Read number of ionization stages of current element in file
        niop = int(read_line(40).split()[0])      # READ (40,*) NIOP
        for iiop in range(1, niop + 1):
            # Read ion identifyer, atomic & electron number, # of levels
            # for current ion
            parts = read_line(40).split()         # READ (40,*) IONID, IATOM_OP, IELEC_OP, NLEVEL_OP
            ionid = parts[0]                      # CHARACTER*4 IONID（读出后未再使用）
            iatom_op = int(parts[1])
            ielec_op = int(parts[2])
            nlevel_op = int(parts[3])
            for ilop in range(1, nlevel_op + 1):
                # Increase sequential level index of Opacity Project data
                iop = iop + 1
                # Read level identifyer and number of sigma fit points
                parts = read_line(40).split()     # READ (40,*) IDLVOP(IOP), NOP(IOP)
                C.IDLVOP[iop] = parts[0]
                C.NOP[iop] = int(parts[1])
                # Read normalized log10 frequency and log10 cross section values
                for is_ in range(1, C.NOP[iop] + 1):
                    parts = read_line(40).split()  # READ (40,*) INDEX, XOP(IS,IOP), SOP(IS,IOP)
                    index = int(parts[0])          # INDEX（读出后未再使用）
                    C.XOP[is_, iop] = float(parts[1])
                    C.SOP[is_, iop] = float(parts[2])
    C.NTOTOP = iop
    #          = total number of levels in Opacity Project data
    C.LOPREA = True
    #          = set flag as data has been read in
    return


def ylintp(xint, x, y, n, ntot):
    """
    linear interpolation routine. Determines YINT = Y(XINT) from
    grid Y(X) with N points and dimension NTOT.

    对应 tlusty208.f 行 10820–10850
    """
    # bisection (see Numerical Recipes par 3.4 page 90)
    jl = 0
    ju = n + 1
    # 标号 10 的 GO TO 10 循环 → while
    while ju - jl > 1:
        jm = idiv(ju + jl, 2)              # (JU+JL)/2 整数除法
        if (x[n] > x[1]) == (xint > x[jm]):   # .EQV.
            jl = jm
        else:
            ju = jm
    j = jl
    if j == n:
        j = j - 1
    if j == 0:
        j = j + 1
    # CM42 version: enable extrapolation
    rc = (y[j + 1] - y[j]) / (x[j + 1] - x[j])
    ylintp_ = rc * (xint - x[j]) + y[j]
    return ylintp_


def gfree0(id):
    """
    depth-dependent quantities for the hydrogenic free-free Gaunt factor

    对应 tlusty208.f 行 10857–10918
    """
    # PARAMETER (THET0=5.0404D3, ...)
    THET0 = 5.0404e3
    THET1 = UN / THET0
    A0 = 1.0823e0
    B0 = 2.98e-2
    C0 = 6.70e-3
    D0 = 1.12e-2
    A1 = 3.9999187e-3
    B1 = -7.8622889e-5
    C1 = 1.070192e0
    A2 = 6.4628601e-2
    B2 = -6.1953813e-4
    C2 = 2.6061249e-1
    A3 = 3.7542343e-2
    B3 = 1.3983474e-5
    C3 = 5.7917786e-1
    A4 = 3.4169006e-1
    B4 = 1.1852264e-2
    XMIN = 0.2e0
    XMINI = UN / XMIN
    THMIN = 4.0e-2

    t = C.TEMP[id]
    thet = UN / max(THET0 / t, THMIN)
    C.GF0[id] = (A0 + B0 * thet)
    C.GF1[id] = (A1 + B1 * thet) * thet + C1
    C.GF2[id] = (A2 + B2 * thet) * thet + C2
    C.GF3[id] = (A3 + B3 * thet) * thet + C3
    C.GF4[id] = A4 + B4 * thet
    C.GF5[id] = C0 + D0 * thet
    C.GF6[id] = C.GF0[id] + C.GF5[id] * XMINI

    # auxiliary quantities for derivatives
    tht = THET0 / t
    if tht >= THMIN:
        thet = tht
        C.GF0D[id] = B0 * THET1
        C.GF1D[id] = (A1 + B1 * thet * TWO) * THET1
        C.GF2D[id] = (A2 + B2 * thet * TWO) * THET1
        C.GF3D[id] = (A3 + B3 * thet * TWO) * THET1
        C.GF4D[id] = B4 * THET1
        C.GF5D[id] = D0 * THET1
        C.GF6D[id] = C.GF0D[id] + C.GF5D[id] * XMINI
    else:
        C.GF0D[id] = 0.0
        C.GF1D[id] = 0.0
        C.GF2D[id] = 0.0
        C.GF3D[id] = 0.0
        C.GF4D[id] = 0.0
        C.GF5D[id] = 0.0
        C.GF6D[id] = 0.0
    return


def gfree1(id, x):
    """
    Hydrogenic free-free Gaunt factor, for depth ID,
    frequency FR, and charge CH

    对应 tlusty208.f 行 10925–10945
    """
    # PARAMETER (XMIN=0.2D0, XMINI=UN/XMIN)
    XMIN = 0.2e0
    XMINI = UN / XMIN
    if x < UN:
        gfree1_ = ((C.GF4[id] * x - C.GF3[id]) * x + C.GF2[id]) * x + C.GF1[id]
    elif x < XMINI:
        gfree1_ = C.GF0[id] + C.GF5[id] * x
    else:
        gfree1_ = C.GF6[id]
    return gfree1_


def gfreed(id, fr, ch, gfr, gfrd):
    """
    Hydrogenic free-free Gaunt factor (GFR) and its derivative (GFRD)
    for depth ID, frequency FR, and charge CH

    对应 tlusty208.f 行 10952–10977

    修改标量哑元 GFR、GFRD → 按约定 return 全部标量哑元
    (id, fr, ch, gfr, gfrd)。
    """
    # PARAMETER (C14=2.997925D14, XMIN=0.2D0, XMINI=UN/XMIN)
    C14 = 2.997925e14
    XMIN = 0.2e0
    XMINI = UN / XMIN

    x = C14 * ch / fr
    if x < UN:
        gfr = ((C.GF4[id] * x - C.GF3[id]) * x + C.GF2[id]) * x + C.GF1[id]
        gfrd = ((C.GF4D[id] * x - C.GF3D[id]) * x + C.GF2D[id]) * x + C.GF1D[id]
    elif x < XMINI:
        gfr = C.GF0[id] + C.GF5[id] * x
        gfrd = C.GF0D[id] + C.GF5D[id] * x
    else:
        gfr = C.GF6[id]
        gfrd = C.GF6D[id]
    return id, fr, ch, gfr, gfrd


