    ct = CC0 * math.sqrt(t)
    tk = hkt / H
    t0 = t
    x = math.log10(t)
    x2 = x * x
    x3 = x * x2
    x4 = x2 * x2
    x5 = x3 * x2
    xtt[1] = 1.0
    xtt[2] = t
    xtt[3] = t * t
    xtt[4] = t * t * t
    sqt = math.sqrt(t)
