# -*- coding: utf-8 -*-
# 分片 08：tlusty208.f 行 19115–22046
# 包含子程序：ALIFR1、ALIFR3、ALIFR6


def alifr1(ij):
    """
    hydrostatic and radiative equilibrium quantities -
    derivatives of the total heating and cooling rates in the
    ALI points with respect to the
    temperature, electron density, and populations
    a variant for consistent tridiagonal operator

    对应 tlusty208.f 行 19115–20248
    """
    # PARAMETER (T23=TWO/3.D0, T43=4.D0/3.D0)
    T23 = TWO / 3.0
    T43 = 4.0 / 3.0
    # DIMENSION DSFP1(MLVEXP),DSFP1M(MLVEXP),DSFP1D(MLVEXP),
    #           DSFP1P(MLVEXP),DSFPMM(MLVEXP)
    # 局部数组，保持 Fortran 1 基索引（每维 +1）
    DSFP1 = np.zeros(MLVEXP + 1)
    DSFP1M = np.zeros(MLVEXP + 1)
    DSFP1D = np.zeros(MLVEXP + 1)
    DSFP1P = np.zeros(MLVEXP + 1)
    DSFPMM = np.zeros(MLVEXP + 1)

    if C.IFALI <= 1:
        return
    if C.IFALI > 5:
        # CALL ALIFR3(IJ)；ALIFR3 不修改标量哑元 IJ，故调用点不解包接收
        alifr3(ij)
        return

    WW = C.WC[ij]

    DSFT1M = 0.
    DSFN1M = 0.
    DSFM1M = 0.
    DSFT1D = 0.
    DSFN1D = 0.
    DSFM1D = 0.
    DSFX1 = 0.
    DSFX1D = 0.
    for II in range(1, C.NLVEXP + 1):
        DSFP1M[II] = 0.
        DSFP1D[II] = 0.

    # c     Non-standard value of ILASCT & ILMCOR
    #
    # 原代码控制流：
    #   IF(ILMCOR.NE.3) GO TO 199      —— ILMCOR==3 时顺序执行第 1 段
    #   199 IF(ILASCT.NE.0) GO TO 299  —— ILMCOR!=3 且 ILASCT==0 时执行第 2 段
    #   299 ...                        —— ILASCT!=0 时执行第 3 段
    # 三段均以 RETURN 结束，重构为 if/return 结构，保持源码段落顺序。
    if C.ILMCOR == 3:
        # c
        # c ****1. Special expressions for the first depth  -  id=1
        # c
        ID = 1
        LNSKIP = not C.LSKIP[ID, ij]
        # c
        # c     Basic auxliliary quantities - derivatives of the source function
        # c
        if C.EMIS1[ID] < 1.e-35:
            C.EMIS1[ID] = 1.e-35
        EMISIV = UN / C.EMIS1[ID]
        ABST = UN / C.ABSO1[ID]
        S0 = C.EMIS1[ID] * ABST
        # c     SC=ELEC(ID)*SIGEC(IJ)   （原代码已注释掉）
        # c
        # c     contribution from the improved boundary condition
        # c
        dt = (C.ABSO1[ID] / C.DENS[ID] + C.ABSO1[ID + 1] / C.DENS[ID + 1]) * \
            (C.DM[ID + 1] - C.DM[ID]) * HALF
        sa = S0 * (UN + 4. / dt * C.Q0[ij])
        S0 = S0 * (UN + TWO / dt * C.Q0[ij])
        # c     sa=s0   （原代码已注释掉）
        sc = C.SCAT1[ID]
        SCT = sc * ABST
        ST = S0 + SCT * C.RAD1[ID]
        CORR = UN / (UN - C.ALI1[ID] * SCT)
        DSFT1 = CORR * (S0 * C.DEMT1[ID] * EMISIV - S0 * C.DABT1[ID] * ABST)
        # 原代码第 19184 行 "c  +SIGEC(IJ)*RAD1(ID)*ABST-" 第 1 列为 c，
        # 是注释行而非续行，故 DSFN1 中不含 SIGEC 项：
        # DSFN1=CORR*(S0*DEMN1(ID)*EMISIV - S0*DABN1(ID)*ABST)
        DSFN1 = CORR * (S0 * C.DEMN1[ID] * EMISIV - S0 * C.DABN1[ID] * ABST)
        DSFM1 = CORR * (S0 * C.DEMM1[ID] * EMISIV - S0 * C.DABM1[ID] * ABST)
        for II in range(1, C.NLVEXP + 1):
            DSFP1[II] = CORR * (S0 * C.DEMP1[II, ID] * EMISIV -
                                sa * C.DABP1[II, ID] * ABST)
        if C.EMIS1[ID + 1] < 1.e-35:
            C.EMIS1[ID + 1] = 1.e-35
        EMISIP = UN / C.EMIS1[ID + 1]
        ABSTP = UN / C.ABSO1[ID + 1]
        S0P = C.EMIS1[ID + 1] * ABSTP
        scp = C.SCAT1[ID + 1]
        SCTP = scp * ABSTP
        STP = S0P + SCTP * C.RAD1[ID + 1]
        CORRP = UN / (UN - C.ALI1[ID + 1] * SCTP)
        DSFT1P = CORRP * (S0P * C.DEMT1[ID + 1] * EMISIP -
                          S0P * C.DABT1[ID + 1] * ABSTP)
        DSFN1P = CORRP * (S0P * C.DEMN1[ID + 1] * EMISIP -
                          S0P * C.DABN1[ID + 1] * ABSTP)
        DSFM1P = CORRP * (S0P * C.DEMM1[ID + 1] * EMISIP -
                          S0P * C.DABM1[ID + 1] * ABSTP)
        for II in range(1, C.NLVEXP + 1):
            DSFP1P[II] = CORRP * (S0P * C.DEMP1[II, ID + 1] * EMISIP -
                                  S0P * C.DABP1[II, ID + 1] * ABSTP)
        if C.IRDER == 1 or C.IRDER == 3:
            C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
            C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
            C.DSFDM[ID] = DSFM1 * C.ALI1[ID]
        if C.IRDER > 1:
            for II in range(1, C.NLVEXP + 1):
                C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]
        # c
        # c     Hydrostatic equilibrium quantities
        # c
        WF = WW * C.FH[ij]
        if LNSKIP:
            C.FPRD[ID] = C.FPRD[ID] + WF * C.ABSO1[ID] * C.RAD1[ID] - \
                WW * C.HEXTRD[ij] * C.ABSO1[ID]
            E0 = WF * C.RAD1[ID]
            D0 = WF * C.ABSO1[ID] * C.ALI1[ID]
            C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
            C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1 + E0 * C.DABN1[ID]
            C.HEIM[ID] = C.HEIM[ID] + D0 * DSFM1 + E0 * C.DABM1[ID]
            for II in range(1, C.NLVEXP + 1):
                C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II] + \
                    E0 * C.DABP1[II, ID]
        # c
        # c     Differential equation part of radiative equilibrium
        # c
        C.FLFIX[ID] = C.FLFIX[ID] + WF * C.RAD1[ID] - WW * C.HEXTRD[ij]
        C.FLRD[ID] = C.FLRD[ID] + C.W[ij] * C.FH[ij] * C.RAD1[ID] - \
            C.W[ij] * HALF * C.EXTRAD[ij]
        if C.REDIF[ID] > 0.:
            WF = WF * C.ALI1[ID]
            C.REDT[ID] = C.REDT[ID] + WF * DSFT1
            C.REDN[ID] = C.REDN[ID] + WF * DSFN1
            C.REDM[ID] = C.REDM[ID] + WF * DSFM1
            C.REDX[ID] = C.REDX[ID] + WF * DSFX1
            for II in range(1, C.NLVEXP + 1):
                C.REDP[II, ID] = C.REDP[II, ID] + WF * DSFP1[II]
        # C
        # C     Integral equation part of the radiative equilibrium
        # C
        if C.REINT[ID] > 0:
            ABST = C.ABSO1[ID] - C.ELSCAT[ID]
            D0 = ABST * C.ALI1[ID]
            C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] - ABST * C.RAD1[ID])
            C.REIT[ID] = C.REIT[ID] + WW * (D0 * DSFT1 +
                                            C.RAD1[ID] * C.DABT1[ID] - C.DEMT1[ID])
            C.REIN[ID] = C.REIN[ID] + WW * (D0 * DSFN1 +
                                            C.RAD1[ID] * (C.DABN1[ID] - C.SIGEC[ij]) -
                                            C.DEMN1[ID])
            C.REIM[ID] = C.REIM[ID] + WW * (D0 * DSFM1 +
                                            C.RAD1[ID] * C.DABM1[ID] - C.DEMM1[ID])
            for II in range(1, C.NLVEXP + 1):
                C.REIP[II, ID] = C.REIP[II, ID] + WW * (D0 * DSFP1[II] +
                                                       C.RAD1[ID] * C.DABP1[II, ID] -
                                                       C.DEMP1[II, ID])
        # C
        # c ****2. loop over depths
        # c
        for ID in range(2, C.ND - 1 + 1):

            LNSKIP = not C.LSKIP[ID, ij]

            DSFTMM = DSFT1M
            DSFNMM = DSFN1M
            DSFMMM = DSFM1M
            for II in range(1, C.NLVEXP + 1):
                DSFPMM[II] = DSFP1M[II]
            DSFT1M = DSFT1
            DSFN1M = DSFN1
            DSFM1M = DSFM1
            for II in range(1, C.NLVEXP + 1):
                DSFP1M[II] = DSFP1[II]
            S0 = S0P
            DSFT1 = DSFT1P
            DSFN1 = DSFN1P
            DSFM1 = DSFM1P
            for II in range(1, C.NLVEXP + 1):
                DSFP1[II] = DSFP1P[II]
            # c
            if C.EMIS1[ID + 1] < 1.e-35:
                C.EMIS1[ID + 1] = 1.e-35
            EMISIP = UN / C.EMIS1[ID + 1]
            ABSTP = UN / C.ABSO1[ID + 1]
            S0P = C.EMIS1[ID + 1] * ABSTP
            scp = C.SCAT1[ID + 1]
            SCTP = scp * ABSTP
            STP = S0P + SCTP * C.RAD1[ID + 1]
            CORRP = UN / (UN - C.ALI1[ID + 1] * SCTP)
            DSFT1P = CORRP * (S0P * C.DEMT1[ID + 1] * EMISIP -
                              S0P * C.DABT1[ID + 1] * ABSTP)
            DSFN1P = CORRP * (S0P * C.DEMN1[ID + 1] * EMISIP -
                              S0P * C.DABN1[ID + 1] * ABSTP)
            DSFM1P = CORRP * (S0P * C.DEMM1[ID + 1] * EMISIP -
                              STP * C.DABM1[ID + 1] * ABSTP)
            for II in range(1, C.NLVEXP + 1):
                DSFP1P[II] = CORRP * (S0P * C.DEMP1[II, ID + 1] * EMISIP -
                                      S0P * C.DABP1[II, ID + 1] * ABSTP)

            if C.IRDER == 1 or C.IRDER == 3:
                C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
                C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
                C.DSFDM[ID] = DSFM1 * C.ALI1[ID]
            if C.IRDER > 1:
                for II in range(1, C.NLVEXP + 1):
                    C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]
            # c
            # c       Hydrostatic equilibrium equation
            # c
            if LNSKIP:
                D0 = WW * C.FAK1[ID]
                A0 = WW * C.FAK1[ID - 1]
                C.FPRD[ID] = C.FPRD[ID] + D0 * C.RAD1[ID] - A0 * C.RAD1[ID - 1]
                E0 = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
                D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
                C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1
                C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1
                C.HEIM[ID] = C.HEIM[ID] + D0 * DSFM1
                C.HEITM[ID] = C.HEITM[ID] + E0 * DSFT1M
                C.HEINM[ID] = C.HEINM[ID] + E0 * DSFN1M
                C.HEIMM[ID] = C.HEIMM[ID] + E0 * DSFM1M
                for II in range(1, C.NLVEXP + 1):
                    C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II]
                    C.HEIPM[II, ID] = C.HEIPM[II, ID] + E0 * DSFP1M[II]
            # C
            # C       Differential equation part of radiative equilibrium
            # C
            DDT = UN / (C.ABSOT[ID] + C.ABSOT[ID - 1])
            dt = DDT / C.DELDMZ[ID - 1]
            FL = (C.RAD1[ID] * C.FAK1[ID] - C.RAD1[ID - 1] * C.FAK1[ID - 1]) * dt
            C.FLFIX[ID] = C.FLFIX[ID] + WW * FL
            C.FLRD[ID] = C.FLRD[ID] + C.W[ij] * FL
            if C.REDIF[ID] > 0:
                if C.IFALIH == 0:
                    D0 = WW * C.FAK1[ID] * dt
                    A0 = WW * C.FAK1[ID - 1] * dt
                    D0M = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
                    D0P = D0 * C.ALIP1[ID]
                    D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
                    E0 = WW * FL * DDT
                    C.REDX[ID] = C.REDX[ID] + E0 * C.ABSO1[ID]
                    C.REDXM[ID] = C.REDXM[ID] + E0 * C.ABSO1[ID - 1]
                    E0M = E0 * C.DENSI[ID - 1]
                    E0 = E0 * C.DENSI[ID]
                    C.REDT[ID] = C.REDT[ID] + D0 * DSFT1 - E0 * C.DABT1[ID]
                    C.REDTM[ID] = C.REDTM[ID] + D0M * DSFT1M - E0M * C.DABT1[ID - 1]
                    C.REDN[ID] = C.REDN[ID] + D0 * DSFN1 - E0 * C.DABN1[ID]
                    C.REDNM[ID] = C.REDNM[ID] + D0M * DSFN1M - E0M * C.DABN1[ID - 1]
                    C.REDM[ID] = C.REDM[ID] + D0 * DSFM1 - E0 * C.DABM1[ID]
                    C.REDMM[ID] = C.REDMM[ID] + D0M * DSFM1M - E0M * C.DABM1[ID - 1]
                    for II in range(1, C.NLVEXP + 1):
                        C.REDP[II, ID] = C.REDP[II, ID] + D0 * DSFP1[II] - \
                            E0 * C.DABP1[II, ID]
                        C.REDPM[II, ID] = C.REDPM[II, ID] + D0M * DSFP1M[II] - \
                            E0M * C.DABP1[II, ID - 1]
                else:
                    # 原：d0=ww*alih1(id)；alih1 在 commons.py 中规范拼写为小写
                    D0 = WW * C.alih1[ID]
                    C.REDT[ID] = C.REDT[ID] + D0 * DSFT1
                    C.REDN[ID] = C.REDN[ID] + D0 * DSFN1
                    C.REDM[ID] = C.REDM[ID] + D0 * DSFM1
                    for II in range(1, C.NLVEXP + 1):
                        C.REDP[II, ID] = C.REDP[II, ID] + D0 * DSFP1[II]
            # c
            # C       Integral equation part of the radiative equilibrium
            # C
            if C.REINT[ID] > 0:
                ABST = C.ABSO1[ID] - C.ELSCAT[ID]
                D0 = ABST * C.ALI1[ID]
                C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] -
                                                    ABST * C.RAD1[ID])
                C.REIN[ID] = C.REIN[ID] + WW * (D0 * DSFN1 +
                                                C.RAD1[ID] * (C.DABN1[ID] - C.SIGEC[ij]) -
                                                C.DEMN1[ID])
                for II in range(1, C.NLVEXP + 1):
                    C.REIP[II, ID] = C.REIP[II, ID] + WW * (D0 * DSFP1[II] +
                                                           C.RAD1[ID] * C.DABP1[II, ID] -
                                                           C.DEMP1[II, ID])
                C.REIT[ID] = C.REIT[ID] + WW * (D0 * DSFT1 +
                                                C.RAD1[ID] * C.DABT1[ID] - C.DEMT1[ID])
                C.REIM[ID] = C.REIM[ID] + WW * (D0 * DSFM1 +
                                                C.RAD1[ID] * C.DABM1[ID] - C.DEMM1[ID])

        # C
        # c ****3. deepest point - ID=ND
        # c
        ID = C.ND

        LNSKIP = not C.LSKIP[ID, ij]

        DSFTMM = DSFT1M
        DSFNMM = DSFN1M
        DSFMMM = DSFM1M
        for II in range(1, C.NLVEXP + 1):
            DSFPMM[II] = DSFP1M[II]
        DSFT1M = DSFT1
        DSFN1M = DSFN1
        DSFM1M = DSFM1
        for II in range(1, C.NLVEXP + 1):
            DSFP1M[II] = DSFP1[II]
        S0 = S0P
        DSFT1 = DSFT1P
        DSFN1 = DSFN1P
        DSFM1 = DSFM1P
        for II in range(1, C.NLVEXP + 1):
            DSFP1[II] = DSFP1P[II]
        DSFT1D = 0.
        DSFN1D = 0.
        DSFM1D = 0.
        for II in range(1, C.NLVEXP + 1):
            DSFP1D[II] = 0.
        # C
        # C     Improved lower boundary condition
        # C
        if C.IBC > 0 and C.IDISK == 0:
            dt = UN / (C.DELDMZ[ID - 1] * (C.ABSOT[ID] + C.ABSOT[ID - 1]))
            PLAD = C.XKFB[ID] / C.XKF1[ID]
            DBDT = PLAD / C.XKF1[ID] * C.HKT21[ID] * C.FREQ[ij] * dt
            if C.IBC == 1:
                DSFT1 = DSFT1 + DBDT
            elif C.IBC >= 2:
                PLAM = C.XKFB[ID - 1] / C.XKF1[ID - 1]
                TAU23 = T23 * dt
                TAU43 = T43 * dt
                D0 = (PLAD * (UN + TAU43) - T43 * PLAM * dt) * dt * dt
                RHD = C.DELDMZ[ID - 1] * C.DENSI[ID]
                E0 = D0 * RHD
                DSFT1 = DSFT1 + DBDT * (UN + TAU23) - E0 * C.DABT1[ID]
                DSFN1 = DSFN1 - E0 * (C.DABN1[ID] + C.ABSO1[ID] * C.DENSIM[ID])
                for II in range(1, C.NLVEXP + 1):
                    DSFP1[II] = DSFP1[II] - E0 * C.DABP1[II, ID]
                if C.IBC >= 3:
                    DBDTM = PLAM / C.XKF1[ID - 1] * C.HKT21[ID - 1] * C.FREQ[ij] * dt
                    RHD = C.DELDMZ[ID - 1] * C.DENSI[ID - 1]
                    E0 = D0 * RHD
                    DSFT1D = -DBDTM * dt * T23 - E0 * C.DABT1[ID - 1]
                    DSFN1D = -E0 * (C.DABN1[ID - 1] +
                                    C.ABSO1[ID - 1] * C.DENSIM[ID - 1])
                    for II in range(1, C.NLVEXP + 1):
                        DSFP1D[II] = -E0 * C.DABP1[II, ID - 1]
        # C
        if C.IRDER == 1 or C.IRDER == 3:
            C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
            C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
            C.DSFDM[ID] = DSFM1 * C.ALI1[ID]
        if C.IRDER > 1:
            for II in range(1, C.NLVEXP + 1):
                C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]
        # c
        # c     Hydrostatic equilibrium equation
        # c
        if LNSKIP:
            D0 = WW * C.FAK1[ID]
            A0 = WW * C.FAK1[ID - 1]
            C.FPRD[ID] = C.FPRD[ID] + D0 * C.RAD1[ID] - A0 * C.RAD1[ID - 1]
            E0 = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
            D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
            C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1
            C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1
            C.HEIM[ID] = C.HEIM[ID] + D0 * DSFM1
            C.HEITM[ID] = C.HEITM[ID] + E0 * DSFT1M
            C.HEINM[ID] = C.HEINM[ID] + E0 * DSFN1M
            C.HEIMM[ID] = C.HEIMM[ID] + E0 * DSFM1M
            for II in range(1, C.NLVEXP + 1):
                C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II]
                C.HEIPM[II, ID] = C.HEIPM[II, ID] + E0 * DSFP1M[II]
            if C.IBC >= 3:
                C.HEITM[ID] = C.HEITM[ID] - D0 * DSFT1D
                C.HEINM[ID] = C.HEINM[ID] - D0 * DSFN1D
                C.HEIMM[ID] = C.HEIMM[ID] - D0 * DSFM1D
                for II in range(1, C.NLVEXP + 1):
                    C.HEIPM[II, ID] = C.HEIPM[II, ID] - D0 * DSFP1D[II]
        # C
        # C     Differential equation part of radiative equilibrium
        # C
        DDT = UN / (C.ABSOT[ID] + C.ABSOT[ID - 1])
        dt = DDT / C.DELDMZ[ID - 1]
        FL = (C.RAD1[ID] * C.FAK1[ID] - C.RAD1[ID - 1] * C.FAK1[ID - 1]) * dt
        C.FLFIX[ID] = C.FLFIX[ID] + WW * FL
        C.FLRD[ID] = C.FLRD[ID] + C.W[ij] * FL
        if C.REDIF[ID] > 0:
            D0 = WW * C.FAK1[ID] * dt
            A0 = WW * C.FAK1[ID - 1] * dt
            D0M = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
            D0P = D0 * C.ALIP1[ID]
            D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
            E0 = WW * FL * DDT
            C.REDX[ID] = C.REDX[ID] + E0 * C.ABSO1[ID]
            C.REDXM[ID] = C.REDXM[ID] + E0 * C.ABSO1[ID - 1]
            E0M = E0 * C.DENSI[ID - 1]
            E0 = E0 * C.DENSI[ID]
            C.REDT[ID] = C.REDT[ID] + D0 * DSFT1 - E0 * C.DABT1[ID]
            C.REDTM[ID] = C.REDTM[ID] + D0M * DSFT1M - E0M * C.DABT1[ID - 1]
            C.REDN[ID] = C.REDN[ID] + D0 * DSFN1 - E0 * C.DABN1[ID]
            C.REDNM[ID] = C.REDNM[ID] + D0M * DSFN1M - E0M * C.DABN1[ID - 1]
            C.REDM[ID] = C.REDM[ID] + D0 * DSFM1 - E0 * C.DABM1[ID]
            C.REDMM[ID] = C.REDMM[ID] + D0M * DSFM1M - E0M * C.DABM1[ID - 1]
            for II in range(1, C.NLVEXP + 1):
                C.REDP[II, ID] = C.REDP[II, ID] + D0 * DSFP1[II] - \
                    E0 * C.DABP1[II, ID]
                C.REDPM[II, ID] = C.REDPM[II, ID] + D0M * DSFP1M[II] - \
                    E0M * C.DABP1[II, ID - 1]
            if C.IBC >= 3:
                C.REDTM[ID] = C.REDTM[ID] + D0 * DSFT1D
                C.REDNM[ID] = C.REDNM[ID] + D0 * DSFN1D
                C.REDMM[ID] = C.REDMM[ID] + D0 * DSFM1D
                for II in range(1, C.NLVEXP + 1):
                    C.REDPM[II, ID] = C.REDPM[II, ID] + D0 * DSFP1D[II]
        # c
        # C     Integral equation part of the radiative equilibrium
        # C
        if C.REINT[ID] > 0:
            ABST = C.ABSO1[ID] - C.ELSCAT[ID]
            D0 = ABST * C.ALI1[ID]
            C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] - ABST * C.RAD1[ID])
            C.REIN[ID] = C.REIN[ID] + WW * (D0 * DSFN1 +
                                            C.RAD1[ID] * (C.DABN1[ID] - C.SIGEC[ij]) -
                                            C.DEMN1[ID])
            C.REIM[ID] = C.REIM[ID] + WW * (D0 * DSFM1 +
                                            C.RAD1[ID] * C.DABM1[ID] - C.DEMM1[ID])
            for II in range(1, C.NLVEXP + 1):
                C.REIP[II, ID] = C.REIP[II, ID] + WW * (D0 * DSFP1[II] +
                                                       C.RAD1[ID] * C.DABP1[II, ID] -
                                                       C.DEMP1[II, ID])
            if C.IBC == 0:
                C.REIT[ID] = C.REIT[ID] + WW * (D0 * DSFT1 +
                                                C.RAD1[ID] * C.DABT1[ID] - C.DEMT1[ID])
            else:
                # TODO(port): 此分支引用 DBDT/E0；DBDT 仅在上面
                # IF(IBC.GT.0.AND.IDISK.EQ.0) 块内赋值。Fortran 中未赋值时
                # 取局部变量残留值；Python 局部变量在同一次调用内同样保留旧值，
                # 但若本次调用从未赋值（如 IBC>0 且 IDISK!=0 且此前路径也未赋值）
                # 将抛 NameError，与 Fortran 的"未定义值"行为不完全等价。
                C.REIT[ID] = C.REIT[ID] + WW * (D0 * (DSFT1 - DBDT) +
                                                E0 * C.DABT1[ID] +
                                                C.RAD1[ID] * C.DABT1[ID] - C.DEMT1[ID] +
                                                C.ALI1[ID] / ABST * DBDT)
        return

    # c     Non-standard value of ILASCT & ILMCOR
    #
    # 199 IF(ILASCT.NE.0) GO TO 299
    if C.ILASCT != 0:
        # GO TO 299 —— 见下方标号 299 段
        pass
    else:
        # c
        # c ****1. Special expressions for the first depth  -  id=1
        # c
        ID = 1

        LNSKIP = not C.LSKIP[ID, ij]
        # c
        # c     Basic auxliliary quantities - derivatives of the source function
        # c
        EMISIV = UN / C.EMIS1[ID]
        ABST = UN / (C.ABSO1[ID] - C.ELSCAT[ID])
        S0 = C.EMIS1[ID] * ABST
        DSFN1 = S0 * (C.DEMN1[ID] * EMISIV - (C.DABN1[ID] - C.SIGEC[ij]) * ABST)
        DSFT1 = S0 * (C.DEMT1[ID] * EMISIV - C.DABT1[ID] * ABST)
        for II in range(1, C.NLVEXP + 1):
            DSFP1[II] = S0 * (C.DEMP1[II, ID] * EMISIV - C.DABP1[II, ID] * ABST)
        EMISIP = UN / C.EMIS1[ID + 1]
        ABSTP = UN / (C.ABSO1[ID + 1] - C.ELSCAT[ID + 1])
        S0P = C.EMIS1[ID + 1] * ABSTP
        DSFN1P = S0P * (C.DEMN1[ID + 1] * EMISIP -
                        (C.DABN1[ID + 1] - C.SIGEC[ij]) * ABSTP)
        DSFT1P = S0P * (C.DEMT1[ID + 1] * EMISIP - C.DABT1[ID + 1] * ABSTP)
        for II in range(1, C.NLVEXP + 1):
            DSFP1P[II] = S0P * (C.DEMP1[II, ID + 1] * EMISIP -
                                C.DABP1[II, ID + 1] * ABSTP)

        if C.IRDER == 1 or C.IRDER == 3:
            C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
            C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
        if C.IRDER > 1:
            for II in range(1, C.NLVEXP + 1):
                C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]
        # c
        # c     Hydrostatic equilibrium quantities
        # c
        WF = WW * C.FH[ij]
        if LNSKIP:
            C.FPRD[ID] = C.FPRD[ID] + WF * C.ABSO1[ID] * C.RAD1[ID] - \
                WW * C.HEXTRD[ij] * C.ABSO1[ID]
            E0 = WF * C.RAD1[ID]
            D0 = WF * C.ABSO1[ID] * C.ALI1[ID]
            C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
            C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1 + E0 * C.DABN1[ID]
            for II in range(1, C.NLVEXP + 1):
                C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II] + \
                    E0 * C.DABP1[II, ID]
        # c
        # c     Differential equation part of radiative equilibrium
        # c
        C.FLFIX[ID] = C.FLFIX[ID] + WF * C.RAD1[ID] - WW * C.HEXTRD[ij]
        C.FLRD[ID] = C.FLRD[ID] + C.W[ij] * C.FH[ij] * C.RAD1[ID] - \
            C.W[ij] * HALF * C.EXTRAD[ij]
        if C.REDIF[ID] > 0.:
            WF = WF * C.ALI1[ID]
            C.REDT[ID] = C.REDT[ID] + WF * DSFT1
            C.REDN[ID] = C.REDN[ID] + WF * DSFN1
            for II in range(1, C.NLVEXP + 1):
                C.REDP[II, ID] = C.REDP[II, ID] + WF * DSFP1[II]
        # c
        # C     Integral equation part of the radiative equilibrium
        # C
        if C.REINT[ID] > 0:
            ABST = C.ABSO1[ID] - C.ELSCAT[ID]
            WWK = WW * ABST
            C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] - ABST * C.RAD1[ID])
            D0 = WW * (C.ALI1[ID] - UN) * ABST
            E0 = WW * (C.RAD1[ID] - S0)
            C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + E0 * (C.DABN1[ID] - C.SIGEC[ij])
            C.REIT[ID] = C.REIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
            for II in range(1, C.NLVEXP + 1):
                C.REIP[II, ID] = C.REIP[II, ID] + D0 * DSFP1[II] + \
                    E0 * C.DABP1[II, ID]

        # C
        # c ****2. loop over depths
        # c
        for ID in range(2, C.ND - 1 + 1):

            LNSKIP = not C.LSKIP[ID, ij]

            DSFTMM = DSFT1M
            DSFNMM = DSFN1M
            for II in range(1, C.NLVEXP + 1):
                DSFPMM[II] = DSFP1M[II]
            DSFT1M = DSFT1
            DSFN1M = DSFN1
            for II in range(1, C.NLVEXP + 1):
                DSFP1M[II] = DSFP1[II]
            S0 = S0P
            DSFT1 = DSFT1P
            DSFN1 = DSFN1P
            for II in range(1, C.NLVEXP + 1):
                DSFP1[II] = DSFP1P[II]

            EMISIP = UN / C.EMIS1[ID + 1]
            ABSTP = UN / (C.ABSO1[ID + 1] - C.ELSCAT[ID + 1])
            S0P = C.EMIS1[ID + 1] * ABSTP
            DSFN1P = S0P * (C.DEMN1[ID + 1] * EMISIP -
                            (C.DABN1[ID + 1] - C.SIGEC[ij]) * ABSTP)
            DSFT1P = S0P * (C.DEMT1[ID + 1] * EMISIP - C.DABT1[ID + 1] * ABSTP)
            for II in range(1, C.NLVEXP + 1):
                DSFP1P[II] = S0P * (C.DEMP1[II, ID + 1] * EMISIP -
                                    C.DABP1[II, ID + 1] * ABSTP)

            if C.IRDER == 1 or C.IRDER == 3:
                C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
                C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
            if C.IRDER > 1:
                for II in range(1, C.NLVEXP + 1):
                    C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]
            # c
            # c       Hydrostatic equilibrium equation
            # c
            if LNSKIP:
                D0 = WW * C.FAK1[ID]
                A0 = WW * C.FAK1[ID - 1]
                C.FPRD[ID] = C.FPRD[ID] + D0 * C.RAD1[ID] - A0 * C.RAD1[ID - 1]
                E0 = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
                D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
                C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1
                C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1
                C.HEITM[ID] = C.HEITM[ID] + E0 * DSFT1M
                C.HEINM[ID] = C.HEINM[ID] + E0 * DSFN1M
                for II in range(1, C.NLVEXP + 1):
                    C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II]
                    C.HEIPM[II, ID] = C.HEIPM[II, ID] + E0 * DSFP1M[II]
            # C
            # C       Differential equation part of radiative equilibrium
            # C
            DDT = UN / (C.ABSOT[ID] + C.ABSOT[ID - 1])
            dt = DDT / C.DELDMZ[ID - 1]
            FL = (C.RAD1[ID] * C.FAK1[ID] - C.RAD1[ID - 1] * C.FAK1[ID - 1]) * dt
            C.FLFIX[ID] = C.FLFIX[ID] + WW * FL
            if C.REDIF[ID] > 0:
                D0 = WW * C.FAK1[ID] * dt
                A0 = WW * C.FAK1[ID - 1] * dt
                D0M = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
                D0P = D0 * C.ALIP1[ID]
                D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
                E0 = WW * FL * DDT
                C.REDX[ID] = C.REDX[ID] + E0 * C.ABSO1[ID]
                C.REDXM[ID] = C.REDXM[ID] + E0 * C.ABSO1[ID - 1]
                E0M = E0 * C.DENSI[ID - 1]
                E0 = E0 * C.DENSI[ID]
                C.REDT[ID] = C.REDT[ID] + D0 * DSFT1 - E0 * C.DABT1[ID]
                C.REDTM[ID] = C.REDTM[ID] + D0M * DSFT1M - E0M * C.DABT1[ID - 1]
                C.REDN[ID] = C.REDN[ID] + D0 * DSFN1 - E0 * C.DABN1[ID]
                C.REDNM[ID] = C.REDNM[ID] + D0M * DSFN1M - E0M * C.DABN1[ID - 1]
                for II in range(1, C.NLVEXP + 1):
                    C.REDP[II, ID] = C.REDP[II, ID] + D0 * DSFP1[II] - \
                        E0 * C.DABP1[II, ID]
                    C.REDPM[II, ID] = C.REDPM[II, ID] + D0M * DSFP1M[II] - \
                        E0M * C.DABP1[II, ID - 1]
            # c
            # C       Integral equation part of the radiative equilibrium
            # C
            if C.REINT[ID] > 0:
                ABST = C.ABSO1[ID] - C.ELSCAT[ID]
                WWK = WW * ABST
                C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] -
                                                    ABST * C.RAD1[ID])
                D0 = WW * (C.ALI1[ID] - UN) * ABST
                E0 = WW * (C.RAD1[ID] - S0)
                C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + \
                    E0 * (C.DABN1[ID] - C.SIGEC[ij])
                C.REIT[ID] = C.REIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
                for II in range(1, C.NLVEXP + 1):
                    C.REIP[II, ID] = C.REIP[II, ID] + D0 * DSFP1[II] + \
                        E0 * C.DABP1[II, ID]

        # C
        # c ****3. deepest point - ID=ND
        # c
        ID = C.ND

        LNSKIP = not C.LSKIP[ID, ij]

        DSFTMM = DSFT1M
        DSFNMM = DSFN1M
        for II in range(1, C.NLVEXP + 1):
            DSFPMM[II] = DSFP1M[II]
        DSFT1M = DSFT1
        DSFN1M = DSFN1
        for II in range(1, C.NLVEXP + 1):
            DSFP1M[II] = DSFP1[II]
        S0 = S0P
        DSFT1 = DSFT1P
        DSFN1 = DSFN1P
        for II in range(1, C.NLVEXP + 1):
            DSFP1[II] = DSFP1P[II]
        # C
        # C     Improved lower boundary condition
        # C
        if C.IBC > 0 and C.IDISK == 0:
            dt = UN / (C.DELDMZ[ID - 1] * (C.ABSOT[ID] + C.ABSOT[ID - 1]))
            PLAD = C.XKFB[ID] / C.XKF1[ID]
            DBDT = PLAD / C.XKF1[ID] * C.HKT21[ID] * C.FREQ[ij] * dt
            if C.IBC == 1:
                DSFT1 = DSFT1 + DBDT
            elif C.IBC >= 2:
                PLAM = C.XKFB[ID - 1] / C.XKF1[ID - 1]
                TAU23 = T23 * dt
                TAU43 = T43 * dt
                D0 = (PLAD * (UN + TAU43) - T43 * PLAM * dt) * dt * dt
                RHD = C.DELDMZ[ID - 1] * C.DENSI[ID]
                E0 = D0 * RHD
                DSFT1 = DSFT1 + DBDT * (UN + TAU23) - E0 * C.DABT1[ID]
                DSFN1 = DSFN1 - E0 * (C.DABN1[ID] + C.ABSO1[ID] * C.DENSIM[ID])
                for II in range(1, C.NLVEXP + 1):
                    DSFP1[II] = DSFP1[II] - E0 * C.DABP1[II, ID]
                if C.IBC >= 3:
                    DBDTM = PLAM / C.XKF1[ID - 1] * C.HKT21[ID - 1] * C.FREQ[ij] * dt
                    RHD = C.DELDMZ[ID - 1] * C.DENSI[ID - 1]
                    E0 = D0 * RHD
                    DSFT1D = -DBDTM * dt * T23 - E0 * C.DABT1[ID - 1]
                    DSFN1D = -E0 * (C.DABN1[ID - 1] +
                                    C.ABSO1[ID - 1] * C.DENSIM[ID - 1])
                    for II in range(1, C.NLVEXP + 1):
                        DSFP1D[II] = -E0 * C.DABP1[II, ID - 1]
        # C
        if C.IRDER == 1 or C.IRDER == 3:
            C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
            C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
        if C.IRDER > 1:
            for II in range(1, C.NLVEXP + 1):
                C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]
        # c
        # c     Hydrostatic equilibrium equation
        # c
        if LNSKIP:
            D0 = WW * C.FAK1[ID]
            A0 = WW * C.FAK1[ID - 1]
            C.FPRD[ID] = C.FPRD[ID] + D0 * C.RAD1[ID] - A0 * C.RAD1[ID - 1]
            E0 = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
            D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
            C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1
            C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1
            C.HEITM[ID] = C.HEITM[ID] + E0 * DSFT1M
            C.HEINM[ID] = C.HEINM[ID] + E0 * DSFN1M
            for II in range(1, C.NLVEXP + 1):
                C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II]
                C.HEIPM[II, ID] = C.HEIPM[II, ID] + E0 * DSFP1M[II]
            if C.IBC >= 3:
                C.HEITM[ID] = C.HEITM[ID] - D0 * DSFT1D
                C.HEINM[ID] = C.HEINM[ID] - D0 * DSFN1D
                for II in range(1, C.NLVEXP + 1):
                    C.HEIPM[II, ID] = C.HEIPM[II, ID] - D0 * DSFP1D[II]
        # C
        # C     Differential equation part of radiative equilibrium
        # C
        DDT = UN / (C.ABSOT[ID] + C.ABSOT[ID - 1])
        dt = DDT / C.DELDMZ[ID - 1]
        FL = (C.RAD1[ID] * C.FAK1[ID] - C.RAD1[ID - 1] * C.FAK1[ID - 1]) * dt
        C.FLFIX[ID] = C.FLFIX[ID] + WW * FL
        if C.REDIF[ID] > 0:
            D0 = WW * C.FAK1[ID] * dt
            A0 = WW * C.FAK1[ID - 1] * dt
            D0M = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
            D0P = D0 * C.ALIP1[ID]
            D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
            E0 = WW * FL * DDT
            C.REDX[ID] = C.REDX[ID] + E0 * C.ABSO1[ID]
            C.REDXM[ID] = C.REDXM[ID] + E0 * C.ABSO1[ID - 1]
            E0M = E0 * C.DENSI[ID - 1]
            E0 = E0 * C.DENSI[ID]
            C.REDT[ID] = C.REDT[ID] + D0 * DSFT1 - E0 * C.DABT1[ID]
            C.REDTM[ID] = C.REDTM[ID] + D0M * DSFT1M - E0M * C.DABT1[ID - 1]
            C.REDN[ID] = C.REDN[ID] + D0 * DSFN1 - E0 * C.DABN1[ID]
            C.REDNM[ID] = C.REDNM[ID] + D0M * DSFN1M - E0M * C.DABN1[ID - 1]
            for II in range(1, C.NLVEXP + 1):
                C.REDP[II, ID] = C.REDP[II, ID] + D0 * DSFP1[II] - \
                    E0 * C.DABP1[II, ID]
                C.REDPM[II, ID] = C.REDPM[II, ID] + D0M * DSFP1M[II] - \
                    E0M * C.DABP1[II, ID - 1]
            if C.IBC >= 3:
                C.REDTM[ID] = C.REDTM[ID] + D0 * DSFT1D
                C.REDNM[ID] = C.REDNM[ID] + D0 * DSFN1D
                for II in range(1, C.NLVEXP + 1):
                    C.REDPM[II, ID] = C.REDPM[II, ID] + D0 * DSFP1D[II]
        # c
        # C     Integral equation part of the radiative equilibrium
        # C
        if C.REINT[ID] > 0:
            ABST = C.ABSO1[ID] - C.ELSCAT[ID]
            WWK = WW * ABST
            C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] - ABST * C.RAD1[ID])
            D0 = WW * (C.ALI1[ID] - UN) * ABST
            E0 = WW * (C.RAD1[ID] - S0)
            C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + E0 * (C.DABN1[ID] - C.SIGEC[ij])
            if C.IBC == 0:
                C.REIT[ID] = C.REIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
            else:
                # TODO(port): DBDT 仅在 IF(IBC.GT.0.AND.IDISK.EQ.0) 块内赋值；
                # 未赋值时 Fortran 取残留值，Python 同一次调用内亦保留旧值，
                # 但首次使用前未赋值将抛 NameError（见 ALIFR1 主分支同名注释）。
                C.REIT[ID] = C.REIT[ID] + D0 * (DSFT1 - DBDT) + E0 * C.DABT1[ID] + \
                    C.ALI1[ID] / ABST * DBDT
            for II in range(1, C.NLVEXP + 1):
                C.REIP[II, ID] = C.REIP[II, ID] + D0 * DSFP1[II] + \
                    E0 * C.DABP1[II, ID]
        return

    # C     Non-standard value of ILASCT (ILASCT != 0)
    # c
    # c ****1. Special expressions for the first depth  -  id=1
    # c
    # 299 ID=1  —— 上面 GO TO 299 跳转到此处
    ID = 1

    LNSKIP = not C.LSKIP[ID, ij]
    # c
    # c     Basic auxliliary quantities - derivatives of the source function
    # c
    EMISIV = UN / C.EMIS1[ID]
    ABST = UN / C.ABSO1[ID]
    S0 = C.EMIS1[ID] * ABST
    DSFN1 = S0 * (C.DEMN1[ID] * EMISIV - C.DABN1[ID] * ABST)
    DSFT1 = S0 * (C.DEMT1[ID] * EMISIV - C.DABT1[ID] * ABST)
    for II in range(1, C.NLVEXP + 1):
        DSFP1[II] = S0 * (C.DEMP1[II, ID] * EMISIV - C.DABP1[II, ID] * ABST)
    EMISIP = UN / C.EMIS1[ID + 1]
    ABSTP = UN / C.ABSO1[ID + 1]
    S0P = C.EMIS1[ID + 1] * ABSTP
    DSFN1P = S0P * (C.DEMN1[ID + 1] * EMISIP - C.DABN1[ID + 1] * ABSTP)
    DSFT1P = S0P * (C.DEMT1[ID + 1] * EMISIP - C.DABT1[ID + 1] * ABSTP)
    for II in range(1, C.NLVEXP + 1):
        DSFP1P[II] = S0P * (C.DEMP1[II, ID + 1] * EMISIP -
                            C.DABP1[II, ID + 1] * ABSTP)

    if C.IRDER == 1 or C.IRDER == 3:
        C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
        C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
    if C.IRDER > 1:
        for II in range(1, C.NLVEXP + 1):
            C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]

    # c
    # c     Hydrostatic equilibrium quantities
    # c
    WF = WW * C.FH[ij]
    if LNSKIP:
        C.FPRD[ID] = C.FPRD[ID] + WF * C.ABSO1[ID] * C.RAD1[ID] - \
            WW * C.HEXTRD[ij] * C.ABSO1[ID]
        E0 = WF * C.RAD1[ID]
        D0 = WF * C.ABSO1[ID] * C.ALI1[ID]
        C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
        C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1 + E0 * C.DABN1[ID]
        for II in range(1, C.NLVEXP + 1):
            C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II] + \
                E0 * C.DABP1[II, ID]
    # c
    # c     Differential equation part of radiative equilibrium
    # c
    C.FLFIX[ID] = C.FLFIX[ID] + WF * C.RAD1[ID] - WW * C.HEXTRD[ij]
    C.FLRD[ID] = C.FLRD[ID] + C.W[ij] * C.FH[ij] * C.RAD1[ID] - \
        C.W[ij] * HALF * C.EXTRAD[ij]
    if C.REDIF[ID] > 0.:
        WF = WF * C.ALI1[ID]
        C.REDT[ID] = C.REDT[ID] + WF * DSFT1
        C.REDN[ID] = C.REDN[ID] + WF * DSFN1
        for II in range(1, C.NLVEXP + 1):
            C.REDP[II, ID] = C.REDP[II, ID] + WF * DSFP1[II]
    # c
    # C     Integral equation part of the radiative equilibrium
    # C
    if C.REINT[ID] > 0:
        SRH = SIGE * C.DENS1[ID]
        ABST = C.ABSO1[ID]
        ABSTE = ABST - C.ELSCAT[ID]
        WWK = WW * ABST
        C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] - ABSTE * C.RAD1[ID])
        D0 = WW * (ABSTE * C.ALI1[ID] - ABST)
        E0 = WW * (C.RAD1[ID] - S0)
        C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + E0 * C.DABN1[ID] - \
            WW * C.SIGEC[ij] * C.RAD1[ID]
        C.REIT[ID] = C.REIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
        for II in range(1, C.NLVEXP + 1):
            C.REIP[II, ID] = C.REIP[II, ID] + D0 * DSFP1[II] + \
                E0 * C.DABP1[II, ID]

    # C
    # c ****2. loop over depths
    # c
    for ID in range(2, C.ND - 1 + 1):

        LNSKIP = not C.LSKIP[ID, ij]

        DSFTMM = DSFT1M
        DSFNMM = DSFN1M
        for II in range(1, C.NLVEXP + 1):
            DSFPMM[II] = DSFP1M[II]
        DSFT1M = DSFT1
        DSFN1M = DSFN1
        for II in range(1, C.NLVEXP + 1):
            DSFP1M[II] = DSFP1[II]
        S0 = S0P
        DSFT1 = DSFT1P
        DSFN1 = DSFN1P
        for II in range(1, C.NLVEXP + 1):
            DSFP1[II] = DSFP1P[II]

        EMISIP = UN / C.EMIS1[ID + 1]
        ABSTP = UN / C.ABSO1[ID + 1]
        S0P = C.EMIS1[ID + 1] * ABSTP
        DSFN1P = S0P * (C.DEMN1[ID + 1] * EMISIP - C.DABN1[ID + 1] * ABSTP)
        DSFT1P = S0P * (C.DEMT1[ID + 1] * EMISIP - C.DABT1[ID + 1] * ABSTP)
        for II in range(1, C.NLVEXP + 1):
            DSFP1P[II] = S0P * (C.DEMP1[II, ID + 1] * EMISIP -
                                C.DABP1[II, ID + 1] * ABSTP)

        if C.IRDER == 1 or C.IRDER == 3:
            C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
            C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
        if C.IRDER > 1:
            for II in range(1, C.NLVEXP + 1):
                C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]
        # c
        # c       Hydrostatic equilibrium equation
        # c
        if LNSKIP:
            D0 = WW * C.FAK1[ID]
            A0 = WW * C.FAK1[ID - 1]
            C.FPRD[ID] = C.FPRD[ID] + D0 * C.RAD1[ID] - A0 * C.RAD1[ID - 1]
            E0 = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
            D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
            C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1
            C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1
            C.HEITM[ID] = C.HEITM[ID] + E0 * DSFT1M
            C.HEINM[ID] = C.HEINM[ID] + E0 * DSFN1M
            for II in range(1, C.NLVEXP + 1):
                C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II]
                C.HEIPM[II, ID] = C.HEIPM[II, ID] + E0 * DSFP1M[II]
        # C
        # C       Differential equation part of radiative equilibrium
        # C
        DDT = UN / (C.ABSOT[ID] + C.ABSOT[ID - 1])
        dt = DDT / C.DELDMZ[ID - 1]
        FL = (C.RAD1[ID] * C.FAK1[ID] - C.RAD1[ID - 1] * C.FAK1[ID - 1]) * dt
        C.FLFIX[ID] = C.FLFIX[ID] + WW * FL
        if C.REDIF[ID] > 0:
            D0 = WW * C.FAK1[ID] * dt
            A0 = WW * C.FAK1[ID - 1] * dt
            D0M = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
            D0P = D0 * C.ALIP1[ID]
            D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
            E0 = WW * FL * DDT
            C.REDX[ID] = C.REDX[ID] + E0 * C.ABSO1[ID]
            C.REDXM[ID] = C.REDXM[ID] + E0 * C.ABSO1[ID - 1]
            E0M = E0 * C.DENSI[ID - 1]
            E0 = E0 * C.DENSI[ID]
            C.REDT[ID] = C.REDT[ID] + D0 * DSFT1 - E0 * C.DABT1[ID]
            C.REDTM[ID] = C.REDTM[ID] + D0M * DSFT1M - E0M * C.DABT1[ID - 1]
            C.REDN[ID] = C.REDN[ID] + D0 * DSFN1 - E0 * C.DABN1[ID]
            C.REDNM[ID] = C.REDNM[ID] + D0M * DSFN1M - E0M * C.DABN1[ID - 1]
            for II in range(1, C.NLVEXP + 1):
                C.REDP[II, ID] = C.REDP[II, ID] + D0 * DSFP1[II] - \
                    E0 * C.DABP1[II, ID]
                C.REDPM[II, ID] = C.REDPM[II, ID] + D0M * DSFP1M[II] - \
                    E0M * C.DABP1[II, ID - 1]
        # c
        # C       Integral equation part of the radiative equilibrium
        # C
        if C.REINT[ID] > 0:
            SRH = SIGE * C.DENS1[ID]
            ABST = C.ABSO1[ID]
            ABSTE = ABST - C.ELSCAT[ID]
            WWK = WW * ABST
            C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] - ABSTE * C.RAD1[ID])
            D0 = WW * (ABSTE * C.ALI1[ID] - ABST)
            E0 = WW * (C.RAD1[ID] - S0)
            C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + E0 * C.DABN1[ID] - \
                WW * C.SIGEC[ij] * C.RAD1[ID]
            C.REIT[ID] = C.REIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
            for II in range(1, C.NLVEXP + 1):
                C.REIP[II, ID] = C.REIP[II, ID] + D0 * DSFP1[II] + \
                    E0 * C.DABP1[II, ID]

    # C
    # c ****3. deepest point - ID=ND
    # c
    ID = C.ND

    LNSKIP = not C.LSKIP[ID, ij]

    DSFTMM = DSFT1M
    DSFNMM = DSFN1M
    for II in range(1, C.NLVEXP + 1):
        DSFPMM[II] = DSFP1M[II]
    DSFT1M = DSFT1
    DSFN1M = DSFN1
    for II in range(1, C.NLVEXP + 1):
        DSFP1M[II] = DSFP1[II]
    S0 = S0P
    DSFT1 = DSFT1P
    DSFN1 = DSFN1P
    for II in range(1, C.NLVEXP + 1):
        DSFP1[II] = DSFP1P[II]
    # C
    # C     Improved lower boundary condition
    # C
    if C.IBC > 0 and C.IDISK == 0:
        dt = UN / (C.DELDMZ[ID - 1] * (C.ABSOT[ID] + C.ABSOT[ID - 1]))
        PLAD = C.XKFB[ID] / C.XKF1[ID]
        DBDT = PLAD / C.XKF1[ID] * C.HKT21[ID] * C.FREQ[ij] * dt
        if C.IBC == 1:
            DSFT1 = DSFT1 + DBDT
        elif C.IBC >= 2:
            PLAM = C.XKFB[ID - 1] / C.XKF1[ID - 1]
            TAU23 = T23 * dt
            TAU43 = T43 * dt
            D0 = (PLAD * (UN + TAU43) - T43 * PLAM * dt) * dt * dt
            RHD = C.DELDMZ[ID - 1] * C.DENSI[ID]
            E0 = D0 * RHD
            DSFT1 = DSFT1 + DBDT * (UN + TAU23) - E0 * C.DABT1[ID]
            DSFN1 = DSFN1 - E0 * (C.DABN1[ID] + C.ABSO1[ID] * C.DENSIM[ID])
            for II in range(1, C.NLVEXP + 1):
                DSFP1[II] = DSFP1[II] - E0 * C.DABP1[II, ID]
            if C.IBC >= 3:
                DBDTM = PLAM / C.XKF1[ID - 1] * C.HKT21[ID - 1] * C.FREQ[ij] * dt
                RHD = C.DELDMZ[ID - 1] * C.DENSI[ID - 1]
                E0 = D0 * RHD
                DSFT1D = -DBDTM * dt * T23 - E0 * C.DABT1[ID - 1]
                DSFN1D = -E0 * (C.DABN1[ID - 1] +
                                C.ABSO1[ID - 1] * C.DENSIM[ID - 1])
                for II in range(1, C.NLVEXP + 1):
                    DSFP1D[II] = -E0 * C.DABP1[II, ID - 1]
    # C
    if C.IRDER == 1 or C.IRDER == 3:
        C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
        C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
    if C.IRDER > 1:
        for II in range(1, C.NLVEXP + 1):
            C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]
    # c
    # c     Hydrostatic equilibrium equation
    # c
    if LNSKIP:
        D0 = WW * C.FAK1[ID]
        A0 = WW * C.FAK1[ID - 1]
        C.FPRD[ID] = C.FPRD[ID] + D0 * C.RAD1[ID] - A0 * C.RAD1[ID - 1]
        # c       F0=D0*ALIP1(ID)   （原代码已注释掉）
        E0 = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
        D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
        C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1
        C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1
        C.HEITM[ID] = C.HEITM[ID] + E0 * DSFT1M
        C.HEINM[ID] = C.HEINM[ID] + E0 * DSFN1M
        for II in range(1, C.NLVEXP + 1):
            C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II]
            C.HEIPM[II, ID] = C.HEIPM[II, ID] + E0 * DSFP1M[II]
        if C.IBC >= 3:
            C.HEITM[ID] = C.HEITM[ID] - D0 * DSFT1D
            C.HEINM[ID] = C.HEINM[ID] - D0 * DSFN1D
            for II in range(1, C.NLVEXP + 1):
                C.HEIPM[II, ID] = C.HEIPM[II, ID] - D0 * DSFP1D[II]
    # C
    # C     Differential equation part of radiative equilibrium
    # C
    DDT = UN / (C.ABSOT[ID] + C.ABSOT[ID - 1])
    dt = DDT / C.DELDMZ[ID - 1]
    FL = (C.RAD1[ID] * C.FAK1[ID] - C.RAD1[ID - 1] * C.FAK1[ID - 1]) * dt
    C.FLFIX[ID] = C.FLFIX[ID] + WW * FL
    if C.REDIF[ID] > 0:
        D0 = WW * C.FAK1[ID] * dt
        A0 = WW * C.FAK1[ID - 1] * dt
        D0M = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
        D0P = D0 * C.ALIP1[ID]
        D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
        E0 = WW * FL * DDT
        C.REDX[ID] = C.REDX[ID] + E0 * C.ABSO1[ID]
        C.REDXM[ID] = C.REDXM[ID] + E0 * C.ABSO1[ID - 1]
        E0M = E0 * C.DENSI[ID - 1]
        E0 = E0 * C.DENSI[ID]
        C.REDT[ID] = C.REDT[ID] + D0 * DSFT1 - E0 * C.DABT1[ID]
        C.REDTM[ID] = C.REDTM[ID] + D0M * DSFT1M - E0M * C.DABT1[ID - 1]
        C.REDN[ID] = C.REDN[ID] + D0 * DSFN1 - E0 * C.DABN1[ID]
        C.REDNM[ID] = C.REDNM[ID] + D0M * DSFN1M - E0M * C.DABN1[ID - 1]
        for II in range(1, C.NLVEXP + 1):
            C.REDP[II, ID] = C.REDP[II, ID] + D0 * DSFP1[II] - \
                E0 * C.DABP1[II, ID]
            C.REDPM[II, ID] = C.REDPM[II, ID] + D0M * DSFP1M[II] - \
                E0M * C.DABP1[II, ID - 1]
        if C.IBC >= 3:
            C.REDTM[ID] = C.REDTM[ID] + D0 * DSFT1D
            C.REDNM[ID] = C.REDNM[ID] + D0 * DSFN1D
            for II in range(1, C.NLVEXP + 1):
                C.REDPM[II, ID] = C.REDPM[II, ID] + D0 * DSFP1D[II]
    # c
    # C     Integral equation part of the radiative equilibrium
    # C
    if C.REINT[ID] > 0:
        SRH = SIGE * C.DENS1[ID]
        ABST = C.ABSO1[ID]
        ABSTE = ABST - C.ELSCAT[ID]
        WWK = WW * ABST
        C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] - ABSTE * C.RAD1[ID])
        D0 = WW * (ABSTE * C.ALI1[ID] - ABST)
        E0 = WW * (C.RAD1[ID] - S0)
        C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + E0 * C.DABN1[ID] - \
            WW * C.SIGEC[ij] * C.RAD1[ID]
        if C.IBC == 0:
            C.REIT[ID] = C.REIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
        else:
            # TODO(port): DBDT 仅在 IF(IBC.GT.0.AND.IDISK.EQ.0) 块内赋值；
            # 未赋值时 Fortran 取残留值，Python 同一次调用内亦保留旧值，
            # 但首次使用前未赋值将抛 NameError（见 ALIFR1 主分支同名注释）。
            C.REIT[ID] = C.REIT[ID] + D0 * (DSFT1 - DBDT) + E0 * C.DABT1[ID] + \
                C.ALI1[ID] / ABST * DBDT
        for II in range(1, C.NLVEXP + 1):
            C.REIP[II, ID] = C.REIP[II, ID] + D0 * DSFP1[II] + \
                E0 * C.DABP1[II, ID]

    return


def alifr3(ij):
    """
    hydrostatic and radiative equilibrium quantities -
    derivatives of the total heating and cooling rates in the
    ALI points with respect to the
    temperature, electron density, and populations
    a variant for consistent tridiagonal operator

    对应 tlusty208.f 行 20254–21380
    """
    # PARAMETER (T23=TWO/3.D0, T43=4.D0/3.D0)
    T23 = TWO / 3.0
    T43 = 4.0 / 3.0
    # DIMENSION DSFP1(MLVEXP),DSFP1M(MLVEXP),DSFP1D(MLVEXP),
    #           DSFP1P(MLVEXP),DSFPMM(MLVEXP)
    # 局部数组，保持 Fortran 1 基索引（每维 +1）
    DSFP1 = np.zeros(MLVEXP + 1)
    DSFP1M = np.zeros(MLVEXP + 1)
    DSFP1D = np.zeros(MLVEXP + 1)
    DSFP1P = np.zeros(MLVEXP + 1)
    DSFPMM = np.zeros(MLVEXP + 1)

    if C.IFALI <= 1:
        return
    WW = C.WC[ij]

    DSFT1M = 0.
    DSFN1M = 0.
    DSFT1D = 0.
    DSFN1D = 0.
    for II in range(1, C.NLVEXP + 1):
        DSFP1M[II] = 0.
        DSFP1D[II] = 0.

    # c     Non-standard value of ILASCT & ILMCOR
    #
    # 原代码控制流（与 ALIFR1 相同的三段结构）：
    #   IF(ILMCOR.NE.3) GO TO 199
    #   199 IF(ILASCT.NE.0) GO TO 299
    # 重构为 if/return，保持源码段落顺序。
    if C.ILMCOR == 3:
        # c
        # c ****1. Special expressions for the first depth  -  id=1
        # c
        ID = 1
        LNSKIP = not C.LSKIP[ID, ij]
        # c
        # c     Basic auxliliary quantities - derivatives of the source function
        # c
        EMISIV = UN / C.EMIS1[ID]
        ABST = UN / C.ABSO1[ID]
        S0 = C.EMIS1[ID] * ABST
        SC = C.ELEC[ID] * C.SIGEC[ij]
        SCT = SC * ABST
        ST = S0 + SCT * C.RAD1[ID]
        CORR = UN / (UN - C.ALI1[ID] * SCT)
        DSFT1 = CORR * (S0 * C.DEMT1[ID] * EMISIV - ST * C.DABT1[ID] * ABST)
        DSFN1 = CORR * (S0 * C.DEMN1[ID] * EMISIV +
                        C.SIGEC[ij] * C.RAD1[ID] * ABST -
                        ST * C.DABN1[ID] * ABST)
        for II in range(1, C.NLVEXP + 1):
            DSFP1[II] = CORR * (S0 * C.DEMP1[II, ID] * EMISIV -
                                ST * C.DABP1[II, ID] * ABST)
        EMISIP = UN / C.EMIS1[ID + 1]
        ABSTP = UN / C.ABSO1[ID + 1]
        S0P = C.EMIS1[ID + 1] * ABSTP
        # 原代码此处为 SCP=ELEC(ID+1)*SIGE（常数 SIGE，非 SIGEC(IJ)），直译保留
        SCP = C.ELEC[ID + 1] * SIGE
        SCTP = SCP * ABSTP
        STP = S0P + SCTP * C.RAD1[ID + 1]
        CORRP = UN / (UN - C.ALI1[ID + 1] * SCTP)
        DSFT1P = CORRP * (S0P * C.DEMT1[ID + 1] * EMISIP -
                          STP * C.DABT1[ID + 1] * ABSTP)
        DSFN1P = CORRP * (S0P * C.DEMN1[ID + 1] * EMISIP +
                          C.SIGEC[ij] * C.RAD1[ID + 1] * ABSTP -
                          STP * C.DABN1[ID + 1] * ABSTP)
        for II in range(1, C.NLVEXP + 1):
            DSFP1P[II] = CORRP * (S0P * C.DEMP1[II, ID + 1] * EMISIP -
                                  STP * C.DABP1[II, ID + 1] * ABSTP)
        # C
        # C
        # C     additional quantites in case of external irradiation
        # C
        extd = C.EXTRAD[ij]
        if extd > 0:
            DT = UN / (C.DELDMZ[ID] * (C.ABSOT[ID] + C.ABSOT[ID + 1]))
            D0 = TWO * C.HEXTRD[ij] * DT * DT
            E0 = D0 * C.DELDMZ[ID] * C.DENSI[ID]
            E1 = D0 * C.DELDMZ[ID + 1] * C.DENSI[ID + 1]
            DSFT1 = DSFT1 - E0 * C.DABT1[ID]
            DSFN1 = DSFN1 - E0 * (C.DABN1[ID] + C.ABSO1[ID] * C.DENSIM[ID])
            DSFX1 = E0 * C.ABSO1[ID] * C.DENSIM[ID]
            DSFT1D = DSFT1D - E1 * C.DABT1[ID + 1]
            DSFN1D = DSFN1D - E1 * (C.DABN1[ID + 1] +
                                    C.ABSO1[ID + 1] * C.DENSIM[ID + 1])
            DSFX1D = E1 * C.ABSO1[ID + 1] * C.DENSIM[ID + 1]
            for II in range(1, C.NLVEXP + 1):
                DSFP1[II] = DSFP1[II] - E0 * C.DABP1[II, ID]
                DSFP1D[II] = DSFP1D[II] - E0 * C.DABP1[II, ID + 1]
        # c
        if C.IRDER == 1 or C.IRDER == 3:
            C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
            C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
            C.DSFDTM[ID] = DSFT1M * C.ALIM1[ID]
            C.DSFDNM[ID] = DSFN1M * C.ALIM1[ID]
            C.DSFDTP[ID] = DSFT1P * C.ALIP1[ID]
            C.DSFDNP[ID] = DSFN1P * C.ALIP1[ID]
        if C.IRDER > 1:
            for II in range(1, C.NLVEXP + 1):
                C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]
                C.DSFDPM[II, ID] = DSFP1M[II] * C.ALIM1[ID]
                C.DSFDPP[II, ID] = DSFP1P[II] * C.ALIP1[ID]
        # c
        # c     Hydrostatic equilibrium quantities
        # c
        WF = WW * C.FH[ij]
        if LNSKIP:
            C.FPRD[ID] = C.FPRD[ID] + WF * C.ABSO1[ID] * C.RAD1[ID] - \
                WW * C.HEXTRD[ij] * C.ABSO1[ID]
            E0 = WF * C.RAD1[ID]
            D0 = WF * C.ABSO1[ID] * C.ALI1[ID]
            C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
            C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1 + E0 * C.DABN1[ID]
            for II in range(1, C.NLVEXP + 1):
                C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II] + \
                    E0 * C.DABP1[II, ID]
        # c
        # c     Differential equation part of radiative equilibrium
        # c
        C.FLFIX[ID] = C.FLFIX[ID] + WF * C.RAD1[ID] - WW * C.HEXTRD[ij]
        if C.REDIF[ID] > 0.:
            WF = WF * C.ALI1[ID]
            C.REDT[ID] = C.REDT[ID] + WF * DSFT1
            C.REDN[ID] = C.REDN[ID] + WF * DSFN1
            for II in range(1, C.NLVEXP + 1):
                C.REDP[II, ID] = C.REDP[II, ID] + WF * DSFP1[II]
            C.REDTP[ID] = C.REDTP[ID] + WF * DSFT1D
            C.REDNP[ID] = C.REDNP[ID] + WF * DSFN1D
        # c
        # C     Integral equation part of the radiative equilibrium
        # C
        if C.REINT[ID] > 0:
            ABST = C.ABSO1[ID] - C.ELSCAT[ID]
            D0 = ABST * C.ALI1[ID]
            WWKC = WW * ABST * C.ALIP1[ID]
            C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] - ABST * C.RAD1[ID])
            C.REIN[ID] = C.REIN[ID] + WW * (D0 * DSFN1 +
                                            C.RAD1[ID] * (C.DABN1[ID] - C.SIGEC[ij]) -
                                            C.DEMN1[ID])
            C.CREIT[ID] = C.CREIT[ID] + WWKC * DSFT1P
            C.CREIN[ID] = C.CREIN[ID] + WWKC * DSFN1P
            for II in range(1, C.NLVEXP + 1):
                C.REIP[II, ID] = C.REIP[II, ID] + WW * (D0 * DSFP1[II] +
                                                       C.RAD1[ID] * C.DABP1[II, ID] -
                                                       C.DEMP1[II, ID])
                C.CREIP[II, ID] = C.CREIP[II, ID] + WWKC * DSFP1P[II]
            C.REIT[ID] = C.REIT[ID] + WW * (D0 * DSFT1 +
                                            C.RAD1[ID] * C.DABT1[ID] - C.DEMT1[ID])
            if extd > 0.:
                C.CREIT[ID] = C.CREIT[ID] + WW * D0 * DSFT1D
                C.CREIN[ID] = C.CREIN[ID] + WW * D0 * DSFN1D

        # C
        # c ****2. loop over depths
        # c
        for ID in range(2, C.ND - 1 + 1):

            LNSKIP = not C.LSKIP[ID, ij]

            DSFTMM = DSFT1M
            DSFNMM = DSFN1M
            for II in range(1, C.NLVEXP + 1):
                DSFPMM[II] = DSFP1M[II]
            DSFT1M = DSFT1
            DSFN1M = DSFN1
            for II in range(1, C.NLVEXP + 1):
                DSFP1M[II] = DSFP1[II]
            S0 = S0P
            DSFT1 = DSFT1P
            DSFN1 = DSFN1P
            for II in range(1, C.NLVEXP + 1):
                DSFP1[II] = DSFP1P[II]

            EMISIP = UN / C.EMIS1[ID + 1]
            ABSTP = UN / C.ABSO1[ID + 1]
            S0P = C.EMIS1[ID + 1] * ABSTP
            SCP = C.ELEC[ID + 1] * C.SIGEC[ij]
            SCTP = SCP * ABSTP
            STP = S0P + SCTP * C.RAD1[ID + 1]
            CORRP = UN / (UN - C.ALI1[ID + 1] * SCTP)
            DSFT1P = CORRP * (S0P * C.DEMT1[ID + 1] * EMISIP -
                              STP * C.DABT1[ID + 1] * ABSTP)
            DSFN1P = CORRP * (S0P * C.DEMN1[ID + 1] * EMISIP +
                              C.SIGEC[ij] * C.RAD1[ID + 1] * ABSTP -
                              STP * C.DABN1[ID + 1] * ABSTP)
            for II in range(1, C.NLVEXP + 1):
                DSFP1P[II] = CORRP * (S0P * C.DEMP1[II, ID + 1] * EMISIP -
                                      STP * C.DABP1[II, ID + 1] * ABSTP)

            if C.IRDER == 1 or C.IRDER == 3:
                C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
                C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
            if C.IRDER > 1:
                for II in range(1, C.NLVEXP + 1):
                    C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]
            # c
            # c       Hydrostatic equilibrium equation
            # c
            if LNSKIP:
                D0 = WW * C.FAK1[ID]
                A0 = WW * C.FAK1[ID - 1]
                C.FPRD[ID] = C.FPRD[ID] + D0 * C.RAD1[ID] - A0 * C.RAD1[ID - 1]
                E0 = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
                D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
                C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1
                C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1
                C.HEITM[ID] = C.HEITM[ID] + E0 * DSFT1M
                C.HEINM[ID] = C.HEINM[ID] + E0 * DSFN1M
                for II in range(1, C.NLVEXP + 1):
                    C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II]
                    C.HEIPM[II, ID] = C.HEIPM[II, ID] + E0 * DSFP1M[II]
            # C
            # C       Differential equation part of radiative equilibrium
            # C
            DDT = UN / (C.ABSOT[ID] + C.ABSOT[ID - 1])
            DT = DDT / C.DELDMZ[ID - 1]
            FL = (C.RAD1[ID] * C.FAK1[ID] - C.RAD1[ID - 1] * C.FAK1[ID - 1]) * DT
            C.FLFIX[ID] = C.FLFIX[ID] + WW * FL
            if C.REDIF[ID] > 0:
                if C.IFALIH == 0:
                    D0 = WW * C.FAK1[ID] * DT
                    A0 = WW * C.FAK1[ID - 1] * DT
                    D0M = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
                    D0P = D0 * C.ALIP1[ID]
                    D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
                    E0 = WW * FL * DDT
                    C.REDX[ID] = C.REDX[ID] + E0 * C.ABSO1[ID]
                    C.REDXM[ID] = C.REDXM[ID] + E0 * C.ABSO1[ID - 1]
                    E0M = E0 * C.DENSI[ID - 1]
                    E0 = E0 * C.DENSI[ID]
                    C.REDT[ID] = C.REDT[ID] + D0 * DSFT1 - E0 * C.DABT1[ID]
                    C.REDTM[ID] = C.REDTM[ID] + D0M * DSFT1M - E0M * C.DABT1[ID - 1]
                    C.REDN[ID] = C.REDN[ID] + D0 * DSFN1 - E0 * C.DABN1[ID]
                    C.REDNM[ID] = C.REDNM[ID] + D0M * DSFN1M - E0M * C.DABN1[ID - 1]
                    for II in range(1, C.NLVEXP + 1):
                        C.REDP[II, ID] = C.REDP[II, ID] + D0 * DSFP1[II] - \
                            E0 * C.DABP1[II, ID]
                        C.REDPM[II, ID] = C.REDPM[II, ID] + D0M * DSFP1M[II] - \
                            E0M * C.DABP1[II, ID - 1]
                else:
                    # 原：d0=ww*alih1(id)；alih1 在 commons.py 中规范拼写为小写
                    D0 = WW * C.alih1[ID]
                    C.REDT[ID] = C.REDT[ID] + D0 * DSFT1
                    C.REDN[ID] = C.REDN[ID] + D0 * DSFN1
                    for II in range(1, C.NLVEXP + 1):
                        C.REDP[II, ID] = C.REDP[II, ID] + D0 * DSFP1[II]
            # c
            # C       Integral equation part of the radiative equilibrium
            # C
            if C.REINT[ID] > 0:
                # 注意原代码顺序：先用（旧的）ABST 计算 WWK/WWKA/WWKC，
                # 然后才重新赋值 ABST
                WWK = WW * ABST
                WWKA = WWK * C.ALIM1[ID]
                WWKC = WWK * C.ALIP1[ID]
                ABST = C.ABSO1[ID] - C.ELSCAT[ID]
                D0 = ABST * C.ALI1[ID]
                C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] -
                                                    ABST * C.RAD1[ID])
                C.REIN[ID] = C.REIN[ID] + WW * (D0 * DSFN1 +
                                                C.RAD1[ID] * (C.DABN1[ID] - C.SIGEC[ij]) -
                                                C.DEMN1[ID])
                for II in range(1, C.NLVEXP + 1):
                    C.REIP[II, ID] = C.REIP[II, ID] + WW * (D0 * DSFP1[II] +
                                                           C.RAD1[ID] * C.DABP1[II, ID] -
                                                           C.DEMP1[II, ID])
                    C.AREIP[II, ID] = C.AREIP[II, ID] + WWKA * DSFP1M[II]
                    C.CREIP[II, ID] = C.CREIP[II, ID] + WWKC * DSFP1P[II]
                C.REIT[ID] = C.REIT[ID] + WW * (D0 * DSFT1 +
                                                C.RAD1[ID] * C.DABT1[ID] - C.DEMT1[ID])
                C.AREIT[ID] = C.AREIT[ID] + WWKA * DSFT1M
                C.AREIN[ID] = C.AREIN[ID] + WWKA * DSFN1M
                C.CREIT[ID] = C.CREIT[ID] + WWKC * DSFT1P
                C.CREIN[ID] = C.CREIN[ID] + WWKC * DSFN1P

        # C
        # c ****3. deepest point - ID=ND
        # c
        ID = C.ND

        LNSKIP = not C.LSKIP[ID, ij]

        DSFTMM = DSFT1M
        DSFNMM = DSFN1M
        for II in range(1, C.NLVEXP + 1):
            DSFPMM[II] = DSFP1M[II]
        DSFT1M = DSFT1
        DSFN1M = DSFN1
        for II in range(1, C.NLVEXP + 1):
            DSFP1M[II] = DSFP1[II]
        S0 = S0P
        DSFT1 = DSFT1P
        DSFN1 = DSFN1P
        for II in range(1, C.NLVEXP + 1):
            DSFP1[II] = DSFP1P[II]
        # C
        # C     Improved lower boundary condition
        # C
        if C.IBC > 0 and C.IDISK == 0:
            DT = UN / (C.DELDMZ[ID - 1] * (C.ABSOT[ID] + C.ABSOT[ID - 1]))
            PLAD = C.XKFB[ID] / C.XKF1[ID]
            DBDT = PLAD / C.XKF1[ID] * C.HKT21[ID] * C.FREQ[ij] * DT
            if C.IBC == 1:
                DSFT1 = DSFT1 + DBDT
            elif C.IBC >= 2:
                PLAM = C.XKFB[ID - 1] / C.XKF1[ID - 1]
                TAU23 = T23 * DT
                TAU43 = T43 * DT
                D0 = (PLAD * (UN + TAU43) - T43 * PLAM * DT) * DT * DT
                RHD = C.DELDMZ[ID - 1] * C.DENSI[ID]
                E0 = D0 * RHD
                DSFT1 = DSFT1 + DBDT * (UN + TAU23) - E0 * C.DABT1[ID]
                DSFN1 = DSFN1 - E0 * (C.DABN1[ID] + C.ABSO1[ID] * C.DENSIM[ID])
                for II in range(1, C.NLVEXP + 1):
                    DSFP1[II] = DSFP1[II] - E0 * C.DABP1[II, ID]
                if C.IBC >= 3:
                    DBDTM = PLAM / C.XKF1[ID - 1] * C.HKT21[ID - 1] * C.FREQ[ij] * DT
                    RHD = C.DELDMZ[ID - 1] * C.DENSI[ID - 1]
                    E0 = D0 * RHD
                    DSFT1D = -DBDTM * DT * T23 - E0 * C.DABT1[ID - 1]
                    DSFN1D = -E0 * (C.DABN1[ID - 1] +
                                    C.ABSO1[ID - 1] * C.DENSIM[ID - 1])
                    for II in range(1, C.NLVEXP + 1):
                        DSFP1D[II] = -E0 * C.DABP1[II, ID - 1]
        # C
        if C.IRDER == 1 or C.IRDER == 3:
            C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
            C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
            C.DSFDTM[ID] = DSFT1M * C.ALIM1[ID]
            C.DSFDNM[ID] = DSFN1M * C.ALIM1[ID]
            C.DSFDTP[ID] = DSFT1P * C.ALIP1[ID]
            C.DSFDNP[ID] = DSFN1P * C.ALIP1[ID]
        if C.IRDER > 1:
            for II in range(1, C.NLVEXP + 1):
                C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]
                C.DSFDPM[II, ID] = DSFP1M[II] * C.ALIM1[ID]
                C.DSFDPP[II, ID] = DSFP1P[II] * C.ALIP1[ID]
        # c
        # c     Hydrostatic equilibrium equation
        # c
        if LNSKIP:
            D0 = WW * C.FAK1[ID]
            A0 = WW * C.FAK1[ID - 1]
            C.FPRD[ID] = C.FPRD[ID] + D0 * C.RAD1[ID] - A0 * C.RAD1[ID - 1]
            E0 = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
            D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
            C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1
            C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1
            C.HEITM[ID] = C.HEITM[ID] + E0 * DSFT1M
            C.HEINM[ID] = C.HEINM[ID] + E0 * DSFN1M
            for II in range(1, C.NLVEXP + 1):
                C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II]
                C.HEIPM[II, ID] = C.HEIPM[II, ID] + E0 * DSFP1M[II]
            if C.IBC >= 3:
                C.HEITM[ID] = C.HEITM[ID] - D0 * DSFT1D
                C.HEINM[ID] = C.HEINM[ID] - D0 * DSFN1D
                for II in range(1, C.NLVEXP + 1):
                    C.HEIPM[II, ID] = C.HEIPM[II, ID] - D0 * DSFP1D[II]
        # C
        # C     Differential equation part of radiative equilibrium
        # C
        DDT = UN / (C.ABSOT[ID] + C.ABSOT[ID - 1])
        DT = DDT / C.DELDMZ[ID - 1]
        FL = (C.RAD1[ID] * C.FAK1[ID] - C.RAD1[ID - 1] * C.FAK1[ID - 1]) * DT
        C.FLFIX[ID] = C.FLFIX[ID] + WW * FL
        if C.REDIF[ID] > 0:
            D0 = WW * C.FAK1[ID] * DT
            A0 = WW * C.FAK1[ID - 1] * DT
            D0M = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
            D0P = D0 * C.ALIP1[ID]
            D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
            E0 = WW * FL * DDT
            C.REDX[ID] = C.REDX[ID] + E0 * C.ABSO1[ID]
            C.REDXM[ID] = C.REDXM[ID] + E0 * C.ABSO1[ID - 1]
            E0M = E0 * C.DENSI[ID - 1]
            E0 = E0 * C.DENSI[ID]
            C.REDT[ID] = C.REDT[ID] + D0 * DSFT1 - E0 * C.DABT1[ID]
            C.REDTM[ID] = C.REDTM[ID] + D0M * DSFT1M - E0M * C.DABT1[ID - 1]
            C.REDN[ID] = C.REDN[ID] + D0 * DSFN1 - E0 * C.DABN1[ID]
            C.REDNM[ID] = C.REDNM[ID] + D0M * DSFN1M - E0M * C.DABN1[ID - 1]
            for II in range(1, C.NLVEXP + 1):
                C.REDP[II, ID] = C.REDP[II, ID] + D0 * DSFP1[II] - \
                    E0 * C.DABP1[II, ID]
                C.REDPM[II, ID] = C.REDPM[II, ID] + D0M * DSFP1M[II] - \
                    E0M * C.DABP1[II, ID - 1]
            if C.IBC >= 3:
                C.REDTM[ID] = C.REDTM[ID] + D0 * DSFT1D
                C.REDNM[ID] = C.REDNM[ID] + D0 * DSFN1D
                for II in range(1, C.NLVEXP + 1):
                    C.REDPM[II, ID] = C.REDPM[II, ID] + D0 * DSFP1D[II]
        # c
        # C     Integral equation part of the radiative equilibrium
        # C
        if C.REINT[ID] > 0:
            ABST = C.ABSO1[ID] - C.ELSCAT[ID]
            WWKA = WW * ABST * C.ALIM1[ID]
            D0 = ABST * C.ALI1[ID]
            C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] - ABST * C.RAD1[ID])
            C.REIN[ID] = C.REIN[ID] + WW * (D0 * DSFN1 +
                                            C.RAD1[ID] * (C.DABN1[ID] - C.SIGEC[ij]) -
                                            C.DEMN1[ID])
            for II in range(1, C.NLVEXP + 1):
                C.REIP[II, ID] = C.REIP[II, ID] + WW * (D0 * DSFP1[II] +
                                                       C.RAD1[ID] * C.DABP1[II, ID] -
                                                       C.DEMP1[II, ID])
                C.AREIP[II, ID] = C.AREIP[II, ID] + WWKA * DSFP1M[II]
            if C.IBC == 0:
                C.REIT[ID] = C.REIT[ID] + WW * (D0 * DSFT1 +
                                                C.RAD1[ID] * C.DABT1[ID] - C.DEMT1[ID])
            else:
                # TODO(port): 此分支引用 DBDT/E0；DBDT 仅在上面
                # IF(IBC.GT.0.AND.IDISK.EQ.0) 块内赋值。Fortran 未赋值时取残留值；
                # Python 同一次调用内同样保留旧值，但首次使用前未赋值将抛
                # NameError（与 Fortran "未定义值" 行为不完全等价）。
                C.REIT[ID] = C.REIT[ID] + WW * (D0 * (DSFT1 - DBDT) +
                                                E0 * C.DABT1[ID] +
                                                C.RAD1[ID] * C.DABT1[ID] - C.DEMT1[ID] +
                                                C.ALI1[ID] / ABST * DBDT)
            C.AREIT[ID] = C.AREIT[ID] + WWKA * DSFT1M
            C.AREIN[ID] = C.AREIN[ID] + WWKA * DSFN1M
        return

    # c     Non-standard value of ILASCT & ILMCOR
    #
    # 199 IF(ILASCT.NE.0) GO TO 299
    if C.ILASCT != 0:
        # GO TO 299 —— 见下方标号 299 段
        pass
    else:
        # c
        # c ****1. Special expressions for the first depth  -  id=1
        # c
        ID = 1

        LNSKIP = not C.LSKIP[ID, ij]
        # c
        # c     Basic auxliliary quantities - derivatives of the source function
        # c
        EMISIV = UN / C.EMIS1[ID]
        ABST = UN / (C.ABSO1[ID] - C.ELSCAT[ID])
        S0 = C.EMIS1[ID] * ABST
        DSFN1 = S0 * (C.DEMN1[ID] * EMISIV - (C.DABN1[ID] - C.SIGEC[ij]) * ABST)
        DSFT1 = S0 * (C.DEMT1[ID] * EMISIV - C.DABT1[ID] * ABST)
        for II in range(1, C.NLVEXP + 1):
            DSFP1[II] = S0 * (C.DEMP1[II, ID] * EMISIV - C.DABP1[II, ID] * ABST)
        EMISIP = UN / C.EMIS1[ID + 1]
        ABSTP = UN / (C.ABSO1[ID + 1] - C.ELSCAT[ID + 1])
        S0P = C.EMIS1[ID + 1] * ABSTP
        DSFN1P = S0P * (C.DEMN1[ID + 1] * EMISIP -
                        (C.DABN1[ID + 1] - C.SIGEC[ij]) * ABSTP)
        DSFT1P = S0P * (C.DEMT1[ID + 1] * EMISIP - C.DABT1[ID + 1] * ABSTP)
        for II in range(1, C.NLVEXP + 1):
            DSFP1P[II] = S0P * (C.DEMP1[II, ID + 1] * EMISIP -
                                C.DABP1[II, ID + 1] * ABSTP)

        if C.IRDER == 1 or C.IRDER == 3:
            C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
            C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
        if C.IRDER > 1:
            for II in range(1, C.NLVEXP + 1):
                C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]
        # c
        # c     Hydrostatic equilibrium quantities
        # c
        WF = WW * C.FH[ij]
        if LNSKIP:
            C.FPRD[ID] = C.FPRD[ID] + WF * C.ABSO1[ID] * C.RAD1[ID] - \
                WW * C.HEXTRD[ij] * C.ABSO1[ID]
            E0 = WF * C.RAD1[ID]
            D0 = WF * C.ABSO1[ID] * C.ALI1[ID]
            C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
            C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1 + E0 * C.DABN1[ID]
            for II in range(1, C.NLVEXP + 1):
                C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II] + \
                    E0 * C.DABP1[II, ID]
        # c
        # c     Differential equation part of radiative equilibrium
        # c
        C.FLFIX[ID] = C.FLFIX[ID] + WF * C.RAD1[ID] - WW * C.HEXTRD[ij]
        if C.REDIF[ID] > 0.:
            WF = WF * C.ALI1[ID]
            C.REDT[ID] = C.REDT[ID] + WF * DSFT1
            C.REDN[ID] = C.REDN[ID] + WF * DSFN1
            for II in range(1, C.NLVEXP + 1):
                C.REDP[II, ID] = C.REDP[II, ID] + WF * DSFP1[II]
        # c
        # C     Integral equation part of the radiative equilibrium
        # C
        if C.REINT[ID] > 0:
            ABST = C.ABSO1[ID] - C.ELSCAT[ID]
            WWK = WW * ABST
            C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] - ABST * C.RAD1[ID])
            D0 = WW * (C.ALI1[ID] - UN) * ABST
            E0 = WW * (C.RAD1[ID] - S0)
            C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + E0 * (C.DABN1[ID] - C.SIGEC[ij])
            C.REIT[ID] = C.REIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
            for II in range(1, C.NLVEXP + 1):
                C.REIP[II, ID] = C.REIP[II, ID] + D0 * DSFP1[II] + \
                    E0 * C.DABP1[II, ID]

        # C
        # c ****2. loop over depths
        # c
        for ID in range(2, C.ND - 1 + 1):

            LNSKIP = not C.LSKIP[ID, ij]

            DSFTMM = DSFT1M
            DSFNMM = DSFN1M
            for II in range(1, C.NLVEXP + 1):
                DSFPMM[II] = DSFP1M[II]
            DSFT1M = DSFT1
            DSFN1M = DSFN1
            for II in range(1, C.NLVEXP + 1):
                DSFP1M[II] = DSFP1[II]
            S0 = S0P
            DSFT1 = DSFT1P
            DSFN1 = DSFN1P
            for II in range(1, C.NLVEXP + 1):
                DSFP1[II] = DSFP1P[II]

            EMISIP = UN / C.EMIS1[ID + 1]
            ABSTP = UN / (C.ABSO1[ID + 1] - C.ELSCAT[ID + 1])
            S0P = C.EMIS1[ID + 1] * ABSTP
            DSFN1P = S0P * (C.DEMN1[ID + 1] * EMISIP -
                            (C.DABN1[ID + 1] - C.SIGEC[ij]) * ABSTP)
            DSFT1P = S0P * (C.DEMT1[ID + 1] * EMISIP - C.DABT1[ID + 1] * ABSTP)
            for II in range(1, C.NLVEXP + 1):
                DSFP1P[II] = S0P * (C.DEMP1[II, ID + 1] * EMISIP -
                                    C.DABP1[II, ID + 1] * ABSTP)

            if C.IRDER == 1 or C.IRDER == 3:
                C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
                C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
            if C.IRDER > 1:
                for II in range(1, C.NLVEXP + 1):
                    C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]
            # c
            # c       Hydrostatic equilibrium equation
            # c
            if LNSKIP:
                D0 = WW * C.FAK1[ID]
                A0 = WW * C.FAK1[ID - 1]
                C.FPRD[ID] = C.FPRD[ID] + D0 * C.RAD1[ID] - A0 * C.RAD1[ID - 1]
                E0 = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
                D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
                C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1
                C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1
                C.HEITM[ID] = C.HEITM[ID] + E0 * DSFT1M
                C.HEINM[ID] = C.HEINM[ID] + E0 * DSFN1M
                for II in range(1, C.NLVEXP + 1):
                    C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II]
                    C.HEIPM[II, ID] = C.HEIPM[II, ID] + E0 * DSFP1M[II]
            # C
            # C       Differential equation part of radiative equilibrium
            # C
            DDT = UN / (C.ABSOT[ID] + C.ABSOT[ID - 1])
            DT = DDT / C.DELDMZ[ID - 1]
            FL = (C.RAD1[ID] * C.FAK1[ID] - C.RAD1[ID - 1] * C.FAK1[ID - 1]) * DT
            C.FLFIX[ID] = C.FLFIX[ID] + WW * FL
            if C.REDIF[ID] > 0:
                D0 = WW * C.FAK1[ID] * DT
                A0 = WW * C.FAK1[ID - 1] * DT
                D0M = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
                D0P = D0 * C.ALIP1[ID]
                D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
                E0 = WW * FL * DDT
                C.REDX[ID] = C.REDX[ID] + E0 * C.ABSO1[ID]
                C.REDXM[ID] = C.REDXM[ID] + E0 * C.ABSO1[ID - 1]
                E0M = E0 * C.DENSI[ID - 1]
                E0 = E0 * C.DENSI[ID]
                C.REDT[ID] = C.REDT[ID] + D0 * DSFT1 - E0 * C.DABT1[ID]
                C.REDTM[ID] = C.REDTM[ID] + D0M * DSFT1M - E0M * C.DABT1[ID - 1]
                C.REDN[ID] = C.REDN[ID] + D0 * DSFN1 - E0 * C.DABN1[ID]
                C.REDNM[ID] = C.REDNM[ID] + D0M * DSFN1M - E0M * C.DABN1[ID - 1]
                for II in range(1, C.NLVEXP + 1):
                    C.REDP[II, ID] = C.REDP[II, ID] + D0 * DSFP1[II] - \
                        E0 * C.DABP1[II, ID]
                    C.REDPM[II, ID] = C.REDPM[II, ID] + D0M * DSFP1M[II] - \
                        E0M * C.DABP1[II, ID - 1]
            # c
            # C       Integral equation part of the radiative equilibrium
            # C
            if C.REINT[ID] > 0:
                ABST = C.ABSO1[ID] - C.ELSCAT[ID]
                WWK = WW * ABST
                C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] -
                                                    ABST * C.RAD1[ID])
                D0 = WW * (C.ALI1[ID] - UN) * ABST
                E0 = WW * (C.RAD1[ID] - S0)
                C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + \
                    E0 * (C.DABN1[ID] - C.SIGEC[ij])
                C.REIT[ID] = C.REIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
                for II in range(1, C.NLVEXP + 1):
                    C.REIP[II, ID] = C.REIP[II, ID] + D0 * DSFP1[II] + \
                        E0 * C.DABP1[II, ID]

        # C
        # c ****3. deepest point - ID=ND
        # c
        ID = C.ND

        LNSKIP = not C.LSKIP[ID, ij]

        DSFTMM = DSFT1M
        DSFNMM = DSFN1M
        for II in range(1, C.NLVEXP + 1):
            DSFPMM[II] = DSFP1M[II]
        DSFT1M = DSFT1
        DSFN1M = DSFN1
        for II in range(1, C.NLVEXP + 1):
            DSFP1M[II] = DSFP1[II]
        S0 = S0P
        DSFT1 = DSFT1P
        DSFN1 = DSFN1P
        for II in range(1, C.NLVEXP + 1):
            DSFP1[II] = DSFP1P[II]
        # C
        # C     Improved lower boundary condition
        # C
        if C.IBC > 0 and C.IDISK == 0:
            DT = UN / (C.DELDMZ[ID - 1] * (C.ABSOT[ID] + C.ABSOT[ID - 1]))
            PLAD = C.XKFB[ID] / C.XKF1[ID]
            DBDT = PLAD / C.XKF1[ID] * C.HKT21[ID] * C.FREQ[ij] * DT
            if C.IBC == 1:
                DSFT1 = DSFT1 + DBDT
            elif C.IBC >= 2:
                PLAM = C.XKFB[ID - 1] / C.XKF1[ID - 1]
                TAU23 = T23 * DT
                TAU43 = T43 * DT
                D0 = (PLAD * (UN + TAU43) - T43 * PLAM * DT) * DT * DT
                RHD = C.DELDMZ[ID - 1] * C.DENSI[ID]
                E0 = D0 * RHD
                DSFT1 = DSFT1 + DBDT * (UN + TAU23) - E0 * C.DABT1[ID]
                DSFN1 = DSFN1 - E0 * (C.DABN1[ID] + C.ABSO1[ID] * C.DENSIM[ID])
                for II in range(1, C.NLVEXP + 1):
                    DSFP1[II] = DSFP1[II] - E0 * C.DABP1[II, ID]
                if C.IBC >= 3:
                    DBDTM = PLAM / C.XKF1[ID - 1] * C.HKT21[ID - 1] * C.FREQ[ij] * DT
                    RHD = C.DELDMZ[ID - 1] * C.DENSI[ID - 1]
                    E0 = D0 * RHD
                    DSFT1D = -DBDTM * DT * T23 - E0 * C.DABT1[ID - 1]
                    DSFN1D = -E0 * (C.DABN1[ID - 1] +
                                    C.ABSO1[ID - 1] * C.DENSIM[ID - 1])
                    for II in range(1, C.NLVEXP + 1):
                        DSFP1D[II] = -E0 * C.DABP1[II, ID - 1]
        # C
        if C.IRDER == 1 or C.IRDER == 3:
            C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
            C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
        if C.IRDER > 1:
            for II in range(1, C.NLVEXP + 1):
                C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]
        # c
        # c     Hydrostatic equilibrium equation
        # c
        if LNSKIP:
            D0 = WW * C.FAK1[ID]
            A0 = WW * C.FAK1[ID - 1]
            C.FPRD[ID] = C.FPRD[ID] + D0 * C.RAD1[ID] - A0 * C.RAD1[ID - 1]
            E0 = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
            D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
            C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1
            C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1
            C.HEITM[ID] = C.HEITM[ID] + E0 * DSFT1M
            C.HEINM[ID] = C.HEINM[ID] + E0 * DSFN1M
            for II in range(1, C.NLVEXP + 1):
                C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II]
                C.HEIPM[II, ID] = C.HEIPM[II, ID] + E0 * DSFP1M[II]
            if C.IBC >= 3:
                C.HEITM[ID] = C.HEITM[ID] - D0 * DSFT1D
                C.HEINM[ID] = C.HEINM[ID] - D0 * DSFN1D
                for II in range(1, C.NLVEXP + 1):
                    C.HEIPM[II, ID] = C.HEIPM[II, ID] - D0 * DSFP1D[II]
        # C
        # C     Differential equation part of radiative equilibrium
        # C
        DDT = UN / (C.ABSOT[ID] + C.ABSOT[ID - 1])
        DT = DDT / C.DELDMZ[ID - 1]
        FL = (C.RAD1[ID] * C.FAK1[ID] - C.RAD1[ID - 1] * C.FAK1[ID - 1]) * DT
        C.FLFIX[ID] = C.FLFIX[ID] + WW * FL
        if C.REDIF[ID] > 0:
            D0 = WW * C.FAK1[ID] * DT
            A0 = WW * C.FAK1[ID - 1] * DT
            D0M = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
            D0P = D0 * C.ALIP1[ID]
            D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
            E0 = WW * FL * DDT
            C.REDX[ID] = C.REDX[ID] + E0 * C.ABSO1[ID]
            C.REDXM[ID] = C.REDXM[ID] + E0 * C.ABSO1[ID - 1]
            E0M = E0 * C.DENSI[ID - 1]
            E0 = E0 * C.DENSI[ID]
            C.REDT[ID] = C.REDT[ID] + D0 * DSFT1 - E0 * C.DABT1[ID]
            C.REDTM[ID] = C.REDTM[ID] + D0M * DSFT1M - E0M * C.DABT1[ID - 1]
            C.REDN[ID] = C.REDN[ID] + D0 * DSFN1 - E0 * C.DABN1[ID]
            C.REDNM[ID] = C.REDNM[ID] + D0M * DSFN1M - E0M * C.DABN1[ID - 1]
            for II in range(1, C.NLVEXP + 1):
                C.REDP[II, ID] = C.REDP[II, ID] + D0 * DSFP1[II] - \
                    E0 * C.DABP1[II, ID]
                C.REDPM[II, ID] = C.REDPM[II, ID] + D0M * DSFP1M[II] - \
                    E0M * C.DABP1[II, ID - 1]
            if C.IBC >= 3:
                C.REDTM[ID] = C.REDTM[ID] + D0 * DSFT1D
                C.REDNM[ID] = C.REDNM[ID] + D0 * DSFN1D
                for II in range(1, C.NLVEXP + 1):
                    C.REDPM[II, ID] = C.REDPM[II, ID] + D0 * DSFP1D[II]
        # c
        # C     Integral equation part of the radiative equilibrium
        # C
        if C.REINT[ID] > 0:
            ABST = C.ABSO1[ID] - C.ELSCAT[ID]
            WWK = WW * ABST
            C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] - ABST * C.RAD1[ID])
            D0 = WW * (C.ALI1[ID] - UN) * ABST
            E0 = WW * (C.RAD1[ID] - S0)
            C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + E0 * (C.DABN1[ID] - C.SIGEC[ij])
            if C.IBC == 0:
                C.REIT[ID] = C.REIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
            else:
                # TODO(port): DBDT 仅在 IF(IBC.GT.0.AND.IDISK.EQ.0) 块内赋值；
                # 未赋值时 Fortran 取残留值，Python 同一次调用内亦保留旧值，
                # 但首次使用前未赋值将抛 NameError（见 ALIFR1 主分支同名注释）。
                C.REIT[ID] = C.REIT[ID] + D0 * (DSFT1 - DBDT) + E0 * C.DABT1[ID] + \
                    C.ALI1[ID] / ABST * DBDT
            for II in range(1, C.NLVEXP + 1):
                C.REIP[II, ID] = C.REIP[II, ID] + D0 * DSFP1[II] + \
                    E0 * C.DABP1[II, ID]
        return

    # C     Non-standard value of ILASCT (ILASCT != 0)
    # c
    # c ****1. Special expressions for the first depth  -  id=1
    # c
    # 299 ID=1  —— 上面 GO TO 299 跳转到此处
    ID = 1

    LNSKIP = not C.LSKIP[ID, ij]
    # c
    # c     Basic auxliliary quantities - derivatives of the source function
    # c
    EMISIV = UN / C.EMIS1[ID]
    ABST = UN / C.ABSO1[ID]
    S0 = C.EMIS1[ID] * ABST
    DSFN1 = S0 * (C.DEMN1[ID] * EMISIV - C.DABN1[ID] * ABST)
    DSFT1 = S0 * (C.DEMT1[ID] * EMISIV - C.DABT1[ID] * ABST)
    for II in range(1, C.NLVEXP + 1):
        DSFP1[II] = S0 * (C.DEMP1[II, ID] * EMISIV - C.DABP1[II, ID] * ABST)
    EMISIP = UN / C.EMIS1[ID + 1]
    ABSTP = UN / C.ABSO1[ID + 1]
    S0P = C.EMIS1[ID + 1] * ABSTP
    DSFN1P = S0P * (C.DEMN1[ID + 1] * EMISIP - C.DABN1[ID + 1] * ABSTP)
    DSFT1P = S0P * (C.DEMT1[ID + 1] * EMISIP - C.DABT1[ID + 1] * ABSTP)
    for II in range(1, C.NLVEXP + 1):
        DSFP1P[II] = S0P * (C.DEMP1[II, ID + 1] * EMISIP -
                            C.DABP1[II, ID + 1] * ABSTP)

    if C.IRDER == 1 or C.IRDER == 3:
        C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
        C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
    if C.IRDER > 1:
        for II in range(1, C.NLVEXP + 1):
            C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]

    # c
    # c     Hydrostatic equilibrium quantities
    # c
    WF = WW * C.FH[ij]
    if LNSKIP:
        C.FPRD[ID] = C.FPRD[ID] + WF * C.ABSO1[ID] * C.RAD1[ID] - \
            WW * C.HEXTRD[ij] * C.ABSO1[ID]
        E0 = WF * C.RAD1[ID]
        D0 = WF * C.ABSO1[ID] * C.ALI1[ID]
        C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
        C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1 + E0 * C.DABN1[ID]
        for II in range(1, C.NLVEXP + 1):
            C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II] + \
                E0 * C.DABP1[II, ID]
    # c
    # c     Differential equation part of radiative equilibrium
    # c
    C.FLFIX[ID] = C.FLFIX[ID] + WF * C.RAD1[ID] - WW * C.HEXTRD[ij]
    if C.REDIF[ID] > 0.:
        WF = WF * C.ALI1[ID]
        C.REDT[ID] = C.REDT[ID] + WF * DSFT1
        C.REDN[ID] = C.REDN[ID] + WF * DSFN1
        for II in range(1, C.NLVEXP + 1):
            C.REDP[II, ID] = C.REDP[II, ID] + WF * DSFP1[II]
    # c
    # C     Integral equation part of the radiative equilibrium
    # C
    if C.REINT[ID] > 0:
        SRH = SIGE * C.DENS1[ID]
        ABST = C.ABSO1[ID]
        ABSTE = ABST - C.ELSCAT[ID]
        WWK = WW * ABST
        C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] - ABSTE * C.RAD1[ID])
        D0 = WW * (ABSTE * C.ALI1[ID] - ABST)
        E0 = WW * (C.RAD1[ID] - S0)
        C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + E0 * C.DABN1[ID] - \
            WW * C.SIGEC[ij] * C.RAD1[ID]
        C.REIT[ID] = C.REIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
        for II in range(1, C.NLVEXP + 1):
            C.REIP[II, ID] = C.REIP[II, ID] + D0 * DSFP1[II] + \
                E0 * C.DABP1[II, ID]

    # C
    # c ****2. loop over depths
    # c
    for ID in range(2, C.ND - 1 + 1):

        LNSKIP = not C.LSKIP[ID, ij]

        DSFTMM = DSFT1M
        DSFNMM = DSFN1M
        for II in range(1, C.NLVEXP + 1):
            DSFPMM[II] = DSFP1M[II]
        DSFT1M = DSFT1
        DSFN1M = DSFN1
        for II in range(1, C.NLVEXP + 1):
            DSFP1M[II] = DSFP1[II]
        S0 = S0P
        DSFT1 = DSFT1P
        DSFN1 = DSFN1P
        for II in range(1, C.NLVEXP + 1):
            DSFP1[II] = DSFP1P[II]

        EMISIP = UN / C.EMIS1[ID + 1]
        ABSTP = UN / C.ABSO1[ID + 1]
        S0P = C.EMIS1[ID + 1] * ABSTP
        DSFN1P = S0P * (C.DEMN1[ID + 1] * EMISIP - C.DABN1[ID + 1] * ABSTP)
        DSFT1P = S0P * (C.DEMT1[ID + 1] * EMISIP - C.DABT1[ID + 1] * ABSTP)
        for II in range(1, C.NLVEXP + 1):
            DSFP1P[II] = S0P * (C.DEMP1[II, ID + 1] * EMISIP -
                                C.DABP1[II, ID + 1] * ABSTP)

        if C.IRDER == 1 or C.IRDER == 3:
            C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
            C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
        if C.IRDER > 1:
            for II in range(1, C.NLVEXP + 1):
                C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]
        # c
        # c       Hydrostatic equilibrium equation
        # c
        if LNSKIP:
            D0 = WW * C.FAK1[ID]
            A0 = WW * C.FAK1[ID - 1]
            C.FPRD[ID] = C.FPRD[ID] + D0 * C.RAD1[ID] - A0 * C.RAD1[ID - 1]
            E0 = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
            D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
            C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1
            C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1
            C.HEITM[ID] = C.HEITM[ID] + E0 * DSFT1M
            C.HEINM[ID] = C.HEINM[ID] + E0 * DSFN1M
            for II in range(1, C.NLVEXP + 1):
                C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II]
                C.HEIPM[II, ID] = C.HEIPM[II, ID] + E0 * DSFP1M[II]
        # C
        # C       Differential equation part of radiative equilibrium
        # C
        DDT = UN / (C.ABSOT[ID] + C.ABSOT[ID - 1])
        DT = DDT / C.DELDMZ[ID - 1]
        FL = (C.RAD1[ID] * C.FAK1[ID] - C.RAD1[ID - 1] * C.FAK1[ID - 1]) * DT
        C.FLFIX[ID] = C.FLFIX[ID] + WW * FL
        if C.REDIF[ID] > 0:
            D0 = WW * C.FAK1[ID] * DT
            A0 = WW * C.FAK1[ID - 1] * DT
            D0M = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
            D0P = D0 * C.ALIP1[ID]
            D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
            E0 = WW * FL * DDT
            C.REDX[ID] = C.REDX[ID] + E0 * C.ABSO1[ID]
            C.REDXM[ID] = C.REDXM[ID] + E0 * C.ABSO1[ID - 1]
            E0M = E0 * C.DENSI[ID - 1]
            E0 = E0 * C.DENSI[ID]
            C.REDT[ID] = C.REDT[ID] + D0 * DSFT1 - E0 * C.DABT1[ID]
            C.REDTM[ID] = C.REDTM[ID] + D0M * DSFT1M - E0M * C.DABT1[ID - 1]
            C.REDN[ID] = C.REDN[ID] + D0 * DSFN1 - E0 * C.DABN1[ID]
            C.REDNM[ID] = C.REDNM[ID] + D0M * DSFN1M - E0M * C.DABN1[ID - 1]
            for II in range(1, C.NLVEXP + 1):
                C.REDP[II, ID] = C.REDP[II, ID] + D0 * DSFP1[II] - \
                    E0 * C.DABP1[II, ID]
                C.REDPM[II, ID] = C.REDPM[II, ID] + D0M * DSFP1M[II] - \
                    E0M * C.DABP1[II, ID - 1]
        # c
        # C       Integral equation part of the radiative equilibrium
        # C
        if C.REINT[ID] > 0:
            SRH = SIGE * C.DENS1[ID]
            ABST = C.ABSO1[ID]
            ABSTE = ABST - C.ELSCAT[ID]
            WWK = WW * ABST
            C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] - ABSTE * C.RAD1[ID])
            D0 = WW * (ABSTE * C.ALI1[ID] - ABST)
            E0 = WW * (C.RAD1[ID] - S0)
            C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + E0 * C.DABN1[ID] - \
                WW * C.SIGEC[ij] * C.RAD1[ID]
            C.REIT[ID] = C.REIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
            for II in range(1, C.NLVEXP + 1):
                C.REIP[II, ID] = C.REIP[II, ID] + D0 * DSFP1[II] + \
                    E0 * C.DABP1[II, ID]

    # C
    # c ****3. deepest point - ID=ND
    # c
    ID = C.ND

    LNSKIP = not C.LSKIP[ID, ij]

    DSFTMM = DSFT1M
    DSFNMM = DSFN1M
    for II in range(1, C.NLVEXP + 1):
        DSFPMM[II] = DSFP1M[II]
    DSFT1M = DSFT1
    DSFN1M = DSFN1
    for II in range(1, C.NLVEXP + 1):
        DSFP1M[II] = DSFP1[II]
    S0 = S0P
    DSFT1 = DSFT1P
    DSFN1 = DSFN1P
    for II in range(1, C.NLVEXP + 1):
        DSFP1[II] = DSFP1P[II]
    # C
    # C     Improved lower boundary condition
    # C
    if C.IBC > 0 and C.IDISK == 0:
        DT = UN / (C.DELDMZ[ID - 1] * (C.ABSOT[ID] + C.ABSOT[ID - 1]))
        PLAD = C.XKFB[ID] / C.XKF1[ID]
        DBDT = PLAD / C.XKF1[ID] * C.HKT21[ID] * C.FREQ[ij] * DT
        if C.IBC == 1:
            DSFT1 = DSFT1 + DBDT
        elif C.IBC >= 2:
            PLAM = C.XKFB[ID - 1] / C.XKF1[ID - 1]
            TAU23 = T23 * DT
            TAU43 = T43 * DT
            D0 = (PLAD * (UN + TAU43) - T43 * PLAM * DT) * DT * DT
            RHD = C.DELDMZ[ID - 1] * C.DENSI[ID]
            E0 = D0 * RHD
            DSFT1 = DSFT1 + DBDT * (UN + TAU23) - E0 * C.DABT1[ID]
            DSFN1 = DSFN1 - E0 * (C.DABN1[ID] + C.ABSO1[ID] * C.DENSIM[ID])
            for II in range(1, C.NLVEXP + 1):
                DSFP1[II] = DSFP1[II] - E0 * C.DABP1[II, ID]
            if C.IBC >= 3:
                DBDTM = PLAM / C.XKF1[ID - 1] * C.HKT21[ID - 1] * C.FREQ[ij] * DT
                RHD = C.DELDMZ[ID - 1] * C.DENSI[ID - 1]
                E0 = D0 * RHD
                DSFT1D = -DBDTM * DT * T23 - E0 * C.DABT1[ID - 1]
                DSFN1D = -E0 * (C.DABN1[ID - 1] +
                                C.ABSO1[ID - 1] * C.DENSIM[ID - 1])
                for II in range(1, C.NLVEXP + 1):
                    DSFP1D[II] = -E0 * C.DABP1[II, ID - 1]
    # C
    if C.IRDER == 1 or C.IRDER == 3:
        C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
        C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
    if C.IRDER > 1:
        for II in range(1, C.NLVEXP + 1):
            C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]
    # c
    # c     Hydrostatic equilibrium equation
    # c
    if LNSKIP:
        D0 = WW * C.FAK1[ID]
        A0 = WW * C.FAK1[ID - 1]
        C.FPRD[ID] = C.FPRD[ID] + D0 * C.RAD1[ID] - A0 * C.RAD1[ID - 1]
        E0 = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
        D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
        C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1
        C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1
        C.HEITM[ID] = C.HEITM[ID] + E0 * DSFT1M
        C.HEINM[ID] = C.HEINM[ID] + E0 * DSFN1M
        for II in range(1, C.NLVEXP + 1):
            C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II]
            C.HEIPM[II, ID] = C.HEIPM[II, ID] + E0 * DSFP1M[II]
        if C.IBC >= 3:
            C.HEITM[ID] = C.HEITM[ID] - D0 * DSFT1D
            C.HEINM[ID] = C.HEINM[ID] - D0 * DSFN1D
            for II in range(1, C.NLVEXP + 1):
                C.HEIPM[II, ID] = C.HEIPM[II, ID] - D0 * DSFP1D[II]
    # C
    # C     Differential equation part of radiative equilibrium
    # C
    DDT = UN / (C.ABSOT[ID] + C.ABSOT[ID - 1])
    DT = DDT / C.DELDMZ[ID - 1]
    FL = (C.RAD1[ID] * C.FAK1[ID] - C.RAD1[ID - 1] * C.FAK1[ID - 1]) * DT
    C.FLFIX[ID] = C.FLFIX[ID] + WW * FL
    if C.REDIF[ID] > 0:
        D0 = WW * C.FAK1[ID] * DT
        A0 = WW * C.FAK1[ID - 1] * DT
        D0M = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
        D0P = D0 * C.ALIP1[ID]
        D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
        E0 = WW * FL * DDT
        C.REDX[ID] = C.REDX[ID] + E0 * C.ABSO1[ID]
        C.REDXM[ID] = C.REDXM[ID] + E0 * C.ABSO1[ID - 1]
        E0M = E0 * C.DENSI[ID - 1]
        E0 = E0 * C.DENSI[ID]
        C.REDT[ID] = C.REDT[ID] + D0 * DSFT1 - E0 * C.DABT1[ID]
        C.REDTM[ID] = C.REDTM[ID] + D0M * DSFT1M - E0M * C.DABT1[ID - 1]
        C.REDN[ID] = C.REDN[ID] + D0 * DSFN1 - E0 * C.DABN1[ID]
        C.REDNM[ID] = C.REDNM[ID] + D0M * DSFN1M - E0M * C.DABN1[ID - 1]
        for II in range(1, C.NLVEXP + 1):
            C.REDP[II, ID] = C.REDP[II, ID] + D0 * DSFP1[II] - \
                E0 * C.DABP1[II, ID]
            C.REDPM[II, ID] = C.REDPM[II, ID] + D0M * DSFP1M[II] - \
                E0M * C.DABP1[II, ID - 1]
        if C.IBC >= 3:
            C.REDTM[ID] = C.REDTM[ID] + D0 * DSFT1D
            C.REDNM[ID] = C.REDNM[ID] + D0 * DSFN1D
            for II in range(1, C.NLVEXP + 1):
                C.REDPM[II, ID] = C.REDPM[II, ID] + D0 * DSFP1D[II]
    # c
    # C     Integral equation part of the radiative equilibrium
    # C
    if C.REINT[ID] > 0:
        SRH = SIGE * C.DENS1[ID]
        ABST = C.ABSO1[ID]
        ABSTE = ABST - C.ELSCAT[ID]
        WWK = WW * ABST
        C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] - ABSTE * C.RAD1[ID])
        D0 = WW * (ABSTE * C.ALI1[ID] - ABST)
        E0 = WW * (C.RAD1[ID] - S0)
        C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + E0 * C.DABN1[ID] - \
            WW * C.SIGEC[ij] * C.RAD1[ID]
        if C.IBC == 0:
            C.REIT[ID] = C.REIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
        else:
            # TODO(port): DBDT 仅在 IF(IBC.GT.0.AND.IDISK.EQ.0) 块内赋值；
            # 未赋值时 Fortran 取残留值，Python 同一次调用内亦保留旧值，
            # 但首次使用前未赋值将抛 NameError（见 ALIFR1 主分支同名注释）。
            C.REIT[ID] = C.REIT[ID] + D0 * (DSFT1 - DBDT) + E0 * C.DABT1[ID] + \
                C.ALI1[ID] / ABST * DBDT
        for II in range(1, C.NLVEXP + 1):
            C.REIP[II, ID] = C.REIP[II, ID] + D0 * DSFP1[II] + \
                E0 * C.DABP1[II, ID]

    return


def alifr6(ij):
    """
    hydrostatic and radiative equilibrium quantities -
    derivatives of the total heating and cooling rates in the
    ALI points with respect to the
    temperature, electron density, and populations
    a variant for consistent tridiagonal operator

    对应 tlusty208.f 行 21387–22039
    """
    # PARAMETER (T23=TWO/3.D0, T43=4.D0/3.D0)
    T23 = TWO / 3.0
    T43 = 4.0 / 3.0
    # DIMENSION DSFP1(MLVEXP),DSFP1M(MLVEXP),DSFP1D(MLVEXP),
    #           DSFP1P(MLVEXP),DSFPMM(MLVEXP)
    # 局部数组，保持 Fortran 1 基索引（每维 +1）
    DSFP1 = np.zeros(MLVEXP + 1)
    DSFP1M = np.zeros(MLVEXP + 1)
    DSFP1D = np.zeros(MLVEXP + 1)
    DSFP1P = np.zeros(MLVEXP + 1)
    DSFPMM = np.zeros(MLVEXP + 1)

    WW = C.WC[ij]

    DSFT1M = 0.
    DSFN1M = 0.
    for II in range(1, C.NLVEXP + 1):
        DSFP1M[II] = 0.
    # c
    # c ****1. Special expressions for the first depth  -  id=1
    # c
    ID = 1

    LNSKIP = not C.LSKIP[ID, ij]
    # c
    # c     Basic auxliliary quantities - derivatives of the source function
    # c
    EMISIV = UN / C.EMIS1[ID]
    if C.ILMCOR != 3:
        if C.ILASCT == 0:
            ABST = UN / (C.ABSO1[ID] - C.ELSCAT[ID])
            S0 = C.EMIS1[ID] * ABST
            DSFN1 = S0 * (C.DEMN1[ID] * EMISIV -
                          (C.DABN1[ID] - C.SIGEC[ij]) * ABST)
        else:
            ABST = UN / C.ABSO1[ID]
            S0 = C.EMIS1[ID] * ABST
            DSFN1 = S0 * (C.DEMN1[ID] * EMISIV - C.DABN1[ID] * ABST)
        DSFT1 = S0 * (C.DEMT1[ID] * EMISIV - C.DABT1[ID] * ABST)
        for II in range(1, C.NLVEXP + 1):
            DSFP1[II] = S0 * (C.DEMP1[II, ID] * EMISIV - C.DABP1[II, ID] * ABST)
    # C
    # c     correction for electron scattering source function contribution
    # c
    else:
        ABST = UN / C.ABSO1[ID]
        S0 = C.EMIS1[ID] * ABST
        sc = C.ELEC[ID] * C.SIGEC[ij]
        sct = sc * ABST
        st = S0 + sct * C.RAD1[ID]
        corr = UN / (UN - C.ALI1[ID] * sct)
        DSFT1 = corr * (S0 * C.DEMT1[ID] * EMISIV - st * C.DABT1[ID] * ABST)
        DSFN1 = corr * (S0 * C.DEMN1[ID] * EMISIV +
                        C.SIGEC[ij] * C.RAD1[ID] * ABST -
                        st * C.DABN1[ID] * ABST)
        for II in range(1, C.NLVEXP + 1):
            DSFP1[II] = corr * (S0 * C.DEMP1[II, ID] * EMISIV -
                                st * C.DABP1[II, ID] * ABST)

    EMISIP = UN / C.EMIS1[ID + 1]
    if C.ILMCOR != 3:
        if C.ILASCT == 0:
            ABSTP = UN / (C.ABSO1[ID + 1] - C.ELSCAT[ID + 1])
            S0P = C.EMIS1[ID + 1] * ABSTP
            DSFN1P = S0P * (C.DEMN1[ID + 1] * EMISIP -
                            (C.DABN1[ID + 1] - C.SIGEC[ij]) * ABSTP)
        else:
            ABSTP = UN / C.ABSO1[ID + 1]
            S0P = C.EMIS1[ID + 1] * ABSTP
            DSFN1P = S0P * (C.DEMN1[ID + 1] * EMISIP - C.DABN1[ID + 1] * ABSTP)
        DSFT1P = S0P * (C.DEMT1[ID + 1] * EMISIP - C.DABT1[ID + 1] * ABSTP)
        for II in range(1, C.NLVEXP + 1):
            DSFP1P[II] = S0P * (C.DEMP1[II, ID + 1] * EMISIP -
                                C.DABP1[II, ID + 1] * ABSTP)
    else:
        ABSTP = UN / C.ABSO1[ID + 1]
        S0P = C.EMIS1[ID + 1] * ABSTP
        scp = C.ELEC[ID + 1] * C.SIGEC[ij]
        sctp = scp * ABSTP
        stp = S0P + sctp * C.RAD1[ID + 1]
        corrp = UN / (UN - C.ALI1[ID + 1] * sctp)
        DSFT1P = corrp * (S0P * C.DEMT1[ID + 1] * EMISIP -
                          stp * C.DABT1[ID + 1] * ABSTP)
        DSFN1P = corrp * (S0P * C.DEMN1[ID + 1] * EMISIP +
                          C.SIGEC[ij] * C.RAD1[ID + 1] * ABSTP -
                          stp * C.DABN1[ID + 1] * ABSTP)
        for II in range(1, C.NLVEXP + 1):
            DSFP1P[II] = corrp * (S0P * C.DEMP1[II, ID + 1] * EMISIP -
                                  stp * C.DABP1[II, ID + 1] * ABSTP)

    if C.IRDER == 1 or C.IRDER == 3:
        C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
        C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
    if C.IRDER > 1:
        for II in range(1, C.NLVEXP + 1):
            C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]

    if C.IRDER == 1 or C.IRDER == 3:
        C.DSFDTM[ID] = DSFT1M * C.ALIM1[ID]
        C.DSFDNM[ID] = DSFN1M * C.ALIM1[ID]
        C.DSFDTP[ID] = DSFT1P * C.ALIP1[ID]
        C.DSFDNP[ID] = DSFN1P * C.ALIP1[ID]
    if C.IRDER > 1:
        for II in range(1, C.NLVEXP + 1):
            C.DSFDPM[II, ID] = DSFP1M[II] * C.ALIM1[ID]
            C.DSFDPP[II, ID] = DSFP1P[II] * C.ALIP1[ID]
    # c
    # c     Hydrostatic equilibrium quantities
    # c
    WF = WW * C.FH[ij]
    if LNSKIP:
        C.FPRD[ID] = C.FPRD[ID] + WF * C.ABSO1[ID] * C.RAD1[ID] - \
            WW * C.HEXTRD[ij] * C.ABSO1[ID]
        E0 = WF * C.RAD1[ID]
        D0 = WF * C.ABSO1[ID] * C.ALI1[ID]
        C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
        C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1 + E0 * C.DABN1[ID]
        for II in range(1, C.NLVEXP + 1):
            C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II] + \
                E0 * C.DABP1[II, ID]
        if C.IFALI >= 7:
            D0P = WF * C.ABSO1[ID] * C.ALIP1[ID]
            C.HEITP[ID] = C.HEITP[ID] + D0P * DSFT1P
            C.HEINP[ID] = C.HEINP[ID] + D0P * DSFN1P
            for II in range(1, C.NLVEXP + 1):
                C.HEIPP[II, ID] = C.HEIPP[II, ID] + D0P * DSFP1P[II]
    # c
    # c     Differential equation part of radiative equilibrium
    # c
    C.FLFIX[ID] = C.FLFIX[ID] + WF * C.RAD1[ID] - WW * C.HEXTRD[ij]
    if C.REDIF[ID] > 0.:
        WF = WF * C.ALI1[ID]
        C.REDT[ID] = C.REDT[ID] + WF * DSFT1
        C.REDN[ID] = C.REDN[ID] + WF * DSFN1
        for II in range(1, C.NLVEXP + 1):
            C.REDP[II, ID] = C.REDP[II, ID] + WF * DSFP1[II]
    # c
    # C     Integral equation part of the radiative equilibrium
    # C
    if C.REINT[ID] > 0:
        if C.ILMCOR != 3:
            if C.ILASCT == 0:
                ABST = C.ABSO1[ID] - C.ELSCAT[ID]
                WWK = WW * ABST
                C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] -
                                                    ABST * C.RAD1[ID])
                D0 = WW * (C.ALI1[ID] - UN) * ABST
                E0 = WW * (C.RAD1[ID] - S0)
                C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + \
                    E0 * (C.DABN1[ID] - C.SIGEC[ij])
            else:
                SRH = SIGE * C.DENS1[ID]
                ABST = C.ABSO1[ID]
                ABSTE = ABST - C.ELSCAT[ID]
                WWK = WW * ABST
                C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] -
                                                    ABSTE * C.RAD1[ID])
                D0 = WW * (ABSTE * C.ALI1[ID] - ABST)
                E0 = WW * (C.RAD1[ID] - S0)
                C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + E0 * C.DABN1[ID] - \
                    WW * C.SIGEC[ij] * C.RAD1[ID]
            C.REIT[ID] = C.REIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
            for II in range(1, C.NLVEXP + 1):
                C.REIP[II, ID] = C.REIP[II, ID] + D0 * DSFP1[II] + \
                    E0 * C.DABP1[II, ID]
        else:
            ABST = C.ABSO1[ID] - C.ELSCAT[ID]
            D0 = ABST * C.ALI1[ID]
            C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] - ABST * C.RAD1[ID])
            C.REIN[ID] = C.REIN[ID] + WW * (D0 * DSFN1 +
                                            C.RAD1[ID] * (C.DABN1[ID] - C.SIGEC[ij]) -
                                            C.DEMN1[ID])
            for II in range(1, C.NLVEXP + 1):
                C.REIP[II, ID] = C.REIP[II, ID] + WW * (D0 * DSFP1[II] +
                                                       C.RAD1[ID] * C.DABP1[II, ID] -
                                                       C.DEMP1[II, ID])
            C.REIT[ID] = C.REIT[ID] + WW * (D0 * DSFT1 +
                                            C.RAD1[ID] * C.DABT1[ID] - C.DEMT1[ID])
        # c
        # c       the following are needed only for tridiagonal Lambda^star
        # C
        # C       Upper sub-diagonal band
        # C
        # TODO(port): ILMCOR==3 分支中 WWK 从未赋值；Fortran 中取残留值，
        # Python 同一次调用内保留旧值，但若 ID=1 即 ILMCOR==3 且 REINT(1)>0，
        # WWK 首次使用前未赋值将抛 NameError（与 Fortran "未定义值" 不等价）。
        WWKC = WWK * C.ALIP1[ID]
        C.CREIT[ID] = C.CREIT[ID] + WWKC * DSFT1P
        C.CREIN[ID] = C.CREIN[ID] + WWKC * DSFN1P
        for II in range(1, C.NLVEXP + 1):
            C.CREIP[II, ID] = C.CREIP[II, ID] + WWKC * DSFP1P[II]

    # C
    # c ****2. loop over depths
    # c
    for ID in range(2, C.ND - 1 + 1):

        LNSKIP = not C.LSKIP[ID, ij]

        DSFTMM = DSFT1M
        DSFNMM = DSFN1M
        for II in range(1, C.NLVEXP + 1):
            DSFPMM[II] = DSFP1M[II]
        DSFT1M = DSFT1
        DSFN1M = DSFN1
        for II in range(1, C.NLVEXP + 1):
            DSFP1M[II] = DSFP1[II]
        S0 = S0P
        DSFT1 = DSFT1P
        DSFN1 = DSFN1P
        for II in range(1, C.NLVEXP + 1):
            DSFP1[II] = DSFP1P[II]

        EMISIP = UN / C.EMIS1[ID + 1]
        if C.ILMCOR != 3:
            if C.ILASCT == 0:
                ABSTP = UN / (C.ABSO1[ID + 1] - C.ELSCAT[ID + 1])
                S0P = C.EMIS1[ID + 1] * ABSTP
                DSFN1P = S0P * (C.DEMN1[ID + 1] * EMISIP -
                                (C.DABN1[ID + 1] - C.SIGEC[ij]) * ABSTP)
            else:
                ABSTP = UN / C.ABSO1[ID + 1]
                S0P = C.EMIS1[ID + 1] * ABSTP
                DSFN1P = S0P * (C.DEMN1[ID + 1] * EMISIP -
                                C.DABN1[ID + 1] * ABSTP)
            DSFT1P = S0P * (C.DEMT1[ID + 1] * EMISIP - C.DABT1[ID + 1] * ABSTP)
            for II in range(1, C.NLVEXP + 1):
                DSFP1P[II] = S0P * (C.DEMP1[II, ID + 1] * EMISIP -
                                    C.DABP1[II, ID + 1] * ABSTP)
        else:
            ABSTP = UN / C.ABSO1[ID + 1]
            S0P = C.EMIS1[ID + 1] * ABSTP
            scp = C.ELEC[ID + 1] * C.SIGEC[ij]
            sctp = scp * ABSTP
            stp = S0P + sctp * C.RAD1[ID + 1]
            corrp = UN / (UN - C.ALI1[ID + 1] * sctp)
            DSFT1P = corrp * (S0P * C.DEMT1[ID + 1] * EMISIP -
                              stp * C.DABT1[ID + 1] * ABSTP)
            DSFN1P = corrp * (S0P * C.DEMN1[ID + 1] * EMISIP +
                              C.SIGEC[ij] * C.RAD1[ID + 1] * ABSTP -
                              stp * C.DABN1[ID + 1] * ABSTP)
            for II in range(1, C.NLVEXP + 1):
                DSFP1P[II] = corrp * (S0P * C.DEMP1[II, ID + 1] * EMISIP -
                                      stp * C.DABP1[II, ID + 1] * ABSTP)

        if C.IRDER == 1 or C.IRDER == 3:
            C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
            C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
        if C.IRDER > 1:
            for II in range(1, C.NLVEXP + 1):
                C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]

        if C.IRDER == 1 or C.IRDER == 3:
            C.DSFDTM[ID] = DSFT1M * C.ALIM1[ID]
            C.DSFDNM[ID] = DSFN1M * C.ALIM1[ID]
            C.DSFDTP[ID] = DSFT1P * C.ALIP1[ID]
            C.DSFDNP[ID] = DSFN1P * C.ALIP1[ID]
        if C.IRDER > 1:
            for II in range(1, C.NLVEXP + 1):
                C.DSFDPM[II, ID] = DSFP1M[II] * C.ALIM1[ID]
                C.DSFDPP[II, ID] = DSFP1P[II] * C.ALIP1[ID]
        # c
        # c       Hydrostatic equilibrium equation
        # c
        if LNSKIP:
            D0 = WW * C.FAK1[ID]
            A0 = WW * C.FAK1[ID - 1]
            C.FPRD[ID] = C.FPRD[ID] + D0 * C.RAD1[ID] - A0 * C.RAD1[ID - 1]
            F0 = D0 * C.ALIP1[ID]
            E0 = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
            D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
            C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1
            C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1
            C.HEITM[ID] = C.HEITM[ID] + E0 * DSFT1M
            C.HEINM[ID] = C.HEINM[ID] + E0 * DSFN1M
            for II in range(1, C.NLVEXP + 1):
                C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II]
                C.HEIPM[II, ID] = C.HEIPM[II, ID] + E0 * DSFP1M[II]
            if C.IFALI >= 7:
                C.HEITP[ID] = C.HEITP[ID] + F0 * DSFT1P
                C.HEINP[ID] = C.HEINP[ID] + F0 * DSFN1P
                for II in range(1, C.NLVEXP + 1):
                    C.HEIPP[II, ID] = C.HEIPP[II, ID] + F0 * DSFP1P[II]
                A0M = A0 * C.ALIM1[ID - 1]
                C.EHET[ID] = C.EHET[ID] - A0M * DSFTMM
                C.EHEN[ID] = C.EHEN[ID] - A0M * DSFNMM
                # TODO(port): EHEP 在 ALIPAR.FOR 中声明为 EHEP(MLVEX3,MDEPTH)，
                # 当前 MLVEX3=1（diag.prec.），而此处 II 循环到 NLVEXP；
                # IFALI>=7（三对角算子）时 Fortran 依靠 MLVEX3=MLEXP 的
                # 重新编译维度。直译保留原索引，numpy 下 II>1 会越界。
                for II in range(1, C.NLVEXP + 1):
                    C.EHEP[II, ID] = C.EHEP[II, ID] - A0M * DSFPMM[II]
        # C
        # C       Differential equation part of radiative equilibrium
        # C
        DDT = UN / (C.ABSOT[ID] + C.ABSOT[ID - 1])
        DT = DDT / C.DELDMZ[ID - 1]
        FL = (C.RAD1[ID] * C.FAK1[ID] - C.RAD1[ID - 1] * C.FAK1[ID - 1]) * DT
        C.FLFIX[ID] = C.FLFIX[ID] + WW * FL
        if C.REDIF[ID] > 0:
            D0 = WW * C.FAK1[ID] * DT
            A0 = WW * C.FAK1[ID - 1] * DT
            D0M = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
            D0P = D0 * C.ALIP1[ID]
            D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
            E0 = WW * FL * DDT
            C.REDX[ID] = C.REDX[ID] + E0 * C.ABSO1[ID]
            C.REDXM[ID] = C.REDXM[ID] + E0 * C.ABSO1[ID - 1]
            E0M = E0 * C.DENSI[ID - 1]
            E0 = E0 * C.DENSI[ID]
            C.REDT[ID] = C.REDT[ID] + D0 * DSFT1 - E0 * C.DABT1[ID]
            C.REDTM[ID] = C.REDTM[ID] + D0M * DSFT1M - E0M * C.DABT1[ID - 1]
            C.REDN[ID] = C.REDN[ID] + D0 * DSFN1 - E0 * C.DABN1[ID]
            C.REDNM[ID] = C.REDNM[ID] + D0M * DSFN1M - E0M * C.DABN1[ID - 1]
            for II in range(1, C.NLVEXP + 1):
                C.REDP[II, ID] = C.REDP[II, ID] + D0 * DSFP1[II] - \
                    E0 * C.DABP1[II, ID]
                C.REDPM[II, ID] = C.REDPM[II, ID] + D0M * DSFP1M[II] - \
                    E0M * C.DABP1[II, ID - 1]
            if C.IFALI >= 7:
                # 原代码为 REDTP(ID)=REDTP(ID)+D0P*DSFT1M（用的是 DSFT1M，
                # 而非 DSFT1P；疑似原作者笔误，直译保留）
                C.REDTP[ID] = C.REDTP[ID] + D0P * DSFT1M
                C.REDNP[ID] = C.REDNP[ID] + D0P * DSFN1M
                for II in range(1, C.NLVEXP + 1):
                    C.REDPP[II, ID] = C.REDPP[II, ID] + D0P * DSFP1P[II]
                A0M = A0 * C.ALIM1[ID - 1]
                C.ERET[ID] = C.ERET[ID] - A0M * DSFTMM
                C.EREN[ID] = C.EREN[ID] - A0M * DSFNMM
                # TODO(port): EREP 维度为 (MLVEX3,MDEPTH)，同 EHEP 的越界疑点。
                for II in range(1, C.NLVEXP + 1):
                    C.EREP[II, ID] = C.EREP[II, ID] - A0M * DSFPMM[II]
        # c
        # C       Integral equation part of the radiative equilibrium
        # C
        if C.REINT[ID] > 0:
            if C.ILMCOR != 3:
                if C.ILASCT == 0:
                    ABST = C.ABSO1[ID] - C.ELSCAT[ID]
                    WWK = WW * ABST
                    C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] -
                                                        ABST * C.RAD1[ID])
                    D0 = WW * (C.ALI1[ID] - UN) * ABST
                    E0 = WW * (C.RAD1[ID] - S0)
                    C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + \
                        E0 * (C.DABN1[ID] - C.SIGEC[ij])
                else:
                    SRH = SIGE * C.DENS1[ID]
                    ABST = C.ABSO1[ID]
                    ABSTE = ABST - C.ELSCAT[ID]
                    WWK = WW * ABST
                    C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] -
                                                        ABSTE * C.RAD1[ID])
                    D0 = WW * (ABSTE * C.ALI1[ID] - ABST)
                    E0 = WW * (C.RAD1[ID] - S0)
                    # 原代码此处为 WW*SIGE*RAD1(ID)（常数 SIGE），直译保留
                    C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + E0 * C.DABN1[ID] - \
                        WW * SIGE * C.RAD1[ID]
                C.REIT[ID] = C.REIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
                for II in range(1, C.NLVEXP + 1):
                    C.REIP[II, ID] = C.REIP[II, ID] + D0 * DSFP1[II] + \
                        E0 * C.DABP1[II, ID]
            else:
                ABST = C.ABSO1[ID] - C.ELSCAT[ID]
                D0 = ABST * C.ALI1[ID]
                C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] -
                                                    ABST * C.RAD1[ID])
                # 原代码此处为 (DABN1(ID)-SIGE)（常数 SIGE），直译保留
                C.REIN[ID] = C.REIN[ID] + WW * (D0 * DSFN1 +
                                                C.RAD1[ID] * (C.DABN1[ID] - SIGE) -
                                                C.DEMN1[ID])
                for II in range(1, C.NLVEXP + 1):
                    C.REIP[II, ID] = C.REIP[II, ID] + WW * (D0 * DSFP1[II] +
                                                           C.RAD1[ID] * C.DABP1[II, ID] -
                                                           C.DEMP1[II, ID])
                C.REIT[ID] = C.REIT[ID] + WW * (D0 * DSFT1 +
                                                C.RAD1[ID] * C.DABT1[ID] - C.DEMT1[ID])
            # c
            # c         the following are needed only for tridiagonal Lambda^star
            # C
            # C         Lower sub-diagonal band
            # C
            # TODO(port): ILMCOR==3 分支中 WWK 未赋值（同前 TODO）。
            WWKA = WWK * C.ALIM1[ID]
            C.AREIT[ID] = C.AREIT[ID] + WWKA * DSFT1M
            C.AREIN[ID] = C.AREIN[ID] + WWKA * DSFN1M
            for II in range(1, C.NLVEXP + 1):
                C.AREIP[II, ID] = C.AREIP[II, ID] + WWKA * DSFP1M[II]
            # C
            # C         Upper sub-diagonal band
            # C
            WWKC = WWK * C.ALIP1[ID]
            C.CREIT[ID] = C.CREIT[ID] + WWKC * DSFT1P
            C.CREIN[ID] = C.CREIN[ID] + WWKC * DSFN1P
            for II in range(1, C.NLVEXP + 1):
                C.CREIP[II, ID] = C.CREIP[II, ID] + WWKC * DSFP1P[II]

    # C
    # c ****3. deepest point - ID=ND
    # c
    ID = C.ND

    LNSKIP = not C.LSKIP[ID, ij]

    DSFTMM = DSFT1M
    DSFNMM = DSFN1M
    for II in range(1, C.NLVEXP + 1):
        DSFPMM[II] = DSFP1M[II]
    DSFT1M = DSFT1
    DSFN1M = DSFN1
    for II in range(1, C.NLVEXP + 1):
        DSFP1M[II] = DSFP1[II]
    S0 = S0P
    DSFT1 = DSFT1P
    DSFN1 = DSFN1P
    for II in range(1, C.NLVEXP + 1):
        DSFP1[II] = DSFP1P[II]
    # C
    # C     Improved lower boundary condition
    # C
    if C.IBC > 0 and C.IDISK == 0:
        DT = UN / (C.DELDMZ[ID - 1] * (C.ABSOT[ID] + C.ABSOT[ID - 1]))
        PLAD = C.XKFB[ID] / C.XKF1[ID]
        DBDT = PLAD / C.XKF1[ID] * C.HKT21[ID] * C.FREQ[ij] * DT
        if C.IBC == 1:
            DSFT1 = DSFT1 + DBDT
        elif C.IBC >= 2:
            PLAM = C.XKFB[ID - 1] / C.XKF1[ID - 1]
            TAU23 = T23 * DT
            TAU43 = T43 * DT
            D0 = (PLAD * (UN + TAU43) - T43 * PLAM * DT) * DT * DT
            RHD = C.DELDMZ[ID - 1] * C.DENSI[ID]
            E0 = D0 * RHD
            DSFT1 = DSFT1 + DBDT * (UN + TAU23) - E0 * C.DABT1[ID]
            DSFN1 = DSFN1 - E0 * (C.DABN1[ID] + C.ABSO1[ID] * C.DENSIM[ID])
            for II in range(1, C.NLVEXP + 1):
                DSFP1[II] = DSFP1[II] - E0 * C.DABP1[II, ID]
            if C.IBC >= 3:
                DBDTM = PLAM / C.XKF1[ID - 1] * C.HKT21[ID - 1] * C.FREQ[ij] * DT
                RHD = C.DELDMZ[ID - 1] * C.DENSI[ID - 1]
                E0 = D0 * RHD
                DSFT1D = -DBDTM * DT * T23 - E0 * C.DABT1[ID - 1]
                DSFN1D = -E0 * (C.DABN1[ID - 1] +
                                C.ABSO1[ID - 1] * C.DENSIM[ID - 1])
                for II in range(1, C.NLVEXP + 1):
                    DSFP1D[II] = -E0 * C.DABP1[II, ID - 1]
    # C
    if C.IRDER == 1 or C.IRDER == 3:
        C.DSFDT[ID] = DSFT1 * C.ALI1[ID]
        C.DSFDN[ID] = DSFN1 * C.ALI1[ID]
    if C.IRDER > 1:
        for II in range(1, C.NLVEXP + 1):
            C.DSFDP[II, ID] = DSFP1[II] * C.ALI1[ID]

    if C.IRDER == 1 or C.IRDER == 3:
        C.DSFDTM[ID] = DSFT1M * C.ALIM1[ID]
        C.DSFDNM[ID] = DSFN1M * C.ALIM1[ID]
        C.DSFDTP[ID] = DSFT1P * C.ALIP1[ID]
        C.DSFDNP[ID] = DSFN1P * C.ALIP1[ID]
    if C.IRDER > 1:
        for II in range(1, C.NLVEXP + 1):
            C.DSFDPM[II, ID] = DSFP1M[II] * C.ALIM1[ID]
            C.DSFDPP[II, ID] = DSFP1P[II] * C.ALIP1[ID]
    # c
    # c     Hydrostatic equilibrium equation
    # c
    if LNSKIP:
        D0 = WW * C.FAK1[ID]
        A0 = WW * C.FAK1[ID - 1]
        C.FPRD[ID] = C.FPRD[ID] + D0 * C.RAD1[ID] - A0 * C.RAD1[ID - 1]
        F0 = D0 * C.ALIP1[ID]
        E0 = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
        D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
        C.HEIT[ID] = C.HEIT[ID] + D0 * DSFT1
        C.HEIN[ID] = C.HEIN[ID] + D0 * DSFN1
        C.HEITM[ID] = C.HEITM[ID] + E0 * DSFT1M
        C.HEINM[ID] = C.HEINM[ID] + E0 * DSFN1M
        for II in range(1, C.NLVEXP + 1):
            C.HEIP[II, ID] = C.HEIP[II, ID] + D0 * DSFP1[II]
            C.HEIPM[II, ID] = C.HEIPM[II, ID] + E0 * DSFP1M[II]
        if C.IFALI >= 7:
            C.HEITP[ID] = C.HEITP[ID] + F0 * DSFT1P
            C.HEINP[ID] = C.HEINP[ID] + F0 * DSFN1P
            for II in range(1, C.NLVEXP + 1):
                C.HEIPP[II, ID] = C.HEIPP[II, ID] + F0 * DSFP1P[II]
            A0M = A0 * C.ALIM1[ID - 1]
            C.EHET[ID] = C.EHET[ID] - A0M * DSFTMM
            C.EHEN[ID] = C.EHEN[ID] - A0M * DSFNMM
            # TODO(port): EHEP 维度 (MLVEX3,MDEPTH)，II 循环到 NLVEXP 的疑点同前。
            for II in range(1, C.NLVEXP + 1):
                C.EHEP[II, ID] = C.EHEP[II, ID] - A0M * DSFPMM[II]
        if C.IBC >= 3:
            C.HEITM[ID] = C.HEITM[ID] - D0 * DSFT1D
            C.HEINM[ID] = C.HEINM[ID] - D0 * DSFN1D
            for II in range(1, C.NLVEXP + 1):
                C.HEIPM[II, ID] = C.HEIPM[II, ID] - D0 * DSFP1D[II]
    # C
    # C     Differential equation part of radiative equilibrium
    # C
    DDT = UN / (C.ABSOT[ID] + C.ABSOT[ID - 1])
    DT = DDT / C.DELDMZ[ID - 1]
    FL = (C.RAD1[ID] * C.FAK1[ID] - C.RAD1[ID - 1] * C.FAK1[ID - 1]) * DT
    C.FLFIX[ID] = C.FLFIX[ID] + WW * FL
    if C.REDIF[ID] > 0:
        D0 = WW * C.FAK1[ID] * DT
        A0 = WW * C.FAK1[ID - 1] * DT
        D0M = D0 * C.ALIM1[ID] - A0 * C.ALI1[ID - 1]
        D0P = D0 * C.ALIP1[ID]
        D0 = D0 * C.ALI1[ID] - A0 * C.ALIP1[ID - 1]
        E0 = WW * FL * DDT
        C.REDX[ID] = C.REDX[ID] + E0 * C.ABSO1[ID]
        C.REDXM[ID] = C.REDXM[ID] + E0 * C.ABSO1[ID - 1]
        E0M = E0 * C.DENSI[ID - 1]
        E0 = E0 * C.DENSI[ID]
        C.REDT[ID] = C.REDT[ID] + D0 * DSFT1 - E0 * C.DABT1[ID]
        C.REDTM[ID] = C.REDTM[ID] + D0M * DSFT1M - E0M * C.DABT1[ID - 1]
        C.REDN[ID] = C.REDN[ID] + D0 * DSFN1 - E0 * C.DABN1[ID]
        C.REDNM[ID] = C.REDNM[ID] + D0M * DSFN1M - E0M * C.DABN1[ID - 1]
        for II in range(1, C.NLVEXP + 1):
            C.REDP[II, ID] = C.REDP[II, ID] + D0 * DSFP1[II] - \
                E0 * C.DABP1[II, ID]
            C.REDPM[II, ID] = C.REDPM[II, ID] + D0M * DSFP1M[II] - \
                E0M * C.DABP1[II, ID - 1]
        if C.IFALI >= 7:
            # 原代码为 REDTP(ID)=REDTP(ID)+D0P*DSFT1M（DSFT1M 而非 DSFT1P，
            # 疑似原作者笔误，直译保留）
            C.REDTP[ID] = C.REDTP[ID] + D0P * DSFT1M
            C.REDNP[ID] = C.REDNP[ID] + D0P * DSFN1M
            for II in range(1, C.NLVEXP + 1):
                C.REDPP[II, ID] = C.REDPP[II, ID] + D0P * DSFP1P[II]
            A0M = A0 * C.ALIM1[ID - 1]
            C.ERET[ID] = C.ERET[ID] - A0M * DSFTMM
            C.EREN[ID] = C.EREN[ID] - A0M * DSFNMM
            # TODO(port): EREP 维度 (MLVEX3,MDEPTH)，II 循环到 NLVEXP 的疑点同前。
            for II in range(1, C.NLVEXP + 1):
                C.EREP[II, ID] = C.EREP[II, ID] - A0M * DSFPMM[II]
        if C.IBC >= 3:
            C.REDTM[ID] = C.REDTM[ID] + D0 * DSFT1D
            C.REDNM[ID] = C.REDNM[ID] + D0 * DSFN1D
            for II in range(1, C.NLVEXP + 1):
                C.REDPM[II, ID] = C.REDPM[II, ID] + D0 * DSFP1D[II]
    # c
    # C     Integral equation part of the radiative equilibrium
    # C
    if C.REINT[ID] > 0:
        if C.ILMCOR != 3:
            if C.ILASCT == 0:
                ABST = C.ABSO1[ID] - C.ELSCAT[ID]
                WWK = WW * ABST
                C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] -
                                                    ABST * C.RAD1[ID])
                D0 = WW * (C.ALI1[ID] - UN) * ABST
                E0 = WW * (C.RAD1[ID] - S0)
                C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + \
                    E0 * (C.DABN1[ID] - C.SIGEC[ij])
            else:
                SRH = SIGE * C.DENS1[ID]
                ABST = C.ABSO1[ID]
                ABSTE = ABST - C.ELSCAT[ID]
                WWK = WW * ABST
                C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] -
                                                    ABSTE * C.RAD1[ID])
                D0 = WW * (ABSTE * C.ALI1[ID] - ABST)
                E0 = WW * (C.RAD1[ID] - S0)
                C.REIN[ID] = C.REIN[ID] + D0 * DSFN1 + E0 * C.DABN1[ID] - \
                    WW * C.SIGEC[ij] * C.RAD1[ID]
            if C.IBC == 0:
                C.REIT[ID] = C.REIT[ID] + D0 * DSFT1 + E0 * C.DABT1[ID]
            else:
                # TODO(port): DBDT 仅在 IF(IBC.GT.0.AND.IDISK.EQ.0) 块内赋值；
                # 未赋值时 Fortran 取残留值，Python 同一次调用内亦保留旧值，
                # 但首次使用前未赋值将抛 NameError（见 ALIFR1 主分支同名注释）。
                C.REIT[ID] = C.REIT[ID] + D0 * (DSFT1 - DBDT) + E0 * C.DABT1[ID] + \
                    C.ALI1[ID] / ABST * DBDT
            for II in range(1, C.NLVEXP + 1):
                C.REIP[II, ID] = C.REIP[II, ID] + D0 * DSFP1[II] + \
                    E0 * C.DABP1[II, ID]
        else:
            ABST = C.ABSO1[ID] - C.ELSCAT[ID]
            D0 = ABST * C.ALI1[ID]
            C.FCOOLI[ID] = C.FCOOLI[ID] + WW * (C.EMIS1[ID] - ABST * C.RAD1[ID])
            C.REIN[ID] = C.REIN[ID] + WW * (D0 * DSFN1 +
                                            C.RAD1[ID] * (C.DABN1[ID] - C.SIGEC[ij]) -
                                            C.DEMN1[ID])
            for II in range(1, C.NLVEXP + 1):
                C.REIP[II, ID] = C.REIP[II, ID] + WW * (D0 * DSFP1[II] +
                                                       C.RAD1[ID] * C.DABP1[II, ID] -
                                                       C.DEMP1[II, ID])
            if C.IBC == 0:
                C.REIT[ID] = C.REIT[ID] + WW * (D0 * DSFT1 +
                                                C.RAD1[ID] * C.DABT1[ID] - C.DEMT1[ID])
            else:
                # TODO(port): DBDT/E0 的赋值条件同上；此处 E0 取自前面
                # REDIF/LNSKIP 块的残留值（Fortran 语义，Python 同一次调用内
                # 同样保留），DBDT 的疑点同前。
                C.REIT[ID] = C.REIT[ID] + WW * (D0 * (DSFT1 - DBDT) +
                                                E0 * C.DABT1[ID] +
                                                C.RAD1[ID] * C.DABT1[ID] - C.DEMT1[ID] +
                                                C.ALI1[ID] / ABST * DBDT)
        # c
        # c       the following are needed only for tridiagonal Lambda^star
        # C
        # C       Lower sub-diagonal band
        # C
        # TODO(port): ILMCOR==3 分支中 WWK 未赋值（同前 TODO）。
        WWKA = WWK * C.ALIM1[ID]
        C.AREIT[ID] = C.AREIT[ID] + WWKA * DSFT1M
        C.AREIN[ID] = C.AREIN[ID] + WWKA * DSFN1M
        for II in range(1, C.NLVEXP + 1):
            C.AREIP[II, ID] = C.AREIP[II, ID] + WWKA * DSFP1M[II]

    return


