if '_save_opadd_T' not in globals():
    _save_opadd_T = 0.0
    _save_opadd_DELTAT = 0.0
    _save_opadd_ANE = 0.0
    _save_opadd_HKT = 0.0
    _save_opadd_T32 = 0.0
    _save_opadd_XHM = 0.0
    _save_opadd_POPI = 0.0
    _save_opadd_SB00 = 0.0
    _save_opadd_AH = 0.0
    _save_opadd_AHP = 0.0
    _save_opadd_AHE = 0.0


def alifrk(ij):
    """Simplified routine ALIFR1 for a Kantorovich iteration

    hydrostatic and radiative equilibrium quantities -
    derivatives of the total heating and cooling rates in the
    ALI points with respect to the
    temperature, electron density, and populations

    对应 tlusty208.f 行 22047–22097
    """
    wfl = np.zeros(MDEPTH + 1)          # DIMENSION WFL(MDEPTH)，1 基索引
    if C.IFALI <= 1:
        return
    ww = C.WC[ij]

    # **** Special expressions for the first depth  -  id=1

    id = 1
    lnskip = not C.LSKIP[id, ij]
    wf = ww * (C.FH[ij] * C.RAD1[id] - C.HEXTRD[ij])
    if lnskip:
        C.FPRD[id] = C.FPRD[id] + wf * C.ABSO1[id]
    C.FLFIX[id] = C.FLFIX[id] + wf
    C.FLRD[id] = C.FLRD[id] + C.W[ij] * (C.FH[ij] * C.RAD1[id] - HALF * C.EXTRAD[ij])
    if C.REINT[id] > 0:
        abst = C.ABSO1[id] - C.SCAT1[id]
        C.FCOOLI[id] = C.FCOOLI[id] + ww * (C.EMIS1[id] - abst * C.RAD1[id])

    # Loop over depths

    for id in range(2, C.ND + 1):
        lnskip = not C.LSKIP[id, ij]
        dt = UN / ((C.ABSOT[id] + C.ABSOT[id - 1]) * C.DELDMZ[id - 1])
        fl = C.RAD1[id] * C.FAK1[id] - C.RAD1[id - 1] * C.FAK1[id - 1]
        wfl[id] = ww * fl
        if lnskip:
            C.FPRD[id] = C.FPRD[id] + wfl[id]
        C.FLFIX[id] = C.FLFIX[id] + wfl[id] * dt
        C.FLRD[id] = C.FLRD[id] + fl * C.W[ij] * dt
        if C.REINT[id] > 0:
            abst = C.ABSO1[id] - C.SCAT1[id]
            C.FCOOLI[id] = C.FCOOLI[id] + ww * (C.EMIS1[id] - abst * C.RAD1[id])

    return


def emat(id):
    """Auxiliary procedure for SOLVE

    sub-sub-diagonal band matrix E

    Input:  ID - depth index

    对应 tlusty208.f 行 22103–22141
    """
    if C.IFALI <= 7:
        return

    if id <= 2:
        return
    nse = C.NFREQE + C.INSE - 1
    if C.INHE > 0:
        nhe = C.NFREQE + C.INHE
        if C.INRE > 0:
            C.E[nhe, C.NFREQE + C.INRE] = C.EHET[id] * PCK
        if C.INPC > 0:
            C.E[nhe, C.NFREQE + C.INPC] = C.EHEN[id] * PCK
        for ii in range(1, C.NLVEXP + 1):
            # TODO(port): EHEP 声明维度为 EHEP(MLVEX3,MDEPTH) 且 MLVEX3=1，
            # 而循环 II=1..NLVEXP 会越出第一维；Fortran 会读入 /FIXALP/ 中
            # 相邻存储，Python 下若执行到此路径将抛 IndexError。按原样直译。
            C.E[nhe, nse + ii] = C.EHEP[ii, id] * PCK

    if C.INRE > 0 and C.REDIF[id] > 0.0:
        nre = C.NFREQE + C.INRE
        if C.INRE > 0:
            C.E[nre, nre] = C.ERET[id] * C.REDIF[id]
        if C.INPC > 0:
            C.E[nre, C.NFREQE + C.INPC] = C.EREN[id] * C.REDIF[id]
        for ii in range(1, C.NLVEXP + 1):
            # TODO(port): EREP 维度问题同上面 EHEP。
            C.E[nre, nse + ii] = C.EREP[ii, id] * C.REDIF[id]
    return


def rhsgen(id):
    """Auxiliary procedure for SOLVE
    controls evaluation of rhs vector when
    matrices A,B, and C are kept fixed.

    Input:  ID - depth index

    对应 tlusty208.f 行 22147–22868
    """
    XCON = 8.0935e-21                     # PARAMETER (XCON=8.0935D-21,YCON=1.68638E-10)
    YCON = 1.68638e-10
    SIXTH = UN / 6.0                      # PARAMETER (SIXTH=UN/6.D0, THIRD=UN/3.D0)
    THIRD = UN / 3.0
    popp = np.zeros(MLEVEL + 1)           # DIMENSION POPP(MLEVEL)，1 基索引
    # COMMON/CUBCON/ACNV,BCNV,DEL,GRDADB,DELMDE,RHO,FLXTOT,GRAVD
    # → 本例程只写 GRAVD（C.GRAVD）

    # TODO(port): PR1 在 IBCHE=1 分支被引用却从未在本例程赋值
    # （IBCHE=2 分支才赋值；Fortran 中为未初始化局部量），此处按 0 初始化。
    pr1 = 0.0
    # TODO(port): 标号 50（正常深度点）的 IJ 循环内调用 COMPT0 时使用了
    # 未在本循环赋值的 IJT（Fortran 静态存储下为上次循环/调用的残留值），
    # 疑似原代码漏写 IJT=IJFR(IJ)。此处初始化为 0，仅近似其静态语义。
    ijt = 0

    ispl = C.ISPLIN
    if C.ISPLIN >= 5:
        C.ISPLIN = C.ISPLIN - 5
    ij1 = 1

    # in the case of Compton scattering - boundary condition
    # for the highest frequency

    if C.icompt > 0 and C.icombc > 0 and C.IJEX[1] > 0:
        ij1 = 2
        ij = 1
        iji = C.NFREQ
        zj1 = math.exp(-HK * C.FREQ[ij] / C.TEMP[id])
        zj2 = math.exp(-HK * C.FREQ[ij + 1] / C.TEMP[id])
        dlt = C.DELJ[iji - 1, id]
        if C.ichcoo == 0:
            zj0 = UN / (HK * math.sqrt(C.FREQ[ij] * C.FREQ[ij + 1]) / C.TEMP[id])
            zxx = UN - 3.0 * zj0 + (UN - dlt) * zj1 + dlt * zj2
            combid = zj0 / C.DLNFR[iji - 1] + (UN - dlt) * zxx
            comaid = -zj0 / C.DLNFR[iji - 1] + dlt * zxx
        else:
            e2 = YCON * C.TEMP[id]
            zxx0 = XCON * C.FREQ[ij] * (UN + zj1) - 3.0 * e2
            zxxm = XCON * C.FREQ[ij + 1] * (UN + zj2) - 3.0 * e2
            zxx = (UN - dlt) * zxx0 + dlt * zxxm
            combid = e2 / C.DLNFR[iji - 1] + (UN - dlt) * zxx
            comaid = -e2 / C.DLNFR[iji - 1] + dlt * zxx
        C.VECL[ij] = -combid * C.RAD[iji, id] - comaid * C.RAD[iji - 1, id]

    # evaluation of the opacity, emissivity, scattering, and
    # their derivatives, at the current depth point ID;

    for i in range(1, C.NN + 1):
        C.PSI0[i] = C.PSY0[i, id]
    if C.NFREQE > 0:
        for ij in range(1, C.NFREQE + 1):
            ijt = C.IJFR[ij]
            C.WDEP0[ij] = C.W[ijt]
            C.RAD0[ij] = C.RADEX[ij, id]
            C.FK0[ij] = C.FAKEX[ij, id]
            C.ABSO0[ij] = C.ABSOEX[ij, id]
            C.EMIS0[ij] = C.EMISEX[ij, id]
            C.SCAT0[ij] = C.SCATEX[ij, id]

    if id > 1:
        for i in range(1, C.NN + 1):
            C.PSIM[i] = C.PSY0[i, id - 1]
        if C.NFREQE > 0:
            for ij in range(1, C.NFREQE + 1):
                ijt = C.IJFR[ij]
                C.RADM[ij] = C.RADEX[ij, id - 1]
                C.FKM[ij] = C.FAKEX[ij, id - 1]
                C.ABSOM[ij] = C.ABSOEX[ij, id - 1]
                C.EMISM[ij] = C.EMISEX[ij, id - 1]
                C.SCATM[ij] = C.SCATEX[ij, id - 1]

    if id < C.ND:
        for i in range(1, C.NN + 1):
            C.PSIP[i] = C.PSY0[i, id + 1]
        if C.NFREQE > 0:
            for ij in range(1, C.NFREQE + 1):
                ijt = C.IJFR[ij]
                C.RADP[ij] = C.RADEX[ij, id + 1]
                C.FKP[ij] = C.FAKEX[ij, id + 1]
                C.ABSOP[ij] = C.ABSOEX[ij, id + 1]
                C.EMISP[ij] = C.EMISEX[ij, id + 1]
                C.SCATP[ij] = C.SCATEX[ij, id + 1]

    # ------------------------------------------------------------
    # Actual evaluation of the rhs vector VECL
    # ------------------------------------------------------------

    for i in range(1, C.NN + 1):
        C.VECL[i] = 0.0

    # IF(NFREQE.LE.0) GO TO 100
    if C.NFREQE > 0:
        # -----------------------------------------------------------
        # 1. Radiative transfer components
        # -----------------------------------------------------------

        # For  ID = 1  -  upper boundary condition
        # IF(ID.GT.1) GO TO 50
        if id == 1:
            ddp = C.DELDMZ[1]
            for ij in range(1, C.NFREQE + 1):
                ijt = C.IJFR[ij]
                if C.IZSCAL == 0:
                    omeg0 = C.ABSO0[ij] / C.DENS[id]
                    omegp = C.ABSOP[ij] / C.DENS[id + 1]
                else:
                    omeg0 = C.ABSO0[ij]
                    omegp = C.ABSOP[ij]
                dzp = omeg0 + omegp
                dtaup = dzp * ddp
                alf1 = (C.FK0[ij] * C.RAD0[ij] - C.FKP[ij] * C.RADP[ij]) / dtaup
                chiel0 = C.SCAT0[ij]
                chielp = C.SCATP[ij]
                s0 = (C.EMIS0[ij] + chiel0 * C.RAD0[ij]) / C.ABSO0[ij]
                bs = HALF * dtaup
                cs = 0.0
                c2 = 0.0
                sp = 0.0
                bet2 = 0.0
                gam2 = 0.0

                # additional terms for Compton scattering

                if C.icompt > 0:
                    # COMPT0 给标量哑元 compa..compd 赋值 → 按约定解包全部标量
                    cma = cmb = cmc = cme = cms = cmd = 0.0
                    ijt, id, _ab, cma, cmb, cmc, cme, cms, cmd = compt0(
                        ijt, id, C.ABSO0[ij], cma, cmb, cmc, cme, cms, cmd)
                    s0 = s0 + cms

                if C.ISPLIN > 0:
                    # Spline collocation and/or Hermitian method (ISPLIN=1 or 2) -
                    # both give the same expression for the boundary conditions
                    bs = dtaup * THIRD
                    cs = HALF * bs
                    sp = (C.EMISP[ij] + chielp * C.RADP[ij]) / C.ABSOP[ij]
                    c2 = cs / C.ABSOP[ij]
                    gam2 = cs * (C.RADP[ij] - sp)

                # auxiliary quantities

                alf2 = bs * (C.RAD0[ij] - s0)
                bet2 = alf2 + gam2

                # *** the IJ-th element of the rhs vector

                C.VECL[ij] = alf1 + bet2 + C.FH[ijt] * C.RAD0[ij] - s0 * C.Q0[ijt]
                if C.IWINBL < 0:
                    C.VECL[ij] = C.VECL[ij] - C.HEXTRD[ijt]
            # GO TO 100

        # For  1 < ID < ND  -  normal depth point
        # 标号 50
        elif id < C.ND:                       # IF(ID.EQ.ND) GO TO 80
            ddm = C.DELDMZ[id - 1]
            ddp = C.DELDMZ[id]
            for ij in range(1, C.NFREQE + 1):
                if C.IZSCAL == 0:
                    omeg0 = C.ABSO0[ij] / C.DENS[id]
                    omegp = C.ABSOP[ij] / C.DENS[id + 1]
                    omegm = C.ABSOM[ij] / C.DENS[id - 1]
                else:
                    omeg0 = C.ABSO0[ij]
                    omegp = C.ABSOP[ij]
                    omegm = C.ABSOM[ij]
                dzp = omeg0 + omegp
                dzm = omeg0 + omegm
                dtaup = dzp * ddp
                dtaum = dzm * ddm
                dtau0 = HALF * (dtaup + dtaum)
                frd = C.FK0[ij] * C.RAD0[ij]
                alf1 = (frd - C.FKP[ij] * C.RADP[ij]) / dtaup / dtau0
                gam1 = (frd - C.FKM[ij] * C.RADM[ij]) / dtaum / dtau0
                bet1 = alf1 + gam1
                bs = UN
                chielm = C.SCATM[ij]
                chiel0 = C.SCAT0[ij]
                chielp = C.SCATP[ij]
                s0 = (C.EMIS0[ij] + chiel0 * C.RAD0[ij]) / C.ABSO0[ij]
                bet2 = 0.0

                # additional terms for Compton scattering

                if C.icompt > 0:
                    # COMPT0 给标量哑元赋值 → 解包全部标量；
                    # 注意此处 IJT 为残留值（见函数顶部 TODO）
                    cma = cmb = cmc = cme = cms = cmd = 0.0
                    ijt, id, _ab, cma, cmb, cmc, cme, cms, cmd = compt0(
                        ijt, id, C.ABSO0[ij], cma, cmb, cmc, cme, cms, cmd)
                    s0 = s0 + cms

                if C.ISPLIN == 1:
                    # spline collocation (ISPLIN=1)
                    a_s = dtaum / dtau0 * SIXTH
                    cs = dtaup / dtau0 * SIXTH
                    bs = 0.666666666666667
                    sm = (C.EMISM[ij] + C.RADM[ij] * chielm) / C.ABSOM[ij]
                    sp = (C.EMISP[ij] + C.RADP[ij] * chielp) / C.ABSOP[ij]
                    alf2 = a_s * (C.RADM[ij] - sm)
                    gam2 = cs * (C.RADP[ij] - sp)
                    bet2 = alf2 + gam2
                elif C.ISPLIN == 2:
                    # Hermitian method (ISPLIN=2)
                    a_s = dtaup * dtaup / dtaum / dtau0
                    cs = dtaum * dtaum / dtaup / dtau0
                    sm = (C.EMISM[ij] + C.RADM[ij] * chielm) / C.ABSOM[ij]
                    sp = (C.EMISP[ij] + C.RADP[ij] * chielp) / C.ABSOP[ij]
                    a_s = (UN - HALF * a_s) * SIXTH
                    cs = (UN - HALF * cs) * SIXTH
                    bs = UN - a_s - cs
                    bet2 = a_s * (C.RADM[ij] - sm) + cs * (C.RADP[ij] - sp)

                # *** the IJ-th element of the rhs vector

                C.VECL[ij] = bet1 + bet2 + bs * (C.RAD0[ij] - s0)
            # GO TO 100

        # For ID=ND  -  lower boundary condition
        # 标号 80
        else:
            # 标号 50 处的 DDM=DELDMZ(ID-1) 在 GO TO 80 之前执行，此处补齐
            ddm = C.DELDMZ[id - 1]
            t = C.TEMP[id]
            if C.TEMPBD > 0.0:
                t = C.TEMPBD
            hkt = HK / t

            # the case of stellar atmospheres

            if C.IDISK == 0 or C.IFZ0 < 0:
                # 1. the case NDRE.le.ND, ie. radiative equilibrium equation at this
                #    depth is treated as differential equation.
                #
                # 2. the case NDRE > ND, ie. radiative equilibrium equation at this
                #    depth is treated as integral equation.
                #    Boundary condition of the transfer equation is then complex,
                #    because it has to incorporate the constraint of the total flux
                #    equal to SIG4P*Teff**4 (integral form of the radiative
                #    equation does not fix the total flux)
                #
                #    Details of this approach are presented in Mihalas, Heasley, Auer
                #    NCAR-TN/STR-104 (1975).
                #
                #    This option is presented here for the sake of continuity with
                #    previous work; otherwise the first option (NDRE.le.ND) is
                #    recommended due to its better numerical properties
                #
                #    auxiliary quantities for the second option

                if id < C.NDRE and C.INRE != 0:
                    sumb = 0.0
                    sumf = 0.0
                    for ij in range(1, C.NFREQE + 1):
                        ijt = C.IJFR[ij]
                        fr = C.FREQ[ijt]
                        fr15 = fr * 1.0e-15
                        wd = C.WDEP0[ij]
                        x = hkt * fr
                        ex = math.exp(x)
                        plan = BN * fr15 * fr15 * fr15 / (ex - UN) * C.RRDIL
                        dplan = plan * x / t / (UN - UN / ex) * wd
                        sumb = sumb + (plan - C.RAD0[ij]) * wd
                        fi = dplan / C.ABSO0[ij]
                        sumf = sumf + fi
                    fl = SIG4P * C.TEFF * C.TEFF * C.TEFF * C.TEFF
                    zz = (fl - HALF * sumb) / sumf

                # auxiliary quantities for both options

                for ij in range(1, C.NFREQE + 1):
                    ijt = C.IJFR[ij]
                    chielm = C.SCATM[ij]
                    chiel0 = C.SCAT0[ij]
                    if C.IZSCAL == 0:
                        omeg0 = C.ABSO0[ij] / C.DENS[id]
                        omegm = C.ABSOM[ij] / C.DENS[id - 1]
                    else:
                        omeg0 = C.ABSO0[ij]
                        omegm = C.ABSOM[ij]
                    dzm = omeg0 + omegm
                    dtaum = dzm * ddm
                    gam1 = (C.FK0[ij] * C.RAD0[ij] - C.FKM[ij] * C.RADM[ij]) / dtaum
                    bet2 = 0.0

                    # second-order boundary condition

                    if C.IBC > 0 and C.IBC < 4:
                        bs = dtaum * HALF
                        s0 = (C.EMIS0[ij] + chiel0 * C.RAD0[ij]) / C.ABSO0[ij]

                        # additional terms for Compton scattering

                        if C.icompt > 0:
                            cma = cmb = cmc = cme = cms = cmd = 0.0
                            ijt, id, _ab, cma, cmb, cmc, cme, cms, cmd = compt0(
                                ijt, id, C.ABSO0[ij], cma, cmb, cmc, cme, cms, cmd)
                            s0 = s0 + cms

                        bet2 = bs * (C.RAD0[ij] - s0)

                    fr = C.FREQ[ijt]
                    x = hkt * fr
                    ex = math.exp(x)
                    plan = BN * (fr * 1.0e-15) ** 3 / (ex - UN) * C.RRDIL
                    if C.INRE == 0 or id >= C.NDRE:
                        dplan = BN * (fr * 1.0e-15) ** 3 / (math.exp(HK * fr / C.TEMP[id - 1]) - UN)
                        gam1 = gam1 - (plan - dplan) / dtaum * THIRD
                    else:
                        dplan = plan * x / t / (UN - UN / ex)
                        fi = dplan / C.ABSO0[ij]
                        x1 = fi * zz
                        gam1 = gam1 - x1

                    # *** the IJ-th element of the rhs vector

                    if C.IBC == 0 or C.IBC == 4:
                        C.VECL[ij] = gam1 + bet2 - HALF * (plan - C.RAD0[ij])
                    else:
                        C.VECL[ij] = gam1 + bet2 - HALF * plan + C.FHD[ijt] * C.RAD0[ij]

            # the case of accretion disks

            else:
                for ij in range(ij1, C.NFREQE + 1):
                    chielm = C.SCATM[ij]
                    chiel0 = C.SCAT0[ij]
                    if C.IZSCAL == 0:
                        omeg0 = C.ABSO0[ij] / C.DENS[id]
                        omegm = C.ABSOM[ij] / C.DENS[id - 1]
                    else:
                        omeg0 = C.ABSO0[ij]
                        omegm = C.ABSOM[ij]
                    dzm = omeg0 + omegm
                    dtaum = dzm * ddm
                    frd = C.FK0[ij] * C.RAD0[ij] - C.FKM[ij] * C.RADM[ij]
                    gam1 = frd / dtaum
                    bs = dtaum * HALF
                    s0 = (C.EMIS0[ij] + chiel0 * C.RAD0[ij]) / C.ABSO0[ij]
                    gam2 = bs * (C.RAD0[ij] - s0)

                    # *** the IJ-th element of the rhs vector

                    C.VECL[ij] = gam1 + gam2

    # -----------------------------------------------------------
    # 2. Hydrostatic equilibrium
    # -----------------------------------------------------------

    # 标号 100：GO TO 100 的目标
    C.ISPLIN = ispl
    if C.INHE != 0:                           # IF(INHE.EQ.0) GO TO 170
        nhe = C.NFREQE + C.INHE
        grd = 0.0

        if id == 1:
            # Upper boundary condition (ID=1)
            # Basically, linearized eq. (7-10) of Mihalas (1978)

            if C.IDISK == 0 or C.ibche == 0:
                if C.NFREQE > 0:
                    for ij in range(1, C.NFREQE + 1):
                        ijt = C.IJFR[ij]
                        if not C.LSKIP[id, ijt]:
                            fluxw = C.W[ijt] * C.FH[ijt] * C.RAD0[ij]
                            grd = grd + fluxw * C.ABSO0[ij]

                x1 = PCK / C.DENS[id]
                vt0 = HALF * C.VTURB[id] * C.VTURB[id] / C.DM[id] * C.WMM[id]

                # The rhs vector also accounts for the total radiation pressure in
                # the fixed-option transitions (array FPRD, generated by FIXLIN)

                C.VECL[nhe] = (C.GRAV - BOLK * C.TEMP[id] * C.PSI0[nhe] / C.DM[id]
                               - x1 * (grd + C.FPRD[id])
                               - vt0 / C.WMM[id] * C.DENS[id])

            else:
                if C.ibche == 1:
                    # specifically disk - newer variant
                    ccc = PCK / C.QGRAV
                    hr1 = ccc * SIG4P * C.TEFF ** 4 * C.ABROSD[1]  # 原代码计算后未使用
                    pg1 = BOLK * C.PSI0[nhe] * C.TEMP[1]
                    hg1 = math.sqrt(TWO * pg1 / C.DENS[1] / C.QGRAV)
                    x = (C.ZD[1] - pr1) / hg1   # TODO(port): pr1 未赋值（见函数顶部）
                    if x < 3.0:
                        if x < 0.0:
                            x = 0.0
                        f1 = 8.86226925e-1 * math.exp(x * x) * erfcx(x)
                    else:
                        f1 = HALF * (UN - HALF / x / x) / x
                    ggg = C.DENS[1] * hg1 * f1
                    C.VECL[nhe] = C.DM[1] - ggg

                # specifically disk - older variant

                elif C.ibche == 2:
                    if C.NFREQE > 0:
                        for ij in range(ij1, C.NFREQE + 1):
                            ijt = C.IJFR[ij]
                            if not C.LSKIP[id, ijt]:
                                fluxw = C.W[ijt] * C.FH[ijt] * C.RAD0[ij]
                                grd = grd + fluxw * C.ABSO0[ij]

                    ccc = PCK / C.QGRAV
                    pr1 = ccc * (grd + C.FPRD[1]) / C.DENS[1]
                    pg1 = BOLK * C.PSI0[nhe] * C.TEMP[1]
                    hg1 = math.sqrt(TWO * pg1 / C.DENS[1] / C.QGRAV)
                    x = (C.ZD[1] - pr1) / hg1
                    if x < 3.0:
                        if x < 0.0:
                            x = 0.0
                        f1 = 8.86226925e-1 * math.exp(x * x) * erfcx(x)
                    else:
                        f1 = HALF * (UN - HALF / x / x) / x
                    ggg = hg1 * C.QGRAV * HALF / f1

                    # The rhs vector

                    C.VECL[nhe] = C.DM[1] * ggg - pg1
                else:
                    C.VECL[nhe] = C.pgas0 - BOLK * C.TEMP[1] * C.PSI0[nhe]

        else:
            # Normal depth point (ID > 1)

            if C.NFREQE > 0:
                for ij in range(1, C.NFREQE + 1):
                    if not C.LSKIP[id, C.IJFR[ij]]:
                        grd = grd + (C.FK0[ij] * C.RAD0[ij] - C.FKM[ij] * C.RADM[ij]) * C.W[C.IJFR[ij]]

            vt0 = HALF * C.VTURB[id] * C.VTURB[id] * C.WMM[id]
            vtm = HALF * C.VTURB[id - 1] * C.VTURB[id - 1] * C.WMM[id - 1]

            # the rhs vector
            # again, which accounts for the total radiation pressure in the
            # fixed-option transitions (array FPRD, generated by FIXLIN)

            if C.IDISK == 1:
                C.GRAV = C.QGRAV * (C.ZD[id] + C.ZD[id - 1]) * HALF
            if C.IZSCAL == 0:
                C.VECL[nhe] = (C.GRAV * (C.DM[id] - C.DM[id - 1])
                               - BOLK * (C.TEMP[id] * C.PSI0[nhe] - C.TEMP[id - 1] * C.PSIM[nhe])
                               - PCK * (grd + C.FPRD[id])
                               - vt0 / C.WMM[id] * C.DENS[id]
                               + vtm / C.WMM[id - 1] * C.DENS[id - 1])
            else:
                gravz = C.GRAV * (C.ZD[id] - C.ZD[id - 1])
                C.VECL[nhe] = (-gravz * (C.DENS[id] + C.DENS[id - 1]) * HALF
                               - BOLK * (C.TEMP[id] * C.PSI0[nhe] - C.TEMP[id - 1] * C.PSIM[nhe])
                               - PCK * (grd + C.FPRD[id])
                               - vt0 / C.WMM[id] * C.DENS[id]
                               + vtm / C.WMM[id - 1] * C.DENS[id - 1])

    # -----------------------------------------------------------
    # 2a. z-m relation
    # -----------------------------------------------------------

    # 标号 170：IF(INZD.LE.0.OR.ID.EQ.ND.OR.IDISK.EQ.0) GO TO 200
    if not (C.INZD <= 0 or id == C.ND or C.IDISK == 0):
        nzd = C.NFREQE + C.INZD
        ddp = (C.DM[id + 1] - C.DM[id]) * HALF
        C.VECL[nzd] = C.ZD[id + 1] - C.ZD[id] + ddp / C.DENS[id] + ddp / C.DENS[id + 1]

    # -----------------------------------------------------------
    # 3. Radiative equilibrium
    # -----------------------------------------------------------

    # 标号 200
    if C.INRE != 0:                           # IF(INRE.EQ.0) GO TO 250
        nre = C.NFREQE + C.INRE

        ittc = idiv(abs(C.NRETC), 100)        # Fortran 整数除法 abs(nretc)/100
        # if(iter.gt.ittc) / if(id.le.mod(...)) / go to 250 → 用 skip 标志重构
        skip_to_250 = False
        if C.ITER > ittc:
            if id <= imod(abs(C.NRETC), 100):
                if C.NRETC < 0:
                    C.VECL[nre] = C.TEMP[id + 1] - C.TEMP[id]
                skip_to_250 = True            # GO TO 250
        if not skip_to_250:
            # integral equation part of the radiative
            # equilibrium equation

            # the rhs vector accounts for total net cooling in ALI transitions

            C.VECL[nre] = C.FCOOL[id]
            if C.IDISK == 1:
                C.VECL[nre] = C.FCOOL[id] - C.TVISC[id] * C.REINT[id]

            if C.REINT[id] > 0 and C.NFREQE > 0:
                for ij in range(1, C.NFREQE + 1):
                    heat = C.ABSO0[ij] - C.SCAT0[ij]
                    C.VECL[nre] = (C.VECL[nre]
                                   - (heat * C.RAD0[ij] - C.EMIS0[ij]) * C.WDEP0[ij] * C.REINT[id])

                    # additional terms for Compton scattering

                    if C.icompt > 5:
                        ijt = C.IJFR[ij]
                        cma = cmb = cmc = cme = cms = cmd = 0.0
                        ijt, id, _ab, cma, cmb, cmc, cme, cms, cmd = compt0(
                            ijt, id, C.ABSO0[ij], cma, cmb, cmc, cme, cms, cmd)
                        C.VECL[nre] = C.VECL[nre] + C.ABSO0[ij] * cms * C.WDEP0[ij] * C.REINT[id]

            # differential equation part of the
            # radiative equilibrium equation

            if C.REDIF[id] > 0:
                teffd = C.TEFF ** 4
                if C.IDISK == 1:
                    teffd = teffd * (UN - C.THETAV[id])
                C.VECL[nre] = C.VECL[nre] + SIG4P * teffd * C.REDIF[id]
                if id > 1:
                    ddm = (C.DM[id] - C.DM[id - 1]) * HALF
                    ddm = C.DELDMZ[id - 1]    # 原代码连续两次赋值，前一次为死代码
                    if C.NFREQE > 0:
                        for ij in range(1, C.NFREQE + 1):
                            omeg0 = C.ABSO0[ij] * C.DENSI[id]
                            omegm = C.ABSOM[ij] * C.DENSI[id - 1]
                            dtaum = (omeg0 + omegm) * ddm
                            frd = C.FK0[ij] * C.RAD0[ij] - C.FKM[ij] * C.RADM[ij]
                            gamr = frd / dtaum
                            C.VECL[nre] = C.VECL[nre] - C.WDEP0[ij] * gamr * C.REDIF[id]
                else:
                    if C.NFREQE > 0:
                        for ij in range(1, C.NFREQE + 1):
                            ijt = C.IJFR[ij]
                            C.VECL[nre] = (C.VECL[nre]
                                           - C.WDEP0[ij] * C.FH[ijt] * C.RAD0[ij] * C.REDIF[id])

    # -----------------------------------------------------------
    # 4. Statistical equilibrium
    # -----------------------------------------------------------

    # 标号 250
    if abs(C.IFPOPR) >= 3 and C.IFPOPR <= 5:
        if C.INSE > 0:
            nse = C.NFREQE + C.INSE - 1
            sabolf(id)                        # SABOLF 不修改标量哑元
            levgrp(id, C.iiexp, 0, popp)      # LEVGRP 只写数组哑元 POPP
            ratmat(id, C.iiexp, 0, C.ESEMAT, C.BESE)  # RATMAT 只写数组哑元 A、B
            if C.IFPOPR <= 3:
                matinv(C.ESEMAT, C.NLVEXP, MLEVEL)    # MATINV 不修改 N、NR
                for i in range(1, C.NLVEXP + 1):
                    sum_l = 0.0               # 原变量 SUM（避免遮蔽内建 sum）
                    for j in range(1, C.NLVEXP + 1):
                        sum_l = sum_l + C.ESEMAT[i, j] * C.BESE[j]
                    C.VECL[nse + i] = C.POPGRP[i] - sum_l
                    if C.IGZERO[i, id] > 0:
                        C.VECL[C.NFREQE + C.INSE - 1 + i] = 0.0
            else:
                for i in range(1, C.NLVEXP + 1):
                    sum_l = 0.0
                    for j in range(1, C.NLVEXP + 1):
                        sum_l = sum_l + C.ESEMAT[i, j] * C.POPGRP[j]
                    C.VECL[nse + i] = C.BESE[i] - sum_l
                    if C.IGZERO[i, id] > 0:
                        C.VECL[C.NFREQE + C.INSE - 1 + i] = 0.0

    # -----------------------------------------------------------
    # 5. charge conservation
    # -----------------------------------------------------------

    if C.INPC != 0:                           # IF(INPC.EQ.0) GO TO 400
        npc = C.NFREQE + C.INPC

        # This part is very similar to procedure ELCOR (obviously);
        # array AJ has the meaning of coefficients of the charge conserv.
        # ie. charge conservation is written
        #       AJ * (vector of populations) = electron density

        t = C.TEMP[id]
        ane = C.ELEC[id]
        # STATE 的 MODE=0 分支把标量哑元 ID 用作 DO 循环变量 → 按约定返回全部
        # 标量哑元 (mode, id, t, ane)，调用点解包接收（MODE=2 分支实际不改 T/ANE）
        _mode_s, id, t, ane = state(2, id, t, ane)

        vpc = C.QFIX[id] + C.Q * C.DENS[id] / C.WMM[id] / C.YTOT[id]
        if C.IOPTAB == 0:
            vpc = vpc * C.ABUND[C.iatref, id]
        for iat in range(1, C.NATOM + 1):
            if C.iifix[iat] != 1:
                for i in range(C.N0A[iat], C.NKA[iat] + 1):
                    il = C.ILK[i]
                    ch = C.IZ[C.IEL[i]] - 1
                    if il > 0:
                        ch = C.IZ[il] + (C.IZ[il] - 1) * ane * C.USUMS[il, id]
                    if C.imodl[i] >= 0:
                        vpc = vpc + ch * C.POPUL[i, id]

        C.VECL[npc] = ane - vpc

    # -----------------------------------------------------------
    # 6. Convection
    # -----------------------------------------------------------

    # 标号 400
    if C.HMIX0 > 0.0:
        nre = C.NFREQE + C.INRE
        ndel = C.NFREQE + C.INDL

        # Upper boundary condition (ID=1)

        anerel = C.ELEC[1] / (C.DENS[1] / C.WMM[1] + C.ELEC[1])  # 原代码计算后未使用
        if id == 1:
            C.DELTA[id] = 0.0
            C.FLXC[id] = 0.0
        else:
            # Normal depth point 1 < ID < ND

            t = C.TEMP[id]
            p = C.PTOTAL[id]
            pg = C.PGS[id]
            prad = p - pg - HALF * C.DENS[id] * C.VTURB[id] ** 2
            tm = C.TEMP[id - 1]
            pm = C.PTOTAL[id - 1]
            pgm = C.PGS[id - 1]
            pradm = pm - pgm - HALF * C.DENS[id - 1] * C.VTURB[id - 1] ** 2
            t0 = HALF * (t + tm)
            p0 = HALF * (p + pm)
            pg0 = HALF * (pg + pgm)
            pr0 = HALF * (prad + pradm)
            ab0 = HALF * (C.ABROSD[id] + C.ABROSD[id - 1])
            dlt = (t - tm) / (p - pm) * p0 / t0
            C.DELTA[id] = dlt
            if C.INDL > 0:
                C.VECL[ndel] = C.DELTA[id] - dlt
            if C.IDISK == 1:
                C.GRAVD = C.ZD[id] * C.QGRAV   # COMMON/CUBCON/ 的 GRAVD

            # convective flux

            # CONVEC 修改标量哑元 FLXCNV、VCONV → 按约定解包全部标量
            flxcnv = 0.0
            vcon = 0.0
            id, t0, p0, pg0, pr0, ab0, dlt, flxcnv, vcon = convec(
                id, t0, p0, pg0, pr0, ab0, dlt, flxcnv, vcon)
            C.FLXC[id] = flxcnv
            if C.REDIF[id] > 0:
                C.VECL[nre] = C.VECL[nre] - C.FLXC[id] * C.REDIF[id]

            if C.REINT[id] > 0 and C.ICONV <= 2:
                tp = C.TEMP[id + 1]
                pm = C.PTOTAL[id + 1]
                pgp = C.PGS[id + 1]
                pradp = pm - pgp - HALF * C.DENS[id + 1] * C.VTURB[id + 1] ** 2
                t0 = HALF * (t + tp)
                p0 = HALF * (p + pm)
                pg0 = HALF * (pg + pgp)
                pr0 = HALF * (prad + pradp)
                ab0 = HALF * (C.ABROSD[id] + C.ABROSD[id + 1])
                dlt = (tp - t) / (pm - p) * (pm + p) / (tp + t)
                # 实参 ID+1 为表达式 → 用 _idp 接收（CONVEC 不修改 ID）
                flxcp = 0.0
                vcon = 0.0
                _idp, t0, p0, pg0, pr0, ab0, dlt, flxcp, vcon = convec(
                    id + 1, t0, p0, pg0, pr0, ab0, dlt, flxcp, vcon)
                delm = (C.DM[id + 1] - C.DM[id]) * HALF
                rdelm = C.DENS[id] / delm
                C.VECL[nre] = C.VECL[nre] - rdelm * (flxcp - flxcnv) * C.REINT[id]

    # skip rows corresponding to fully-zeroed populations

    nse = C.NFREQE + C.INSE
    inonz = nse
    for ii in range(nse, C.NN0 + 1):
        if C.igzert[ii - nse + 1] == 0:
            if inonz != ii:
                C.VECL[inonz] = C.VECL[ii]
            inonz = inonz + 1

    return


def prchan(chang, chm, chmt):
    """Diagnostic output of relative changes of vector PSI

    Input:
     CHANG - array of relative changes of vector PSI at depth ID
     ID    - depth index
    Output:
     CHM   - maximum relative change of all unknowns at all depths
     CHMT  - maximum relative change in temperature at all depths

    对应 tlusty208.f 行 22876–22961

    修改标量哑元 CHM、CHMT → 按约定返回 (chm, chmt)（CHANG 为数组哑元，不返回）。
    """
    chanm = np.zeros(MDEPTH + 1)          # DIMENSION CHANM(MDEPTH)，1 基索引

    # maximum relative change of all unknowns in depth ID

    chmt = 0.0
    i1 = 1
    if C.icompt > 0 and C.icombc > 0 and C.IJEX[1] > 0:
        i1 = 2
    # TODO(port): JJP/JJR 在内层循环未执行时不被赋值（Fortran 中为残留值），
    # 此处先初始化为 0。
    jjp = 0
    jjr = 0
    for id in range(C.ND, 0, -1):         # DO ID=ND,1,-1
        ch = 0.0
        chrad = 0.0
        chpop = 0.0
        cht = 0.0
        che = 0.0
        for i in range(i1, C.NN + 1):     # DO 10 I=i1,NN
            if C.ITER == 1 and i == C.NFREQE + C.INDL:
                continue                  # GO TO 10
            if i >= C.NFREQE + C.INSE:
                ii = C.indlgz[i - C.NFREQE - C.INSE + 1]
                if C.RPOP0[ii, id] < C.POPZCH:
                    continue              # GO TO 10
            if abs(chang[i, id]) < abs(ch):
                continue                  # GO TO 10
            ch = chang[i, id]
        chanm[id] = ch
        if C.NFREQE > 0:
            for i in range(i1, C.NFREQE + 1):   # DO 11 I=i1,NFREQE
                if abs(chang[i, id]) < abs(chrad):
                    continue              # GO TO 11
                chrad = chang[i, id]
                jjr = i
        for i in range(C.NFREQE + C.INSE, C.NFREQE + C.INSE + C.NLVEXZ - 1 + 1):  # DO 12
            ii = C.indlgz[i - C.NFREQE - C.INSE + 1]
            if C.RPOP0[ii, id] < C.POPZCH:
                continue                  # GO TO 12
            if abs(chang[i, id]) < abs(chpop):
                continue                  # GO TO 12
            chpop = chang[i, id]
            jjp = ii
        if C.INRE > 0:
            cht = chang[C.NFREQE + C.INRE, id]
            if abs(cht) >= abs(chmt):
                chmt = abs(cht)
        if C.INPC > 0:
            che = chang[C.NFREQE + C.INPC, id]

        # output onto file 9

        # 800 FORMAT(' RELATIVE CHANGES OF VECTOR PSI'/
        #  '  ITER  ID    TEMP        NE       POP     RAD      MAXIMUM',
        #  '   ilev   ifr',/)
        if id == C.ND and C.ITER == 1:
            write_line(9, ' RELATIVE CHANGES OF VECTOR PSI\n'
                          '  ITER  ID    TEMP        NE       POP     RAD      MAXIMUM'
                          '   ilev   ifr\n')
        # 801 FORMAT(2I5,1P5e10.2,2i5)
        # 注：1P 缩放因子在 f-string 中无法表达，按 %10.2e 近似
        write_line(9, f"{C.ITER:5d}{id:5d}{cht:10.2e}{che:10.2e}{chpop:10.2e}"
                      f"{chrad:10.2e}{ch:10.2e}{jjp:5d}{jjr:5d}")

    # determination of the maximum relative change of all unknowns
    # at all depths

    chm = 0.0
    for i in range(1, C.ND + 1):
        if abs(chanm[i]) >= abs(chm):
            chm = chanm[i]

    if chmt < C.CHMAXT:
        for itl in range(C.ITER, C.NITER + 1 + 1):   # do itl=iter,niter+1
            C.NITLAM[itl] = C.NLAMT

    return chm, chmt


def opadd(mode, icall, ij, id):
    """Additional opacities
    This is basically user-supplied procedure; here are some more
    important non-standard opacity sources, namely
    Rayleigh scattering, H- opacity, H2+ opacity, and additional
    opacity of He I and He II.
    Inclusion of these opacities is contolled by switches transmitted
    by COMMON/OPCKEY - see description in START.

    Input parameters:
    MODE  - controls the nature and the amount of calculations
          = -1 - (OPADD called from START) evaluation of relevant
                 depth-dependent quantities (usually photoionization
                 cross-sections, but also possibly other), which are
                 stored in array CROS
          = 0  - evaluation of an additional opacity, emissivity, and
                 scattering - for procedure OPACF1
          = 1  - the same, but also derivatives wrt temperature,
                 electron density, and level populations
    IJ    - frequency index
    ID    - depth index

    Output: transmitted by COMMON/OPACAD:

    ABAD  - absorption coefficient (at frequency point IJ and depth ID)
    EMAD  - emission coefficient (at frequency point IJ and depth ID)
    SCAD  - scattering coefficient (at frequency point IJ and depth ID)
    Dxy   - derivatives of x (=A for Absorption, =E for Emission,
            =S for scattering) coefficient wrt y (=T for temperature,
            =N for electron density)
    DDN(I)  - quantity proportional to a derivative of absorption (and
              emission) coefficient wrt population of I-th level; ie.
              d(abs)/d(pop) = DDN * [1-exp(-h*nu/kT)]
              d(em)/d(pop) = DDN * (2h*nu**3/c**2)*exp(-h*nu/kT)

    对应 tlusty208.f 行 22968–23241

    不修改任何标量哑元（输出全部经 COMMON/OPACAD），隐式返回 None。
    """
    global _save_opadd_T, _save_opadd_DELTAT, _save_opadd_ANE, _save_opadd_HKT
    global _save_opadd_T32, _save_opadd_XHM, _save_opadd_POPI, _save_opadd_SB00
    global _save_opadd_AH, _save_opadd_AHP, _save_opadd_AHE
    FRRAY = 2.463e15                      # PARAMETER (FRRAY=..., ...)
    FRAYHE = 5.150e15
    FRAYH2 = 2.922e15
    CLS = 2.997925e18
    C18 = 2.997925e18
    CR0 = 5.799e-13
    CR1 = 1.422e-6
    CR2 = 2.784
    TENM4 = 1.0e-4
    THM0 = 8.7629e3
    SBHM = 1.0353e-16
    TRHA = 1.5
    SFF0 = 1.3727e-25
    SFF1 = 4.3748e-10
    SFFM2 = -2.5993e-7
    F0HE1 = 3.29e15
    F0HE2 = 1.316e16
    SBH0 = 4.1412e-16
    SG01 = 2.815e-16
    SG02 = 4.504e-15
    # SAVE T,DELTAT,ANE,HKT,T32,XHM,POPI,SB00 → 模块级 _save_opadd_*（文件头）
    # 读出 SAVE/静态存储变量
    t = _save_opadd_T
    deltat = _save_opadd_DELTAT
    ane = _save_opadd_ANE
    hkt = _save_opadd_HKT
    t32 = _save_opadd_T32
    xhm = _save_opadd_XHM
    popi = _save_opadd_POPI
    sb00 = _save_opadd_SB00
    ah = _save_opadd_AH
    ahp = _save_opadd_AHP
    ahe = _save_opadd_AHE
    # common/eospar/anmol,anato,anion → C.anmol/C.anato/C.anion（规范名直访）

    ab0 = 0.0
    ab1 = 0.0
    dab0 = 0.0
    dab1 = 0.0
    C.ABAD = 0.0
    C.EMAD = 0.0
    C.SCAD = 0.0
    dbf = 0.0                             # DBF/DFF 原代码置 0 后再未使用
    dff = 0.0
    C.DAT = 0.0
    C.DET = 0.0
    C.DAN = 0.0
    C.DEN = 0.0
    C.DST = 0.0
    C.DSN = 0.0
    for i in range(1, C.NLEVEL + 1):
        C.DDN[i] = 0.0

    fr = C.FREQ[ij]
    al = 2.997925e18 / fr
    lpri = al > 1579.0 and al < 1579.5    # 原代码计算后未再使用
    # TODO(port): IELH<=0 时 N0HN/NKH 在 Fortran 中未初始化（ IOPH2P 分支会读
    # N0HN/NKH），此处按 0 初始化（条件 N0HN.GT.0 / NKH.GT.0 为假，安全）。
    n0hn = 0
    nkh = 0
    if C.IELH > 0:
        n0hn = C.NFIRST[C.IELH]
        nkh = C.NKA[C.IATH]

    if icall > 0:
        t = C.TEMP[id]
        deltat = TENM4 * t
        ane = C.ELEC[id]
        hkt = HK / t
        t32 = UN / t / math.sqrt(t)
        xhm = THM0 / t
        if C.IELH > 0:
            ah = C.POPUL[n0hn, id]
            ahp = C.POPUL[nkh, id]
        else:
            ah = C.anato[1, id]
            ahp = C.anion[1, id]
        popi = ah
        sb00 = SBHM * t32 * math.exp(xhm) * popi * ane

        if C.IATHE > 0:
            ahe = C.POPUL[C.N0A[C.IATHE], id]
        else:
            ahe = C.anato[2, id]
        # 写回 SAVE/静态存储变量（此后它们在本调用内不再被真正修改；
        # 下文 h2minus/cia_* 调用点的解包只是把原值写回）
        _save_opadd_T = t
        _save_opadd_DELTAT = deltat
        _save_opadd_ANE = ane
        _save_opadd_HKT = hkt
        _save_opadd_T32 = t32
        _save_opadd_XHM = xhm
        _save_opadd_POPI = popi
        _save_opadd_SB00 = sb00
        _save_opadd_AH = ah
        _save_opadd_AHP = ahp
        _save_opadd_AHE = ahe

    it = C.NCON

    #   -----------------------
    #   HI  Rayleigh scattering
    #   -----------------------

    if C.IRSCT != 0:
        it = it + 1
        C.SCAD = ah * cross(it, ij)

    #   -----------------------
    #   He I  Rayleigh scattering
    #   -----------------------

    if C.IRSCHE != 0 and mode >= 0:
        it = it + 1
        C.SCAD = C.SCAD + ahe * cross(it, ij)

    #   -----------------------
    #   H2  Rayleigh scattering
    #   -----------------------

    if C.IRSCH2 != 0 and mode >= 0 and C.IFMOL > 0:
        it = it + 1
        sg = cross(it, ij) * C.anmol[2, id]
        if t < C.TMOLIM:
            C.SCAD = C.SCAD + sg

    if C.IOPHMI > 0:
        #   ----------------------------
        #   H-  bound-free and free-free
        #   ----------------------------
        it = it + 1
        if t < 20000.0:
            sb = sb00 * cross(it, ij)
            sf = sffhmi(ah, fr, t) * ane
            ab0 = sb + sf

    if C.IOPH2P > 0:
        #   -----------------------------
        #   H2+  bound-free and free-free
        #   -----------------------------
        it = it + 1
        x2 = -cross(it, ij) / t + cross(it + 1, ij)
        it = it + 1
        sb = 0.0
        if x2 > -150.0 and fr < 3.28e15 and t <= 9000.0:
            sb = ah * math.exp(x2) * ahp
        ab0 = ab0 + sb
        dab1 = sb * cross(it - 1, ij) / t / t
        if n0hn > 0:
            C.DDN[n0hn] = C.DDN[n0hn] + sb / popi
        if nkh > 0:
            C.DDN[nkh] = C.DDN[nkh] + sb / C.POPUL[nkh, id]

    #   -----------------------------
    #   He-  free-free
    #   -----------------------------

    if C.IOPHEM > 0:
        it = it + 1
        sg = cross(it, ij) * t + cross(it + 1, ij) + cross(it + 2, ij) / t
        ab0 = ab0 + sg * ane * ahe

    #   -----------------------------
    #   H2-  free-free
    #   -----------------------------

    if C.IOPH2M != 0 and mode >= 0 and C.IFMOL > 0 and t < C.TMOLIM:
        # h2minus 修改标量哑元 oph2m → 按约定解包全部标量
        t, C.anmol[2, id], ane, fr, oph2 = h2minus(
            t, C.anmol[2, id], ane, fr, 0.0)
        ab1 = ab1 + oph2

    #   -----------------------------
    #     CH and OH continuuum opacity
    #   -----------------------------

    if mode >= 0 and C.IFMOL > 0 and t < C.TMOLIM:
        if C.IOPCH > 0:
            ab0 = ab0 + sbfch(fr, t) * C.anmol[5, id]
        if C.IOPOH > 0:
            ab0 = ab0 + sbfoh(fr, t) * C.anmol[4, id]

        #     ---------------------------
        #     CIA H2-H2 opacity
        #     ---------------------------

        if C.IOH2H2 > 0:
            # cia_h2h2 修改标量哑元 opac → 按约定解包全部标量
            t, C.anmol[2, id], fr, oph2 = cia_h2h2(
                t, C.anmol[2, id], fr, 0.0)
            ab1 = ab1 + oph2

        #     ---------------------------
        #     CIA H2-He opacity
        #     ---------------------------

        if C.IOH2HE > 0:
            t, C.anmol[2, id], ahe, fr, oph2 = cia_h2he(
                t, C.anmol[2, id], ahe, fr, 0.0)
            ab1 = ab1 + oph2

        #     ---------------------------
        #     CIA H2-H opacity
        #     ---------------------------

        if C.IOH2H > 0:
            t, C.anmol[2, id], ah, fr, oph2 = cia_h2h(
                t, C.anmol[2, id], ah, fr, 0.0)
            ab1 = ab1 + oph2

        #     ---------------------------
        #     CIA H-He opacity
        #     ---------------------------

        if C.IOHHE > 0:
            t, ah, ahe, fr, oph2 = cia_hhe(t, ah, ahe, fr, 0.0)
            ab1 = ab1 + oph2

    #     ----------------------------------------------
    #     The user may supply more opacity sources here:
    #     ----------------------------------------------

    # Finally, actual absorption and emission coefficients and
    # their derivatives

    if mode < 0:
        return
    x = math.exp(-hkt * fr)
    x1 = UN - x
    fr15 = fr * 1.0e-15
    bnx = BN * fr15 * fr15 * fr15 * x     # 原代码计算后未再使用
    ab1 = ab1 / x1
    C.ABAD = C.ABAD + ab0 + ab1
    C.EMAD = C.EMAD + ab0 + ab1
    if mode == 1:
        hkft = hkt * fr / t
        db = hkft * ab0                   # 原代码计算后未再使用
        C.DAT = dab1
        C.DET = dab1
        C.DAN = ab0 / ane
        C.DEN = ab0 / ane
    return


def opadd0(ij):
    """setting cross secxtion for ondividual addiaopnal opacity sources

    对应 tlusty208.f 行 23248–23357
    """
    FRRAY = 2.463e15                      # PARAMETER (FRRAY=..., ...)
    FRAYHE = 5.150e15
    FRAYH2 = 2.922e15
    CLS = 2.997925e18
    CR0 = 5.799e-13
    CR1 = 1.422e-6
    CR2 = 2.784

    fr = C.FREQ[ij]
    if C.ISPODF >= 1:
        fr = C.FREQ[C.IFREQB[ij]]

    it = C.NCON

    #     -----------------------
    #     HI  Rayleigh scattering
    #     -----------------------

    if C.IRSCT != 0:
        it = it + 1
        if it > MCROSS:
            quit('it.gt.mcross in opadd', it, MCROSS)   # QUIT 不修改标量哑元
        frm = min(fr, FRRAY)
        x = (CLS / frm) ** 2
        C.BFCS[it, ij] = float((CR0 + (CR1 + CR2 / x) / x) / x / x)  # real(...)

    #     -----------------------
    #     He I  Rayleigh scattering
    #     -----------------------

    if C.IRSCHE != 0:
        it = it + 1
        if it > MCROSS:
            quit('it.gt.mcross in opadd', it, MCROSS)
        x = (CLS / min(fr, FRAYHE)) ** 2
        cs = 5.484e-14 / x / x * (1.0 + (2.44e5 + 5.94e10 / (x - 2.90e5)) / x) ** 2
        C.BFCS[it, ij] = float(cs)

    #   -----------------------
    #   H2  Rayleigh scattering
    #   -----------------------

    if C.IRSCH2 != 0 and C.IFMOL > 0:
        it = it + 1
        if it > MCROSS:
            quit('it.gt.mcross in opadd', it, MCROSS)
        x = (CLS / min(fr, FRAYH2)) ** 2
        x2 = 1.0 / x / x
        cs = (8.14e-13 + 1.28e-6 / x + 1.61 * x2) * x2
        C.BFCS[it, ij] = float(cs)

    #     ----------------------------
    #     H-  bound-free and free-free
    #     ----------------------------

    if C.IOPHMI > 0:
        it = it + 1
        if it > MCROSS:
            quit('it.gt.mcross in opadd', it, MCROSS)
        C.BFCS[it, ij] = float(sbfhmi(fr))

    #     -----------------------------
    #     H2+  bound-free and free-free
    #     -----------------------------

    if C.IOPH2P > 0:
        it = it + 1
        if it + 1 > MCROSS:
            quit('it.gt.mcross in opadd', it, MCROSS)
        x = fr * 1.0e-15
        C.BFCS[it, ij] = float((-7.342e-3 + (-2.409 + (1.028 + (-4.23e-1
            + (1.224e-1 - 1.351e-2 * x) * x) * x) * x) * x) * 1.602e-12 / BOLK)
        it = it + 1
        x = math.log(fr)
        cs0 = -3.0233e3 + (3.7797e2 + (-1.82496e1 + (3.9207e-1
            - 3.1672e-3 * x) * x) * x) * x
        C.BFCS[it, ij] = float(cs0)

    #     -----------------------------
    #     He-  free-free
    #     -----------------------------

    if C.IOPHEM > 0:
        it = it + 1
        if it + 2 > MCROSS:
            quit('it.gt.mcross in opadd', it, MCROSS)
        a = 3.397e-46 + (-5.216e-31 + 7.039e-15 / fr) / fr
        b = -4.116e-42 + (1.067e-26 + 8.135e-11 / fr) / fr
        # 原名 C；改名 c_l 避免遮蔽 commons 模块别名 C
        c_l = 5.081e-37 + (-8.724e-23 - 5.659e-8 / fr) / fr
        C.BFCS[it, ij] = float(a)
        C.BFCS[it + 1, ij] = float(b)
        C.BFCS[it + 2, ij] = float(c_l)

    return


