        7.166, 6.666, 6.166, 5.666, 5.166, 4.667, 4.171, 3.684, 3.237, 2.847,
        7.370, 6.870, 6.369, 5.869, 5.369, 4.870, 4.373, 3.882, 3.417, 3.008,
