        4.0, 9.0, 6.0, 1.0, 10.0, 21.0, 28.0, 25.0, 6.0, 25.0, 30.0, 25.0,
        *([0.0] * 4),
        2.0, 1.0, 2.0, 1.0, 6.0, 9.0, 4.0, 9.0, 6.0, 1.0, 2.0, 1.0, 6.0, 9.0,
