    uu[1:12, 7] = [41.449, 381.395, 577.8, 797.8, 1116.2, 1388.5, 1681.5,
                   2130.8, 2418.7, 11817.061, 13297.676]                 # u11
    uu[1:13, 8] = [61.671, 121.268, 646.41, 881.1, 1139.4, 1504.3, 1814.3,
                   2144.7, 2645.2, 2964.4, 14210.261, 15829.951]         # u12
