def pzeval():
    """C     =================
C
C     Auxiliary procedure called from RESOLV
C     determination of the total and gas pressures, and logarithmic
C     gradient of pressure
C
C     total pressure, gas pressure, and logarithmic gradient DELTA

    对应 tlusty208.f 行 28308–28356"""
    # TODO(port): IPPZEV 未在任何 COMMON/INCLUDE 中声明（全文件仅出现于本例程），
    # 是未初始化的隐式局部整型变量，疑为 COMMON /ifpzpa/ 的 IFPZEV 之笔误；
    # 按常见编译器行为取 0（即不打印）。
    ippzev = 0
    if ippzev > 0:
        # 601 FORMAT(/'  ID   PTOT-SUM  PTOT-MG   PGAS-RHO  PGAS-P    PRAD',
        #  *       '       A'/)
        print()
        print('  ID   PTOT-SUM  PTOT-MG   PGAS-RHO  PGAS-P    PRAD       A')
        print()
    for id in range(1, C.ND + 1):
        pturb = HALF * C.DENS[id] * C.VTURB[id] * C.VTURB[id]
        pgs0 = (C.DENS[id] / C.WMM[id] + C.ELEC[id]) * BOLK * C.TEMP[id]
        ptotl0 = pgs0 + C.PRADT[id] + pturb
        ptotl1 = C.GRAV * C.DM[id] + C.PRADT[1] - C.PRD0
        pgs1 = ptotl1 - pturb - C.PRADT[id]
        aaa = 3.0 * C.PRADT[id] / C.TEMP[id] ** 4 / 7.5639e-15
        if C.IDISK == 0:
            C.PTOTAL[id] = ptotl1
            C.PGS[id] = pgs1
        else:
            C.PTOTAL[id] = ptotl0
            C.PGS[id] = pgs0
        if ippzev > 0:
            # 602 FORMAT(I4,1P6D10.3)
            print('%4d%s' % (id, ''.join('%10.3E' % v for v in
                  (ptotl0, ptotl1, pgs0, pgs1, C.PRADT[id], aaa))))
    if C.HMIX0 < 0.0:
        return
    if ippzev > 0:
        # 600 FORMAT(/' CONVECTIVE FLUX: RESOLV; GLOBAL ITERATION =',I2/)
        print()
        print(' CONVECTIVE FLUX: RESOLV; GLOBAL ITERATION =%2d' % (C.ITER - 1))
        print()
        conout(1, C.ipconf)  # CONOUT 不修改标量哑元
    if C.iconre > 0 and C.ITER <= C.iconre and C.ITER >= C.iconrs:
        conref()
    if ippzev == 0 and C.LFIN:
        # 600 FORMAT(/' CONVECTIVE FLUX: RESOLV; GLOBAL ITERATION =',I2/)
        print()
        print(' CONVECTIVE FLUX: RESOLV; GLOBAL ITERATION =%2d' % (C.ITER - 1))
        print()
        conout(1, 1)
    return


