def pzevld():
    """C     =================
C
C     Auxiliary procedure called from RESOLV
C     determination of the total and gas pressures, and logarithmic
C     gradient of pressure
C
C     (disk 版本：含 /PRSAUX/、/DEPTDR/、/grdpra/、/ifpzpa/ 局部 COMMON)

    对应 tlusty208.f 行 28363–28538"""
    # 局部数组（dimension dpp,zd1,zd2,zd3,ZOLD (mdepth)），1 基
    dpp = np.zeros(MDEPTH + 1)
    zd1 = np.zeros(MDEPTH + 1)
    zd2 = np.zeros(MDEPTH + 1)
    zd3 = np.zeros(MDEPTH + 1)
    zold = np.zeros(MDEPTH + 1)
    # C.ifpzev: common/ifpzpa/（规范名见 INLINE_COMMONS.md）
    if C.IFRYB > 0 and C.ifpzev == 0:
        return
    iheitr = 0
    while True:  # 标号 5
        iheitr = iheitr + 1
        # geometrical distance from the central plane - z
        if C.IHECOR >= 0:
            C.ZD[C.ND] = C.ZND
            for iid in range(1, C.ND):  # DO IID=1,ND-1
                id = C.ND - iid
                if iheitr == 1:
                    C.ZD[id] = C.ZD[id + 1] + HALF * (C.DM[id + 1] - C.DM[id]) * (
                        UN / C.DENS[id + 1] + UN / C.DENS[id])
                    zold[id] = C.ZD[id]
        else:
            zd1[1] = -C.DDC[1] / C.DDB[1]
            zd2[1] = -C.DENS1[1] / C.DDB[1]
            for id in range(2, C.ND):  # do id=2,nd-1
                x = UN / (C.DDB[id] - C.DDA[id] * zd1[id - 1])
                zd1[id] = -x * C.DDC[id]
                zd2[id] = -x * (C.DENS1[id] - C.DDA[id] * zd2[id - 1])
            C.ZD[C.ND] = C.ZND
            for id in range(C.ND - 1, 0, -1):  # do id=nd-1,1,-1
                C.ZD[id] = zd1[id] * C.ZD[id + 1] + zd2[id]
        # total pressure, gas pressure, and sound speed
        for id in range(1, C.ND + 1):
            pturb = HALF * C.DENS[id] * C.VTURB[id] * C.VTURB[id]
            pgsc = (C.DENS[id] / C.WMM[id] + C.ELEC[id]) * BOLK * C.TEMP[id]
            C.PGS[id] = pgsc
            ptotl0 = C.PGS[id] + C.PRADT[id] + pturb
            C.PTOTAL[id] = ptotl0
            C.VSND2[id] = C.PTOTAL[id] / C.DENS[id]
        id = 1
        C.HG1 = math.sqrt(2.0 * C.PGS[1] / C.DENS[1] / C.QGRAV)
        C.HR1 = C.PRD0 / C.QGRAV
        C.RR1 = C.HR1 / C.HG1
        # recalculate the z-distance
        ij1 = 1
        if C.icompt > 0 and C.icombc > 0 and C.IJEX[1] > 0:
            ij1 = 2
        for id in range(1, C.ND + 1):
            grp = 0.0
            flex = 0.0  # 原代码赋值后未使用，保留
            if C.NFREQE > 0 or C.IFRYB == 0:
                for ij in range(ij1, C.NFREQE + 1):
                    C.RAD0[ij] = C.RADEX[ij, id]
                    C.FK0[ij] = C.FAKEX[ij, id]
                    C.ABSO0[ij] = C.ABSOEX[ij, id]
                    ijt = C.IJFR[ij]
                    wd0 = C.W[ijt]
                    fluxw = C.FH[ijt] * C.RAD0[ij] - C.HEXTRD[ijt]
                    if not C.LSKIP[id, ijt]:
                        if id == 1:
                            grp = grp + wd0 * fluxw * C.ABSO0[ij]
                        else:
                            C.RADM[ij] = C.RADEX[ij, id - 1]
                            C.FKM[ij] = C.FAKEX[ij, id - 1]
                            C.ABSOM[ij] = C.ABSOEX[ij, id - 1]
                            frd = C.FK0[ij] * C.RAD0[ij] - C.FKM[ij] * C.RADM[ij]
                            grp = grp + wd0 * frd
                C.GRD[id] = grp + C.FPRD[id]
            if id == 1:
                grv = C.QGRAV * C.ZD[id]
            else:
                grv = C.QGRAV * (C.ZD[id] + C.ZD[id - 1]) * HALF
                dpt = (C.PTOTAL[id] - C.PTOTAL[id - 1]) / C.DDM[id]  # 未再使用，保留
                dpr = (C.PRADT[id] - C.PRADT[id - 1]) / C.DDM[id]
                dpg = (C.PGS[id] - C.PGS[id - 1]) / C.DDM[id]
                dpr1 = C.GRD[id] / (C.DM[id] - C.DM[id - 1]) * 4.19168946e-10
                err = 10.0
                if grv != 0.0:
                    err = (dpg + dpr - grv) / grv  # err 未再使用，保留
                dpp[id] = (dpg + dpr1) / C.QGRAV
        if C.ITER <= abs(C.IFZ0):
            zd1[1] = dpp[2]
            zd1[C.ND] = C.ZND
            for id in range(2, C.ND):
                zd1[id] = (dpp[id] + dpp[id + 1]) * HALF
            zd2[C.ND] = C.ZND
            zd3[C.ND] = C.ZND
            izdiv = 0
            nzdiv = 0
            for id in range(C.ND - 1, 0, -1):
                zd2[id] = 2.0 * dpp[id + 1] - zd2[id + 1]
                zd3[id] = dpp[id] * C.DDMIN[id] + dpp[id + 1] * C.DDPLU[id]
                if zd2[id] <= zd2[id + 1]:
                    nzdiv = nzdiv + 1
                if nzdiv == 1:
                    izdiv = id
            if C.IHECOR >= 0:
                for id in range(1, C.ND + 1):
                    C.ZD[id] = zd2[id]
                    if id <= izdiv:
                        C.ZD[id] = zd1[id]
            else:
                for id in range(1, C.ND + 1):
                    C.ZD[id] = zd3[id]
            # recalculate densities (if required)
            if C.IHECOR > 0:
                for id in range(C.ND - 1, 0, -1):
                    x = HALF * (C.DM[id + 1] - C.DM[id])
                    xne = C.ELEC[id] / C.DENS[id]
                    C.DENS[id] = x * C.DENS[id + 1] / (
                        (C.ZD[id] - C.ZD[id + 1]) * C.DENS[id + 1] - x)
                    C.DENS1[id] = UN / C.DENS[id]
                    C.ELEC[id] = xne * C.DENS[id]
            elif C.IHECOR < -1:
                for id in range(C.ND - 1, 0, -1):
                    xne = C.ELEC[id] / C.DENS[id]
                    if id > 1:
                        C.DENS1[id] = (C.ZD[id - 1] * C.DDA[id] - C.ZD[id] * C.DDB[id]
                                       - C.ZD[id + 1] * C.DDC[id])
                    else:
                        C.DENS1[id] = -C.ZD[id] * C.DDB[id] - C.ZD[id + 1] * C.DDC[id]
                    C.DENS[id] = UN / C.DENS1[id]
                    C.ELEC[id] = xne * C.DENS[id]
            dzmx = 0.0
            for id in range(1, C.ND):
                dzmx = max(dzmx, abs((C.ZD[id] - zold[id]) / C.ZD[id]))
                zold[id] = C.ZD[id]
            if iheitr >= 5 or dzmx < 1.0e-3:
                break  # GO TO 25
            continue  # GO TO 5
        # iter > abs(ifz0)：跳过重算块（end if 之后即 RETURN）
        break
    # 25 continue
    return


