def lemini():
    """C     =================
C
C     Initializes necessary arrays for evaluating hydrogen line profiles
C     from the Lemke tables
C
C     read Lemke or Tremblay tables

    对应 tlusty208.f 行 28544–28628"""
    for i in range(1, 5):
        for j in range(1, 23):
            C.ILINH[i, j] = 0
    if C.IHYDPR == 21:
        open_unit(C.IHYDPR, './data/lemke.dat', 'r')  # status='old'
        # 641 format(' -----------'/' reading Lemke tables; ihydpr =',i3/' -----------')
        print(' -----------')
        print(' reading Lemke tables; ihydpr =%3d' % C.IHYDPR)
        print(' -----------')
    elif C.IHYDPR == 22:
        open_unit(C.IHYDPR, './data/tremblay.dat', 'r')  # status='old'
        # 642 format(' -----------'/' reading Tremblay tables; ihydpr =',i3/' -----------')
        print(' -----------')
        print(' reading Tremblay tables; ihydpr =%3d' % C.IHYDPR)
        print(' -----------')
    iline = 0
    ntab = int(_ldread(C.IHYDPR, 1)[0])  # READ(IHYDPR,*) NTAB
    for itab in range(1, ntab + 1):
        ilineb = iline
        nlly = int(_ldread(C.IHYDPR, 1)[0])  # READ(IHYDPR,*) NLLY
        for ili in range(1, nlly + 1):
            iline = iline + 1
            # READ(IHYDPR,*) I,J,ALMIN,ANEMIN,TMIN,DLA,DLE,DLT,NWL,NE,NT
            _v = _ldread(C.IHYDPR, 11)
            i = int(_v[0])
            j = int(_v[1])
            almin = _v[2]
            anemin = _v[3]
            tmin = _v[4]
            dla = _v[5]
            dle = _v[6]
            dlt = _v[7]
            nwl = int(_v[8])
            ne = int(_v[9])
            nt = int(_v[10])
            # 643 format(' ntab,nlly,iline,i,j ',5i4)
            print(' ntab,nlly,iline,i,j %4d%4d%4d%4d%4d' % (ntab, nlly, iline, i, j))
            C.ILINH[i, j] = iline
            C.NWLH[iline] = nwl
            C.NWLHYD[iline] = nwl
            C.NTH[iline] = nt
            C.NEH[iline] = ne
            for iwl in range(1, nwl + 1):
                C.WLH[iwl, iline] = almin + (iwl - 1) * dla
                C.WLHYD[iline, iwl] = C.WLH[iwl, iline]
                C.WLH[iwl, iline] = math.exp(2.3025851 * C.WLH[iwl, iline])
            for ine in range(1, ne + 1):
                C.XNELEM[ine, iline] = anemin + (ine - 1) * dle
            for it in range(1, nt + 1):
                C.XTLEM[it, iline] = tmin + (it - 1) * dlt
        for ili in range(1, nlly + 1):
            ilne = ilineb + ili
            nwl = C.NWLH[ilne]
            # READ(IHYDPR,500)；500 FORMAT(1X)：读掉一整行
            read_line(C.IHYDPR)
            for ine in range(1, C.NEH[ilne] + 1):
                for it in range(1, C.NTH[ilne] + 1):
                    # READ(IHYDPR,*) QLT,(PRFHYD(ILNE,IWL,IT,INE),IWL=1,NWL)
                    _v = _ldread(C.IHYDPR, nwl + 1)
                    qlt = _v[0]  # qlt 读入后未使用，保留
                    for iwl in range(1, nwl + 1):
                        C.PRFHYD[ilne, iwl, it, ine] = _v[iwl]
            # coefficient for the asymptotic profile is determined from
            # the input data
            xclog = C.PRFHYD[ilne, nwl, 1, 1] + 2.5 * C.WLHYD[ilne, nwl] - 0.477121
            xklog = 0.6666667 * xclog
            C.XK0[ilne] = math.exp(xklog * 2.3025851)
    close_unit(C.IHYDPR)
    return


