def wnstor(id):
    """C     =====================
C
C     Stores occupation probabilities for hydrogen levels
C     in common WNCOM for further use
C
    哑元 ID 不被修改 → 无返回。
    对应 tlusty208.f 行 29090–29153"""
    # PARAMETER (SIXTH=UN/6.,CCOR=0.09)
    SIXTH = UN / 6.0
    CCOR = 0.09
    # parameter (p1=0.1402,p2=0.1285,p3=un,p4=3.15,p5=4.)
    P1 = 0.1402
    P2 = 0.1285
    P3 = UN
    P4 = 3.15
    P5 = 4.0
    # parameter (tkn=3.01,ckn=5.33333333,cb0=8.59d14,f23=-2./3.)
    TKN = 3.01
    CKN = 5.33333333
    CB0 = 8.59e14
    F23 = -2.0 / 3.0
    if C.IOPTAB < 0:
        return
    cb = CB0 * C.bergfc
    ane = C.ELEC[id]
    a = CCOR * math.exp(SIXTH * math.log(ane)) / math.sqrt(C.TEMP[id])
    z = UN
    x = math.exp(P4 * math.log(UN + P3 * a))
    c1 = P1 * (x + P5 * (z - UN) * a * a * a)
    c2 = P2 * x
    beta0 = cb * z * z * z * math.exp(F23 * math.log(ane))
    for i in range(1, NLMX + 1):
        xn = i
        if xn <= TKN:
            xkn = UN
        else:
            xn1 = UN / (xn + UN)
            xkn = CKN * xn * xn1 * xn1
        beta = beta0 * xkn * C.XI2[i] * C.XI2[i]
        f = (c1 * beta * beta * beta) / (UN + c2 * beta * math.sqrt(beta))
        C.WNHINT[i, id] = f / (UN + f)
    # array WOP - occupation probabilities for explicit levels
    #   (if ifwop>1, occ. probabilities have been initialized
    #      for iron-peak elements and are not updated)
    for ii in range(1, C.NLEVEL + 1):
        if C.ifwop[ii] <= 0:
            C.wop[ii, id] = UN
        elif C.ifwop[ii] == 1:
            ie = C.IEL[ii]
            nq = C.NQUANT[ii]
            if C.IZ[ie] == 1:
                C.wop[ii, id] = C.WNHINT[nq, id]
            else:
                z = C.IZ[ie]
                xn = nq
                C.wop[ii, id] = wn(xn, a, ane, z)
        if C.ifwop[ii] > 1 and C.LTE:
            C.wop[ii, id] = UN
    return


