def odf1(imode, il, iu, id, odf):
    """C     ===================================
C
C     opacity distribution function for overlapping lines near the series limit
C
C     The lines converge to the edge of the (continuum) transition IL - IU,
C     IL - index of the lower level
C     IU - index of the upper level (usually the ground state of teh next ion)
C     ID - depth index
C
C     Output: ODF - opacity distribution function interpolated to the set of
C                   explicit frequencies
C
    标量哑元 IMODE,IL,IU,ID 均不被修改 → 无返回。
    SAVE FRO,SGFR,ODF0,IODF → 模块级 _save_odf1_*（调用间保持）。
    对应 tlusty208.f 行 29257–29435"""
    # PARAMETER (FRH=3.28805D15,CQT=1.284523D12)
    FRH = 3.28805e15  # 未使用，保留
    CQT = 1.284523e12
    # PARAMETER (CCOR=0.09,C00=1.25D-9,CID=0.02654,SIXTH=UN/6.)
    CCOR = 0.09  # 未使用，保留
    C00 = 1.25e-9
    CID = 0.02654
    SIXTH = UN / 6.0
    # DIMENSION FRO(MFRO),ODF0(MFRO),ABSO0(MFRO),ODF(MFREQ),SGT(MFRO),
    #           ALAM(MFRO),FROD(MFRO),SGFR(MFRO),IODF(MFRO),IODR(MFRO),DWF(MFRO)
    # SAVE FRO,SGFR,ODF0,IODF → 模块级；注意本例程的 ABSO0 是局部数组
    # （未 include ARRAY1.FOR 且本地 DIMENSION），与 blank COMMON 的 ABSO0 无关。
    fro = _save_odf1_fro
    sgfr = _save_odf1_sgfr
    odf0 = _save_odf1_odf0
    iodf = _save_odf1_iodf
    abso0 = np.zeros(MFRO + 1)
    sgt = np.zeros(MFRO + 1)
    alam = np.zeros(MFRO + 1)
    frod = np.zeros(MFRO + 1)
    iodr = np.zeros(MFRO + 1, dtype=np.int64)
    dwf = np.zeros(MFRO + 1)
    i = C.NQUANT[il]  # 未再使用，保留
    kl = C.INDODF[il]
    ielo = C.IEL[il]
    n1h = C.NLAST[ielo]  # 未再使用，保留
    nq1 = C.NQLODF[il]
    fre = C.ENION[il] / H
    t = C.TEMP[id]
    sqt = math.sqrt(t)
    ane = C.ELEC[id]
    anes = math.exp(SIXTH * math.log(ane))
    f00 = C00 * anes * anes * anes * anes
    dop0 = CQT * sqt
    qz = C.IZ[ielo]  # 未再使用，保留
    # pseudocontinuum opacity (non-zero in all frequencies);
    # formulated through the dissolved fraction
    itr = C.ITRA[il, iu]
    nfr0 = C.NFRODF[kl]
    if imode == 0:
        for ij in range(1, nfr0 + 1):
            fro[ij] = C.FROS[ij, kl]
            sgfr[ij] = sigk(fro[ij], itr, 1)  # SIGK 为函数，不修改标量哑元
            alam[ij] = CAS / fro[ij]
    # function D(nu) - dissolved fraction
    # CALL DWNFR(1,NFR0,FRE,ACOR,ANE,QZ,FRO,DWF)  ← 原代码中该调用已被注释掉
    # TODO(port): 因此 DWF 从未赋值（Fortran 未定义值），此处为全 0；
    # 下面的 ABSO0=SGFR*DWF 恒为 0。直译保留原状。
    for ij in range(1, nfr0 + 1):
        abso0[ij] = sgfr[ij] * dwf[ij]
    # summation over individual lines
    for j in range(nq1, NLMX + 1):
        xj = j  # 未再使用，保留
        fxk = f00 * C.XKIJ[kl, j]
        dop = dop0 / C.WL0[kl, j]
        C.DBETA = C.WL0[kl, j] * C.WL0[kl, j] / CAS / fxk
        C.BETAD = dop * C.DBETA
        fid = CID * C.FIJ[kl, j] * C.DBETA
        divstr(1)
        wprob = C.WNHINT[j, id]
        odfhst(nfr0, fxk, fid, wprob, C.WL0[kl, j], alam, sgt)
        for ij in range(1, nfr0 + 1):
            abso0[ij] = abso0[ij] + sgt[ij]
    # opacity distribution function in the internal set of frequencies
    if imode == 0:
        odf0[1] = abso0[1]
        iodf[1] = 1
        for ij in range(2, nfr0 + 1):
            odf0[ij] = abso0[ij]
            iodf[ij] = ij
            if odf0[ij] < odf0[ij - 1]:
                ab = odf0[ij]
                ijodf = iodf[ij]
                for ij0 in range(1, ij):  # DO IJ0=1,IJ-1（插入排序回移）
                    ij1 = ij - ij0 + 1
                    if odf0[ij1] >= odf0[ij1 - 1]:
                        break  # GO TO 71
                    odf0[ij1] = odf0[ij1 - 1]
                    odf0[ij1 - 1] = ab
                    iodf[ij1] = iodf[ij1 - 1]
                    iodf[ij1 - 1] = ijodf
                # 71 CONTINUE
            if odf0[ij] > 0.001:
                # 603 format(' ij,id,odf0',2i5,1pd10.3)
                print(' ij,id,odf0%5d%5d%10.3E' % (ij, id, odf0[ij]))
    else:
        odf0[1] = abso0[iodf[1]]
        iodr[1] = iodf[1]
        for ij in range(2, nfr0 + 1):
            odf0[ij] = abso0[iodf[ij]]
            iodr[ij] = iodf[ij]
            if odf0[ij] < odf0[ij - 1]:
                ab = odf0[ij]
                ijodf = iodr[ij]
                for ij0 in range(1, ij):  # DO IJ0=1,IJ-1
                    ij1 = ij - ij0 + 1
                    if odf0[ij1] >= odf0[ij1 - 1]:
                        break  # GO TO 86
                    odf0[ij1] = odf0[ij1 - 1]
                    odf0[ij1 - 1] = ab
                    iodr[ij1] = iodr[ij1 - 1]
                    iodr[ij1 - 1] = ijodf
                # 86 CONTINUE
            if odf0[ij] > 0.001:
                # 603 format(' ij,id,odf0',2i5,1pd10.3)
                print(' ij,id,odf0%5d%5d%10.3E' % (ij, id, odf0[ij]))
        for ij in range(1, nfr0 + 1):
            iodf[ij] = iodr[ij]
    # Reinitialization of the internal frequencies set
    frod[1] = fro[1]
    iw = iodf[1]
    if iw > 1 and iw < nfr0:
        w1 = fro[iw - 1] - fro[iw + 1]
    elif iw == 1:
        w1 = fro[1] - fro[2]
    else:
        w1 = fro[nfr0 - 1] - fro[nfr0]
    for ij in range(2, nfr0):  # DO IJ=2,NFR0-1
        iw = iodf[ij]
        if iw > 1 and iw < nfr0:
            w2 = HALF * (fro[iw - 1] - fro[iw + 1])
        elif iw == 1:
            w2 = HALF * (fro[1] - fro[2])
        else:
            w2 = HALF * (fro[nfr0 - 1] - fro[nfr0])
        frod[ij] = frod[ij - 1] - HALF * (w1 + w2)
        w1 = w2
    ij = nfr0
    iw = iodf[ij]
    if iw > 1 and iw < nfr0:
        w2 = fro[iw - 1] - fro[iw + 1]
    elif iw == 1:
        w2 = fro[1] - fro[2]
    else:
        w2 = fro[nfr0 - 1] - fro[nfr0]
    frod[ij] = frod[ij - 1] - HALF * (w1 + w2)
    # Interpolated opacity distribution function to explicit frequencies
    for ij in range(2, C.NFREQ + 1):  # DO 150 IJ=2,NFREQ
        if C.FREQ[ij] > C.FREQ[ij - 1]:
            return
        odf[ij] = 0.0
        if C.FREQ[ij] > frod[1] or C.FREQ[ij] < frod[nfr0]:
            continue  # GO TO 150
        if id == 1:
            if C.FREQ[ij - 1] > frod[1]:
                C.I1ODF[il] = ij
            C.I2ODF[il] = ij
        ij0 = nfr0  # 若循环未触发 GO TO 120，IJ0 保持循环最后赋值 NFR0
        for ij1 in range(2, nfr0 + 1):  # DO IJ1=2,NFR0
            ij0 = ij1
            if C.FREQ[ij] >= frod[ij1]:
                break  # GO TO 120
        # 120
        odf[ij] = odf0[ij0 - 1] + (odf0[ij0] - odf0[ij0 - 1]) / (
            frod[ij0] - frod[ij0 - 1]) * (C.FREQ[ij] - frod[ij0 - 1])
    # 150 CONTINUE
    return


# ---------------------------------------------------------------------

def odfhst(n, fxk, fid, wp, wl, alam, sg):
    """C     ==========================================
C
C     Auxiliary routine for ODF1 (replaces multiple calls to STARKA)
C
    仅修改数组哑元 SG → 无返回。
    对应 tlusty208.f 行 29441–29494"""
    # PARAMETER (F0=-0.5758228,F1=0.4796232,F2=0.07209481,AL=1.26)
    F0 = -0.5758228
    F1 = 0.4796232
    F2 = 0.07209481
    AL = 1.26
    # PARAMETER (SD=0.5641895,SLO=-2.5,THRA=1.5,BL1=1.14,BL2=11.4)
    SD = 0.5641895
    SLO = -2.5
    THRA = 1.5
    BL1 = 1.14
    BL2 = 11.4
    # PARAMETER (SAC=0.08, THR=THRA*TWO)
    SAC = 0.08
    THR = THRA * TWO
    betad1 = UN / C.BETAD
    fxk1 = UN / fxk
    fidwp = fid * wp
    # for a > 1 Doppler core + asymptotic Holtzmark wing with division
    #           point DIV
    if C.ADH > AL:
        for ij in range(1, n + 1):
            beta = abs(alam[ij] - wl) * fxk1
            xd = beta * betad1
            if xd <= C.DIVH:
                st = SD * math.exp(-xd * xd) * betad1
            else:
                st = THR * math.exp(SLO * math.log(beta))
            sg[ij] = st * fidwp
    else:
        # empirical formula for a < 1
        for ij in range(1, n + 1):
            beta = abs(alam[ij] - wl) * fxk1
            xd = beta * betad1  # 此分支中未使用，保留
            if beta <= BL1:
                st = SAC
            elif beta < BL2:
                xl = math.log(beta)
                fl = (F0 * xl + F1) * xl
                st = F2 * math.exp(fl)
            else:
                st = THR * math.exp(SLO * math.log(beta))
            sg[ij] = st * fidwp
    return


# ---------------------------------------------------------------------

def odffr(il, iu):
    """C     =======================
C
C     Internal frequencies set for opacity distribution function
C     for overlapping lines near the series limit
C
C     The lines converge to the edge of the (continuum) transition IL - IU,
C     IL - index of the lower level
C     IU - index of the upper level (usually the ground state of the next ion)
C          or a mean level in the line ODF formalism
C
C     Output: FROS - set of internal frequencies
C                    in common ODFFRQ
C
    哑元 IL,IU 不被修改 → 无返回。
    对应 tlusty208.f 行 29500–29596"""
    # PARAMETER (FRH=3.28805D15,CDOP=2.84511D-7,CDOM=14.)
    FRH = 3.28805e15
    CDOP = 2.84511e-7
    CDOM = 14.0
    # PARAMETER (SIX=6.,SEPT=7.)
    SIX = 6.0
    SEPT = 7.0
    ffro = np.zeros(MFRO + 1)  # DIMENSION FFRO(MFRO)
    ch = C.IZ[C.IEL[il]] * C.IZ[C.IEL[il]]
    frion = ch * FRH
    fre = C.ENION[il] / H
    nf = 1
    nq1 = C.NQUANT[iu]
    xl2 = UN / (C.NQUANT[il] * C.NQUANT[il])
    xu1 = UN / ((C.NQUANT[iu] - 1) * (C.NQUANT[iu] - 1))
    xu2 = UN / (C.NQUANT[iu] * C.NQUANT[iu])
    frc = frion * (xl2 - xu2)
    ffro[nf] = HALF * (frc + frion * (xl2 - xu1))
    kt = C.ITRA[il, iu]
    kl = C.JNDODF[kt]
    dopo = CDOP * math.sqrt(C.TEFF) * frc
    dopm = CDOM * dopo
    fr1 = ffro[1]
    goto10 = False
    for i in range(nq1, NLMX + 1):
        ii = i * i
        fr2 = fre - frion / ii
        df = fr2 - fr1
        if df > dopm:
            for j in range(1, 8):  # DO J=1,7
                nf = nf + 1
                ffro[nf] = fr1 + j * dopo
            df = fr2 - SEPT * dopo - ffro[nf]
            ni = int(df / SIX / dopo)  # Fortran INT：向零截断
            ddf = df / (ni + 1)
            for j in range(1, ni + 1):
                nf = nf + 1
                ffro[nf] = fr1 + SEPT * dopo + j * ddf
            for j in range(7, -1, -1):  # DO J=7,0,-1
                nf = nf + 1
                ffro[nf] = fr2 - j * dopo
            fr1 = fr2
        else:
            ni = int(df / dopo)  # Fortran INT
            ddf = df / (ni + 1)
            for j in range(1, ni + 1):
                nf = nf + 1
                if nf > MFRO - 3:
                    nf = nf - 1
                    goto10 = True
                    break  # GO TO 10
                ffro[nf] = fr1 + j * ddf
            if goto10:
                break  # GO TO 10（跳出 I 循环）
            nf = nf + 1
            ffro[nf] = fr2
            fr1 = fr2
    # 10 CONTINUE
    nf = nf + 1
    ffro[nf] = fre * 0.999999999
    C.NFRODF[kl] = nf
    if nf > MFRO:
        quit('too many points for hydrogen ODF - nf.gt.mfro', nf, MFRO)
    for i in range(1, nf + 1):
        C.FROS[i, kl] = ffro[nf - i + 1]
    # Associated weights
    C.WNUS[1, kl] = HALF * (C.FROS[1, kl] - C.FROS[2, kl])
    C.WNUS[nf, kl] = HALF * (C.FROS[nf - 1, kl] - C.FROS[nf, kl])
    for i in range(2, nf):  # DO I=2,NF-1
        C.WNUS[i, kl] = HALF * (C.FROS[i - 1, kl] - C.FROS[i + 1, kl])
    return


# ---------------------------------------------------------------------

def chckse():
    """C     ==================
C
C     Auxiliary output routine, which enables printing
C     total rates to check statistical equilibrium at each depth.
C
C     Output: unit 16: <OUT> and <IN> rates, and relative difference,
C                      for each level.
C
    对应 tlusty208.f 行 29602–29687"""
    # PARAMETER (MLEVES=mlevel)；DIMENSION ROUT(MLEVES,MDEPTH),RIN(MLEVES,MDEPTH)
    rout = np.zeros((MLEVEL + 1, MDEPTH + 1))
    rin = np.zeros((MLEVEL + 1, MDEPTH + 1))
    if C.IOPTAB < 0:
        return
    for id in range(1, C.ND + 1):
        t = C.TEMP[id]
        hkt = HK / t
        tk = hkt / H
        ane = C.ELEC[id]
        sabolf(id)  # SABOLF 不修改标量哑元 ID
        for iat in range(1, C.NATOM + 1):
            n0i = C.N0A[iat]
            nki = C.NKA[iat]
            n1i = nki - 1  # 未再使用，保留
            for i in range(n0i, nki + 1):
                out = 0.0
                xin = 0.0
                nke = C.NNEXT[C.IEL[i]]
                for it in range(1, C.NTRANS + 1):
                    ii = C.ILOW[it]
                    jj = C.IUP[it]
                    if ii == i:
                        j = jj
                        if C.LINE[it]:
                            aij = (C.COLTAR[it, id] * C.wop[i, id]
                                   + C.RRD[it, id] * C.G[i] / C.G[j] * C.wop[i, id]
                                   * math.exp(hkt * C.FR0[it]))
                        else:
                            corr = UN
                            nke = C.NNEXT[C.IEL[i]]
                            if nke != j:
                                corr = (C.G[nke] / C.G[j]
                                        * math.exp((C.ENION[nke] - C.ENION[j]) * tk))
                            # 原文确为 COLTAR+WOP+RRD*...（"+WOP(I,ID)+" 照原样直译）
                            aij = (C.COLTAR[it, id] + C.wop[i, id]
                                   + C.RRD[it, id] * ane * C.SBF[i] * corr * C.wop[i, id])
                        aji = (C.COLRAT[it, id] + C.RRU[it, id]) * C.wop[j, id]
                        xin = xin + aij * C.POPUL[j, id]
                        out = out + aji
                    elif jj == i:
                        j = ii
                        if C.LINE[it]:
                            aji = (C.COLTAR[it, id] + C.wop[j, id]
                                   + C.RRD[it, id] * C.G[j] / C.G[i] * C.wop[j, id]
                                   * math.exp(hkt * C.FR0[it]))
                        else:
                            corr = UN
                            nke = C.NNEXT[C.IEL[j]]
                            if nke != i:
                                corr = (C.G[nke] / C.G[i]
                                        * math.exp((C.ENION[nke] - C.ENION[i]) * tk))
                            aji = (C.COLTAR[it, id] * C.wop[j, id]
                                   + C.RRD[it, id] * ane * C.SBF[j] * corr * C.wop[j, id])
                        aij = (C.COLRAT[it, id] + C.RRU[it, id]) * C.wop[i, id]
                        xin = xin + aij * C.POPUL[j, id]
                        out = out + aji
                rin[i, id] = xin
                rout[i, id] = out * C.POPUL[i, id]
    _auto_unit(16)  # 单元 16 未显式 OPEN（预连接）
    for i in range(1, C.NLEVEL + 1):
        if rin[i, C.ND] > 0.0:
            # 300 FORMAT('1 Level:',I5///)；'1' 为回车控制字符（换页），
            # 三个 / 表示之后输出两个空记录
            write_line(16, '1 Level:%5d' % i)
            write_line(16, '')
            write_line(16, '')
            for id in range(1, C.ND + 1):
                del_ = (rin[i, id] - rout[i, id]) / rin[i, id]
                # 310 FORMAT(2I5,1P3E16.7,2x,e16.7)
                write_line(16, '%5d%5d%16.7E%16.7E%16.7E  %16.7E'
                           % (i, id, rin[i, id], rout[i, id], del_, C.POPUL[i, id]))
    return


