def odfmer():
    """C     =================
C
C     Opacity distribution function for superlines to merged states
C     (calculated only if DT/T>=CHTL, kept constant after).
C
    对应 tlusty208.f 行 30331–30352"""
    CHTL = 1.0e-3  # PARAMETER
    for itr in range(1, C.NTRANS + 1):  # DO 10
        if not C.LINE[itr] or abs(C.INDEXP[itr]) != 2:
            continue  # GO TO 10
        for id in range(1, C.ND + 1):
            if C.INIT == 1 or abs(C.CHANT[id]) >= CHTL:
                odfhyd(id, itr)  # ODFHYD 不修改标量哑元
    return


# ---------------------------------------------------------------------

def odfhyd(id, itr):
    """C     =========================
C
C     Line ODF's for hydrogen line series
C
    哑元 ID,ITR 不被修改 → 无返回。
    对应 tlusty208.f 行 30359–30454"""
    # PARAMETER (CDOP=TWO*BOLK/HMASS)
    CDOP = TWO * BOLK / HMASS
    # PARAMETER (CA=2.997925D18,CCM=CA/1.D8,FRH=3.28805D15)
    CA = 2.997925e18
    CCM = CA / 1.0e8
    FRH = 3.28805e15
    # PARAMETER (RYDEL=911.764,TTW=2./3.)
    RYDEL = 911.764
    TTW = 2.0 / 3.0
    # PARAMETER (C00=1.25D-9,CID=0.02654)
    C00 = 1.25e-9
    CID = 0.02654
    # DIMENSION SIG,Sgt,ODF(MFRO),IODF(MFRO),YNUS(MFRO),ALAM(MFRO)
    sig = np.zeros(MFRO + 1)
    sgt = np.zeros(MFRO + 1)
    odf = np.zeros(MFRO + 1)
    iodf = np.zeros(MFRO + 1, dtype=np.int64)
    ynus = np.zeros(MFRO + 1)
    alam = np.zeros(MFRO + 1)
    jo = C.JNDODF[itr]
    if C.ISPODF == 0:
        nf = C.NFRODF[jo]
        for ij in range(1, nf + 1):
            iodf[ij] = 0
            sig[ij] = 0.0
            odf[ij] = 0.0
            ynus[ij] = C.FROS[ij, jo]
            alam[ij] = CAS / ynus[ij]
    else:
        nf = C.IFR1[itr] - C.IFR0[itr] + 1
        for ij in range(1, nf + 1):
            sig[ij] = 0.0
            ynus[ij] = C.FREQ[C.IFR0[itr] + ij - 1]
            alam[ij] = CAS / ynus[ij]
    ii = C.ILOW[itr]
    jj = C.IUP[itr]
    anes = math.exp(TTW * math.log(C.ELEC[id]))
    f00 = C00 * anes
    fra = FRH * (C.XI2[C.NQUANT[ii]] - C.XI2[C.NQUANT[jj]])
    dopo = fra / CCM * math.sqrt(CDOP * C.TEMP[id] + C.VTB * C.VTB)
    for j in range(C.NQLODF[ii], NLMX + 1):
        wl = RYDEL / (C.XI2[C.NQUANT[ii]] - C.XI2[j])
        fxk = f00 * C.XKIJ[jo, j]
        C.DBETA = wl * wl / CA / fxk
        C.BETAD = C.DBETA * dopo
        fid = CID * C.FIJ[jo, j] * C.DBETA
        divstr(1)
        wprob = C.WNHINT[j, id]
        odfhst(nf, fxk, fid, wprob, wl, alam, sgt)
        for ij in range(1, nf + 1):
            sig[ij] = sig[ij] + sgt[ij]
    i0 = 0  # 以下两值仅在 ISPODF==0 分支赋值并使用
    i1 = 0
    if C.ISPODF == 0:
        indexx(nf, sig, iodf)  # INDEXX 仅修改数组哑元 INDX
        for ij in range(1, nf + 1):
            odf[ij] = sig[iodf[ij]]
        i0 = C.IFR0[itr]
        i1 = C.IFR1[itr]
        if abs(C.INDEXP[itr]) == 2:
            ynus[1] = C.FREQ[i0]
        iw1 = iodf[1]
        for ij in range(2, nf + 1):
            iw2 = iodf[ij]
            if ij > 2 and ij < nf:
                ynus[ij] = ynus[ij - 1] - HALF * (C.WNUS[iw1, jo] + C.WNUS[iw2, jo])
            elif ij == 2:
                ynus[ij] = ynus[ij - 1] - HALF * (TWO * C.WNUS[iw1, jo] + C.WNUS[iw2, jo])
            elif ij == nf:
                ynus[ij] = ynus[ij - 1] - HALF * (C.WNUS[iw1, jo] + TWO * C.WNUS[iw2, jo])
            iw1 = iw2
    if C.ISPODF == 0:
        C.PRFLIN[id, i1] = 1.0e-35
        # TODO(port): 原文第 30446 行为 PRFLIN(ID,IJ0)=real(PRFLN)，
        # 其中 IJ0 在本例程中从未赋值（疑为循环变量 IJQ 之笔误）；
        # Fortran 中 IJ0 值未定义。此处取 0（numpy 未用的 0 号槽位）。
        ij0 = 0
        for ijq in range(i0, i1):  # DO IJQ=I0,I1-1
            ji = nf  # 若内层循环未触发 GO TO 70，JI 保持循环最后赋值 NF
            for ij in range(2, nf + 1):
                ji = ij
                if ynus[ij] <= C.FREQ[ijq]:
                    break  # GO TO 70
            # 70
            prfln = (odf[ji - 1] + (odf[ji] - odf[ji - 1])
                     * (C.FREQ[ijq] - ynus[ji - 1]) / (ynus[ji] - ynus[ji - 1]))
            C.PRFLIN[id, ij0] = float(prfln)
    else:
        for ij in range(1, nf + 1):
            C.PRFLIN[id, C.KFR0[itr] + ij - 1] = float(sig[ij])
    return


