def indexx(n, arrin, indx):
    """C     ===============================
C
C     Sorting routine（堆排序索引，Numerical Recipes INDEXX）
C
    仅修改数组哑元 INDX → 无返回。
    对应 tlusty208.f 行 30460–30504"""
    for j in range(1, n + 1):
        indx[j] = j
    m = idiv(n, 2) + 1  # Fortran 整数除法 N/2+1
    ir = n
    while True:  # 标号 10
        if m > 1:
            m = m - 1
            indxt = indx[m]
            q = arrin[indxt]
        else:
            indxt = indx[ir]
            q = arrin[indxt]
            indx[ir] = indx[1]
            ir = ir - 1
            if ir == 1:
                indx[1] = indxt
                return
        i = m
        j = m + m
        while j <= ir:  # 标号 20 的 IF/GO TO 20 循环
            if j < ir:
                if arrin[indx[j]] < arrin[indx[j + 1]]:
                    j = j + 1
            if q < arrin[indx[j]]:
                indx[i] = indx[j]
                i = j
                j = j + j
            else:
                j = ir + 1
            # GO TO 20
        indx[i] = indxt
        # GO TO 10


