def sigave():
    """C     =================
C
C     Read bound-free cross-sections for averaged levels
C     from the unit INSA (given by IFANCY), with increasing frequencies
C     It assumes that all continuum transitions for a given ion are
C     given in a successive order in the data
C
    对应 tlusty208.f 行 30510–30602"""
    # PARAMETER (HCCM=H*2.997925D10)
    HCCM = H * 2.997925e10
    # PARAMETER (TX=2.30258509299405,BAM=1.e-18)
    TX = 2.30258509299405
    BAM = 1.0e-18
    # DIMENSION XIFE(8)；DATA XIFE/.../（之后不修改 → 直接赋值）
    xife = [0.0, 63480.0, 130563.0, 247220.0, 442000.0, 605000.0, 799000.0,
            1008000.0, 1218380.0]  # 1 基（0 号槽不用）
    # DIMENSION FRINSG(MFREQ),CRIN(MFREQ),JKF(MFREQ)
    frinsg = np.zeros(MFREQ + 1)
    crin = np.zeros(MFREQ + 1)
    jkf = np.zeros(MFREQ + 1, dtype=np.int64)
    nfreqb = C.NFREQ
    if C.IBFINT > 0:
        nfreqb = C.NFREQC
    itr = 0
    while True:  # 标号 10
        itr = itr + 1
        if itr > C.NTRANS:
            return
        ic = C.ITRA[C.IUP[itr], C.ILOW[itr]]
        insa = C.IBF[ic]
        if insa < 50 or insa > 100:
            continue  # GO TO 10
        ie = C.IEL[C.ILOW[itr]]
        itr = itr - 1
        nl1 = C.NFIRST[ie]
        nl2 = C.NLAST[ie]
        if not feq(C.FIBFCS[ie], ' '):
            insa = C.INBFCS[ie]
            open_unit(insa, C.FIBFCS[ie], 'r')  # STATUS='OLD'
        # READ(INSA,*,END=500,ERR=500) IERR,IZRR,NLRR
        try:
            _v = _ldread(insa, 3)
            ierr = int(_v[0])
            izrr = int(_v[1])
            nlrr = int(_v[2])  # 未再使用，保留
        except (EOFError, ValueError, IndexError):
            # 标号 500
            quit('error in data for bf-cs of averaged levels - itr,ie:', itr, ie)
            return  # QUIT 中 STOP 已终止；此 return 仅为结构完整
        for i in range(nl1, nl2 + 1):  # DO 100 I=NL1,NL2
            itr = itr + 1
            if C.INDEXP[itr] == 0:
                continue  # GO TO 100
            ic = C.ITRA[C.IUP[itr], C.ILOW[itr]]
            # READ(INSA,*) INL,ECMR,GDUM,NFIS（无 END/ERR：
            # 格式错误时 Fortran 为运行时错误，此处异常自然上抛）
            _v = _ldread(insa, 4)
            inl = int(_v[0])  # 未再使用，保留
            ecmr = _v[1]
            gdum = _v[2]  # 未再使用，保留
            nfis = int(_v[3])
            if ierr == 26:
                ecmr = xife[izrr] - ecmr
                de = abs((C.ENION[C.ILOW[itr]] - HCCM * ecmr) / C.ENION[C.ILOW[itr]])
                if de > 2.0e-2:
                    print(insa, ie, itr, i)  # PRINT *
            # 20
            for ij in range(1, nfis + 1):
                ji = nfis - ij + 1
                # READ(INSA,*,END=500,ERR=500) FRINSG(JI),CRIN(JI)
                try:
                    _v = _ldread(insa, 2)
                except (EOFError, ValueError, IndexError):
                    # 标号 500
                    quit('error in data for bf-cs of averaged levels - itr,ie:', itr, ie)
                    return
                frinsg[ji] = _v[0]
                crin[ji] = _v[1]
            for ij in range(1, nfreqb + 1):
                jk = 0
                fr = C.FREQ[ij]
                if C.ISPODF >= 1:
                    fr = C.FREQ[C.IFREQB[ij]]
                for ik in range(1, nfis + 1):
                    if fr > frinsg[ik]:
                        jk = ik
                        break  # GO TO 40
                else:
                    jk = nfis  # 循环正常结束（未触发 GO TO 40）
                # 40
                if jk == 1:
                    jk = 2
                jkf[ij] = jk
            for ij in range(1, nfreqb + 1):
                jk = jkf[ij]
                fr = C.FREQ[ij]
                if C.ISPODF >= 1:
                    fr = C.FREQ[C.IFREQB[ij]]
                if crin[jk - 1] == 0.0 or crin[jk] == 0.0:
                    C.BFCS[ic, ij] = float(crin[jk] + (fr - frinsg[jk])
                                           / (frinsg[jk - 1] - frinsg[jk])
                                           * (crin[jk - 1] - crin[jk]))
                else:
                    xf1 = math.log10(frinsg[jk - 1])
                    xf2 = math.log10(frinsg[jk])
                    ys1 = math.log10(crin[jk - 1])
                    ys2 = math.log10(crin[jk])
                    xxf = math.log10(fr)
                    yyf = (xxf - xf2) / (xf1 - xf2) * (ys1 - ys2) + ys2
                    extx = math.exp(TX * yyf)
                    C.BFCS[ic, ij] = float(extx)
                C.BFCS[ic, ij] = float(BAM * C.BFCS[ic, ij])
        # 100 CONTINUE；GO TO 10 → 外层 while 继续


