def corrwm():
    """C     =================
C
C     The routine for management of various flags for treating
C     frequency points; in particular those connected to the so-called
C     "subtraction weights" (in the non-overlapping mode only)
C
    对应 tlusty208.f 行 30642–30766"""
    T15 = 1.0e-15  # PARAMETER
    C.NFREQE = 0
    for ij in range(1, C.NFREQ + 1):  # DO 10
        C.IJEX[ij] = 0
        for id in range(1, C.ND + 1):
            C.LSKIP[id, ij] = False
        if C.IFPRAD == 0:
            for id in range(1, C.ND + 1):
                C.LSKIP[id, ij] = True
        if C.IJALI[ij] != 0:
            continue  # GO TO 10
        C.NFREQE = C.NFREQE + 1
        C.IJEX[ij] = C.NFREQE
        C.IJFR[C.NFREQE] = ij
    if C.IFRYB != 0:
        C.NFREQE = 0
        for ij in range(1, C.NFREQ + 1):
            C.IJEX[ij] = 0
    if C.IBFINT <= 0:
        for ij in range(1, C.NFREQ + 1):
            C.IJBF[ij] = ij
            C.AIJBF[ij] = UN
    else:
        if C.ISPODF == 0:
            for ij in range(1, C.NFREQC + 1):
                C.IJBF[ij] = ij
                C.AIJBF[ij] = UN
            if C.NFREQ > C.NFREQC:
                for ij in range(C.NFREQC + 1, C.NFREQ + 1):
                    fr = C.FREQ[ij]
                    ij0 = 1
                    for ijt in range(1, C.NFREQC + 1):
                        if C.FREQ[ijt] <= fr:
                            ij0 = ijt
                            break  # GO TO 12
                    # 12
                    ij1 = ij0 - 1
                    a1 = (fr - C.FREQ[ij0]) / (C.FREQ[ij1] - C.FREQ[ij0])
                    C.IJBF[ij] = ij1
                    C.AIJBF[ij] = a1
        else:
            for ij in range(1, C.NFREQC):  # DO IJ=1,NFREQC-1
                ij0 = C.IFREQB[ij]
                ij1 = C.IFREQB[ij + 1]
                for kj in range(ij0, ij1):  # DO KJ=IJ0,IJ1-1
                    C.IJBF[kj] = ij
                    C.AIJBF[kj] = ((C.FREQ[kj] - C.FREQ[ij1])
                                   / (C.FREQ[ij0] - C.FREQ[ij1]))
            ij0 = C.IFREQB[C.NFREQC]
            C.IJBF[ij0] = C.NFREQC
            C.AIJBF[ij0] = UN
    if C.NFREQE > MFREX:
        quit('nfreqe.gt.mfrex', C.NFREQE, MFREX)
    for itr in range(1, C.NTRANS + 1):  # DO 100
        if not C.LINE[itr]:
            continue  # GO TO 100
        # first set up array LSKIP(ID,IJ), which has values
        # TRUE - if the radiation at frequency point IJ does not contribute
        #        radiation pressure (ie. this point belongs to a transition
        #        for which the user required the radiation pressure to be
        #        skipped - IABS(INDEXP) chosen as 9 or 19)
        # FALSE - normal calculatitn of radiation pressure
        inx = abs(C.INDEXP[itr])
        if inx == 9 or inx >= 19:
            for ij in range(C.IFR0[itr], C.IFR1[itr] + 1):
                for id in range(1, C.ND + 1):
                    C.LSKIP[id, ij] = True
    if C.NFREQE > 0:
        # 609 FORMAT(1H0//' FREQUENCY POINTS AND WEIGHTS - EXPLICIT'/
        #  *            ' ---------------------------------------'//
        #  * '       IJ',7X,'FREQ',13X,'WEIGHT',11X,'PROF'/)
        print()   # 1H0：回车控制（前置空行）
        print()   # /
        print(' FREQUENCY POINTS AND WEIGHTS - EXPLICIT')
        print(' ---------------------------------------')
        print()
        print('       IJ        FREQ             WEIGHT           PROF')
        print()
    for ij in range(1, C.NFREQ + 1):  # DO 110
        fr15 = C.FREQ[ij] * T15
        C.W0E[ij] = C.W[ij] * PI4H / C.FREQ[ij]
        C.BNUE[ij] = BN * fr15 * fr15 * fr15
        if C.IJALI[ij] != 0 or C.IFRYB > 0:
            continue  # GO TO 110
        # 610 FORMAT(1H ,I8,1P2D17.8,D15.5,D17.8)
        if C.ISPODF == 0:
            print(' %8d%17.8E%17.8E%15.5E' % (ij, C.FREQ[ij], C.W[ij], C.PROF[ij]))
        else:
            print(' %8d%17.8E%17.8E' % (ij, C.FREQ[ij], C.W[ij]))
    for ij in range(1, C.NFREQ + 1):
        C.WC[ij] = C.W[ij]
        if C.IJALI[ij] <= 0:
            C.WC[ij] = 0.0
    return


