def ijalis(itr, ifrq0, ifrq1):
    """C     ==================================
C
C     auxiliary routine - sets up the necessary flags for ALI treatment
C      of individual transitions (in the fully hybrid CL/ALI scheme)
C
C     Output:
C
C     IJALI(IJ) = 0 - frequency point IJ is an explicit point
C               = 1 - frequency point IJ is an ALI point
C
C     LEXP(ITR) = T - at least one point within transition ITR is explicit
C     LEXP(ITR) = F - no point within transition ITR is explicit
C     LALI(ITR) = T - at least one point within transition ITR is ALI
C     LALI(ITR) = F - no point within transition ITR is ALI
C
    标量哑元 IFRQ1 被赋值（IFRQ1=NF）→ 返回全部标量哑元 (itr, ifrq0, ifrq1)。
    对应 tlusty208.f 行 30773–30850"""
    # c     NFRECL=NFREQ
    # c     if(nfrecl.ge.nfreq) return  （原代码已注释）
    indxp = C.INDEXP[itr]
    i0 = C.IFR0[itr]
    i1 = C.IFR1[itr]
    nf = i1 - i0 + 1
    for ij in range(i0, i1 + 1):
        if indxp > 0:
            C.IJALI[ij] = 0
        elif indxp < 0:
            C.IJALI[ij] = 1
    if indxp > 0:
        # primarily explicit transitions
        C.LEXP[itr] = True
        C.LALI[itr] = False
        if ifrq0 > 0 and C.iadop[C.IATM[C.ILOW[itr]]] == 0:
            C.LALI[itr] = True
            if ifrq1 == 0 or ifrq1 > nf:
                ifrq1 = nf
            for i in range(ifrq0, ifrq1 + 1):
                C.IJALI[i0 + i - 1] = 1
        elif ifrq0 < 0:
            C.LALI[itr] = True
            # READ(57,*) (IJALI(IJ),IJ=I0,I1)
            # TODO(port): 单元 57 在全程序中从未显式 OPEN，Fortran 依赖预连接
            #（fort.57）；此处直接读，若未连接将抛 KeyError。
            _v = _ldread(57, nf)
            for _k in range(nf):
                C.IJALI[i0 + _k] = int(_v[_k])
        if ifrq0 == 1 and ifrq1 == nf:
            C.LEXP[itr] = False
    elif indxp < 0:
        # primarily ALI transitions
        C.LALI[itr] = True
        C.LEXP[itr] = False
        if ifrq0 > 0 and C.iadop[C.IATM[C.ILOW[itr]]] == 0:
            C.LEXP[itr] = True
            if ifrq1 == 0 or ifrq1 > nf:
                ifrq1 = nf
            for i in range(ifrq0, ifrq1 + 1):
                C.IJALI[i0 + i - 1] = 0
        elif ifrq0 < 0:
            C.LEXP[itr] = True
            # READ(57,*) (IJALI(IJ),IJ=I0,I1)（单元 57 同上 TODO）
            _v = _ldread(57, nf)
            for _k in range(nf):
                C.IJALI[i0 + _k] = int(_v[_k])
        if ifrq0 == 1 and ifrq1 == nf:
            C.LALI[itr] = False
    if C.NFFIX > 0:
        for ij in range(i0, i1 + 1):
            C.IJALI[ij] = 1
        C.LALI[itr] = True
        C.LEXP[itr] = False
    return itr, ifrq0, ifrq1


