# -*- coding: utf-8 -*-
"""
chunk12.py — 分片 12：tlusty208.f 行 30857–33384

包含子程序：
    IJALI2, LEVSET, DWNFR0, DWNFR1, SGMER0, SGMER1, SGMERD,
    TDPINI, OPAINI, TRAINI, RTEDF1, RTEDF2, RTEFR1, RTEINT

拼接时模块头部已有：
    import math, sys
    import numpy as np
    from params import *
    import commons as C
    from fortran import *
故本文件不含任何 import。
"""

# COMMON/OPTDPT/DT(MDEPTH)：RTEDF1/RTEFR1/RTEINT 等子程序共享的内联 COMMON 块，
# 规范名 C.DT（已收录 commons.py DECLS）。
# tlusty208.f 中共 9 处声明 COMMON/OPTDPT/DT(MDEPTH)
# （行 31608/32311/33057/38558/38766/38953/39699/39799/42932），跨分片共享 C.DT。


def ijali2():
    """
    auxiliary routine - sets up the necessary flags for ALI treatment
    of individual transitions (in the fully hybrid CL/ALI scheme)

    Version for opacity sampling mode

    Output:

    IJALI(IJ) = 0 - frequency point IJ is an explicit point
              = 1 - frequency point IJ is an ALI point

    LEXP(ITR) = T - at least one point within transition ITR is explicit
    LEXP(ITR) = F - no point within transition ITR is explicit
    LALI(ITR) = T - at least one point within transition ITR is ALI
    LALI(ITR) = F - no point within transition ITR is ALI

    对应 tlusty208.f 行 30857–30987
    """
    for ij in range(1, C.NFREQ + 1):
        C.IJALI[ij] = 1
        C.IJX[ij] = 1
        C.NLINES[ij] = 0
    nlitot = 0                     # NLITOT/NLIMAX 为隐式局部变量（不在任何 COMMON 中）
    nlimax = 0

    # Overlapping lines at frequency IJ
    for it in range(1, C.NTRANS + 1):            # DO 10 IT=1,NTRANS
        if C.LINEXP[it]:
            continue                             # GO TO 10
        for ij in range(C.IFR0[it], C.IFR1[it] + 1):
            C.NLINES[ij] = C.NLINES[ij] + 1
            # int2：编译器特有的 INTEGER*2 转换内置函数（ITRLIN 为 INTEGER*2 数组）
            C.ITRLIN[C.NLINES[ij], ij] = np.int16(it)
    # 10 CONTINUE
    for ij in range(1, C.NFREQ + 1):
        nlitot = nlitot + C.NLINES[ij]
        if C.NLINES[ij] > MITJ:
            # CALL QUIT(...)：QUIT 不修改标量哑元（内部 STOP 终止程序）
            quit('Too many overlappins-nlines(ij).gt.mitj', C.NLINES[ij], MITJ)
        if C.NLINES[ij] > nlimax:
            nlimax = C.NLINES[ij]
    # 原 WRITE(10,*) 自由格式
    write_line(10, ' Max. number of line overlaps:       ' + str(nlimax))
    write_line(10, ' Total number of line overlaps:      ' + str(nlitot))

    # Switches for ALI and explicit transitions
    if C.NFFIX == 2:
        for itr in range(1, C.NTRANS + 1):
            C.LEXP[itr] = False
            C.LALI[itr] = True
        return

    xfrma = math.log10(C.FRS1)     # XFRMA 赋值后未再使用（原代码如此）
    for itr in range(1, C.NTRANS + 1):           # DO 100 ITR=1,NTRANS
        indxp = C.INDEXP[itr]
        i0 = C.IFR0[itr]
        i1 = C.IFR1[itr]
        nf = i1 - i0 + 1
        if C.FR0[itr] > C.FRS1:
            continue                             # GO TO 100
        ijl = C.IJTC[itr]

        # primarily explicit line transitions
        if C.LINE[itr]:
            if indxp > 0:
                C.LEXP[itr] = True
                C.LALI[itr] = False
                if C.IFC0[itr] == 0:
                    for ij in range(i0, i1 + 1):
                        C.IJALI[ij] = 0
                else:
                    C.LALI[itr] = True
                    nfc = abs(C.IFC1[itr] - C.IFC0[itr] + 1)
                    if nfc == nf:
                        C.LEXP[itr] = False
                    else:
                        nfc = idiv(nfc, 2)       # Fortran 整数除法 NFC/2
                        for ij in range(i0, ijl - nfc + 1):
                            C.IJALI[ij] = 0
                        for ij in range(ijl + nfc, i1 + 1):
                            C.IJALI[ij] = 0
            elif indxp < 0:
                # primarily ALI line transitions
                C.LEXP[itr] = False
                C.LALI[itr] = True
                if C.IFC0[itr] != 0:
                    C.LEXP[itr] = True
                    nfc = abs(C.IFC1[itr] - C.IFC0[itr] + 1)
                    if nfc == nf:
                        C.LALI[itr] = False
                        for ij in range(i0, i1 + 1):
                            C.IJALI[ij] = 0
                    else:
                        nfc = idiv(nfc, 2)       # Fortran 整数除法 NFC/2
                        for ij in range(ijl - nfc, ijl + nfc + 1):
                            C.IJALI[ij] = 0
        else:
            # continuum transitions
            if C.IFC0[itr] > 0:
                for ij in range(1, C.IFC1[itr] - C.IFC0[itr] + 2):
                    C.IJALI[ijl - ij + 1] = 0
    # 100 CONTINUE
    return


def levset():
    """
    sets up level parameters IIEXP and IIFOR which control the
    treatment of levels

    对应 tlusty208.f 行 30994–31170
    """
    if C.IOPTAB < 0:
        return

    # 1. case - treatment of levels determined by IMODL
    if C.IFLEV == 0:
        for i in range(1, C.NLEVEL + 1):
            C.iiexp[i] = 0
            C.iifor[i] = 0
        iie = 0
        iif = 0
        igrp = 0                     # 循环后仍被引用（Fortran 语义保留其值）
        for iat in range(1, C.NATOM + 1):          # DO 20 IAT=1,NATOM
            igrp = 0
            if C.iifix[iat] == 1:
                continue                           # GO TO 20
            for i in range(C.N0A[iat], C.NKA[iat] + 1):
                inew = 1
                if C.imodl[i] == 0:
                    iie = iie + 1
                    iif = iif + 1
                    C.iiexp[i] = iie
                    C.iifor[i] = iif
                    C.indlev[C.iiexp[i]] = i
                elif C.imodl[i] > 0:
                    iif = iif + 1
                    C.iifor[i] = iif
                    if C.iltlev[i] >= 1:
                        iie = iie + 1
                        C.iiexp[i] = iie
                    if i == C.NFIRST[C.IEL[i]] or i == C.NNEXT[C.IEL[i]]:
                        iie = iie + 1
                        C.iiexp[i] = iie
                elif C.imodl[i] < -100:
                    if i > 1:
                        if C.imodl[i] == C.imodl[i - 1]:
                            inew = 0
                    C.iiexp[i] = -iie
                    if inew == 1:
                        iie = iie + 1
                        C.iiexp[i] = -iie
                        im = C.NFIRST[C.IEL[i]]
                        lml = True
                        # DO WHILE (IM.LT.I-1 .AND. LML)
                        while im < i - 1 and lml:
                            if C.imodl[i] == C.imodl[im]:
                                C.iiexp[i] = C.iiexp[im]
                                iie = iie - 1
                                lml = False
                            im = im + 1
                    igrp = 1
                    iif = iif + 1
                    C.iifor[i] = iif
                elif C.imodl[i] < -200:
                    # 原代码中此分支位于 IMODL.LT.-100 分支之后，实际不可达；直译保留
                    if i > 1:
                        if C.imodl[i] == C.imodl[i - 1]:
                            inew = 0
                    if inew == 1:
                        iie = iie + 1
                    if inew == 1:
                        iif = iif + 1
                    C.iiexp[i] = -iie
                    C.iifor[i] = -iif
                    igrp = 1
            if igrp == 1:
                for i in range(C.N0A[iat], C.NKA[iat] + 1):
                    if C.iiexp[i] > 0:
                        C.iiexp[i] = -C.iiexp[i]
                    if C.imodl[i] == 0:
                        C.imodl[i] = 7
        # 20 CONTINUE
        # Fortran DO 循环正常结束后 IAT=NATOM+1；下方 IF(IGRP.EQ.1) 块用到循环后的 IAT
        iat = C.NATOM + 1
        C.NLVEXP = abs(iie)
        if C.NLVEXP > MLVEXP:
            # CALL QUIT('nlvexp.gt.mlvexp',nlvexp,mlvexp)：QUIT 不修改标量哑元
            quit('nlvexp.gt.mlvexp', C.NLVEXP, MLVEXP)
        C.NLVFOR = abs(iif)
        for i in range(1, C.NLEVEL + 1):           # DO 30 I=1,NLEVEL
            if C.imodl[i] == 1 or C.imodl[i] == 3:
                C.iiexp[i] = 0
            elif C.imodl[i] == 4 or C.imodl[i] == 5:
                C.iiexp[i] = 0
            elif C.imodl[i] == -1 or C.imodl[i] == -3:
                C.iiexp[i] = 0
                C.iifor[i] = 0
            elif C.imodl[i] == 6:
                C.iiexp[i] = 0
            elif C.imodl[i] == -5 or C.imodl[i] == -6:
                C.iiexp[i] = 0
                C.iifor[i] = 0
            elif C.imodl[i] < -100:
                C.imodl[i] = 7
            elif C.imodl[i] < -200:
                # 同样位于 IMODL.LT.-100 之后，实际不可达；直译保留
                C.imodl[i] = -7
            for id in range(1, C.ND + 1):
                C.ILTREF[i, id] = C.NNEXT[C.IEL[i]]
        # 30 CONTINUE
        if igrp == 1:
            # TODO(port): 此处 IAT 为 DO 20 循环结束后的值 NATOM+1（Fortran 语义），
            # N0A(NATOM+1)/NKA(NATOM+1) 可能越界；原代码即如此，按 Fortran 语义直译
            for i in range(C.N0A[iat], C.NKA[iat] + 1):
                C.imodl[i] = 7

    else:
        # 2. case - treatment of levels automatic - all levels with ILK=0
        #           in updated LTE mode
        iif = 0
        for i in range(1, C.NLEVEL + 1):           # DO 110 I=1,NLEVEL
            if C.iifix[C.IATM[i]] == 1:
                continue                           # GO TO 110
            C.imodl[i] = 5
            if i == C.NFIRST[C.IEL[i]] or i == C.NNEXT[C.IEL[i]]:
                iif = iif + 1
                C.iifor[i] = iif
        # 110 CONTINUE
        C.NLVEXP = iif
        if C.NLVEXP > MLVEXP:
            quit('nlvexp.gt.mlvexp', C.NLVEXP, MLVEXP)
        C.NLVFOR = iif
        for i in range(1, C.NLEVEL + 1):
            if i != C.NFIRST[C.IEL[i]] and i != C.NNEXT[C.IEL[i]]:
                C.iifor[i] = 0
        for i in range(1, C.NLEVEL + 1):
            C.iiexp[i] = C.iifor[i]
            if C.iiexp[i] > 0:
                C.indlev[C.iiexp[i]] = i
            for id in range(1, C.ND + 1):
                C.ILTREF[i, id] = C.NNEXT[C.IEL[i]]
        if not C.LTE:
            for i in range(1, C.NLEVEL + 1):
                C.iifor[i] = i
            C.NLVFOR = C.NLEVEL

    # initialize b-factors
    for i in range(1, C.NLEVEL + 1):
        for id in range(1, C.ND + 1):
            C.BFAC[i, id] = UN

    for ii in range(1, C.NLVEXP + 1):
        C.indlev[ii] = 0
        for id in range(1, C.ND + 1):
            C.IGZERO[ii, id] = 0
    for i in range(1, C.NLEVEL + 1):
        for id in range(1, C.ND + 1):
            C.IPZERO[i, id] = 0
        if abs(C.imodl[i]) <= 6:
            if C.iiexp[i] > 0:
                C.indlev[C.iiexp[i]] = i
    return


def dwnfr0(id):
    """
    Auxiliary quantities for dissolved fractions

    对应 tlusty208.f 行 31177–31201
    标量哑元 ID 不被修改 → 无返回值
    """
    SIXTH = UN / 6.0
    CCOR = 0.09
    P1 = 0.1402
    P2 = 0.1285
    P3 = UN
    P4 = 3.15
    P5 = 4.0
    F23 = -2.0 / 3.0

    ane = C.ELEC[id]
    C.ELEC23[id] = math.exp(F23 * math.log(ane))
    anes = math.exp(SIXTH * math.log(ane))
    C.ACOR[id] = CCOR * anes / C.SQT1[id]
    x = math.exp(P4 * math.log(UN + P3 * C.ACOR[id]))
    C.DWC2[id] = P2 * x
    a3 = C.ACOR[id] * C.ACOR[id] * C.ACOR[id]
    for izz in range(1, MZZ + 1):
        C.Z3[izz] = izz * izz * izz
        C.DWC1[izz, id] = P1 * (x + P5 * (izz - UN) * a3)
    return


def dwnfr1(fr, fr0, id, izz, dw1):
    """
    dissolved fraction for frequency FR

    对应 tlusty208.f 行 31207–31237
    修改标量哑元 DW1 → 按约定返回全部标量哑元 (fr, fr0, id, izz, dw1)
    注意：哑元 FR0 是标量，与 COMMON 数组 C.FR0 无关
    """
    TKN = 3.01
    CKN = 5.33333333
    CB0 = 8.59e14
    SQFRH = 5.734152e7

    cb = CB0 * C.bergfc

    if fr < fr0:
        xn = SQFRH * izz / math.sqrt(fr0 - fr)
        if xn <= TKN:
            xkn = UN
        else:
            xn1 = UN / (xn + UN)
            xkn = CKN * xn * xn1 * xn1
        beta = cb * C.Z3[izz] * xkn / (xn * xn * xn * xn) * C.ELEC23[id]
        beta3 = beta * beta * beta
        beta32 = math.sqrt(beta3)
        f = (C.DWC1[izz, id] * beta3) / (UN + C.DWC2[id] * beta32)
        dw1 = UN - f / (UN + f)
    else:
        dw1 = UN
    return fr, fr0, id, izz, dw1


def sgmer0():
    """
    （无头部注释；计算合并能级的光致电离截面累积量 SGMSUM）

    对应 tlusty208.f 行 31243–31287
    """
    FRH = 3.28805e15
    PH2 = 2.815e29 * 2.0
    EHB = 157802.77355
    fredg = np.zeros(NLMX + 1)
    s = np.zeros(NLMX + 1)
    sum = np.zeros(NLMX + 1)
    sud = np.zeros(NLMX + 1)

    imer = 0
    for ii in range(1, C.NLEVEL + 1):              # DO 100 II=1,NLEVEL
        if C.ifwop[ii] >= 0:
            continue                               # GO TO 100
        imer = imer + 1
        C.IMRG[ii] = imer
        C.IIMER[imer] = ii
        ie = C.IEL[ii]
        ch = C.IZ[ie] * C.IZ[ie]
        C.FRCH[imer] = FRH * ch
        C.SGM0[imer] = PH2 * ch * ch
        ii0 = C.NQUANT[ii - 1] + 1
        for id in range(1, C.ND + 1):
            ex = EHB * ch * C.TEMP1[id]
            for i in range(ii0, NLMX + 1):
                fredg[i] = C.FRCH[imer] * C.XI2[i]   # FREDG 之后未使用（原代码如此）
                exi = math.exp(ex * C.XI2[i])
                s[i] = exi * C.WNHINT[i, id] * C.XI3[i]
                sum[i] = 0.0
            sum[NLMX] = s[NLMX]
            sud[NLMX] = s[NLMX] * C.XI2[NLMX]        # SUD 之后未使用（原代码如此）
            for i in range(NLMX - 1, ii0 - 1, -1):
                sum[i] = sum[i + 1] + s[i]
            for i in range(1, ii0):
                sum[i] = sum[ii0]
            sgem = C.SGM0[imer] / C.GMER[imer, id]
            for i in range(1, NLMX + 1):
                C.SGMSUM[i, imer, id] = sum[i] * sgem
    # 100 CONTINUE
    return


def sgmer1(frinv, fr3inv, imer, id, sgme1):
    """
    photoionization cross-section for a merged level

    对应 tlusty208.f 行 31293–31306
    修改标量哑元 SGME1 → 按约定返回全部标量哑元 (frinv, fr3inv, imer, id, sgme1)
    """
    # Fortran INT 截断取整（平方根非负，int() 截断等价）
    isu = int(math.sqrt(C.FRCH[imer] * frinv)) + 1
    sgme1 = C.SGMSUM[isu, imer, id] * fr3inv
    return frinv, fr3inv, imer, id, sgme1


def sgmerd(frinv, fr3inv, imer, id, sgme1, dsgme1):
    """
    photoionization cross-section for a merged level

    对应 tlusty208.f 行 31312–31326
    修改标量哑元 SGME1、DSGME1 → 按约定返回全部标量哑元
    (frinv, fr3inv, imer, id, sgme1, dsgme1)
    """
    # Fortran INT 截断取整（平方根非负，int() 截断等价）
    isu = int(math.sqrt(C.FRCH[imer] * frinv)) + 1
    sgme1 = C.SGMSUM[isu, imer, id] * fr3inv
    dsgme1 = -C.SGMSUD[isu, imer, id] * fr3inv
    return frinv, fr3inv, imer, id, sgme1, dsgme1


def tdpini():
    """
    initialization of only temperature dependent quantities

    对应 tlusty208.f 行 31332–31369
    """
    # PARAMETER (CFF1=1.3727D-25,CFF2=4.3748D-10,CFF3=2.5993D-7)
    # PARAMETER (SGFF0 = 3.694D8)  —— 原代码声明但在本例程中未使用，直译保留
    CFF1 = 1.3727e-25
    CFF2 = 4.3748e-10
    CFF3 = 2.5993e-7
    SGFF0 = 3.694e8

    # temperature-dependent quantities
    for id in range(1, C.ND + 1):
        t = C.TEMP[id]
        t1 = UN / t
        C.HKT1[id] = HK * t1
        C.HKT21[id] = C.HKT1[id] * t1
        C.TK1[id] = C.HKT1[id] / H
        C.SQT1[id] = math.sqrt(t)
        C.TEMP1[id] = t1
        gfree0(id)                   # CALL GFREE0(ID)：GFREE0 不修改标量哑元
        C.EMEL1[id] = UN

    # delta m (for evaluation of optical depths)
    for id in range(1, C.ND):        # DO ID=1,ND-1
        C.DELDM[id] = HALF * (C.DM[id + 1] - C.DM[id])
        C.DELDMZ[id] = C.DELDM[id]
        if C.IZSCAL == 1:
            C.DELDMZ[id] = HALF * (C.ZD[id] - C.ZD[id + 1])
    C.DEDM1 = C.DM[1] / C.DENS[1]
    return


# DATA ICOMP /0/：ICOMP 之后被赋值（Fortran 隐含 SAVE）→ 提升为模块级变量
_save_opaini_icomp = 0


def opaini(imod):
    """
    initialization of only depth-dependent quantities
    for evaluation of opacities

    对应 tlusty208.f 行 31376–31530
    标量哑元 IMOD 不被修改 → 无返回值
    """
    global _save_opaini_icomp
    prf = np.zeros(MFREQL + 1)
    popp = np.zeros(MLEVEL + 1)
    # PARAMETER (CFF1=1.3727D-25,CFF2=4.3748D-10,CFF3=2.5993D-7)
    # PARAMETER (SIXTH=UN/6.,CCOR=0.09,T32=1.5D0)
    # PARAMETER (SGFF0 = 3.694D8)
    CFF1 = 1.3727e-25                # CFF1/SIXTH/CCOR 在本例程中未使用（原代码如此）
    CFF2 = 4.3748e-10
    CFF3 = 2.5993e-7
    SIXTH = UN / 6.0
    CCOR = 0.09
    T32 = 1.5
    SGFF0 = 3.694e8
    # TODO(port): N0HN 在原代码 OPAINI 中未赋值即被使用（隐式局部变量，
    # 不在任何 COMMON 中；其他子程序中的 N0HN 均为各自局部量）。
    # Fortran 读到的是未初始化值，此处按 0 初始化。
    n0hn = 0

    for id in range(1, C.ND + 1):
        wmt = C.WMM[id] * C.YTOT[id]   # WMT 之后未使用（原代码如此）
        t = C.TEMP[id]
        ane = C.ELEC[id]
        C.ELEC1[id] = UN / ane
        C.DENS1[id] = UN / C.DENS[id]
        C.DENSI[id] = C.DENS1[id]
        C.DENSIM[id] = C.DENSI[id] * C.WMM[id]
        C.ELSCAT[id] = ane * SIGE
        dwnfr0(id)                     # DWNFR0 不修改标量哑元
        wnstor(id)                     # WNSTOR 不修改标量哑元
        sabolf(id)                     # SABOLF 不修改标量哑元
        reflev(id, imod)               # REFLEV 不修改标量哑元
        # CALL LEVGRP(ID,IIEXP,0,POPP)：LEVGRP 不修改标量哑元 IMODE（实参 0 为字面量）
        levgrp(id, C.iiexp, 0, popp)
        for ii in range(1, C.NLEVEL + 1):
            C.POPINV[ii, id] = 0.0
            if C.POPUL[ii, id] != 0.0:
                C.POPINV[ii, id] = UN / C.POPUL[ii, id]
        for ii in range(1, C.NLEVEL + 1):
            iie = C.iiexp[ii]
            if iie == 0:
                ie = C.ILTREF[ii, id]
                C.PP[ii, id] = C.POPUL[ii, id] * C.POPINV[ie, id]
                if abs(C.imodl[ii]) <= 5:
                    C.PT[ii, id] = C.POPUL[ii, id] * C.DSBPST[ii, id]
                    C.PN[ii, id] = C.POPUL[ii, id] * C.DSBPSN[ii, id]
            elif iie < 0:
                C.PP[ii, id] = C.SBPSI[ii, id]
        for ion in range(1, C.NION + 1):
            C.USUMS[ion, id] = C.USUM[ion]
            C.DUSMT[ion, id] = C.DUSUMT[ion]
            C.DUSMN[ion, id] = C.DUSUMN[ion]

        # quantities for the bound-free opacity
        for ibft in range(1, C.NTRANC + 1):
            itr = C.ITRBF[ibft]
            ii = C.ILOW[itr]
            jj = C.IUP[itr]
            it = C.ITRA[jj, ii]
            ie = C.IEL[ii]
            nke = C.NNEXT[ie]
            corr = UN
            if nke != jj:
                corr = (C.G[nke] / C.G[jj]
                        * math.exp((C.ENION[nke] - C.ENION[jj]) * C.TK1[id]))
            C.ABTRA[itr, id] = C.POPUL[ii, id]
            C.EMTRA[itr, id] = C.POPUL[jj, id] * ane * C.SBF[ii] * C.wop[ii, id] * corr
            C.DEMLT[itr, id] = -(T32 + C.FR0[itr] * C.HKT1[id]) / C.TEMP[id]

        # quantities for the free-free opacity
        if C.IELHM > 0:
            C.CFFN[id] = C.POPUL[C.NFIRST[C.IELH], id] * ane
            C.CFFT[id] = CFF2 - CFF3 / t
        sgff = SGFF0 / C.SQT1[id] * ane
        for ion in range(1, C.NION + 1):
            C.SFF2[ion, id] = math.exp(C.FF[ion] * C.HKT1[id])
            C.SFF3[ion, id] = C.POPUL[C.NNEXT[ion], id] * C.CHARG2[ion] * sgff
            C.DSFF[ion, id] = (C.FF[ion] * C.HKT1[id] + HALF) * C.TEMP1[id]
    if C.IZSCAL == 1:
        for id in range(1, C.ND + 1):
            C.DENSI[id] = UN
            C.DENSIM[id] = 0.0
    sgmer0()

    # initialization of the line opacity
    laser = C.ITER > C.itlas         # LASER 为局部变量（不在任何 COMMON 中）
    for itr in range(1, C.NTRANS + 1):             # DO 200 ITR=1,NTRANS
        indxa = abs(C.INDEXP[itr])
        if not C.LINE[itr]:
            continue                               # GO TO 200
        ii = C.ILOW[itr]
        jj = C.IUP[itr]
        if indxa != 0 and C.INTMOD[itr] != 0 and _save_opaini_icomp == 0:
            ijl0 = C.IFR0[itr]
            ijl1 = C.IFR1[itr]
            if C.ISPODF >= 1:
                ijl0 = C.KFR0[itr]
                ijl1 = C.KFR1[itr]
            if indxa < 2 or indxa > 4:
                for id in range(1, C.ND + 1):
                    linpro(itr, id, prf)           # LINPRO 不修改标量哑元
                    for ij in range(ijl0, ijl1 + 1):
                        # real()：REAL*8 → REAL*4 窄化（PRFLIN 为 REAL*4 数组）
                        C.PRFLIN[id, ij] = float(prf[ij - ijl0 + 1])
        gg = C.G[ii] / C.G[jj]
        for id in range(1, C.ND + 1):
            if C.ifwop[jj] >= 0:
                pi = C.POPUL[ii, id] * C.wop[jj, id]
                pj = gg * C.POPUL[jj, id] * C.wop[ii, id]
            else:
                pi = C.POPUL[ii, id]
                pj = (C.G[ii] / C.GMER[C.IMRG[jj], id]
                      * C.POPUL[jj, id] * C.wop[ii, id])
            C.ABTRA[itr, id] = pi
            C.EMTRA[itr, id] = pj * math.exp(C.FR0[itr] * C.HKT1[id])
            C.DEMLT[itr, id] = -C.FR0[itr] * C.HKT21[id]
            if laser:
                qtt = 0.0
                if pi != pj:
                    qtt = pj / (pi - pj) * (math.exp(C.FR0[itr] * C.HKT1[id]) - UN)
                lfr = C.FR0[itr] < C.frtabm and C.iadop[C.IATM[ii]] > 0
                if qtt < 0.0 or qtt > C.QTLAS or lfr:
                    C.ABTRA[itr, id] = 0.0
                    C.EMTRA[itr, id] = 0.0
                    C.DEMLT[itr, id] = 0.0

            # set up ABTRA and EMTRA to 0 in the range where
            # the hydrogen opacity is calculated from Gomez tables
            if C.ihgom > 0 and C.ELEC[id] > C.hglim:
                if ii >= n0hn and ii <= n0hn - 1 + C.ihgom:
                    C.ABTRA[itr, id] = 0.0
                    C.EMTRA[itr, id] = 0.0
                    C.DEMLT[itr, id] = 0.0
    # 200 CONTINUE
    _save_opaini_icomp = 1
    return


def traini():
    """
    initialization of depth-independent quantities
    for evaluation of opacities

    对应 tlusty208.f 行 31537–31582
    """
    for itr in range(1, C.NTRANS + 1):
        C.IDIEL[itr] = 0

    # bound-free transitions
    C.NCDW = 0
    for ibft in range(1, C.NTRANC + 1):            # DO 10 IBFT=1,NTRANC
        itr = C.ITRBF[ibft]
        ii = C.ILOW[itr]
        if (C.ILK[C.IUP[itr]] != 0 and C.NFIRST[C.IEL[ii]] == ii
                and C.IFDIEL != 0):
            C.IDIEL[itr] = 1
        modw = abs(C.INDEXP[itr])
        if modw != 5 and modw != 15:
            continue                               # GO TO 10
        C.NCDW = C.NCDW + 1
        C.MCDW[itr] = C.NCDW
        C.ITRCDW[C.NCDW] = itr
    # 10 CONTINUE
    if C.ISPODF >= 1:
        return

    # bound-bound transitions
    for ij in range(1, C.NFREQ + 1):
        C.NLINES[ij] = 0

    for itr in range(1, C.NTRANS + 1):             # DO 100 ITR=1,NTRANS
        if C.LINEXP[itr]:
            continue                               # GO TO 100
        for ij in range(C.IFR0[itr], C.IFR1[itr] + 1):
            C.IJLIN[ij] = itr
    # 100 CONTINUE
    return


def rtedf1(ij):
    """
    Solution of the radiative transfer equation - for one frequency
    for the known source function.
    Determination of the radiation field and variable Eddington
    factors.

    The numerical method used:
    Discontinuous Finite Element method
    Castor, Dykema, Klein, 1992, ApJ 387, 561.

    different formulation of the boundary conditions

    对应 tlusty208.f 行 31590–31994
    标量哑元 IJ 不被修改 → 无返回值
    """
    SIXTH = UN / 6.0                 # SIXTH 在本例程中未使用（原代码如此）
    THIRD = UN / 3.0
    TWOTHR = TWO / 3.0
    dt = C.DT                        # COMMON/OPTDPT/DT(MDEPTH)
    rdk = np.zeros(MDEPTH + 1)
    fkk = np.zeros(MDEPTH + 1)
    st0 = np.zeros(MDEPTH + 1)
    sa0 = np.zeros(MDEPTH + 1)
    ss0 = np.zeros(MDEPTH + 1)
    dtau = np.zeros(MDEPTH + 1)
    rip = np.zeros(MDEPTH + 1)
    rim = np.zeros(MDEPTH + 1)
    riin = np.zeros(MDEPTH + 1)
    riup = np.zeros(MDEPTH + 1)
    u = np.zeros(MDEPTH + 1)
    aip = np.zeros(MDEPTH + 1)
    aim = np.zeros(MDEPTH + 1)
    al0 = np.zeros(MDEPTH + 1)
    aiin = np.zeros(MDEPTH + 1)
    aiup = np.zeros(MDEPTH + 1)
    ali0 = np.zeros(MDEPTH + 1)
    ss0c = np.zeros(MDEPTH + 1)
    aaa = np.zeros(MDEPTH + 1)
    bbb = np.zeros(MDEPTH + 1)
    ccc = np.zeros(MDEPTH + 1)
    eee = np.zeros(MDEPTH + 1)
    zzz = np.zeros(MDEPTH + 1)
    alrh = np.zeros(MDEPTH + 1)
    alrm = np.zeros(MDEPTH + 1)
    alrp = np.zeros(MDEPTH + 1)
    ddd = np.zeros(MDEPTH + 1)
    aanu = np.zeros(MDEPTH + 1)

    fr = C.FREQ[ij]

    # optical depth scale
    for id in range(1, C.ND):        # DO ID=1,ND-1
        dt[id] = C.DELDMZ[id] * (C.ABSOT[id + 1] + C.ABSOT[id])
        sa0[id] = C.EMIS1[id] / C.ABSO1[id]
        ss0[id] = -C.SCAT1[id] / C.ABSO1[id]
    sa0[C.ND] = C.EMIS1[C.ND] / C.ABSO1[C.ND]
    ss0[C.ND] = -C.SCAT1[C.ND] / C.ABSO1[C.ND]

    taumin = C.ABSO1[1] * C.DEDM1    # TAUMIN 之后未使用（使用它的代码已被注释）

    # Allowance for wind blanketing
    alb1 = 0.0
    if C.IWINBL > 0:
        alb1 = TWO * C.ALBE[ij] / (UN + C.ALBE[ij])

    # quantities for the lower boundary condition
    fr15 = fr * 1.0e-15
    bnu = BN * fr15 * fr15 * fr15
    pland = bnu / (math.exp(HK * fr / C.TEMP[C.ND]) - UN) * C.RRDIL
    dplan = bnu / (math.exp(HK * fr / C.TEMP[C.ND - 1]) - UN) * C.RRDIL
    if C.TEMPBD > 0.0:
        pland = bnu / (math.exp(HK * fr / C.TEMPBD) - UN) * C.RRDIL
        dplan = bnu / (math.exp(HK * fr / C.TEMPBD) - UN) * C.RRDIL
    dplan = (pland - dplan) / dt[C.ND - 1]

    # global ALI loop for treating electron scattering
    itrali = 0
    while True:                      # 标号 10：GO TO 10 回到此处
        itrali = itrali + 1

        # total source function
        for id in range(1, C.ND + 1):
            st0[id] = sa0[id] - ss0[id] * C.RAD[ij, id]
            C.RAD1[id] = 0.0
            rdk[id] = 0.0
            C.ALI1[id] = 0.0
        ah = 0.0
        ahout = 0.0
        ahd = 0.0
        u0 = 0.0
        qq0 = 0.0
        us0 = 0.0

        # loop over angle poits
        for i in range(1, C.NMU + 1):
            amu2 = C.AMU[i] * C.AMU[i] * C.WTMU[i]
            for id in range(1, C.ND):
                dtau[id] = dt[id] / C.AMU[i]

            # incoming intensity
            id = 1
            p0 = 0.0
            ex = UN                  # EX 之后未使用（使用它的代码已被注释）

            # allowance for non-zero optical depth at the first depth point
            # c        rim(id)=EXTRAD(IJ)   —— 原代码已注释
            rim[id] = C.EXTINT[ij, i]
            # 原代码中 IWINBL.EQ.0 的整段处理（TAMM/EX/P0/QQ0/U0/US0/rim）
            # 均被注释掉，直译保留为注释：
            # c         IF(IWINBL.EQ.0) THEN
            # c            TAMM=TAUMIN/AMU(I)
            # c            EX=EXP(-TAMM)
            # c            P0=UN-EX
            # c            QQ0=QQ0+P0*AMU(I)*WTMU(I)
            # c            U0=U0+EX*WTMU(I)
            # c            US0=US0+P0/TAMM*WTMU(I)
            # c            rim(id)=st0(id)*p0
            # c         END IF

            # incoming intensity
            aim[id] = 0.0
            for id in range(1, C.ND):
                dt0 = dtau[id]
                dtaup1 = dt0 + UN
                dtau2 = dt0 * dt0
                bb = TWO * dtaup1
                cc = dt0 * dtaup1
                aa = UN / (dtau2 + bb)
                rim[id + 1] = (TWO * rim[id] + dt0 * st0[id] + cc * st0[id + 1]) * aa
                rip[id] = (bb * rim[id] + cc * st0[id] - dt0 * st0[id + 1]) * aa
                aim[id + 1] = cc * aa
                aip[id] = (cc + bb * aim[id]) * aa
            for id in range(2, C.ND):
                dtt = UN / (dtau[id - 1] + dtau[id])
                riin[id] = (rim[id] * dtau[id] + rip[id] * dtau[id - 1]) * dtt
                aiin[id] = (aim[id] * dtau[id] + aip[id] * dtau[id - 1]) * dtt
            riin[1] = rim[1]
            riin[C.ND] = rim[C.ND]
            aiin[1] = aim[1]
            aiin[C.ND] = aim[C.ND]

            # outgoing intensity
            if C.IDISK == 0:
                rim[C.ND] = pland + C.AMU[i] * dplan
            for id in range(C.ND - 1, 0, -1):
                dt0 = dtau[id]
                dtaup1 = dt0 + UN
                dtau2 = dt0 * dt0
                bb = TWO * dtaup1
                cc = dt0 * dtaup1
                aa = UN / (dtau2 + bb)
                rim[id] = (TWO * rim[id + 1] + dt0 * st0[id + 1] + cc * st0[id]) * aa
                rip[id + 1] = (bb * rim[id + 1] + cc * st0[id + 1] - dt0 * st0[id]) * aa
                aim[id] = cc * aa
                aip[id + 1] = (cc + bb * aim[id + 1]) * aa
            for id in range(2, C.ND):
                dtt = UN / (dtau[id - 1] + dtau[id])
                riup[id] = (rim[id] * dtau[id - 1] + rip[id] * dtau[id]) * dtt
                aiup[id] = (aim[id] * dtau[id - 1] + aip[id] * dtau[id]) * dtt
            riup[1] = rim[1]
            riup[C.ND] = rim[C.ND]
            aiup[1] = aim[1]
            aiup[C.ND] = aim[C.ND]

            # final symmetrized (Feautrier) intensity -- (riin+riup)/2
            for id in range(1, C.ND + 1):
                u[id] = (riin[id] + riup[id]) * HALF
                al0[id] = (aiin[id] + aiup[id]) * HALF

            for id in range(1, C.ND + 1):
                C.RAD1[id] = C.RAD1[id] + C.WTMU[i] * u[id]
                rdk[id] = rdk[id] + amu2 * u[id]
                C.ALI1[id] = C.ALI1[id] + C.WTMU[i] * al0[id]
            ah = ah + C.AMU[i] * C.WTMU[i] * u[1]
            ahd = ahd + C.AMU[i] * C.WTMU[i] * u[C.ND]
            ahout = ahout + C.AMU[i] * C.WTMU[i] * riup[1]
        # end of the loop over angle points

        # solution of the transfer equation
        # Variables:
        # RAD1    - mean intensity
        # FAK1    - Eddington factor f(K) = K/J
        # FH      - the "surface" Eddington factor
        # ALI1    - diagonal element of the lambda operator
        if C.IBC == 0:
            C.ALI1[C.ND] = C.RAD1[C.ND] / st0[C.ND]
            C.ALI1[C.ND - 1] = C.RAD1[C.ND - 1] / st0[C.ND - 1]

        djtot = 0.0
        for id in range(1, C.ND + 1):
            deltaj = (C.RAD1[id] - C.RAD[ij, id]) / (UN + ss0[id] * C.ALI1[id])
            C.RAD[ij, id] = C.RAD[ij, id] + deltaj
            djtot = max(djtot, abs(deltaj / C.RAD[ij, id]))
        # IF(DJTOT.GT.DJMAX.AND.ITRALI.LE.NTRALI) GO TO 10
        if not (djtot > C.DJMAX and itrali <= C.NTRALI):
            break                    # 条件不满足 → 退出 ALI 循环
    # end of ALI loop for electron scattering

    for id in range(1, C.ND + 1):
        C.RAD1[id] = C.RAD[ij, id]
        C.FAK1[id] = rdk[id] / C.RAD[ij, id]
        fkk[id] = C.FAK1[id]
    C.FLUX[ij] = ahout * HALF
    C.FH[ij] = ah / C.RAD1[1] - HALF * alb1
    fh0 = C.FH[ij]
    C.FHD[ij] = ahd / C.RAD1[C.ND]

    # ********************

    # Again solution of the transfer equation, now with Eddington
    # FKK and FH determined above, to insure strict consistency of the
    # radiation field and Eddington factors
    if C.ILMCOR == 3:
        for id in range(1, C.ND + 1):
            sa0[id] = st0[id]
            ss0c[id] = ss0[id]
            ss0[id] = 0.0

    # Upper boundary condition
    id = 1
    dtp1 = dt[id]
    if imod(C.ISPLIN, 3) == 0:       # MOD(ISPLIN,3).EQ.0
        b = dtp1 * HALF
        c = 0.0
    else:
        b = dtp1 * THIRD
        c = b * HALF
    bq = UN / (b + qq0)
    cq = c * bq
    bbb[id] = (fkk[id] / dtp1 + fh0 + b) * bq + ss0[id]
    ccc[id] = (fkk[id + 1] / dtp1) * bq - cq * (UN + ss0[id + 1])
    zzz[id] = UN / bbb[id]
    vll = sa0[id] + cq * sa0[id + 1]
    if C.IWINBL < 0:
        vll = vll + C.HEXTRD[ij] * bq
    aanu[id] = vll * zzz[id]
    ddd[id] = ccc[id] * zzz[id]
    fff = 0.0                        # FFF 仅在 ISPLIN>2 时使用；原代码未显式初始化
    if C.ISPLIN > 2:
        fff = bbb[id] / ccc[id] - UN

    # Normal depth point
    for id in range(2, C.ND):
        dtm1 = dtp1
        dtp1 = dt[id]
        dt0 = TWO / (dtp1 + dtm1)
        al = UN / dtm1 * dt0
        ga = UN / dtp1 * dt0
        if imod(C.ISPLIN, 3) == 0:
            a = 0.0
            c = 0.0
        elif C.ISPLIN == 1:
            a = dtm1 * dt0 * SIXTH
            c = dtp1 * dt0 * SIXTH
        else:
            a = (UN - HALF * dtp1 * dtp1 * al) * SIXTH
            c = (UN - HALF * dtm1 * dtm1 * ga) * SIXTH
        aaa[id] = al * fkk[id - 1] - a * (UN + ss0[id - 1])
        ccc[id] = ga * fkk[id + 1] - c * (UN + ss0[id + 1])
        bbb[id] = (al + ga) * fkk[id] + (UN - a - c) * (UN + ss0[id])
        vll = a * sa0[id - 1] + c * sa0[id + 1] + (UN - a - c) * sa0[id]
        aanu[id] = vll + aaa[id] * aanu[id - 1]
        if C.ISPLIN <= 2:
            zzz[id] = UN / (bbb[id] - aaa[id] * ddd[id - 1])
            ddd[id] = ccc[id] * zzz[id]
            aanu[id] = aanu[id] * zzz[id]
        else:
            sum = -aaa[id] + bbb[id] - ccc[id]
            fff = (sum + aaa[id] * fff * ddd[id - 1]) / ccc[id]
            ddd[id] = UN / (UN + fff)
            aanu[id] = aanu[id] * ddd[id] / ccc[id]

    # Lower boundary condition
    id = C.ND
    if C.IBC == 0:
        bbb[id] = fkk[id] / dtp1 + HALF
        aaa[id] = fkk[id - 1] / dtp1
        vll = HALF * pland + THIRD * dplan
    elif C.IBC < 4:
        b = UN / dtp1
        a = TWO * b * b
        bbb[id] = UN + ss0[id] + b + a * fkk[id]
        aaa[id] = a * fkk[id - 1]
        vll = sa0[id] + b * (pland + TWOTHR * dplan)
    else:
        b = UN / dtp1
        a = TWO * b * b
        bbb[id] = b + a * fkk[id]
        aaa[id] = a * fkk[id - 1]
        vll = b * (pland + TWOTHR * dplan)
    eee[C.ND] = aaa[id] / bbb[id]
    zzz[id] = UN / (bbb[id] - aaa[id] * ddd[id - 1])
    C.RAD1[id] = (vll + aaa[id] * aanu[id - 1]) * zzz[id]
    C.FAK1[id] = fkk[C.ND]
    alrh[id] = zzz[id]

    # Backsolution
    for id in range(C.ND - 1, 0, -1):
        eee[id] = aaa[id] / (bbb[id] - ccc[id] * eee[id + 1])
        C.RAD1[id] = aanu[id] + ddd[id] * C.RAD1[id + 1]
        C.FAK1[id] = fkk[id]
        alrh[id] = zzz[id] / (UN - ddd[id] * eee[id + 1])
        alrm[id] = 0.0
        alrp[id] = 0.0

    # evaluate approximate Lambda operator

    # a) Rybicki-Hummer Lambda^star operator (diagonal)
    #    (for JALI = 1)
    for id in range(1, C.ND + 1):
        C.ALIM1[id] = 0.0
        C.ALIP1[id] = 0.0
    if C.JALI == 1:
        for id in range(1, C.ND + 1):
            C.ALI1[id] = alrh[id]

        if C.IBC == 0:
            C.ALI1[C.ND - 1] = C.RAD1[C.ND - 1] / sa0[C.ND - 1]
            C.ALI1[C.ND] = C.RAD1[C.ND] / sa0[C.ND]

        # for IFALI>5:
        # tridiagonal Rybicki-Hummer operator (off-diagonal terms)
        if C.IFALI >= 6:
            C.ALIP1[1] = alrh[2] * ddd[1]
            for id in range(2, C.ND):
                C.ALIM1[id] = alrh[id - 1] * eee[id]
                C.ALIP1[id] = alrh[id + 1] * ddd[id]
            C.ALIM1[C.ND] = alrh[C.ND - 1] * eee[C.ND]
            if C.IBC == 0:
                C.ALIM1[C.ND] = 0.0
                C.ALIM1[C.ND - 1] = 0.0
                C.ALIP1[C.ND] = 0.0
                C.ALIP1[C.ND - 1] = 0.0

    # b) diagonal Olson-Kunasz Lambda^star operator,
    #    (for JALI = 2)
    elif C.JALI == 2:
        for id in range(1, C.ND):
            ali0[id] = 0.0
            for i in range(1, C.NMU + 1):
                div = dt[id] / C.AMU[i]
                ali0[id] = ali0[id] + (UN - math.exp(-div)) / div * C.WTMU[i]
        for id in range(2, C.ND):
            C.ALI1[id] = UN - HALF * (ali0[id] + ali0[id - 1])
        C.ALI1[1] = UN - HALF * (ali0[1] + us0)
        C.ALI1[C.ND] = UN - ali0[C.ND - 1]
        C.ALI1[C.ND - 1] = C.RAD1[C.ND - 1] / sa0[C.ND - 1]
        C.ALI1[C.ND] = C.RAD1[C.ND] / sa0[C.ND]

    # correction of Lambda^star for scattering
    if C.ILMCOR == 1:
        for id in range(1, C.ND + 1):
            C.ALI1[id] = C.ALI1[id] * (UN + ss0[id])
            C.ALIM1[id] = C.ALIM1[id] * (UN + ss0[id])
            C.ALIP1[id] = C.ALIP1[id] * (UN + ss0[id])
        if C.IBC == 4:
            C.ALI1[C.ND] = C.ALI1[C.ND] / (UN + ss0[C.ND])
            C.ALIM1[C.ND] = C.ALIM1[C.ND] / (UN + ss0[C.ND])
            C.ALIP1[C.ND] = C.ALIP1[C.ND] / (UN + ss0[C.ND])

    # store quantities for explicit (linearized) frequencies
    if C.IJEX[ij] <= 0:
        return
    ije = C.IJEX[ij]
    for id in range(1, C.ND + 1):
        C.RADEX[ije, id] = C.RAD1[id]
        C.FAKEX[ije, id] = C.FAK1[id]
    C.Q0[ije] = qq0
    C.UU0[ije] = u0
    return


def rtedf2(ij):
    """
    Solution of the radiative transfer equation - for one frequency
    for the known source function.
    Determination of the radiation field and variable Eddington
    factors.
    Analogous to RTEDF1, but using opacity and emissivity
    instead of the source function

    The numerical method used:
    Discontinuous Finite Element method
    Castor, Dykema, Klein, 1992, ApJ 387, 561.

    different formulation of the boundary conditions

    对应 tlusty208.f 行 32002–32257
    标量哑元 IJ 不被修改 → 无返回值
    """
    SIXTH = UN / 6.0                 # SIXTH/THIRD/TWOTHR 在本例程中未使用（原代码如此）
    THIRD = UN / 3.0
    TWOTHR = TWO / 3.0
    THREE = 3.0
    QUART = 0.25
    dt = np.zeros(MDEPTH + 1)        # 注意：RTEDF2 的 DT 是局部数组（非 COMMON/OPTDPT）
    rdk = np.zeros(MDEPTH + 1)
    fkk = np.zeros(MDEPTH + 1)
    st0 = np.zeros(MDEPTH + 1)
    sa0 = np.zeros(MDEPTH + 1)
    ss0 = np.zeros(MDEPTH + 1)
    dtau = np.zeros(MDEPTH + 1)
    rip = np.zeros(MDEPTH + 1)
    rim = np.zeros(MDEPTH + 1)
    riin = np.zeros(MDEPTH + 1)
    riup = np.zeros(MDEPTH + 1)
    u = np.zeros(MDEPTH + 1)
    aip = np.zeros(MDEPTH + 1)
    aim = np.zeros(MDEPTH + 1)
    al0 = np.zeros(MDEPTH + 1)
    aiin = np.zeros(MDEPTH + 1)
    aiup = np.zeros(MDEPTH + 1)
    chip0 = np.zeros(MDEPTH + 1)
    chim0 = np.zeros(MDEPTH + 1)
    ddm0 = np.zeros(MDEPTH + 1)
    chip = np.zeros(MDEPTH + 1)
    chim = np.zeros(MDEPTH + 1)
    etap = np.zeros(MDEPTH + 1)
    etam = np.zeros(MDEPTH + 1)

    fr = C.FREQ[ij]

    # optical depth scale
    for id in range(1, C.ND):        # DO ID=1,ND-1
        dt[id] = C.DELDMZ[id] * (C.ABSOT[id + 1] + C.ABSOT[id])
        sa0[id] = C.EMIS1[id] / C.ABSO1[id]
        ss0[id] = -C.SCAT1[id] / C.ABSO1[id]
        ddm0[id] = C.DM[id + 1] - C.DM[id]
        chip0[id] = (C.ABSO1[id] * C.DENS1[id] + THREE
                     * C.ABSO1[id + 1] * C.DENS1[id + 1]) * QUART * ddm0[id]
        chim0[id] = (C.ABSO1[id] * C.DENS1[id] * THREE
                     + C.ABSO1[id + 1] * C.DENS1[id + 1]) * QUART * ddm0[id]
    sa0[C.ND] = C.EMIS1[C.ND] / C.ABSO1[C.ND]
    ss0[C.ND] = -C.SCAT1[C.ND] / C.ABSO1[C.ND]

    taumin = C.ABSO1[1] * C.DEDM1

    # Allowance for wind blanketing
    alb1 = 0.0
    if C.IWINBL > 0:
        alb1 = TWO * C.ALBE[ij] / (UN + C.ALBE[ij])

    # quantities for the lower boundary condition
    fr15 = fr * 1.0e-15
    bnu = BN * fr15 * fr15 * fr15
    pland = bnu / (math.exp(HK * fr / C.TEMP[C.ND]) - UN) * C.RRDIL
    dplan = bnu / (math.exp(HK * fr / C.TEMP[C.ND - 1]) - UN) * C.RRDIL
    if C.TEMPBD > 0.0:
        pland = bnu / (math.exp(HK * fr / C.TEMPBD) - UN) * C.RRDIL
        dplan = bnu / (math.exp(HK * fr / C.TEMPBD) - UN) * C.RRDIL
    dplan = (pland - dplan) / dt[C.ND - 1]

    # global ALI loop for treating electron scattering
    itrali = 0
    while True:                      # 标号 10：GO TO 10 回到此处
        itrali = itrali + 1

        # total source function
        for id in range(1, C.ND + 1):
            st0[id] = sa0[id] - ss0[id] * C.RAD[ij, id]
            C.RAD1[id] = 0.0
            rdk[id] = 0.0
            C.ALI1[id] = 0.0
        ah = 0.0
        u0 = 0.0
        qq0 = 0.0
        us0 = 0.0

        # loop over angle poits
        for i in range(1, C.NMU + 1):
            amu2 = C.AMU[i] * C.AMU[i] * C.WTMU[i]
            for id in range(1, C.ND):
                dtau[id] = dt[id] / C.AMU[i]
                chip[id] = UN + chip0[id] / C.AMU[i]
                chim[id] = UN + chim0[id] / C.AMU[i]
                etap[id] = C.EMIS1[id + 1] * C.DENS1[id + 1] / C.AMU[i] * ddm0[id]
                etam[id] = C.EMIS1[id] * C.DENS1[id] / C.AMU[i] * ddm0[id]

            # incoming intensity
            id = 1
            p0 = 0.0
            ex = UN

            # allowance for non-zero optical depth at the first depth point
            # c        rim(id)=EXTRAD(IJ)   —— 原代码已注释
            rim[id] = C.EXTINT[ij, i]
            if C.IWINBL == 0:
                tamm = taumin / C.AMU[i]
                ex = math.exp(-tamm)
                p0 = UN - ex
                qq0 = qq0 + p0 * C.AMU[i] * C.WTMU[i]
                u0 = u0 + ex * C.WTMU[i]
                us0 = us0 + p0 / tamm * C.WTMU[i]
                rim[id] = st0[id] * p0

            # incoming intensity
            aim[id] = 0.0
            for id in range(1, C.ND):
                dt0 = dtau[id]
                dtaup1 = dt0 + UN
                dtau2 = dt0 * dt0
                bb = TWO * dtaup1
                cc = dt0 * dtaup1
                aa = UN / (dtau2 + bb)
                aam = UN / (UN + chim[id] * chip[id])
                rim[id + 1] = (TWO * rim[id] + etap[id] * chim[id] + etam[id]) * aam
                rip[id] = (TWO * rim[id] * chim[id] + etam[id] * chip[id]
                           - etap[id]) * aam
                aim[id + 1] = bb * aa
                aip[id] = (cc + bb * aim[id]) * aa
            for id in range(2, C.ND):
                dtt = UN / (dtau[id - 1] + dtau[id])
                dtm = UN / (ddm0[id - 1] + ddm0[id])
                riin[id] = (rim[id] * ddm0[id] + rip[id] * ddm0[id - 1]) * dtm
                aiin[id] = (aim[id] * dtau[id] + aip[id] * dtau[id - 1]) * dtt
            riin[1] = rim[1]
            riin[C.ND] = rim[C.ND]
            aiin[1] = aim[1]
            aiin[C.ND] = aim[C.ND]

            # outgoing intensity
            rim[C.ND] = pland + C.AMU[i] * dplan
            for id in range(C.ND - 1, 0, -1):
                dt0 = dtau[id]
                dtaup1 = dt0 + UN
                dtau2 = dt0 * dt0
                bb = TWO * dtaup1
                cc = dt0 * dtaup1
                aa = UN / (dtau2 + bb)
                aam = UN / (UN + chim[id] * chip[id])
                rim[id] = (TWO * rim[id + 1] + etam[id] * chip[id] + etap[id]) * aam
                rip[id + 1] = (TWO * rim[id + 1] * chip[id] + etap[id] * chim[id]
                               - etam[id]) * aam
                aim[id] = cc * aa
                aip[id + 1] = (cc + bb * aim[id + 1]) * aa
            for id in range(2, C.ND):
                dtt = UN / (dtau[id - 1] + dtau[id])
                dtm = UN / (ddm0[id - 1] + ddm0[id])
                riup[id] = (rim[id] * ddm0[id - 1] + rip[id] * ddm0[id]) * dtm
                aiup[id] = (aim[id] * dtau[id - 1] + aip[id] * dtau[id]) * dtt
            riup[1] = rim[1]
            riup[C.ND] = rim[C.ND]
            aiup[1] = aim[1]
            aiup[C.ND] = aim[C.ND]

            # final symmetrized (Feautrier) intensity -- (riin+riup)/2
            for id in range(1, C.ND + 1):
                u[id] = (riin[id] + riup[id]) * HALF
                al0[id] = (aiin[id] + aiup[id]) * HALF

            for id in range(1, C.ND + 1):
                C.RAD1[id] = C.RAD1[id] + C.WTMU[i] * u[id]
                rdk[id] = rdk[id] + amu2 * u[id]
                C.ALI1[id] = C.ALI1[id] + C.WTMU[i] * al0[id]
            ah = ah + C.AMU[i] * C.WTMU[i] * u[1]
        # end of the loop over angle points

        # solution of the transfer equation
        # Variables:
        # RAD1    - mean intensity
        # FAK1    - Eddington factor f(K) = K/J
        # FH      - the "surface" Eddington factor
        # ALI1    - diagonal element of the lambda operator
        if C.IBC == 0:
            C.ALI1[C.ND] = C.RAD1[C.ND] / st0[C.ND]
            C.ALI1[C.ND - 1] = C.RAD1[C.ND - 1] / st0[C.ND - 1]

        djtot = 0.0
        for id in range(1, C.ND + 1):
            deltaj = (C.RAD1[id] - C.RAD[ij, id]) / (UN + ss0[id] * C.ALI1[id])
            C.RAD[ij, id] = C.RAD[ij, id] + deltaj
            djtot = max(djtot, abs(deltaj / C.RAD[ij, id]))
        # IF(DJTOT.GT.DJMAX.AND.ITRALI.LE.NTRALI) GO TO 10
        if not (djtot > C.DJMAX and itrali <= C.NTRALI):
            break                    # 条件不满足 → 退出 ALI 循环
    # end of ALI loop for electron scattering

    for id in range(1, C.ND + 1):
        C.RAD1[id] = C.RAD[ij, id]
        C.FAK1[id] = rdk[id] / C.RAD[ij, id]
        fkk[id] = C.FAK1[id]
    C.FLUX[ij] = ah
    C.FH[ij] = ah / C.RAD1[1] - HALF * alb1
    fh0 = C.FH[ij]                   # FH0 之后未使用（原代码如此）

    # correction of Lambda^star for scattering
    if C.ILMCOR == 1:
        for id in range(1, C.ND + 1):
            C.ALI1[id] = C.ALI1[id] * (UN + ss0[id])
        if C.IBC == 4:
            C.ALI1[C.ND] = C.ALI1[C.ND] / (UN + ss0[C.ND])
    elif C.ILMCOR == 3:
        for id in range(1, C.ND + 1):
            C.ALI1[id] = C.ALI1[id] / (UN + ss0[id] * C.ALI1[id])
        if C.IBC == 4:
            # TODO(port): 原代码此处为 ALI1(ID)，其中 ID 是前面 DO ID=1,ND 循环
            # 结束后的值 ND+1（Fortran 语义），疑似原作者笔误（应为 ALI1(ND)）；
            # 按 Fortran 语义直译
            id = C.ND + 1
            C.ALI1[C.ND] = C.ALI1[C.ND] * (UN + ss0[C.ND] * C.ALI1[id])

    # store quantities for explicit (linearized) frequencies
    if C.IJEX[ij] <= 0:
        return
    ije = C.IJEX[ij]
    for id in range(1, C.ND + 1):
        C.RADEX[ije, id] = C.RAD1[id]
        C.FAKEX[ije, id] = C.FAK1[id]
    C.Q0[ije] = qq0
    C.UU0[ije] = u0
    return


def rtefr1(ij):
    """
    Solution of the radiative transfer equation - for one frequency
    - for the known source function.
    Determination of the radiation field and variable Eddington
    factors.

    The numerical method used:
     for ISPLIN = 0  -  the ordinary Feautrier scheme
                = 1  -  the spline collocation method
                = 2  -  Hermitian fourth-order method
                = 3  -  improved Feautrier scheme
                        (Rybicki & Hummer 1991, A&A 245, 171.)

    In all cases, the overall matrix system is solved by the standard
    Gaussian elimination, analogous to that described in SOLVE
    (auxiliary matrix D is called ALF in SOLVE; auxiliary vector ANU
    is called BET in SOLVE)

     U0     - derivative of Q0 wrt taumin;
              for "fixed" frequencies, U0 has the meaning of
              absorption coefficient * second moment H
              ( a quantity needed for lower boundary condition of the
              hydrostatic equilibrium equation, specifically for
              accounting for an effect of fixed-option transitions)

    对应 tlusty208.f 行 32264–33015
    标量哑元 IJ 不被修改 → 无返回值
    """
    SIXTH = UN / 6.0
    THIRD = UN / 3.0
    TWOTHR = TWO / 3.0
    aanu = np.zeros(MDEPTH + 1)
    ddd = np.zeros(MDEPTH + 1)
    fkk = np.zeros(MDEPTH + 1)
    rdd = np.zeros(MDEPTH + 1)
    st0 = np.zeros(MDEPTH + 1)
    ss0 = np.zeros(MDEPTH + 1)
    ab0 = np.zeros(MDEPTH + 1)
    aa = np.zeros((MMU + 1, MMU + 1))
    bb = np.zeros((MMU + 1, MMU + 1))
    cc = np.zeros((MMU + 1, MMU + 1))
    vl = np.zeros(MMU + 1)
    ffd = np.zeros((MMU + 1, MMU + 1))
    ff0d = np.zeros((MMU + 1, MMU + 1))
    ffpd = np.zeros((MMU + 1, MMU + 1))
    ali0 = np.zeros(MDEPTH + 1)
    ss0c = np.zeros(MDEPTH + 1)
    aaa = np.zeros(MDEPTH + 1)
    bbb = np.zeros(MDEPTH + 1)
    ccc = np.zeros(MDEPTH + 1)
    eee = np.zeros(MDEPTH + 1)
    zzz = np.zeros(MDEPTH + 1)
    alrh = np.zeros(MDEPTH + 1)
    alrm = np.zeros(MDEPTH + 1)
    alrp = np.zeros(MDEPTH + 1)
    d = np.zeros((MMU + 1, MMU + 1, MDEPTH + 1))
    anu = np.zeros((MMU + 1, MDEPTH + 1))
    scor = np.zeros(MDEPTH + 1)
    rmmu = np.zeros(2 * MMU + 1)
    wmmu = np.zeros(2 * MMU + 1)
    rwmu = np.zeros(2 * MMU + 1)
    dtau = np.zeros(MDEPTH + 1)
    ri = np.zeros(MDEPTH + 1)
    ali = np.zeros(MDEPTH + 1)
    alij1 = np.zeros(MDEPTH + 1)
    tau = np.zeros(MDEPTH + 1)
    dt = C.DT                        # COMMON/OPTDPT/DT(MDEPTH)

    ww = C.W[ij]
    ispl = C.ISPLIN
    if C.ISPLIN >= 5:
        C.ISPLIN = ispl - 5
        if C.IJALI[ij] > 0:
            if C.IRTE == 0:
                rtedf1(ij)           # RTEDF1 不修改标量哑元
            else:
                rtedf2(ij)           # RTEDF2 不修改标量哑元
            C.ISPLIN = ispl
            if C.IFPRAD == 0:
                return
            for id in range(1, C.ND + 1):
                if not C.LSKIP[id, ij]:
                    C.PRADT[id] = C.PRADT[id] + C.RAD1[id] * C.FAK1[id] * C.W[ij]
            if not C.LSKIP[1, ij]:
                C.PRD0 = (C.PRD0 + C.ABSO1[1] * C.W[ij]
                          * (C.RAD1[1] * C.FH[ij] - C.HEXTRD[ij]))
            for id in range(1, C.ND + 1):
                C.PRADA[id] = C.PRADA[id] + C.RAD1[id] * C.FAK1[id] * ww
            return

    if C.icompt > 0 and (C.ITER > 1 or C.ILAM > 0):
        rtecf1(ij)                   # RTECF1 不修改标量哑元
        return

    fr = C.FREQ[ij]

    # total source function
    ah = 0.0
    for id in range(1, C.ND + 1):
        ab0[id] = C.ABSO1[id]
        st0[id] = C.EMIS1[id] / ab0[id]
        C.RAD1[id] = 0.0
        C.ALI1[id] = 0.0

    # non-coherent electron scattering by lambda iteration
    if C.NELSC <= 0:
        for id in range(1, C.ND + 1):
            ss0[id] = -C.SCAT1[id] / ab0[id]
    else:
        for id in range(1, C.ND + 1):
            st0[id] = st0[id] + C.SCAT1[id] * C.EMEL1[id] * C.RAD1[id] / ab0[id]
            ss0[id] = 0.0

    # optical depth scale
    tau[1] = C.ABSOT[1] * C.DM[1]
    for id in range(1, C.ND):
        dt[id] = C.DELDMZ[id] * (C.ABSOT[id + 1] + C.ABSOT[id])
        tau[id + 1] = tau[id] + dt[id]

    u0 = 0.0
    qq0 = 0.0
    us0 = 0.0
    # c TAUMIN=ABSO1(1)*DEDM1   —— 原代码已注释
    taumin = C.ABSOT[1] * C.DM[1] / 2.0
    alb1 = 0.0

    # Allowance for wind blanketing
    if C.IWINBL > 0:
        alb1 = TWO * C.ALBE[ij] / (UN + C.ALBE[ij])

    # ************** Forward elimination

    # Upper boundary condition
    id = 1
    dtp1 = dt[1]
    p0 = 0.0
    ex = UN
    if imod(C.ISPLIN, 3) == 0:       # MOD(ISPLIN,3).EQ.0
        b = dtp1 * HALF
        c = 0.0
    else:
        b = dtp1 * THIRD
        c = b * HALF
    qq0 = 0.0
    us0 = 0.0
    for i in range(1, C.NMU + 1):
        if C.IDISK == 0:
            # allowance for non-zero optical depth at the first depth point
            tamm = taumin / C.AMU[i]
            ex = math.exp(-tamm)
            p0 = UN - ex
            qq0 = qq0 + p0 * C.AMU[i] * C.WTMU[i]
            u0 = u0 + ex * C.WTMU[i]
            us0 = us0 + p0 / tamm * C.WTMU[i]

        bi = b / C.AMU[i]
        ci = c / C.AMU[i]
        vl[i] = (bi + p0) * st0[id] + ci * st0[id + 1]
        if C.IWINBL < 0:
            vl[i] = vl[i] + C.EXTINT[ij, i]
        for j in range(1, C.NMU + 1):
            bb[i, j] = ss0[id] * C.WTMU[j] * (bi + p0) - alb1 * C.WTMU[j]
            cc[i, j] = -ci * ss0[id + 1] * C.WTMU[j]
        bb[i, i] = bb[i, i] + C.AMU[i] / dtp1 + UN + bi
        cc[i, i] = cc[i, i] + C.AMU[i] / dtp1 - ci
        anu[i, id] = 0.0

    if C.ISPLIN <= 2:
        matinv(bb, C.NMU, MMU)       # MATINV 不修改标量哑元（只就地求逆数组）
        for i in range(1, C.NMU + 1):
            for j in range(1, C.NMU + 1):
                d[i, j, id] = 0.0
                for k in range(1, C.NMU + 1):
                    d[i, j, id] = d[i, j, id] + bb[i, k] * cc[k, j]
                anu[i, 1] = anu[i, 1] + bb[i, j] * vl[j]
    else:
        for i in range(1, C.NMU + 1):
            for j in range(1, C.NMU + 1):
                ff0d[i, j] = bb[i, j] / cc[i, i]
            ff0d[i, i] = ff0d[i, i] - UN

        # c CALL MINV3(BB)   —— 原代码已注释
        matinv(bb, C.NMU, MMU)
        for i in range(1, C.NMU + 1):
            anu[i, id] = 0.0
            for j in range(1, C.NMU + 1):
                d[i, j, id] = bb[i, j] * cc[j, j]
                anu[i, id] = anu[i, id] + bb[i, j] * vl[j]

    # Normal depth points  1 < ID < ND
    for id in range(2, C.ND):
        dtm1 = dtp1
        dtp1 = dt[id]
        dt0 = TWO / (dtm1 + dtp1)
        al = UN / dtm1 * dt0
        ga = UN / dtp1 * dt0
        be = al + ga
        if imod(C.ISPLIN, 3) == 0:
            a = 0.0
            c = 0.0
        elif C.ISPLIN == 1:
            a = dtm1 * dt0 * SIXTH
            c = dtp1 * dt0 * SIXTH
        else:
            a = (UN - HALF * al * dtp1 * dtp1) * SIXTH
            c = (UN - HALF * ga * dtm1 * dtm1) * SIXTH
        b = UN - a - c
        vl0 = a * st0[id - 1] + b * st0[id] + c * st0[id + 1]
        for i in range(1, C.NMU + 1):
            for j in range(1, C.NMU + 1):
                aa[i, j] = -a * ss0[id - 1] * C.WTMU[j]
                cc[i, j] = -c * ss0[id + 1] * C.WTMU[j]
                bb[i, j] = b * ss0[id] * C.WTMU[j]
        for i in range(1, C.NMU + 1):
            vl[i] = vl0
            div = C.AMU[i] * C.AMU[i]
            aa[i, i] = aa[i, i] + div * al - a
            cc[i, i] = cc[i, i] + div * ga - c
            bb[i, i] = bb[i, i] + div * be + b
        for i in range(1, C.NMU + 1):
            for j in range(1, C.NMU + 1):
                vl[i] = vl[i] + aa[i, j] * anu[j, id - 1]
        if C.ISPLIN <= 2:
            for i in range(1, C.NMU + 1):
                for j in range(1, C.NMU + 1):
                    s = 0.0
                    for k in range(1, C.NMU + 1):
                        s = s + aa[i, k] * d[k, j, id - 1]
                    bb[i, j] = bb[i, j] - s

            matinv(bb, C.NMU, MMU)
            for i in range(1, C.NMU + 1):
                for j in range(1, C.NMU + 1):
                    d[i, j, id] = 0.0
                    for k in range(1, C.NMU + 1):
                        d[i, j, id] = d[i, j, id] + bb[i, k] * cc[k, j]
        else:
            for i in range(1, C.NMU + 1):
                bb[i, i] = -aa[i, i] + bb[i, i] - cc[i, i]
                for j in range(1, C.NMU + 1):
                    ffpd[i, j] = aa[i, i] * ff0d[i, j]
            for i in range(1, C.NMU + 1):
                for j in range(1, C.NMU + 1):
                    s = 0.0
                    for k in range(1, C.NMU + 1):
                        s = s + ffpd[i, k] * d[k, j, id - 1]
                    ffd[i, j] = (bb[i, j] + s) / cc[i, i]
            for i in range(1, C.NMU + 1):
                for j in range(1, C.NMU + 1):
                    ff0d[i, j] = ffd[i, j]
                ffd[i, i] = ffd[i, i] + UN

            matinv(ffd, C.NMU, MMU)
            for i in range(1, C.NMU + 1):
                for j in range(1, C.NMU + 1):
                    d[i, j, id] = ffd[i, j]
                    bb[i, j] = ffd[i, j] / cc[j, j]
        for i in range(1, C.NMU + 1):
            anu[i, id] = 0.0
            for j in range(1, C.NMU + 1):
                anu[i, id] = anu[i, id] + bb[i, j] * vl[j]

    # Lower boundary condition
    id = C.ND

    # First option:
    # b.c. is different from stellar atmospheres; expresses symmetry
    # at the central plane   I(taumax,-mu,nu)=I(taumax,+mu,nu)
    if C.IFZ0 >= 0 and C.IDISK == 1:
        b = dtp1 * HALF
        a = 0.0
        for i in range(1, C.NMU + 1):
            bi = b / C.AMU[i]
            ai = a / C.AMU[i]
            vl[i] = st0[id] * bi + st0[id - 1] * ai
            for j in range(1, C.NMU + 1):
                aa[i, j] = -ai * ss0[id - 1] * C.WTMU[j]
                bb[i, j] = bi * ss0[id] * C.WTMU[j]
            aa[i, i] = aa[i, i] + C.AMU[i] / dtp1 - ai
            bb[i, i] = bb[i, i] + C.AMU[i] / dtp1 + bi
        for i in range(1, C.NMU + 1):
            s1 = 0.0
            for j in range(1, C.NMU + 1):
                s = 0.0
                s1 = s1 + aa[i, j] * anu[j, id - 1]
                for k in range(1, C.NMU + 1):
                    s = s + aa[i, k] * d[k, j, id - 1]
                bb[i, j] = bb[i, j] - s
            vl[i] = vl[i] + s1

    # Second option:
    # b.c. is the same as in stellar atmospheres - the last depth point
    # is not at the central plane
    else:
        fr15 = fr * 1.0e-15
        bnu = BN * fr15 * fr15 * fr15
        pland = bnu / (math.exp(HK * fr / C.TEMP[C.ND]) - UN) * C.RRDIL
        dplan = bnu / (math.exp(HK * fr / C.TEMP[C.ND - 1]) - UN) * C.RRDIL
        if C.TEMPBD > 0.0:
            pland = bnu / (math.exp(HK * fr / C.TEMPBD) - UN) * C.RRDIL
            dplan = bnu / (math.exp(HK * fr / C.TEMPBD) - UN) * C.RRDIL
        dplan = (pland - dplan) / dt[C.ND - 1]
        if C.IBC == 0 or C.IBC == 4:
            for i in range(1, C.NMU + 1):
                aa[i, i] = C.AMU[i] / dtp1
                vl[i] = pland + C.AMU[i] * dplan + aa[i, i] * anu[i, id - 1]
                for j in range(1, C.NMU + 1):
                    bb[i, j] = -aa[i, i] * d[i, j, id - 1]
                bb[i, i] = bb[i, i] + aa[i, i] + UN
        else:
            for i in range(1, C.NMU + 1):
                a = C.AMU[i] / dtp1
                b = HALF / a
                aa[i, i] = a
                vl[i] = (b * st0[id] + pland + C.AMU[i] * dplan
                         + aa[i, i] * anu[i, id - 1])
                for j in range(1, C.NMU + 1):
                    bb[i, j] = b * ss0[id] * C.WTMU[j] - aa[i, i] * d[i, j, id - 1]
                bb[i, i] = bb[i, i] + a + b + UN

    matinv(bb, C.NMU, MMU)

    for i in range(1, C.NMU + 1):
        anu[i, id] = 0.0
        for j in range(1, C.NMU + 1):
            d[i, j, id] = 0.0
            anu[i, id] = anu[i, id] + bb[i, j] * vl[j]

    # ***************** Backsolution
    fkk[C.ND] = THIRD
    aj = 0.0
    ah = 0.0
    ak = 0.0
    for i in range(1, C.NMU + 1):
        rmu = C.WTMU[i] * anu[i, id]
        aj = aj + rmu
        ah = ah + rmu * C.AMU[i]
        ak = ak + rmu * C.AMU[i] * C.AMU[i]
    rdd[id] = aj
    if C.IBC == 0:
        fkk[C.ND] = THIRD
    else:
        fkk[id] = ak / aj
        C.FHD[ij] = ah / aj

    for id in range(C.ND - 1, 0, -1):
        for i in range(1, C.NMU + 1):
            for j in range(1, C.NMU + 1):
                anu[i, id] = anu[i, id] + d[i, j, id] * anu[j, id + 1]
        aj = 0.0
        ak = 0.0
        for i in range(1, C.NMU + 1):
            rmu = C.WTMU[i] * anu[i, id]
            aj = aj + rmu
            ak = ak + rmu * C.AMU[i] * C.AMU[i]

        # solution of the transfer equation
        # Variables:
        #  ANU     - Feautrier intensity
        #  RDD     - mean intensity
        #  FKK     - Eddington factor f(K) = K/J
        fkk[id] = ak / aj
        rdd[id] = aj

    if C.IDISK == 1:
        for id in range(1, C.ND + 1):
            C.FAK[ij, id] = fkk[id]

    # the "surface" Eddington factor fH
    ah = 0.0
    for i in range(1, C.NMU + 1):
        ah = ah + C.WTMU[i] * C.AMU[i] * anu[i, 1]
    fh0 = ah / aj - HALF * alb1
    C.FH[ij] = fh0
    C.Q0[ij] = qq0
    C.UU0[ij] = u0
    # c q0(ij)=0. / c uu0(ij)=0.   —— 原代码已注释

    # ********************

    # Again solution of the transfer equation, now with Eddington
    # FKK and FH determined above, to insure strict consistency of the
    # radiation field and Eddington factors
    if C.ILMCOR == 2:
        for id in range(1, C.ND + 1):
            scor[id] = UN / (UN + ss0[id])
    elif C.ILMCOR == 3:
        for id in range(1, C.ND + 1):
            ss0c[id] = ss0[id]
            st0[id] = st0[id] - ss0[id] * rdd[id]
            ss0[id] = 0.0

    # Upper boundary condition
    id = 1
    dtp1 = dt[id]
    if imod(C.ISPLIN, 3) == 0:
        b = dtp1 * HALF
        c = 0.0
    else:
        b = dtp1 * THIRD
        c = b * HALF
    bq = UN / (b + qq0)
    cq = c * bq
    bbb[id] = (fkk[id] / dtp1 + fh0 + b) * bq + ss0[id]
    ccc[id] = (fkk[id + 1] / dtp1) * bq - cq * (UN + ss0[id + 1])
    vll = st0[id] + cq * st0[id + 1]
    if C.IWINBL < 0:
        vll = vll + C.HEXTRD[ij] * bq
    if C.ILMCOR == 2:
        bbb[id] = bbb[id] * scor[id]
        ccc[id] = ccc[id] * scor[id]
        vll = vll * scor[id]
    zzz[id] = UN / bbb[id]
    aanu[id] = vll * zzz[id]
    ddd[id] = ccc[id] * zzz[id]
    fff = 0.0                        # FFF 仅在 ISPLIN>2 时使用；原代码未显式初始化
    if C.ISPLIN > 2:
        fff = bbb[id] / ccc[id] - UN

    # Normal depth point
    for id in range(2, C.ND):
        dtm1 = dtp1
        dtp1 = dt[id]
        dt0 = TWO / (dtp1 + dtm1)
        al = UN / dtm1 * dt0
        ga = UN / dtp1 * dt0
        if imod(C.ISPLIN, 3) == 0:
            a = 0.0
            c = 0.0
        elif C.ISPLIN == 1:
            a = dtm1 * dt0 * SIXTH
            c = dtp1 * dt0 * SIXTH
        else:
            a = (UN - HALF * dtp1 * dtp1 * al) * SIXTH
            c = (UN - HALF * dtm1 * dtm1 * ga) * SIXTH
        aaa[id] = al * fkk[id - 1] - a * (UN + ss0[id - 1])
        ccc[id] = ga * fkk[id + 1] - c * (UN + ss0[id + 1])
        bbb[id] = (al + ga) * fkk[id] + (UN - a - c) * (UN + ss0[id])
        vll = a * st0[id - 1] + c * st0[id + 1] + (UN - a - c) * st0[id]
        if C.ILMCOR == 2:
            aaa[id] = aaa[id] * scor[id]
            bbb[id] = bbb[id] * scor[id]
            ccc[id] = ccc[id] * scor[id]
            vll = vll * scor[id]
        aanu[id] = vll + aaa[id] * aanu[id - 1]
        if C.ISPLIN <= 2:
            zzz[id] = UN / (bbb[id] - aaa[id] * ddd[id - 1])
            ddd[id] = ccc[id] * zzz[id]
            aanu[id] = aanu[id] * zzz[id]
        else:
            sum = -aaa[id] + bbb[id] - ccc[id]
            fff = (sum + aaa[id] * fff * ddd[id - 1]) / ccc[id]
            ddd[id] = UN / (UN + fff)
            aanu[id] = aanu[id] * ddd[id] / ccc[id]

    # Lower boundary condition
    id = C.ND

    # stellar atmospheric
    if C.IDISK == 0 or C.IFZ0 < 0:
        if C.IBC == 0:
            bbb[id] = fkk[id] / dtp1 + HALF
            aaa[id] = fkk[id - 1] / dtp1
            vll = HALF * pland + THIRD * dplan
        elif C.IBC < 4:
            b = UN / dtp1
            a = TWO * b * b
            bbb[id] = UN + ss0[id] + b * TWO * C.FHD[ij] + a * fkk[id]
            aaa[id] = a * fkk[id - 1]
            vll = st0[id] + b * (pland + TWOTHR * dplan)
        else:
            b = UN / dtp1
            a = TWO * b * b
            bbb[id] = b + a * fkk[id]
            aaa[id] = a * fkk[id - 1]
            vll = b * (pland + TWOTHR * dplan)

    # accretion disk - symmetric boundary
    else:
        b = TWO / dtp1
        bbb[id] = fkk[id] / dtp1 * b + UN + ss0[C.ND]
        aaa[id] = fkk[id - 1] / dtp1 * b
        vll = st0[id]
    if C.ILMCOR == 2:
        aaa[id] = aaa[id] * scor[id]
        bbb[id] = bbb[id] * scor[id]
        vll = vll * scor[id]
    eee[C.ND] = aaa[id] / bbb[id]
    zzz[id] = UN / (bbb[id] - aaa[id] * ddd[id - 1])
    C.RAD1[id] = (vll + aaa[id] * aanu[id - 1]) * zzz[id]
    C.FAK1[id] = fkk[C.ND]
    alrh[id] = zzz[id]

    # Backsolution
    for id in range(C.ND - 1, 0, -1):
        eee[id] = aaa[id] / (bbb[id] - ccc[id] * eee[id + 1])
        C.RAD1[id] = aanu[id] + ddd[id] * C.RAD1[id + 1]
        C.FAK1[id] = fkk[id]
        alrh[id] = zzz[id] / (UN - ddd[id] * eee[id + 1])
        alrm[id] = 0.0
        alrp[id] = 0.0
    C.FLUX[ij] = (C.FH[ij] * C.RAD1[1] - HALF * C.HEXTRD[ij]
                  - (st0[1] - ss0[1] * C.RAD1[1]) * C.Q0[ij])

    # evaluate approximate Lambda operator

    # a) Rybicki-Hummer Lambda^star operator (diagonal)
    #    (for JALI = 1)
    for id in range(1, C.ND + 1):
        C.ALIM1[id] = 0.0
        C.ALIP1[id] = 0.0
    if C.JALI == 1:
        for id in range(1, C.ND + 1):
            C.ALI1[id] = alrh[id]

        if C.IBC == 0:
            C.ALI1[C.ND - 1] = C.RAD1[C.ND - 1] / st0[C.ND - 1]
            C.ALI1[C.ND] = C.RAD1[C.ND] / st0[C.ND]

        # for IFALI>5:
        # tridiagonal Rybicki-Hummer operator (off-diagonal terms)
        if C.IFALI >= 6:
            C.ALIP1[1] = alrh[2] * ddd[1]
            for id in range(2, C.ND):
                C.ALIM1[id] = alrh[id - 1] * eee[id]
                C.ALIP1[id] = alrh[id + 1] * ddd[id]
            C.ALIM1[C.ND] = alrh[C.ND - 1] * eee[C.ND]
            if C.IBC == 0:
                C.ALIM1[C.ND] = 0.0
                C.ALIM1[C.ND - 1] = 0.0
                C.ALIP1[C.ND] = 0.0
                C.ALIP1[C.ND - 1] = 0.0

    # b) diagonal Olson-Kunasz Lambda^star operator,
    #    (for JALI = 2)
    elif C.JALI == 2:
        for id in range(1, C.ND):
            ali0[id] = 0.0
            for i in range(1, C.NMU + 1):
                div = dt[id] / C.AMU[i]
                ali0[id] = ali0[id] + (UN - math.exp(-div)) / div * C.WTMU[i]
        for id in range(2, C.ND):
            C.ALI1[id] = UN - HALF * (ali0[id] + ali0[id - 1])
        C.ALI1[1] = UN - HALF * (ali0[1] + us0)
        C.ALI1[C.ND] = UN - ali0[C.ND - 1]
        C.ALI1[C.ND - 1] = C.RAD1[C.ND - 1] / st0[C.ND - 1]
        C.ALI1[C.ND] = C.RAD1[C.ND] / st0[C.ND]

    # correction of Lambda^star for scattering
    if C.ILMCOR == 1:
        for id in range(1, C.ND + 1):
            C.ALI1[id] = C.ALI1[id] * (UN + ss0[id])
            C.ALIM1[id] = C.ALIM1[id] * (UN + ss0[id])
            C.ALIP1[id] = C.ALIP1[id] * (UN + ss0[id])
        if C.IBC == 4:
            C.ALI1[C.ND] = C.ALI1[C.ND] / (UN + ss0[C.ND])
            C.ALIM1[C.ND] = C.ALIM1[C.ND] / (UN + ss0[C.ND])
            C.ALIP1[C.ND] = C.ALIP1[C.ND] / (UN + ss0[C.ND])

    if C.IFALIH > 0:
        # solution for the individual angles - to get Lambda^star_H
        for id in range(1, C.ND + 1):
            C.alih1[id] = 0.0
            alij1[id] = 0.0
        nw = C.NMU
        for i in range(1, nw + 1):
            rmmu[i] = -C.AMU[nw - i + 1]
            rmmu[i + nw] = C.AMU[i]
            wmmu[i] = C.WTMU[nw - i + 1]
            wmmu[i + nw] = C.WTMU[i]
        for i in range(1, 2 * nw + 1):
            rwmu[i] = rmmu[i] * wmmu[i] * HALF

        # --------------------- loop over angles
        for i in range(1, 2 * nw + 1):
            for id in range(1, C.ND):
                dtau[id] = dt[id] / abs(rmmu[i])

            # boundary conditions
            # c rup=extrad(ij)   —— 原代码已注释
            # TODO(port): 原代码此处 EXTINT 第二维上界为 MMU，而 i 最大取 2*NMU，
            # 当 NMU=MMU 时 i>NMU 会越界；原代码即如此，直译保留
            rup = C.EXTINT[ij, i]

            # diffusion approximation for semi-infinite atmospheres
            # TODO(port): 若第一遍求解走了 IFZ0>=0.AND.IDISK==1 分支，
            # PLAND/DPLAN 在 Fortran 中是未定义残留值；直译保留（此处可能用到
            # 未赋值的 pland/dplan）
            rdown = pland + rmmu[i] * dplan

            # solution of the transfer equation
            # CALL RTESOL(dtau,st0,rup,rdown,rmmu(i),ri,ali)：RTESOL 不修改标量哑元
            rtesol(dtau, st0, rup, rdown, rmmu[i], ri, ali)

            for id in range(1, C.ND + 1):
                C.alih1[id] = C.alih1[id] + rwmu[i] * ali[id]
                alij1[id] = alij1[id] + wmmu[i] * ali[id] * HALF
    # --------------------- end of loop over angles

    C.ISPLIN = ispl

    if C.IDISK != 0:
        iji = C.NFREQ - C.KIJ[ij] + 1
        for id in range(1, C.ND + 1):
            C.RAD[iji, id] = C.RAD1[id]

    # radiation pressure
    if C.IFPRAD > 0:
        if not C.LSKIP[1, ij]:
            C.PRD0 = C.PRD0 + C.ABSO1[1] * ww * (C.RAD1[1] * C.FH[ij] - C.HEXTRD[ij])
        for id in range(1, C.ND + 1):
            if not C.LSKIP[id, ij]:
                C.PRADT[id] = C.PRADT[id] + C.RAD1[id] * C.FAK1[id] * ww
            C.PRADA[id] = C.PRADA[id] + C.RAD1[id] * C.FAK1[id] * ww

    if C.CHMAX >= 1.91e-3 and C.CHMAX <= 2.03e-3:
        tauij = taumin
        for id in range(1, C.ND + 1):
            if C.ILMCOR == 3:
                ss0[id] = ss0c[id]
            if id > 1:
                tauij = tauij + dt[id - 1]
            # 697 format(2i4,1p6e12.4) —— 1P 缩放前缀按普通 E 格式直译
            write_line(97, '%4d%4d%12.4e%12.4e%12.4e%12.4e%12.4e%12.4e'
                       % (ij, id, tauij, C.RAD1[id], st0[id] / (UN + ss0[id]),
                          st0[id], UN + ss0[id], C.ALI1[id]))

    # store quantities for explicit (linearized) frequencies
    if C.IJEX[ij] <= 0:
        return
    ije = C.IJEX[ij]
    for id in range(1, C.ND + 1):
        C.RADEX[ije, id] = C.RAD1[id]
        C.FAKEX[ije, id] = C.FAK1[id]
    # c Q0(IJE)=QQ0 / c UU0(IJE)=U0   —— 原代码已注释
    return


def rteint():
    """
    Solution of the radiative transfer equation - for one frequency
    - for the known source function.

    Solution for specific intensities

    The numerical method used:
     for ISPLIN = 0  -  the ordinary Feautrier scheme
                = 1  -  the spline collocation method
                = 2  -  Hermitian fourth-order method
                = 3  -  improved Feautrier scheme
                        (Rybicki & Hummer 1991, A&A 245, 171.)

    In all cases, the overall matrix system is solved by the standard
    Gaussian elimination, analogous to that described in SOLVE
    (auxiliary matrix D is called ALF in SOLVE; auxiliary vector ANU
    is called BET in SOLVE)

    对应 tlusty208.f 行 33022–33378
    """
    SIXTH = UN / 6.0
    THIRD = UN / 3.0
    TWOTHR = TWO / 3.0
    MMA = 20                         # PARAMETER (MMA=20)
    st0 = np.zeros(MDEPTH + 1)
    ss0 = np.zeros(MDEPTH + 1)
    ab0 = np.zeros(MDEPTH + 1)
    aa = np.zeros((MMA + 1, MMA + 1))
    bb = np.zeros((MMA + 1, MMA + 1))
    cc = np.zeros((MMA + 1, MMA + 1))
    vl = np.zeros(MMA + 1)
    ffd = np.zeros((MMA + 1, MMA + 1))
    ff0d = np.zeros((MMA + 1, MMA + 1))
    ffpd = np.zeros((MMA + 1, MMA + 1))
    d = np.zeros((MMA + 1, MMA + 1, MDEPTH + 1))
    anu = np.zeros((MMA + 1, MDEPTH + 1))
    tau = np.zeros(MDEPTH + 1)
    angl = np.zeros(MMA + 1)
    wang = np.zeros(MMA + 1)
    dt = C.DT                        # COMMON/OPTDPT/DT(MDEPTH)

    nmuf = C.NMU
    C.NMU = C.INTENS                 # NMU 是 COMMON /ANGLES/ 变量，结尾恢复
    for imu in range(1, C.NMU + 1):
        angl[imu] = 0.1 + float(imu - 1) * 0.9 / float(C.NMU - 1)
        wang[imu] = 0.9 / float(C.NMU - 1)
    wang[1] = wang[1] * 0.5
    wang[C.NMU] = wang[C.NMU] * 0.5

    for ijo in range(1, C.NFREQ + 1):            # DO 500 IJO=1,NFREQ
        ij = ijo
        if C.ISPODF == 0:
            ij = C.JIK[ijo]
        if C.IJX[ij] == -1:
            continue                             # GO TO 500
        opacf1(ij)                               # OPACF1 不修改标量哑元

        fr = C.FREQ[ij]

        # total source function
        ah = 0.0
        for id in range(1, C.ND + 1):
            ab0[id] = C.ABSO1[id]
            st0[id] = C.EMIS1[id] / ab0[id]
            ss0[id] = -C.SCAT1[id] / ab0[id]
            C.RAD1[id] = 0.0

        # optical depth scale
        tau[1] = C.ABSOT[1] * C.DM[1]
        for id in range(1, C.ND):
            dt[id] = C.DELDMZ[id] * (C.ABSOT[id + 1] + C.ABSOT[id])
            tau[id + 1] = tau[id] + dt[id]

        u0 = 0.0
        qq0 = 0.0
        us0 = 0.0
        taumin = C.ABSOT[1] * C.DM[1] / 2.0

        alb1 = 0.0

        # ************** Forward elimination

        # Upper boundary condition
        id = 1
        dtp1 = dt[1]
        p0 = 0.0
        ex = UN
        if imod(C.ISPLIN, 3) == 0:               # MOD(ISPLIN,3).EQ.0
            b = dtp1 * HALF
            c = 0.0
        else:
            b = dtp1 * THIRD
            c = b * HALF
        qq0 = 0.0
        us0 = 0.0
        for i in range(1, C.NMU + 1):
            if C.IDISK == 0:
                # allowance for non-zero optical depth at the first depth point
                tamm = taumin / angl[i]
                ex = math.exp(-tamm)
                p0 = UN - ex
                qq0 = qq0 + p0 * angl[i] * wang[i]
                u0 = u0 + ex * wang[i]
                us0 = us0 + p0 / tamm * wang[i]

            bi = b / angl[i]
            ci = c / angl[i]
            vl[i] = (bi + p0) * st0[id] + ci * st0[id + 1]
            if C.IWINBL < 0:
                vl[i] = vl[i] + C.EXTRAD[ij]
            for j in range(1, C.NMU + 1):
                bb[i, j] = ss0[id] * wang[j] * (bi + p0) - alb1 * wang[j]
                cc[i, j] = -ci * ss0[id + 1] * wang[j]
            bb[i, i] = bb[i, i] + angl[i] / dtp1 + UN + bi
            cc[i, i] = cc[i, i] + angl[i] / dtp1 - ci
            anu[i, id] = 0.0

        if C.ISPLIN <= 2:
            matinv(bb, C.NMU, MMA)   # MATINV 不修改标量哑元（只就地求逆数组）
            for i in range(1, C.NMU + 1):
                for j in range(1, C.NMU + 1):
                    d[i, j, id] = 0.0
                    for k in range(1, C.NMU + 1):
                        d[i, j, id] = d[i, j, id] + bb[i, k] * cc[k, j]
                    anu[i, 1] = anu[i, 1] + bb[i, j] * vl[j]
        else:
            for i in range(1, C.NMU + 1):
                for j in range(1, C.NMU + 1):
                    ff0d[i, j] = bb[i, j] / cc[i, i]
                ff0d[i, i] = ff0d[i, i] - UN

            matinv(bb, C.NMU, MMA)
            for i in range(1, C.NMU + 1):
                anu[i, id] = 0.0
                for j in range(1, C.NMU + 1):
                    d[i, j, id] = bb[i, j] * cc[j, j]
                    anu[i, id] = anu[i, id] + bb[i, j] * vl[j]

        # Normal depth points  1 < ID < ND
        for id in range(2, C.ND):
            dtm1 = dtp1
            dtp1 = dt[id]
            dt0 = TWO / (dtm1 + dtp1)
            al = UN / dtm1 * dt0
            ga = UN / dtp1 * dt0
            be = al + ga
            if imod(C.ISPLIN, 3) == 0:
                a = 0.0
                c = 0.0
            elif C.ISPLIN == 1:
                a = dtm1 * dt0 * SIXTH
                c = dtp1 * dt0 * SIXTH
            else:
                a = (UN - HALF * al * dtp1 * dtp1) * SIXTH
                c = (UN - HALF * ga * dtm1 * dtm1) * SIXTH
            b = UN - a - c
            vl0 = a * st0[id - 1] + b * st0[id] + c * st0[id + 1]
            for i in range(1, C.NMU + 1):
                for j in range(1, C.NMU + 1):
                    aa[i, j] = -a * ss0[id - 1] * wang[j]
                    cc[i, j] = -c * ss0[id + 1] * wang[j]
                    bb[i, j] = b * ss0[id] * wang[j]
            for i in range(1, C.NMU + 1):
                vl[i] = vl0
                div = angl[i] * angl[i]
                aa[i, i] = aa[i, i] + div * al - a
                cc[i, i] = cc[i, i] + div * ga - c
                bb[i, i] = bb[i, i] + div * be + b
            for i in range(1, C.NMU + 1):
                for j in range(1, C.NMU + 1):
                    vl[i] = vl[i] + aa[i, j] * anu[j, id - 1]
            if C.ISPLIN <= 2:
                for i in range(1, C.NMU + 1):
                    for j in range(1, C.NMU + 1):
                        s = 0.0
                        for k in range(1, C.NMU + 1):
                            s = s + aa[i, k] * d[k, j, id - 1]
                        bb[i, j] = bb[i, j] - s

                matinv(bb, C.NMU, MMA)
                for i in range(1, C.NMU + 1):
                    for j in range(1, C.NMU + 1):
                        d[i, j, id] = 0.0
                        for k in range(1, C.NMU + 1):
                            d[i, j, id] = d[i, j, id] + bb[i, k] * cc[k, j]
            else:
                for i in range(1, C.NMU + 1):
                    bb[i, i] = -aa[i, i] + bb[i, i] - cc[i, i]
                    for j in range(1, C.NMU + 1):
                        ffpd[i, j] = aa[i, i] * ff0d[i, j]
                for i in range(1, C.NMU + 1):
                    for j in range(1, C.NMU + 1):
                        s = 0.0
                        for k in range(1, C.NMU + 1):
                            s = s + ffpd[i, k] * d[k, j, id - 1]
                        ffd[i, j] = (bb[i, j] + s) / cc[i, i]
                for i in range(1, C.NMU + 1):
                    for j in range(1, C.NMU + 1):
                        ff0d[i, j] = ffd[i, j]
                    ffd[i, i] = ffd[i, i] + UN

                matinv(ffd, C.NMU, MMA)
                for i in range(1, C.NMU + 1):
                    for j in range(1, C.NMU + 1):
                        d[i, j, id] = ffd[i, j]
                        bb[i, j] = ffd[i, j] / cc[j, j]
            for i in range(1, C.NMU + 1):
                anu[i, id] = 0.0
                for j in range(1, C.NMU + 1):
                    anu[i, id] = anu[i, id] + bb[i, j] * vl[j]

        # Lower boundary condition
        id = C.ND

        # First option:
        # b.c. is different from stellar atmospheres; expresses symmetry
        # at the central plane   I(taumax,-mu,nu)=I(taumax,+mu,nu)
        if C.IFZ0 >= 0 and C.IDISK == 1:
            b = dtp1 * HALF
            a = 0.0
            for i in range(1, C.NMU + 1):
                bi = b / angl[i]
                ai = a / angl[i]
                vl[i] = st0[id] * bi + st0[id - 1] * ai
                for j in range(1, C.NMU + 1):
                    aa[i, j] = -ai * ss0[id - 1] * wang[j]
                    bb[i, j] = bi * ss0[id] * wang[j]
                aa[i, i] = aa[i, i] + angl[i] / dtp1 - ai
                bb[i, i] = bb[i, i] + angl[i] / dtp1 + bi
            for i in range(1, C.NMU + 1):
                s1 = 0.0
                for j in range(1, C.NMU + 1):
                    s = 0.0
                    s1 = s1 + aa[i, j] * anu[j, id - 1]
                    for k in range(1, C.NMU + 1):
                        s = s + aa[i, k] * d[k, j, id - 1]
                    bb[i, j] = bb[i, j] - s
                vl[i] = vl[i] + s1

        # Second option:
        # b.c. is the same as in stellar atmospheres - the last depth point
        # is not at the central plane
        else:
            fr15 = fr * 1.0e-15
            bnu = BN * fr15 * fr15 * fr15
            pland = bnu / (math.exp(HK * fr / C.TEMP[C.ND]) - UN) * C.RRDIL
            dplan = bnu / (math.exp(HK * fr / C.TEMP[C.ND - 1]) - UN) * C.RRDIL
            if C.TEMPBD > 0.0:
                pland = bnu / (math.exp(HK * fr / C.TEMPBD) - UN) * C.RRDIL
                dplan = bnu / (math.exp(HK * fr / C.TEMPBD) - UN) * C.RRDIL
            dplan = (pland - dplan) / dt[C.ND - 1]
            if C.IBC == 0 or C.IBC == 4:
                for i in range(1, C.NMU + 1):
                    aa[i, i] = angl[i] / dtp1
                    vl[i] = pland + angl[i] * dplan + aa[i, i] * anu[i, id - 1]
                    for j in range(1, C.NMU + 1):
                        bb[i, j] = -aa[i, i] * d[i, j, id - 1]
                    bb[i, i] = bb[i, i] + aa[i, i] + UN
            else:
                for i in range(1, C.NMU + 1):
                    a = angl[i] / dtp1
                    b = HALF / a
                    aa[i, i] = a
                    vl[i] = (b * st0[id] + pland + angl[i] * dplan
                             + aa[i, i] * anu[i, id - 1])
                    for j in range(1, C.NMU + 1):
                        bb[i, j] = b * ss0[id] * wang[j] - aa[i, i] * d[i, j, id - 1]
                    bb[i, i] = bb[i, i] + a + b + UN

        matinv(bb, C.NMU, MMA)

        for i in range(1, C.NMU + 1):            # DO 230 I=1,NMU
            anu[i, id] = 0.0
            for j in range(1, C.NMU + 1):        # DO 230 J=1,NMU
                d[i, j, id] = 0.0
                anu[i, id] = anu[i, id] + bb[i, j] * vl[j]
        # 230 CONTINUE

        # ***************** Backsolution
        for id in range(C.ND - 1, 0, -1):
            for i in range(1, C.NMU + 1):
                for j in range(1, C.NMU + 1):
                    anu[i, id] = anu[i, id] + d[i, j, id] * anu[j, id + 1]

        sum = 0.0
        sua = 0.0
        for imu in range(1, C.NMU + 1):
            sum = sum + anu[imu, 1] * angl[imu] * wang[imu]
            sua = sua + angl[imu] * wang[imu]

        wlam = 2.997925e18 / C.FREQ[ij]
        # 641 format(f11.3,(1p13e11.3)) —— 1P 缩放前缀按普通 E 格式直译；
        # 隐式 DO 表 (2.*ANU(IMU,1),IMU=1,NMU) 展开为逐值拼接
        line = '%11.3f' % wlam
        line += '%11.3e%11.3e%11.3e' % (C.FLUX[ij], sum, sua)
        for imu in range(1, C.NMU + 1):
            line += '%11.3e' % (2.0 * anu[imu, 1])
        write_line(18, line)

    # 500 CONTINUE
    C.NMU = nmuf
    return


