def _ff(field):
    """解析 Fortran 定点浮点字段（F/E 编辑符；允许空白与 D 指数）。"""
    s = field.strip()
    if not s:
        return 0.0
    return float(s.replace("D", "E").replace("d", "e"))


def _fi(field):
    """解析 Fortran 定点整数字段（I 编辑符；允许空白）。"""
    s = field.strip()
    if not s:
        return 0
    return int(s)


