def lucy():
    """NLTE Lucy-Unsold temperature correction scheme, following
      Werner & Dreizler

    对应 tlusty208.f 行 35989–36256（SUBROUTINE LUCY）
    """
    global _save_lucy_ilinit
    THIRD = 1.0 / 3.0            # PARAMETER (THIRD=1./3.)（本体内未使用，保留）
    # 局部数组（1 基索引，维度 +1）
    heat = np.zeros(MDEPTH + 1)
    absz = np.zeros(MDEPTH + 1)
    absp = np.zeros(MDEPTH + 1)
    absh = np.zeros(MDEPTH + 1)
    totj = np.zeros(MDEPTH + 1)
    toth = np.zeros(MDEPTH + 1)
    totb = np.zeros(MDEPTH + 1)
    delh = np.zeros(MDEPTH + 1)
    eddf = np.zeros(MDEPTH + 1)
    deltat = np.zeros(MDEPTH + 1)
    dt1 = np.zeros(MDEPTH + 1)
    dt2 = np.zeros(MDEPTH + 1)
    antc = np.zeros(MDEPTH + 1)
    xe = np.zeros(MDEPTH + 1)
    heab = np.zeros(MDEPTH + 1)
    tau = np.zeros(MDEPTH + 1)
    tem0 = np.zeros(MDEPTH + 1)
    tem1 = np.zeros(MDEPTH + 1)
    tem2 = np.zeros(MDEPTH + 1)
    tem3 = np.zeros(MDEPTH + 1)
    col = np.zeros(MTRANS + 1)
    cloc = np.zeros(MTRANS + 1)

    # DATA ILINIT /0/（隐含 SAVE → 模块级 _save_lucy_ilinit）
    if _save_lucy_ilinit == 0:
        _save_lucy_ilinit = 1
        for itr in range(1, C.NTRANS + 1):
            C.ILUCTR[itr] = 0
        ntrl = 0
        try:
            ntrl = int(float(read_line(2).split()[0]))  # read(2,*,end=5,err=5) ntrl
        except (EOFError, ValueError, IndexError):
            pass                     # end=5/err=5 → 标号 5（ntrl 保持 0）
        # 标号 5
        if ntrl > 0:
            for i in range(1, ntrl + 1):
                try:
                    itrl = int(float(read_line(2).split()[0]))  # read(2,*,end=6,err=6) itrl
                except (EOFError, ValueError, IndexError):
                    break            # end=6/err=6 → 标号 6
                C.ILUCTR[itrl] = 1
        # 标号 6

    # IF(MOD(ILAM,4).NE.3) RETURN —— 原代码已注释掉，保留注释
    if C.ITLUCY <= 0:
        return
    lac2t = False                  # LAC2T：局部逻辑变量（每次调用重置）
    iacc0t = C.IACLT - 3

    ilucy = 1
    while True:                    # 标号 10：Lucy 迭代主循环（末尾 GO TO 10）
        opaini(0)                  # CALL OPAINI(0)：OPAINI 不修改标量哑元

        for id in range(1, C.ND + 1):
            heat[id] = 0.0
            heab[id] = 0.0
            absz[id] = 0.0
            absp[id] = 0.0
            absh[id] = 0.0
            totj[id] = 0.0
            toth[id] = 0.0
            totb[id] = 0.0
            eddf[id] = 0.0
        eddh = 0.0

        for ij in range(1, C.NFREQ + 1):
            w0 = C.W[ij]
            fr = C.FREQ[ij]
            fr15 = fr * 1.0e-15
            bnu = BN * fr15 * fr15 * fr15
            opacfl(ij)             # CALL OPACFL(IJ)
            rtefr1(ij)             # CALL RTEFR1(IJ)：RTEFR1 不修改标量哑元
            tau[1] = C.ABSO1[1] / C.DENS[1] * C.DM[1]
            for id in range(1, C.ND + 1):
                if id >= 2:
                    tau[id] = tau[id - 1] + HALF * (C.ABSO1[id] / C.DENS[id] +
                              C.ABSO1[id - 1] / C.DENS[id - 1]) * (C.DM[id] - C.DM[id - 1])
                pland = bnu / (math.exp(HK * fr / C.TEMP[id]) - UN)
                absot0 = C.ABSO1L[id] - C.SCAT1[id]
                heat[id] = heat[id] + w0 * (absot0 * C.RAD1[id] - C.EMIS1L[id])
                heab[id] = heab[id] + w0 * (absot0 * C.RAD1[id] - C.EMIS1L[id]) / \
                    (absot0 * pland)
                absp[id] = absp[id] + w0 * absot0 * pland
                totj[id] = totj[id] + w0 * C.RAD1[id]
                totb[id] = totb[id] + w0 * pland
                eddf[id] = eddf[id] + w0 * C.FAK1[id] * C.RAD1[id]

            id = 1
            eddh = eddh + w0 * C.RAD1[id] * C.FH[ij]
            toth[id] = toth[id] + w0 * (C.RAD1[id] * C.FH[ij] - C.HEXTRD[ij])
            absot0 = C.ABSO1[id]
            absh[id] = absh[id] + w0 * absot0 * (C.RAD1[id] * C.FH[ij] - C.HEXTRD[ij])
            for id in range(2, C.ND + 1):
                absot0 = HALF * (C.ABSO1[id] + C.ABSO1[id - 1])
                dtm = C.DELDM[id - 1] * (C.ABSO1[id] * C.DENS1[id] +
                                         C.ABSO1[id - 1] * C.DENS1[id - 1])
                fluz = (C.RAD1[id] * C.FAK1[id] - C.RAD1[id - 1] * C.FAK1[id - 1]) / dtm
                toth[id] = toth[id] + w0 * fluz
                absh[id] = absh[id] + w0 * absot0 * fluz

        eddh = eddh / totj[1]
        tef4 = SIG4P * C.TEFF ** 4
        toth[C.ND] = tef4
        heat[C.ND] = 0.0
        heat[C.ND - 1] = 0.0
        for id in range(1, C.ND + 1):
            absz[id] = (heat[id] + absp[id]) / totj[id]
            absp[id] = absp[id] / totb[id]
            absh[id] = absh[id] / toth[id]
            eddf[id] = eddf[id] / totj[id]
            delh[id] = -toth[id] + tef4
        dhhmx1 = 0.0
        for id in range(1, C.ND):  # 1..ND-1
            dhh = abs(delh[id] / toth[id])
            if dhh > dhhmx1:
                dhhmx1 = dhh

        id = 1
        tp3 = C.TEMP1[id] * C.TEMP1[id] * C.TEMP1[id]
        xx = eddf[id] / eddh * delh[id]
        xx1 = xx                     # XX1 赋值后未使用（原代码如此）
        dt1[id] = heat[id] / 16.0 / SIG4P * tp3 / absp[id]
        dt2[id] = absz[id] / eddf[id] * xx / 16.0 / SIG4P * tp3 / absp[id]
        deltat[id] = dt1[id] + dt2[id]
        for id in range(2, C.ND + 1):
            tp3 = C.TEMP1[id] * C.TEMP1[id] * C.TEMP1[id]
            # TODO(port): ID=ND 时引用 ABSH(ND+1)/DENS1(ND+1)/DELH(ND+1)，
            # Fortran 越界读（依赖静态存储），Python 下索引 ND+1<=MDEPTH 时有效
            xx = xx + C.DELDM[id] * (absh[id] * C.DENS1[id] * delh[id] +
                                     absh[id + 1] * C.DENS1[id + 1] * delh[id + 1])
            dt1[id] = heat[id] / 16.0 / SIG4P * tp3 / absp[id]
            dt2[id] = absz[id] / eddf[id] * xx / 16.0 / SIG4P * tp3 / absp[id]
            deltat[id] = dt1[id] + dt2[id]

        # New temperature
        for id in range(1, C.ND + 1):
            C.TEMP[id] = C.TEMP[id] + deltat[id]
            tem0[id] = C.TEMP[id]
            aold = C.DENS[id] / C.WMM[id] + C.ELEC[id]
            xe[id] = UN - C.ELEC[id] / aold

        # acceleration
        # GO TO 20 → 跳过整个加速段；用 _goto20 标志重构
        if not (C.ITLUCY < C.IACLT or ilucy < iacc0t):
            ipng = 1
            if C.IACLDT > 0:
                ipng = imod(ilucy - C.IACLT, C.IACLDT)
            _goto20 = False
            if not lac2t:
                ipt = imod(ilucy, 3)
                ipt0 = imod(C.IACLT, 3)        # IPT0 赋值后未使用（原代码如此）
                ipt1 = imod(C.IACLT + 1, 3)
                ipt2 = imod(C.IACLT + 2, 3)
                if ilucy == iacc0t:
                    for id in range(1, C.ND + 1):
                        tem3[id] = tem0[id]
                elif ipt == ipt1:
                    for id in range(1, C.ND + 1):
                        tem2[id] = tem0[id]
                elif ipt == ipt2:
                    for id in range(1, C.ND + 1):
                        tem1[id] = tem0[id]
            elif ipng != 0:
                for id in range(1, C.ND + 1):
                    tem3[id] = tem2[id]
                for id in range(1, C.ND + 1):
                    tem2[id] = tem1[id]
                for id in range(1, C.ND + 1):
                    tem1[id] = tem0[id]
                _goto20 = True                 # GO TO 20

            # IF(ILUCY.LT.IACLT) go to 20
            if not _goto20 and ilucy >= C.IACLT:
                a1 = 0.0
                b1 = 0.0
                b2 = 0.0
                c1 = 0.0
                c2 = 0.0
                for id in range(1, C.ND + 1):
                    wt = 0.0
                    if tem0[id] != 0.0:
                        wt = 1.0 / abs(tem0[id])
                    d0 = tem0[id] - tem1[id]
                    d1 = d0 - tem1[id] + tem2[id]
                    d2 = d0 - tem2[id] + tem3[id]
                    a1 = a1 + wt * d1 * d1
                    b1 = b1 + wt * d1 * d2
                    b2 = b2 + wt * d2 * d2
                    c1 = c1 + wt * d0 * d1
                    c2 = c2 + wt * d0 * d2
                ab = b2 * a1 - b1 * b1
                if ab == 0.0:
                    # 601 FORMAT(/,' **** ACCELT, ITER=',I4,'   AB = ',F7.3,/)
                    print(f"\n **** ACCELT, ITER={ilucy:4d}   AB = {ab:7.3f}\n")
                    C.IACLT = C.IACLT + C.IACLDT
                    iacc0t = C.IACLT - 3
                    # GO TO 20（即跳过下面的加速更新）
                else:
                    a0 = (b2 * c1 - b1 * c2) / ab
                    b0 = (a1 * c2 - b1 * c1) / ab
                    for id in range(1, C.ND + 1):
                        tem0[id] = (1.0 - a0 - b0) * tem0[id] + a0 * tem1[id] + \
                            b0 * tem2[id]
                        C.TEMP[id] = tem0[id]
                    lac2t = True
        # 20 CONTINUE

        tdpini()                   # CALL TDPINI

        # Integrate hydrostatic equilibrium
        if C.IHECOR >= 1:
            id = 1
            ptur = HALF * C.VTURB[id] * C.VTURB[id] * C.DENS[id]
            antc[id] = (C.DM[id] * C.GRAV - C.PRD0 - ptur) / BOLK / C.TEMP[id]
            if antc[id] <= 0:
                antc[id] = C.DENS[id] / C.WMM[id] + C.ELEC[id]
            for id in range(2, C.ND + 1):
                ptur = HALF * C.VTURB[id] * C.VTURB[id] * C.DENS[id]
                pturm = HALF * C.VTURB[id - 1] * C.VTURB[id - 1] * C.DENS[id - 1]
                antc[id] = (C.GRAV * (C.DM[id] - C.DM[id - 1]) +
                            BOLK * C.TEMP[id - 1] * antc[id - 1] -
                            C.PRADT[id] + C.PRADT[id - 1] - ptur + pturm) / \
                    BOLK / C.TEMP[id]
            for id in range(1, C.ND + 1):
                C.ELEC[id] = (UN - xe[id]) * antc[id]
                C.DENS[id] = C.WMM[id] * (antc[id] - C.ELEC[id])
                C.DENS1[id] = UN / C.DENS[id]

        # Other depth-dependent quantities
        for id in range(1, C.ND + 1):
            C.PGS[id] = (C.DENS[id] / C.WMM[id] + C.ELEC[id]) * BOLK * C.TEMP[id]
            wnstor(id)             # CALL WNSTOR(ID)：不修改标量哑元
            if C.LTE:
                continue           # GO TO 60
            sabolf(id)             # CALL SABOLF(ID)：不修改标量哑元
            colis(id, C.TEMP[id], col, cloc)  # CALL COLIS(...)：不修改标量哑元
            for i in range(1, C.NTRANS + 1):
                C.COLRAT[i, id] = col[i]
                C.COLTAR[i, id] = cloc[i]
            # 60 CONTINUE

        # new populations
        for id in range(1, C.ND + 1):
            steqeq(id, C.POP, 1)   # CALL STEQEQ(ID,POP,1)：不修改标量哑元
            if (not C.LCHC) and C.ITER < C.IELCOR:
                elcor(id)          # CALL ELCOR(ID)：不修改标量哑元

        concor()                   # CALL CONCOR
        odfmer()                   # CALL ODFMER
        ilucy = ilucy + 1
        if ilucy <= C.ITLUCY:
            continue               # GO TO 10
        break
    return


# ======================================================================

def iroset():
    """Initialization of opacity sampling for iron-peak lines

    IOBS = 2 : ALL lines except lines to autoionized levels
    IOBS = 1 : ALL lines
    IOBS = 0 : only lines between observed levels

    对应 tlusty208.f 行 36263–36465（SUBROUTINE IROSET）
    """
    CSIG = 0.0149736             # PARAMETER (CSIG=0.0149736)
    # 局部数组：REAL*4 SIGT(MDODF,MFREQ)；DML(MDEPTH)
    sigt = np.zeros((MDODF + 1, MFREQ + 1), dtype=np.float32)
    dml = np.zeros(MDEPTH + 1)
    # TODO(port): KJ 仅在 NFT>0 分支内赋值，之后即被引用；Fortran 静态存储下
    # 沿用上一轮值或 0，这里显式初始化为 0 以避免 NameError
    kj = 0
    # TODO(port): JIDS>0 且循环内条件不满足时 JIDC 未赋值（Fortran 静态存储为 0）
    jidc = 0

    C.JIDR[1] = 1
    if C.JIDS == 0:
        C.JIDR[2] = int(0.7 * C.ND)      # INT 截断取整
        C.JIDR[3] = C.ND
        C.JIDN = 3
        jidc = 2
    else:
        i = 1
        while C.JIDR[i] < C.ND:          # DO WHILE(JIDR(I).LT.ND)
            i = i + 1
            C.JIDR[i] = C.JIDR[i - 1] + C.JIDS
            if C.JIDR[i] <= int(0.7 * C.ND):
                jidc = C.JIDR[i]
        C.JIDN = i
        if C.JIDR[i] > C.ND:
            if C.JIDR[i - 1] >= C.ND - 5:
                C.JIDN = C.JIDN - 1
            C.JIDR[C.JIDN] = C.ND
        if C.JIDN > MDODF:
            quit(' Too many depths for Fe x-sections', C.JIDN, MDODF)

    for id in range(1, C.ND + 1):
        dml[id] = math.log(C.DM[id])
    for i in range(1, C.JIDN):           # 1..JIDN-1
        dxi = dml[C.JIDR[i + 1]] - dml[C.JIDR[i]]
        for id in range(C.JIDR[i] + 1, C.JIDR[i + 1] + 1):
            C.JIDI[id] = i
            C.XJID[id] = (dml[C.JIDR[i + 1]] - dml[id]) / dxi
    C.JIDI[1] = 1
    C.XJID[1] = 1.0

    xfrma = math.log(C.FRS1)
    ijd = int(9.0 / C.DDNU)              # INT 截断取整
    if ijd < 2:
        ijd = 2
    C.NFTT = 0
    nftmx = 0

    for ion in range(1, C.NION + 1):     # DO 500 ION=1,NION
        ind = C.INODF1[ion]
        if ind <= 0:
            continue                     # GO TO 500
        if C.NLLIM[ion] >= C.NLEVS[ion]:
            for id in range(1, C.ND + 1):
                for i in range(C.NFIRST[ion], C.NLAST[ion] + 1):
                    C.wop[i, id] = UN
            continue                     # GO TO 500

        # Set up superlevels and read line data
        iobs = C.IKOBS[ion]
        ion, iobs = levcd(ion, iobs)     # LEVCD 修改标量哑元 IOBS → 解包接收
        inkul(ion, iobs)                 # INKUL 不修改标量哑元

        # 610 format(/' *** superlines for ',i4,': ',a4,
        #     '   selected internal lines:',i10)
        print(f"\n *** superlines for {ion:4d}: {str(C.TYPION[ion]):4s}"
              f"   selected internal lines:{C.NLINKU:10d}")
        if C.NLINKU > MLINE:
            quit('too many internal lines', C.NLINKU, MLINE)

        # Assign line to supertransition and compute cross-section
        n1 = C.NFIRST[ion]
        nlii = C.NLAST[ion] - n1 + 1
        for il in range(1, nlii):        # 1..NLII-1
            kevl = 0
            kodl = 0
            if C.JEN[il] <= C.NEVKU[ion]:
                kevl = C.JEN[il]
            else:
                kodl = C.JEN[il] - C.NEVKU[ion]
            ilok = n1 + il - 1
            for iu in range(il + 1, nlii + 1):
                iupk = n1 + iu - 1
                itr = C.ITRA[ilok, iupk]
                indxpa = abs(C.INDEXP[itr])
                w1 = 0.0
                w2 = 0.0
                ifrku = 0
                nft = 0
                nlt = 0
                kevu = 0
                kodu = 0
                if C.JEN[iu] <= C.NEVKU[ion]:
                    kevu = C.JEN[iu]
                else:
                    kodu = C.JEN[iu] - C.NEVKU[ion]
                if kevl != 0:
                    kev = kevl
                    kod = kodu
                    ieo = 0              # IEO 赋值后未使用（原代码如此）
                    gsuper = C.YMKU[C.JEN[il], 1]
                else:
                    kev = kevu
                    kod = kodl
                    ieo = 1
                    gsuper = C.YMKU[C.JEN[il] - C.NEVKU[ion], 2]
                for ij in range(1, MFREQ + 1):
                    for i in range(1, MDODF + 1):
                        sigt[i, ij] = 0.0
                fcol = 0.0
                for k in range(1, C.NLINKU + 1):   # DO 10 K=1,NLINKU
                    if C.KSEV[C.JTR[k, 1]] != kev:
                        continue         # GO TO 10
                    if C.KSOD[C.JTR[k, 2]] != kod:
                        continue         # GO TO 10
                    nlt = nlt + 1
                    frl = CAS / C.WAVE[k]
                    ijl = int(dnint((xfrma - math.log(frl)) / C.DXNU)) + C.NFRS1
                    d0 = abs((C.FREQ[ijl] - frl) / (C.FREQ[ijl] - C.FREQ[ijl + 1]))
                    if d0 > HALF:
                        while frl > C.FREQ[ijl]:   # DO WHILE
                            ijl = ijl - 1
                        while frl < C.FREQ[ijl]:   # DO WHILE
                            ijl = ijl + 1
                        d1 = frl - C.FREQ[ijl]
                        d2 = C.FREQ[ijl - 1] - frl
                        if d2 < d1:
                            ijl = ijl - 1
                    ij0 = ijl - ijd
                    ij1 = ijl + ijd
                    if ij0 < 1:
                        ij0 = 1
                    if ij1 > C.NFREQ:
                        ij1 = C.NFREQ
                    if ifrku == 0:
                        ifrku = ij0
                    nft = ij1 - ifrku + 1
                    for ij in range(ij0, ij1 + 1):
                        dnu = C.FREQ[ij] - frl
                        for i in range(1, C.JIDN + 1):
                            vv = dnu * float(C.VDOP[k, i])   # dble(VDOP(K,I))
                            prfk = voigte(float(vv), C.AGAM[k, i]) / gsuper
                            sigt[i, ij] = sigt[i, ij] + C.SIG0[k, i] * float(prfk)
                    fcol = fcol + C.SIG0[k, jidc] / C.VDOP[k, jidc]
                # 10 CONTINUE
                C.OSC0[itr] = 0.0
                if indxpa == 3 or indxpa == 4:
                    C.OSC0[itr] = C.STRLX
                if fcol > 0.0:
                    C.OSC0[itr] = fcol / gsuper / CSIG
                if nlt > 0:
                    w1 = CAS / C.FREQ[ifrku]
                    w2 = CAS / C.FREQ[ifrku + nft - 1]
                if nft > 0:
                    C.IFR0[itr] = ifrku
                    C.IFR1[itr] = ifrku + nft - 1
                    C.KFR0[itr] = C.NFTT + 1
                    C.KFR1[itr] = C.NFTT + nft
                    C.NFTT = C.NFTT + nft
                    itrl = itr           # itrl 赋值后未使用（原代码如此）
                    for ij in range(C.IFR0[itr], C.IFR1[itr] + 1):
                        kj = ij - C.IFR0[itr] + C.KFR0[itr]
                        for i in range(1, C.JIDN + 1):
                            sxx = math.log(float(sigt[i, ij]) + 1.0e-40)
                            C.SIGFE[i, kj] = float(sxx)   # real(sxx)：REAL*4 自动转换
                if kj > MCFE:
                    quit(' Too many Fe cross-sect. to store', kj, MCFE)
                # 313 FORMAT(2I4,2F12.3,3I10,1PE12.3)
                write_line(41, f"{il:4d}{iu:4d}{w1:12.3f}{w2:12.3f}{ifrku:10d}"
                               f"{nft:10d}{nlt:10d}{C.OSC0[itr]:12.3E}")
                if nft > nftmx:
                    nftmx = nft
    # 500 CONTINUE
    # WRITE(10,*) 自由格式输出
    write_line(10, f" Max. number of freq. per transition:{nftmx}")
    write_line(10, f" Number of iron line cross-sections: {C.NFTT}")

    ijali2()                   # CALL IJALI2
    return


# ======================================================================

def levcd(ion, iobs):
    """Mean energy and statistical weights of superlevels.
    Read atomic data from Kurucz CD-ROM file (gf*.gam)

    Setup collisional strengths between superlevels, using
     Eissner-Seaton formula for each possible individual
     transition. Assumes Gamma(T)=0.05, and T=Teff
     Contributions from allowed transitions will be superseded
     in routine INKUL.

    对应 tlusty208.f 行 36471–36719（SUBROUTINE LEVCD）
    修改标量哑元 IOBS（IF(IOBS.NE.1 .AND. IOBS.NE.2) IOBS=0）
    → 返回全部标量哑元 (ion, iobs)
    """
    # COMMON/COLKUR/ 标量 GST → C.GST（commons.py 懒分配，跨子程序共享）
    # PARAMETER (BOLCM=1.D8/HK/CAS,CCOR=0.09,SIXTH=UN/6.,GES=0.05)
    BOLCM = 1.0e8 / HK / CAS
    CCOR = 0.09
    SIXTH = UN / 6.0
    GES = 0.05
    # 局部数组 GWE(MDEPTH,MLEVEL,2),GWB(MDEPTH,MLEVEL,2),AA(MDEPTH)
    gwe = np.zeros((MDEPTH + 1, MLEVEL + 1, 3))
    gwb = np.zeros((MDEPTH + 1, MLEVEL + 1, 3))
    aa = np.zeros(MDEPTH + 1)
    # DATA E0FE/E0NI/E0CR（只读）→ 1 基列表
    e0fe = [0.0, 63480.0, 130563.0, 247220.0, 442000.0, 605000.0, 799000.0,
            1008000.0, 1218380.0, 1884000.0, 2114000.0]
    e0ni = [0.0, 61590.0, 146560.0, 283700.0, 443000.0, 613500.0, 871000.0,
            1070000.0, 1310000.0, 1560000.0, 1812000.0]
    e0cr = [0.0, 54576.0, 132966.0, 249700.0, 396500.0, 560200.0, 731020.0,
            1291900.0, 1490000.0, 1688000.0, 1971000.0]

    # Initialization
    if iobs != 1 and iobs != 2:
        iobs = 0
    for i in range(1, C.NEVKU[ion] + 1):
        C.YMKU[i, 1] = 0.0
        C.EMKU[i, 1] = 0.0
        for id in range(1, C.ND + 1):
            gwe[id, i, 1] = 0.0
            gwb[id, i, 1] = 0.0
    for i in range(1, C.NODKU[ion] + 1):
        C.YMKU[i, 2] = 0.0
        C.EMKU[i, 2] = 0.0
        for id in range(1, C.ND + 1):
            gwe[id, i, 2] = 0.0
            gwb[id, i, 2] = 0.0
    nevod = C.NEVKU[ion] + C.NODKU[ion]
    if nevod > 100:
        quit(' Too many superlevels in a single Fe ion', C.NEVKU[ion], C.NODKU[ion])
    for i in range(1, nevod + 1):
        for j in range(1, nevod + 1):
            C.OMES[i, j] = 0.0
    iwsup = C.ifwop[C.NFIRST[ion]]
    if iwsup >= 2:
        for id in range(1, C.ND + 1):
            C.TEMP1[id] = UN / C.TEMP[id]
            aa[id] = CCOR * math.exp(SIXTH * math.log(C.ELEC[id])) / math.sqrt(C.TEMP[id])
        zz = float(C.IZ[ion])
        if C.IZ[ion] > 10:
            quit(' Too high Fe, Ni or Cr ion: ion,iz', ion, C.IZ[ion])
        iat = C.IATM[C.NFIRST[ion]]
        e0 = e0fe[C.IZ[ion]]
        if C.NUMAT[iat] == 28:
            e0 = e0ni[C.IZ[ion]]
        if C.NUMAT[iat] == 24:
            e0 = e0cr[C.IZ[ion]]

    # CD-ROM format: Read energy levels
    iun1 = 31
    open_unit(iun1, C.FIODF1[ion], 'r')  # OPEN(IUN1,FILE=FIODF1(ION),STATUS='OLD')
    _line = read_line(iun1)
    # 170 FORMAT(I7,13X,I6,12X,I6)
    C.NLINKU = _fi(_line[0:7])
    C.KEVE = _fi(_line[20:26])
    C.KODD = _fi(_line[38:44])
    if C.KEVE + C.KODD > 15000:
        quit(' Too many levels in Kurucz file', C.KEVE, C.KODD)

    # Even parity
    for k in range(1, C.KEVE + 1):
        ksl = 0
        _line = read_line(iun1)
        # 171 FORMAT(8X,F4.1,4X,F13.3,18X,3E9.2)
        yj = _ff(_line[8:12])
        e = _ff(_line[16:29])
        ar = _ff(_line[47:56])
        sr = _ff(_line[56:65])
        wr = _ff(_line[65:74])
        gev = TWO * yj + UN
        _goto10 = False
        if e < 0.0:
            e = -e
            if iobs == 0:
                _goto10 = True           # GO TO 10（跳过分类，仍存储）
        if not _goto10:
            if e <= C.XEV[1, ion]:
                ksl = 1
            for i in range(2, C.NEVKU[ion] + 1):
                if e <= C.XEV[i, ion] and e > C.XEV[i - 1, ion]:
                    ksl = i
            if ksl == 0:
                write_line(10, f" Error with even levels {e} {yj}")  # WRITE(10,*)
            C.KKU[k] = ksl
            C.GKU[k] = gev
            C.EKU[k] = e
            C.YMKU[ksl, 1] = C.YMKU[ksl, 1] + gev
            C.EMKU[ksl, 1] = C.EMKU[ksl, 1] + gev * e
            if iwsup == 2:
                ebcm = e / BOLCM
                for id in range(1, C.ND + 1):
                    gwx = gev * math.exp(-ebcm * C.TEMP1[id])
                    gwb[id, ksl, 1] = gwb[id, ksl, 1] + gwx
                    gwe[id, ksl, 1] = gwe[id, ksl, 1] + gwx * e
            elif iwsup == 3:
                ebcm = e / BOLCM
                if e < e0:
                    xn = math.sqrt(e0 / (e0 - e))
                    for id in range(1, C.ND + 1):
                        wid = wn(xn, aa[id], C.ELEC[id], zz)  # 函数 WN
                        gwx = gev * wid * math.exp(-ebcm * C.TEMP1[id])
                        gwb[id, ksl, 1] = gwb[id, ksl, 1] + gwx
                        gwe[id, ksl, 1] = gwe[id, ksl, 1] + gwx * e
                else:
                    for id in range(1, C.ND + 1):
                        wid = UN
                        gwx = gev * wid * math.exp(-ebcm * C.TEMP1[id])
                        gwb[id, ksl, 1] = gwb[id, ksl, 1] + gwx
                        gwe[id, ksl, 1] = gwe[id, ksl, 1] + gwx * e
        # 标号 10
        C.EEV[k] = e
        C.AEV[k] = ar
        C.SEV[k] = sr
        C.WEV[k] = wr
        C.KSEV[k] = ksl
    for i in range(1, C.NEVKU[ion] + 1):
        if C.YMKU[i, 1] == 0.0:
            quit(' No levels in even superlevel', i, i)
        C.EMKU[i, 1] = C.EMKU[i, 1] / C.YMKU[i, 1]

    # Odd parity
    for k in range(1, C.KODD + 1):
        ksl = 0
        _line = read_line(iun1)
        # 171 FORMAT(8X,F4.1,4X,F13.3,18X,3E9.2)
        yj = _ff(_line[8:12])
        e = _ff(_line[16:29])
        ar = _ff(_line[47:56])
        sr = _ff(_line[56:65])
        wr = _ff(_line[65:74])
        god = TWO * yj + UN
        _goto20 = False
        if e < 0.0:
            e = -e
            if iobs == 0:
                _goto20 = True           # GO TO 20（跳过分类，仍存储）
        if not _goto20:
            if e <= C.XOD[1, ion]:
                ksl = 1
            for i in range(2, C.NODKU[ion] + 1):
                if e <= C.XOD[i, ion] and e > C.XOD[i - 1, ion]:
                    ksl = i
            if ksl == 0:
                write_line(10, f" Error with odd levels {e} {yj}")  # WRITE(10,*)
            C.KKU[k + C.KEVE] = ksl + C.NEVKU[ion]
            C.GKU[k + C.KEVE] = god
            C.EKU[k + C.KEVE] = e
            C.YMKU[ksl, 2] = C.YMKU[ksl, 2] + god
            C.EMKU[ksl, 2] = C.EMKU[ksl, 2] + god * e
            if iwsup == 2:
                ebcm = e / BOLCM
                for id in range(1, C.ND + 1):
                    gwx = god * math.exp(-ebcm * C.TEMP1[id])
                    gwb[id, ksl, 2] = gwb[id, ksl, 2] + gwx
                    gwe[id, ksl, 2] = gwe[id, ksl, 2] + gwx * e
            elif iwsup == 3:
                ebcm = e / BOLCM
                if e < e0:
                    xn = math.sqrt(e0 / (e0 - e))
                    for id in range(1, C.ND + 1):
                        wid = wn(xn, aa[id], C.ELEC[id], zz)
                        gwx = god * wid * math.exp(-ebcm * C.TEMP1[id])
                        gwb[id, ksl, 2] = gwb[id, ksl, 2] + gwx
                        gwe[id, ksl, 2] = gwe[id, ksl, 2] + gwx * e
                else:
                    for id in range(1, C.ND + 1):
                        wid = UN
                        gwx = god * wid * math.exp(-ebcm * C.TEMP1[id])
                        gwb[id, ksl, 2] = gwb[id, ksl, 2] + gwx
                        gwe[id, ksl, 2] = gwe[id, ksl, 2] + gwx * e
        # 标号 20
        C.EOD[k] = e
        C.AOD[k] = ar
        C.SOD[k] = sr
        C.WOD[k] = wr
        C.KSOD[k] = ksl
    for i in range(1, C.NODKU[ion] + 1):
        if C.YMKU[i, 2] == 0.0:
            quit(' No levels in odd superlevel', i, i)
        C.EMKU[i, 2] = C.EMKU[i, 2] / C.YMKU[i, 2]
    close_unit(iun1)               # CLOSE(IUN1)

    # Collisional strengths of transitions between super-levels
    #  Eissner-Seaton formula (Gamma=0.05)
    C.GST = 8.63e-6 * GES / math.sqrt(C.TEFF)
    tk0 = UN / BOLCM / C.TEFF
    for i in range(1, C.KEVE + C.KODD):          # 1..KEVE+KODD-1
        ki = C.KKU[i]
        for j in range(i + 1, C.KEVE + C.KODD + 1):
            kj = C.KKU[j]
            u0 = abs(C.EKU[i] - C.EKU[j]) * tk0
            C.OMES[ki, kj] = C.OMES[ki, kj] + C.GST * math.exp(-u0)
            C.OMES[kj, ki] = C.OMES[ki, kj]

    # Sort superlevel energies
    C.NLEVKU = C.NEVKU[ion] + C.NODKU[ion]
    for i in range(1, C.NEVKU[ion] + 1):
        C.EU[i] = C.EMKU[i, 1]
    for i in range(1, C.NODKU[ion] + 1):
        C.EU[i + C.NEVKU[ion]] = C.EMKU[i, 2]
    indexx(C.NLEVKU, C.EU, C.JEN)  # CALL INDEXX：不修改标量哑元 N

    # Superlevel generalized occupation probabilities
    if iwsup >= 2:
        for i in range(1, C.NLEVKU + 1):
            ii = C.NFIRST[ion] + i - 1
            jj = C.JEN[i]
            jk = 1
            if jj > C.NEVKU[ion]:
                jj = C.JEN[i] - C.NEVKU[ion]
                jk = 2
            for id in range(1, C.ND + 1):
                esup = gwe[id, jj, jk] / gwb[id, jj, jk]
                wsup = math.exp(esup / BOLCM * C.TEMP1[id]) / C.YMKU[jj, jk]
                C.wop[ii, id] = wsup * gwb[id, jj, jk]

    # 170 FORMAT(I7,13X,I6,12X,I6)
    # 171 FORMAT(8X,F4.1,4X,F13.3,18X,3E9.2)
    return ion, iobs


# ======================================================================

def inkul(ion, iobs):
    """Read line list from Kurucz CD-ROM files  (gf*.lin)

    INPUT:  Unit 18
              WMIN : Min. wavelength (lines at smaller wave are NOT selected)
              WMAX : Max. wavelength (lines at larger wave are NOT selected)
              IOBS : Type of selected lines

    OUTPUT:  fill up common/lined/
    *******
          -  WAVE     : wavelength in ANGSTROMS
          -  SIG0     : 0.02654/sqrt(pi)*gf/VDOP (divided by g(super) later)
          -  VDOP     : Doppler width
          -  AGAM     : Damping parameter

    对应 tlusty208.f 行 36725–36892（SUBROUTINE INKUL）
    不修改标量哑元 → 无返回
    """
    # PARAMETER 语句
    TEN = 10.0
    TENLG = 2.302585093
    GES = 0.05
    BOL2 = 2.76108e-16
    BOLCM = 1.0e8 / HK / CAS
    CSTK = 3.54
    PSTK = 2.0 / 3.0
    TSTK = UN / 6.0
    CVDW = 3.74                  # 声明但未使用（原代码如此）
    PVDW = 0.4                   # 同上
    TVDW = 0.3                   # 同上
    PI4V = 0.25 / 3.141592654
    CSIG = 0.0149736
    EXPIA1 = -0.57721566
    EXPIA2 = 0.99999193
    EXPIA3 = -0.24991055
    EXPIA4 = 0.05519968
    EXPIA5 = -0.00976004
    EXPIA6 = 0.00107857
    EXPIB1 = 0.2677734343
    EXPIB2 = 8.6347608925
    EXPIB3 = 18.059016973
    EXPIB4 = 8.5733287401
    EXPIC1 = 3.9584969228
    EXPIC2 = 21.0996530827
    EXPIC3 = 25.6329561486
    EXPIC4 = 9.5733223454
    # DATA E0FE/E0NI/E0CR（只读）→ 1 基列表
    e0fe = [0.0, 63480.0, 130563.0, 247220.0, 442000.0, 605000.0, 799000.0,
            1008000.0, 1218380.0, 1884000.0, 2114000.0]
    e0ni = [0.0, 61590.0, 146560.0, 283700.0, 443000.0, 613500.0, 871000.0,
            1070000.0, 1310000.0, 1560000.0, 1812000.0]
    e0cr = [0.0, 54576.0, 132966.0, 249700.0, 396500.0, 560200.0, 731020.0,
            1291900.0, 1490000.0, 1688000.0, 1971000.0]
    # 局部数组 VT0(MDEPTH),GT0(MDEPTH)
    vt0 = np.zeros(MDEPTH + 1)
    gt0 = np.zeros(MDEPTH + 1)

    iat = C.IATM[C.NFIRST[ion]]
    e0 = e0fe[C.IZ[ion]]
    if C.NUMAT[iat] == 28:
        e0 = e0ni[C.IZ[ion]]
    if C.NUMAT[iat] == 24:
        e0 = e0cr[C.IZ[ion]]
    cdop = BOL2 / C.AMASS[iat]
    tk35 = UN / BOLCM / C.TEMP[C.JIDR[2]]
    cvr = 19.7363 / C.TEMP[C.JIDR[2]] / math.sqrt(C.TEMP[C.JIDR[2]])
    if C.JIDN > 3:
        tk35 = UN / BOLCM / C.TEFF
        cvr = 19.7363 / C.TEFF / math.sqrt(C.TEFF)
    tk357 = tk35 * 1.0e7

    xion = 0.0
    for k in range(1, C.JIDN + 1):
        xioni = 0.0
        xiati = 0.0
        id = C.JIDR[k]
        for i in range(C.NFIRST[ion], C.NLAST[ion] + 1):
            xioni = xioni + C.POPUL[i, id]
        for i in range(C.N0A[iat], C.NKA[iat] + 1):
            xiati = xiati + C.POPUL[i, id]
        xionk = xioni / xiati
        if xionk > xion:
            xion = xionk
        vt0[id] = 1.0e-8 / math.sqrt(cdop * C.TEMP[id] + C.VTURBS[id] * C.VTURBS[id])
        gt0[id] = TSTK * math.log10(C.TEMP[id])

    C.NLINKU = 0
    wmin = CAS / C.FRS1 / TEN
    wmax = CAS / C.FRS2 / TEN
    iun2 = 32
    open_unit(iun2, C.FIODF2[ion], 'r')  # OPEN(IUN2,FILE=FIODF2(ION),STATUS='OLD')
    while True:                    # 标号 10：逐行读线表（末尾 GO TO 10）
        try:
            _line = read_line(iun2)      # READ(IUN2,180,ERR=20,END=20)
        except EOFError:
            break                    # END=20 → 标号 20
        # 180 FORMAT(F11.4,F7.3,2I4,I1)
        try:
            wa = _ff(_line[0:11])
            gfr = _ff(_line[11:18])
            jevr = _fi(_line[18:22])
            jodr = _fi(_line[22:26])
            ifpli = _fi(_line[26:27])
        except ValueError:
            break                    # ERR=20 → 标号 20
        gf = math.exp(TENLG * gfr)
        # GO TO 11（WA 越界）→ 跳过线选择但仍执行标号 11 的碰撞强度部分
        if not (wa > wmax or wa < wmin):
            if iobs == 0 and ifpli == 1:
                continue             # GO TO 10
            if iobs == 2 and C.EOD[jodr] > e0:
                continue             # GO TO 10
            if iobs == 2 and C.EEV[jevr] > e0:
                continue             # GO TO 10
            e00 = C.EEV[jevr]
            if C.EOD[jodr] < C.EEV[jevr]:
                e00 = C.EOD[jodr]
            xlstr = xion * gf * math.exp(-e00 * tk35)
            if C.JIDN > 3:
                xlstr = xion * gf * math.exp(-e00 * 8.0 / e0)
            if xlstr < C.STRLX:
                continue             # GO TO 10
            C.NLINKU = C.NLINKU + 1
            C.WAVE[C.NLINKU] = wa * TEN
            C.JTR[C.NLINKU, 1] = jevr
            C.JTR[C.NLINKU, 2] = jodr
            gr = C.AEV[jevr] + C.AOD[jodr]
            c4 = C.SEV[jevr]
            c4p = C.SOD[jodr]
            smx = max(abs(c4p - c4), min(abs(c4), abs(c4p)))
            gslog0 = CSTK + PSTK * math.log10(smx)
            for i in range(1, C.JIDN + 1):
                id = C.JIDR[i]
                C.VDOP[C.NLINKU, i] = C.WAVE[C.NLINKU] * vt0[id]      # real(...)
                gs = math.exp(TENLG * (gslog0 + gt0[id]))
                C.AGAM[C.NLINKU, i] = (gr + gs * C.ELEC[id]) * PI4V * C.VDOP[C.NLINKU, i]
                C.SIG0[C.NLINKU, i] = CSIG * gf * C.VDOP[C.NLINKU, i]

        # 标号 11：允许跃迁对碰撞强度的贡献（Eissner 公式相关项）
        ka = C.KKU[jevr]
        kb = C.KKU[jodr + C.KEVE]
        if ka <= kb:
            k1 = ka
            k2 = kb
        else:
            k1 = kb
            k2 = ka
        if k1 == k2:
            continue                 # GO TO 10
        u0 = tk357 / wa
        if u0 <= UN:
            expiu0 = -math.log(u0) + EXPIA1 + u0 * (EXPIA2 + u0 * (EXPIA3 + u0 *
                     (EXPIA4 + u0 * (EXPIA5 + u0 * EXPIA6))))
        else:
            expiu0 = math.exp(-u0) * ((EXPIB1 + u0 * (EXPIB2 + u0 * (EXPIB3 +
                     u0 * (EXPIB4 + u0)))) / (EXPIC1 + u0 * (EXPIC2 +
                     u0 * (EXPIC3 + u0 * (EXPIC4 + u0))))) / u0
        gb = 0.276 * math.exp(u0) * expiu0
        if gb < 0.25:
            gb = 0.25
        C.OMES[k1, k2] = C.OMES[k1, k2] + (cvr / u0 * gf * gb - C.GST) * math.exp(-u0)
        # GO TO 10 → 循环末尾自然继续
    # 标号 20
    close_unit(iun2)               # CLOSE(IUN2)
    # 600 FORMAT(' Ion',2I3,' : ',I9,' Lines included')
    write_line(10, f" Ion{C.NUMAT[iat]:3d}{C.IZ[ion]:3d} : {C.NLINKU:9d} Lines included")

    # Store collisional excitation strengths
    C.NLEVKU = C.NEVKU[ion] + C.NODKU[ion]
    for i in range(1, C.NLEVKU):             # 1..NLEVKU-1
        ii = C.NFIRST[ion] + i - 1
        i1 = C.JEN[i]
        if i1 <= C.NEVKU[ion]:
            gsup = C.YMKU[i1, 1]
        else:
            gsup = C.YMKU[i1 - C.NEVKU[ion], 2]
        for j in range(i + 1, C.NLEVKU + 1):
            jj = C.NFIRST[ion] + j - 1
            j1 = C.JEN[j]
            it = C.ITRA[ii, jj]
            c2 = C.CPAR[it]
            C.OMECOL[ii, jj] = C.OMES[i1, j1] / gsup * c2 / GES
            C.OMECOL[jj, ii] = C.OMECOL[ii, jj]
    return


# ======================================================================

def opacfl(ij):
    """Absorption, emission, and scattering coefficients
    at frequency IJ and for all depths

    Input: IJ   opacity and emissivity is calculated for the
                frequency points with index IJ
    Output: ABSO1 -  array of absorption coefficient
            EMIS1 -  array of emission coefficient
            SCAT1 -  array of scattering coefficient (all scattering
                      mechanisms except electron scattering)

    对应 tlusty208.f 行 36900–37179（SUBROUTINE OPACFL）
    """
    C14 = 2.99793e14             # PARAMETER (C14=2.99793D14, CFF1=1.3727D-25)
    CFF1 = 1.3727e-25            # 声明但未使用（原代码如此）
    # 输出哑元的占位初值（DWNFR1/SGMER1 只写不读；Fortran 传入值未定义）
    dw1 = 0.0
    sgme1 = 0.0

    # initialize
    for id in range(1, C.ND + 1):
        C.ABSO1[id] = C.ELSCAT[id]
        C.EMIS1[id] = 0.0
        C.SCAT1[id] = C.ELSCAT[id]
        C.ABSO1L[id] = 0.0
        C.EMIS1L[id] = 0.0

    # basic frequency- and depth-dependent quantities
    fr = C.FREQ[ij]
    frinv = UN / fr
    fr3inv = frinv * frinv * frinv
    for id in range(1, C.ND + 1):
        C.XKF[id] = math.exp(-C.HKT1[id] * fr)
        C.XKF1[id] = UN - C.XKF[id]
        C.XKFB[id] = C.XKF[id] * C.BNUE[ij]
    lfre = fr > C.frtabm

    # ********  1a. bound-free contribution - without dielectronic rec.
    if C.IFDIEL == 0:
        for ibft in range(1, C.NTRANC + 1):
            itr = C.ITRBF[ibft]
            sg = cross(ibft, ij)           # CROSS 为函数
            ii = C.ILOW[itr]
            jj = C.IUP[itr]                # JJ 赋值后未使用（原代码如此）
            idp = C.iadop[C.IATM[ii]]
            if sg > 0 and (idp == 0 or (idp > 0 and lfre)):
                izz = C.IZ[C.IEL[ii]]
                imer = C.IMRG[ii]
                for id in range(1, C.ND + 1):
                    sgd = sg
                    if C.MCDW[itr] > 0:
                        # DWNFR1 修改标量哑元 DW1 → 返回全部标量哑元
                        fr, _fr0, id, izz, dw1 = dwnfr1(fr, C.FR0[itr], id, izz, dw1)
                        C.DWF1[C.MCDW[itr], id] = dw1
                        sgd = sg * dw1
                    if C.ifwop[ii] < 0:
                        # SGMER1 修改标量哑元 SGME1 → 返回全部标量哑元
                        frinv, fr3inv, imer, id, sgme1 = sgmer1(frinv, fr3inv,
                                                                imer, id, sgme1)
                        C.SGMG[imer, id] = sgme1
                        sgd = sgme1
                    emisbf = sgd * C.EMTRA[itr, id]
                    C.ABSO1[id] = C.ABSO1[id] + sgd * C.ABTRA[itr, id]
                    C.EMIS1[id] = C.EMIS1[id] + emisbf
                    if C.ILUCTR[itr] > 0:
                        C.ABSO1L[id] = C.ABSO1L[id] + sgd * C.ABTRA[itr, id]
                        C.EMIS1L[id] = C.EMIS1L[id] + emisbf
    else:
        # ********  1. bound-free contribution - with dielectronic rec.
        for ibft in range(1, C.NTRANC + 1):
            itr = C.ITRBF[ibft]
            sg = cross(ibft, ij)
            ii = C.ILOW[itr]
            jj = C.IUP[itr]
            idp = C.iadop[C.IATM[ii]]
            if sg > 0 and (idp == 0 or (idp > 0 and lfre)):
                izz = C.IZ[C.IEL[ii]]
                imer = C.IMRG[ii]
                for id in range(1, C.ND + 1):
                    sg = crossd(ibft, ij, id)  # CROSSD 为函数；注意此处覆盖 SG
                    if sg > 0.0:
                        sgd = sg
                        if C.MCDW[itr] > 0:
                            fr, _fr0, id, izz, dw1 = dwnfr1(fr, C.FR0[itr], id, izz, dw1)
                            C.DWF1[C.MCDW[itr], id] = dw1
                            sgd = sg * dw1
                        if C.ifwop[ii] < 0:
                            frinv, fr3inv, imer, id, sgme1 = sgmer1(frinv, fr3inv,
                                                                    imer, id, sgme1)
                            C.SGMG[imer, id] = sgme1
                            sgd = sgme1
                        emisbf = sgd * C.EMTRA[itr, id]
                        C.ABSO1[id] = C.ABSO1[id] + sgd * C.ABTRA[itr, id]
                        C.EMIS1[id] = C.EMIS1[id] + emisbf
                        if C.ILUCTR[itr] == 0:
                            C.ABSO1L[id] = C.ABSO1L[id] + sgd * C.ABTRA[itr, id]
                            C.EMIS1L[id] = C.EMIS1L[id] + emisbf

    # ******** 2. free-free contribution
    for ion in range(1, C.NION + 1):       # DO 40
        it = C.ITRA[C.NNEXT[ion], C.NNEXT[ion]]
        idp = C.iadop[C.IATM[C.NNEXT[ion]]]
        if idp > 0 and not lfre:
            continue                       # GO TO 40
        if it == 1:
            # hydrogenic with Gaunt factor = 1
            for id in range(1, C.ND + 1):
                sf1 = C.SFF3[ion, id] * fr3inv
                sf2 = C.SFF2[ion, id]
                if fr < C.FF[ion]:
                    sf2 = UN / C.XKF[id]
                absoff = sf1 * sf2
                C.ABSO1[id] = C.ABSO1[id] + absoff
                C.EMIS1[id] = C.EMIS1[id] + absoff
        elif it == 2:
            # hydrogenic with exact Gaunt factor
            for id in range(1, C.ND + 1):
                sf1 = C.SFF3[ion, id] * fr3inv
                sf2 = C.SFF2[ion, id]
                if fr < C.FF[ion]:
                    sf2 = UN / C.XKF[id]
                x = C14 * C.CHARG2[ion] / fr
                sf2 = sf2 - UN + gfree1(id, x)   # 函数 GFREE1
                absoff = sf1 * sf2
                C.ABSO1[id] = C.ABSO1[id] + absoff
                C.EMIS1[id] = C.EMIS1[id] + absoff
        elif it == 3:
            # H minus free-free opacity
            for id in range(1, C.ND + 1):
                absoff = sffhmi(C.POPUL[C.NFIRST[C.IELH], id], fr, C.TEMP[id]) * \
                    C.ELEC[id]                   # 函数 SFFHMI
                C.ABSO1[id] = C.ABSO1[id] + absoff
                C.EMIS1[id] = C.EMIS1[id] + absoff
        elif it < 0:
            # special evaluation of the cross-section
            for id in range(1, C.ND + 1):
                absoff = ffcros(ion, it, C.TEMP[id], fr) * \
                    C.POPUL[C.NNEXT[ion], id] * C.ELEC[id]   # 函数 FFCROS
                C.ABSO1[id] = C.ABSO1[id] + absoff
                C.EMIS1[id] = C.EMIS1[id] + absoff
    # 40 CONTINUE

    # ********  3. - additional continuum opacity (OPADD)
    if C.IOPADD != 0:
        icall = 1
        for id in range(1, C.ND + 1):
            opadd(0, icall, ij, id)        # OPADD 不修改标量哑元；输出经 COMMON/OPACAD/
            C.ABSO1[id] = C.ABSO1[id] + C.ABAD
            C.EMIS1[id] = C.EMIS1[id] + C.EMAD
            C.SCAT1[id] = C.SCAT1[id] + C.SCAD

    # ********  4. - opacity and emissivity in lines
    if C.ISPODF == 0:
        if C.IJLIN[ij] > 0:
            # the "primary" line at the given frequency
            itr = C.IJLIN[ij]
            iad = C.iadop[C.IATM[C.ILOW[itr]]]
            if iad == 0 or (lfre and iad > 0):
                for id in range(1, C.ND + 1):
                    sg = C.PRFLIN[id, ij]
                    C.ABSO1[id] = C.ABSO1[id] + sg * C.ABTRA[itr, id]
                    C.EMIS1[id] = C.EMIS1[id] + sg * C.EMTRA[itr, id]
            if C.ILUCTR[itr] > 0:
                for id in range(1, C.ND + 1):
                    sg = C.PRFLIN[id, ij]
                    C.ABSO1L[id] = C.ABSO1L[id] + sg * C.ABTRA[itr, id]
                    C.EMIS1L[id] = C.EMIS1L[id] + sg * C.EMTRA[itr, id]
        # IF(NLINES(IJ).LE.0) GO TO 200
        if C.NLINES[ij] > 0:
            # the "overlapping" lines at the given frequency
            for ilint in range(1, C.NLINES[ij] + 1):   # DO 100
                itr = C.ITRLIN[ilint, ij]
                iad = C.iadop[C.IATM[C.ILOW[itr]]]
                if iad > 0 and not lfre:
                    continue               # GO TO 100
                if C.LINEXP[itr]:
                    continue               # GO TO 100
                ij0 = C.IFR0[itr]
                for ijt in range(ij0, C.IFR1[itr] + 1):
                    if C.FREQ[ijt] <= fr:
                        ij0 = ijt
                        break              # GO TO 70
                # 标号 70
                ij1 = ij0 - 1
                a1 = (fr - C.FREQ[ij0]) / (C.FREQ[ij1] - C.FREQ[ij0])
                a2 = UN - a1
                for id in range(1, C.ND + 1):
                    sg = a1 * C.PRFLIN[id, ij1] + a2 * C.PRFLIN[id, ij0]
                    C.ABSO1[id] = C.ABSO1[id] + sg * C.ABTRA[itr, id]
                    C.EMIS1[id] = C.EMIS1[id] + sg * C.EMTRA[itr, id]
            # 100 CONTINUE
        # 200 CONTINUE
    else:
        # Opacity sampling option
        # IF(NLINES(IJ).LE.0) GO TO 400
        if C.NLINES[ij] > 0:
            for ilint in range(1, C.NLINES[ij] + 1):   # DO 300
                itr = C.ITRLIN[ilint, ij]
                iad = C.iadop[C.IATM[C.ILOW[itr]]]
                if iad > 0 and not lfre:
                    continue               # GO TO 300
                # IF(LINEXP(ITR)) GO TO 300 —— 原代码已注释掉
                # IF(IJ.LT.IFR0(ITR) .OR. IJ.GT.IFR1(ITR)) GO TO 300 —— 已注释掉
                kj = ij - C.IFR0[itr] + C.KFR0[itr]
                indxpa = abs(C.INDEXP[itr])
                if indxpa != 3 and indxpa != 4:
                    for id in range(1, C.ND + 1):
                        sg = C.PRFLIN[id, kj]
                        C.ABSO1[id] = C.ABSO1[id] + sg * C.ABTRA[itr, id]
                        C.EMIS1[id] = C.EMIS1[id] + sg * C.EMTRA[itr, id]
                else:
                    for id in range(1, C.ND + 1):
                        kjd = C.JIDI[id]
                        sg = math.exp(C.XJID[id] * C.SIGFE[kjd, kj] +
                                      (UN - C.XJID[id]) * C.SIGFE[kjd + 1, kj])
                        C.ABSO1[id] = C.ABSO1[id] + sg * C.ABTRA[itr, id]
                        C.EMIS1[id] = C.EMIS1[id] + sg * C.EMTRA[itr, id]
            # 300 CONTINUE
        # 400 CONTINUE

    # ----------------------------
    # total opacity and emissivity
    # ----------------------------
    for id in range(1, C.ND + 1):
        C.ABSO1[id] = C.ABSO1[id] - C.EMIS1[id] * C.XKF[id]
        C.EMIS1[id] = C.EMIS1[id] * C.XKFB[id]
        C.ABSO1L[id] = C.ABSO1L[id] - C.EMIS1L[id] * C.XKF[id]
        C.EMIS1L[id] = C.EMIS1L[id] * C.XKFB[id]
        C.ABSO1L[id] = C.ABSO1[id] - C.ABSO1L[id]
        C.EMIS1L[id] = C.EMIS1[id] - C.EMIS1L[id]
    return


