def rdatax(itr, ic, iunit):
    """for itr, itrx ne 0 - read input data for an individual transition
    and prepare necessary auxiliary arrays

    对应 tlusty208.f 行 37185–37304（subroutine rdatax）
    修改标量哑元 IC（itr=0 与 itr<0 分支中 ic=icx(itx)）
    → 返回全部标量哑元 (itr, ic, iunit)
    局部数组/计数器依赖 Fortran 静态存储 → 模块级 _rdatax_*（见文件头）
    """
    global _rdatax_itrx, _rdatax_ntrx
    # 局部数组 a(11,5), b(5)
    a = np.zeros((12, 6))
    b = np.zeros(6)

    if itr > 0:
        _rdatax_itrx = _rdatax_itrx + 1
        _rdatax_ntrx = _rdatax_itrx
        ii = C.ILOW[itr]
        ie = C.IEL[ii]
        jj = C.IUP[itr]
        _rdatax_iex[_rdatax_itrx] = ie
        _rdatax_icx[_rdatax_itrx] = ic
        _rdatax_itrind[_rdatax_itrx] = itr
        _rdatax_izx0[_rdatax_itrx] = C.IZ[ie]
        _rdatax_izx1[_rdatax_itrx] = jj - 1000

        # read inner-shell photoionization data from Omer's tables
        # read(iunit,*) 自由格式
        _rdatax_etx[_rdatax_itrx] = float(read_line(iunit).split()[0])
        _l = read_line(iunit).split()
        _rdatax_nmaxx[_rdatax_itrx] = int(_l[0])
        _rdatax_izx[_rdatax_itrx] = int(_l[1])
        _rdatax_nshx[_rdatax_itrx] = int(_l[2])
        _rdatax_ssx[_rdatax_itrx] = float(read_line(iunit).split()[0])
        _rdatax_nax[_rdatax_itrx] = int(read_line(iunit).split()[0])
        _rdatax_dx[_rdatax_itrx] = float(read_line(iunit).split()[0])
        for i in range(1, _rdatax_nax[_rdatax_itrx] + 1):
            _rdatax_bphx[i, _rdatax_itrx] = float(read_line(iunit).split()[0])
        for j in range(1, _rdatax_nax[_rdatax_itrx] + 1):
            for i in range(1, 12):
                _rdatax_aphx[i, j, _rdatax_itrx] = float(read_line(iunit).split()[0])
    elif itr == 0:
        # for itr=0 - set up array BFCS with actual cross-sections
        if _rdatax_ntrx > 0:
            for itx in range(1, _rdatax_ntrx + 1):
                ie = _rdatax_iex[itx]
                it = _rdatax_itrind[itx]
                ii = C.ILOW[it]
                ia = C.IATM[ii]
                iz1 = _rdatax_izx1[itx]
                ic = _rdatax_icx[itx]
                jj = 0
                for i in range(1, C.NLEVEL + 1):
                    if C.IATM[i] == ia:
                        if C.IZ[C.IEL[i]] == iz1:
                            jj = i
                            break          # GO TO 10
                # 标号 10
                if jj == 0:
                    if iz1 == C.IZ[C.IEL[C.NKA[ia] - 1]] + 1:
                        jj = C.NKA[ia]
                if jj == 0:
                    C.INDEXP[it] = 0

                if C.INDEXP[it] != 0:
                    C.IUP[it] = jj
                    C.FR0[it] = _rdatax_etx[itx] / 4.1357e-15
                    C.LINE[it] = False
                    C.ITRCON[it] = ic
                    if C.ICOL[it] != 99:
                        C.ITRA[ii, jj] = it
                        C.ITRA[jj, ii] = ic

                    # 601 format(8i4,1pe12.4,0pf10.2)
                    print(f"{itx:4d}{it:4d}{ii:4d}{jj:4d}{ia:4d}"
                          f"{C.ITRA[ii, jj]:4d}{C.ITRA[jj, ii]:4d}"
                          f"{C.ICOL[it]:4d}{C.FR0[it]:12.4E}{_rdatax_etx[itx]:10.2f}")
    else:
        nfreqb = C.NFREQ
        if C.IBFINT > 0:
            nfreqb = C.NFREQC
        if _rdatax_ntrx > 0:
            for itx in range(1, _rdatax_ntrx + 1):
                it = _rdatax_itrind[itx]
                ic = _rdatax_icx[itx]
                if C.INDEXP[it] != 0:
                    na = _rdatax_nax[itx]
                    for i in range(1, na + 1):
                        b[i] = _rdatax_bphx[i, itx]
                    for j in range(1, na + 1):
                        for i in range(1, 12):
                            a[i, j] = _rdatax_aphx[i, j, itx]

                    for ij in range(1, nfreqb + 1):
                        # bkhsgo 修改标量哑元 sg → 返回全部标量哑元
                        # （末实参 0.0 为输出哑元 sg 的占位初值，Fortran 传入值未定义）
                        _fq, _et, _d, na, _ss, _nmx, _iz, _nsh, sg = bkhsgo(
                            C.FREQ[ij], _rdatax_etx[itx], _rdatax_dx[itx], b, na, a,
                            _rdatax_ssx[itx], _rdatax_nmaxx[itx], _rdatax_izx[itx],
                            _rdatax_nshx[itx], 0.0)
                        C.BFCS[ic, ij] = sg      # real(sg)：BFCS 为 REAL*4
                    # 681 format(4i5,1p1e15.5)
                    write_line(97, f"{it:5d}{ic:5d}{C.ILOW[it]:5d}{C.IUP[it]:5d}"
                                   f"{C.BFCS[ic, 1]:15.5E}")
    return itr, ic, iunit


