def expo(x):
    """指数函数（带钳位）。

    对应 tlusty208.f 行 37868–37877（function expo）
    函数值为 exp(x)，x 钳位到 [-80,80]；
    因经引用传递修改标量哑元 x → 返回 (函数值, x)
    """
    crit = 80.0
    if x < -crit:
        x = -crit
    if x > crit:
        x = crit
    return math.exp(x), x


# ======================================================================

def irc(n, t, ic, rno, se):
    """IRC CALCULATES THE EXCITATION RATE, SE [cm**3/s], FOR IONIZATION
    OF HYDROGEN ATOMS FROM STATE N DUE TO ELECTRON COLLISIONS, ASSUMING
    THE CONTINUUM STARTS AT LEVEL RNO.
    REF. JOHNSON (1972)

    a modification of Tim Kallman's XSTAR routine

    对应 tlusty208.f 行 37884–37931（SUBROUTINE IRC）
    修改标量哑元 SE → 返回全部标量哑元 (n, t, ic, rno, se)
    """
    if ic != 1:                          # MAB
        # CALL SZIRC(N,T,IC,rno,SE)：SZIRC 修改标量哑元 cii → 解包接收
        n, t, ic, rno, se = szirc(n, t, ic, rno, se)
        return n, t, ic, rno, se

    xo = 1.0 - n * n / rno / rno
    yn = xo * 157803.0 / (t * n * n)
    if n <= 1:
        an = 1.9603 * n * (1.133 / 3.0 / xo ** 3 - 0.4059 / 4.0 / xo ** 4 +
                           0.07014 / 5.0 / xo ** 5)
        bn = 2.0 / 3.0 * n * n / xo * (3.0 + 2.0 / xo - 0.603 / xo / xo)
        rn = 0.45
    elif n == 2:
        an = 1.9603 * n * (1.0785 / 3.0 / xo ** 3 - 0.2319 / 4.0 / xo ** 4 +
                           0.02947 / 5.0 / xo ** 5)
        bn = (4.0 - 18.63 / n + 36.24 / (n * n) - 28.09 / (n * n * n)) / n
        bn = 2.0 / 3.0 * n * n / xo * (3.0 + 2.0 / xo + bn / xo / xo)
        rn = 0.653
    else:
        g0 = (0.9935 + 0.2328 / n - 0.1296 / (n * n)) / 3.0 / xo ** 3
        g1 = -(0.6282 - 0.5598 / n + 0.5299 / (n * n)) / (n * 4.0) / xo ** 4
        g2 = (0.3887 - 1.181 / n + 1.470 / (n * n)) / (n * n * 5.0) / xo ** 5
        an = 1.9603 * n * (g0 + g1 + g2)
        bn = (4.0 - 18.63 / n + 36.24 / (n * n) - 28.09 / (n * n * n)) / n
        bn = (3.0 + 2.0 / xo + bn / xo / xo) * 2.0 * n * n / 3.0 / xo
        rn = 1.94 * n ** (-1.57)

    rn = rn * xo
    zn = rn + yn
    # CALL EXPINX(YN,EY)：EXPINX 修改标量哑元 em1 → 解包接收；
    # 第二实参 0.0 为输出哑元 EY 的占位初值（Fortran 传入值未定义）
    yn, ey = expinx(yn, 0.0)
    zn, ez = expinx(zn, 0.0)             # CALL EXPINX(ZN,EZ)
    se = an * (ey / yn / yn - math.exp(-rn) * ez / zn / zn)
    ey = 1.0 + 1.0 / yn - ey * (2.0 / yn + 1.0)
    ez = math.exp(-rn) * (1.0 + 1.0 / zn - ez * (2.0 / zn + 1.0))
    se = se + (bn - an * math.log(2.0 * n * n / xo)) * (ey - ez)
    se = se * math.sqrt(t) * yn * yn * n * n * 1.095e-10 / xo
    return n, t, ic, rno, se


# ======================================================================

def szirc(nn, t, ic, rno, cii):
    """calculates electron impact ionizition rates from semiempirical
    formula (eq.35) from Sampson & Zhang (1988, ApJ 335, 516)

    a modification of Tim Kallman's XSTAR routine

    对应 tlusty208.f 行 37938–37978（subroutine szirc）
    修改标量哑元 cii → 返回全部标量哑元 (nn, t, ic, rno, cii)
    """
    # DATA(abethe(i),i=1,11)/... 等（只读）→ 1 基列表
    # TODO(port): Fortran 声明为 real（REAL*4）abethe/hbethe/rbethe，
    # 此处按双精度存储，相对原单精度存储末位可能有微小差异
    abethe = [0.0, 1.134, 0.603, 0.412, 0.313, 0.252,
              0.211, 0.181, 0.159, 0.142, 0.128, 1.307]
    hbethe = [0.0, 1.48, 3.64, 5.93, 8.32, 10.75, 12.9,
              15.05, 17.2, 19.35, 21.5, 2.15]
    rbethe = [0.0, 2.2, 1.9, 1.73, 1.65, 1.6, 1.56,
              1.54, 1.52, 1.52, 1.52, 1.52]
    rz = float(ic)
    boltz = 1.38066e-16
    eion = 2.179874e-11
    const = 4.6513e-3

    rc = float(int(rno))
    if nn < 11:
        an = abethe[nn]
        hn = hbethe[nn]
        rrn = rbethe[nn]
    else:
        an = abethe[11] / float(nn)
        hn = hbethe[11] * float(nn)
        rrn = rbethe[11]
    tt = t * boltz
    rn = float(nn)
    yy = rz * rz * eion / tt * (1.0 / rn / rn - 1.0 / rc / rc - 0.25 *
        (1.0 / (rc - 1.0) ** 2 - 1.0 / rc / rc))
    # call eint(yy,e1,e2,e3)：eint 修改标量哑元 → 解包接收（占位初值 0.0）
    yy, e1, e2, e3 = eint(yy, 0.0, 0.0, 0.0)
    cii = const * math.sqrt(tt) * (rn ** 5) / (rz ** 4) * an * yy * (
        e1 / rn - (math.exp(-yy) - yy * e3) / (3.0 * rn) +
        (yy * e2 - 2.0 * yy * e1 + math.exp(-yy)) *
        3.0 * hn / rn / (3.0 - rrn) + (e1 - e2) * 3.36 * yy)
    return nn, t, ic, rno, cii


# ======================================================================

def expinx(x, em1):
    """expinx is a subroutine to calculate the value of e1, the exponential
    integral or em1=x*expo(x)*e1 at the point x.  the polynomial
    expressions that are used come from abromowitz and stegen

    a modification of Tim Kallman's XSTAR routine

    对应 tlusty208.f 行 37984–38021（subroutine expinx）
    修改标量哑元 em1（且 x 经 expo 引用传递可能被钳位）→ 返回 (x, em1)
    """
    if x > 1.0:
        b1 = 9.5733223454
        b2 = 25.6329561486
        b3 = 21.0996530827
        b4 = 3.9584969228
        c1 = 8.5733287401
        c2 = 18.0590169730
        c3 = 8.6347608925
        c4 = 0.2677737343
        em1 = x ** 4 + c1 * x ** 3 + c2 * x * x + c3 * x + c4
        em1 = em1 / (x ** 4 + b1 * x * x * x + b2 * x * x + b3 * x + b4)
    else:
        a0 = -0.57721566
        a1 = 0.99999193
        a2 = -0.24991055
        a3 = 0.05519968
        a4 = -0.00976004
        a5 = 0.00107857
        if x > 0:
            e1 = a0 + a1 * x + a2 * x * x + a3 * x ** 3 + a4 * x ** 4 + \
                a5 * x ** 5 - math.log(x)
        else:
            e1 = -a0 + a1 * x + a2 * x * x + a3 * x ** 3 + a4 * x ** 4 + \
                a5 * x ** 5 - math.log(-x)
        # Fortran 引用传递：expo(x) 内部会把 x 钳位到 [-80,80]
        # TODO(port): 原式 em1=e1*x*expo(x) 中 e1*x 与 expo(x) 的求值顺序
        # Fortran 标准未定义；此处按先调用 expo（钳位 x）再相乘处理
        _ex, x = expo(x)
        em1 = e1 * x * _ex
    return x, em1


# ======================================================================

def eint(t, e1, e2, e3):
    """returns the values of the exponential integral function of order
    1, 2, and 3

    a modification of Tim Kallman's XSTAR routine

    对应 tlusty208.f 行 38026–38043（subroutine eint）
    修改标量哑元 e1,e2,e3（且 t 经 expo 引用传递可能被钳位）
    → 返回全部标量哑元 (t, e1, e2, e3)
    """
    e1 = 0.0
    e2 = 0.0
    e3 = 0.0
    t, ss = expinx(t, 0.0)   # call expinx(t,ss)：ss 为输出哑元（占位初值 0.0）
    # Fortran 引用传递：expo(t) 内部会把 t 钳位到 [-80,80]；
    # TODO(port): 原式 e1=ss/t/expo(t) 中 ss/t 与 expo(t) 求值顺序未定义，
    # 此处按先调用 expo（钳位 t）再计算处理；其后 e2/e3 使用钳位后的 t
    _ex, t = expo(t)
    e1 = ss / t / _ex
    e2 = math.exp(-t) - t * e1
    e3 = 0.5 * (expo(-t)[0] - t * e2)   # expo(-t)：实参为表达式 → 取 [0]
    return t, e1, e2, e3


# ======================================================================

def comset():
    """sets up necessary parameters for treating the Compton scattering

    对应 tlusty208.f 行 38051–38214（SUBROUTINE COMSET）
    """
    XCON = 8.0935e-21            # parameter (xcon=8.0935d-21,YCON=1.68638E-10)
    YCON = 1.68638e-10
    T15 = 1.0e-15                # parameter (t15=1.d-15)
    # 局部数组 freqi(mfreq), PL(MDEPTH), PLM(MDEPTH)
    freqi = np.zeros(MFREQ + 1)
    pl = np.zeros(MDEPTH + 1)
    plm = np.zeros(MDEPTH + 1)
    # common/auxcbc/、common/comgfs/ 声明在本体内未使用（变量在 commons.py：C.cden1m 等）

    # if(icompt.le.0) go to 100
    if C.icompt > 0:
        C.nmuc = 3
        C.nsti = 0
        C.nedd = 3

        # frequency-dependent universal parameters
        for ij in range(1, C.NFREQ + 1):
            C.CDER10[ij] = 0.0
            C.CDER1P[ij] = 0.0
            C.CDER1M[ij] = 0.0
            C.CDER20[ij] = 0.0
            C.CDER2P[ij] = 0.0
            C.CDER2M[ij] = 0.0
            iji = C.NFREQ - C.KIJ[ij] + 1
            C.ijorig[iji] = ij
            freqi[iji] = C.FREQ[ij]
            fr = freqi[iji]
            C.BNUS[iji] = TWO * XCON * fr / (BN * (fr * 1.0e-15) ** 3)

        ij = 1
        C.DLNFR[ij] = math.log(freqi[ij + 1] / freqi[ij])
        for ij in range(2, C.NFREQ):       # 2..nfreq-1
            C.DLNFR[ij] = math.log(freqi[ij + 1] / freqi[ij])
            delp = C.DLNFR[ij]
            delm = C.DLNFR[ij - 1]
            del0 = delp + delm
            cd0 = TWO / del0
            C.CDER2M[ij] = cd0 / delm
            C.CDER2P[ij] = cd0 / delp
            C.CDER20[ij] = -C.CDER2M[ij] - C.CDER2P[ij]

        for ij in range(1, C.NFREQ):       # 1..nfreq-1
            frj0 = freqi[ij]
            frjp = freqi[ij + 1]
            frz = math.sqrt(frj0 * frjp)
            for id in range(1, C.ND + 1):
                # to avoid over/underflow problems:
                if HK * frj0 / C.TEMP[id] < 200.0:
                    fjb0 = UN / (math.exp(HK * frj0 / C.TEMP[id]) - UN)
                else:
                    fjb0 = 0.0
                if HK * frjp / C.TEMP[id] < 200.0:
                    fjbp = UN / (math.exp(HK * frjp / C.TEMP[id]) - UN)
                else:
                    fjbp = 0.0
                fjz0 = fjb0 * (BN * (frj0 * T15) ** 3)
                fjzp = fjbp * (BN * (frjp * T15) ** 3)
                if C.ichcoo == 0:
                    zj0 = HK * frz / C.TEMP[id]
                    dfjz = fjz0 - fjzp
                    dfjb = fjb0 - fjbp
                    fzz = UN + fjbp - 3.0 / zj0
                    aa = dfjz * dfjb
                    bb = dfjz * fzz + fjzp * dfjb
                    cc = fjzp * fzz - dfjz / C.DLNFR[ij] / zj0
                else:
                    e2 = YCON * C.TEMP[id]
                    zxxp = XCON * frjp * (UN + fjbp) - 3.0 * e2
                    zxx0 = XCON * frj0 * (UN + fjb0) - 3.0 * e2
                    dzxx = zxx0 - zxxp
                    dfjb = fjb0 - fjbp
                    dfjz = fjz0 - fjzp
                    aa = dfjz * dzxx
                    bb = dfjz * zxxp + fjzp * dzxx
                    cc = fjzp * zxxp - e2 * dfjz / C.DLNFR[ij]
                # XXX  to avoid division by zero:
                if abs(aa) == 0 and abs(bb) == 0.0:
                    xx1 = 0.0
                elif abs(aa) < 1.0e-7 * abs(bb):
                    xx1 = -cc / bb
                else:
                    dd = bb * bb - 4.0 * aa * cc
                    if dd < 0.0:
                        dd = 0.0
                    dd = math.sqrt(dd)
                    xx1 = (dd - bb) * HALF / aa
                    if C.ichcoo > 0:
                        xx2 = -(dd + bb) * HALF / aa
                        dxx1 = abs(xx1 - HALF)
                        dxx2 = abs(xx2 - HALF)
                        if dxx2 < dxx1:
                            xx1 = xx2
                        if xx1 > 1.0 or xx1 < 0.0:
                            xx1 = HALF
                C.DELJ[ij, id] = xx1

        # angle-dependent universal parameters
        angset()                   # call angset

    # 标号 100：frequency-dependent universal parameters（总是执行）
    for ij in range(1, C.NFREQ + 1):
        # first-order expression
        if C.knish == 0:
            C.SIGEC[ij] = SIGE * (UN - TWO * C.FREQ[ij] * XCON)
        # Use full Klein-Nishina cross section (Rybicki & Lightman 1975):
        else:
            xf = XCON * C.FREQ[ij]
            if xf < 1.0e-1:
                C.SIGEC[ij] = SIGE * (1.0 - xf * (2.0 - xf * (26.0 / 5.0 - xf *
                    (13.3 - xf * (1144.0 / 35.0 - xf * (544.0 / 7.0 - xf *
                    (3784.0 / 21.0 - xf * (6148.0 / 15.0 - xf * (151552.0 / 165.0 -
                    xf * 111872.0 / 55.0)))))))))
            elif xf > 1.0e3:
                C.SIGEC[ij] = SIGE * 3.0 / 8.0 / xf * (math.log(2.0 * xf) + 0.5)
            else:
                C.SIGEC[ij] = SIGE * 0.75 * ((1.0 + xf) / xf ** 3 *
                    (2.0 * xf * (1.0 + xf) / (1.0 + 2.0 * xf) -
                     math.log(1.0 + 2.0 * xf)) +
                    0.5 * math.log(1.0 + 2.0 * xf) / xf -
                    (1.0 + 3.0 * xf) / (1.0 + 2.0 * xf) ** 2)

    if C.icompt <= 0:
        return
    ij = 1
    ijo = C.ijorig[ij]
    for id in range(1, C.ND + 1):
        plm[id] = C.BNUE[ijo] / (math.exp(HK / C.TEMP[id] * C.FREQ[ijo]) - UN)

    for ij in range(2, C.NFREQ + 1):
        ijo = C.ijorig[ij]
        for id in range(1, C.ND + 1):
            # to avoid over/underflow problems:
            if HK / C.TEMP[id] * C.FREQ[ijo] < 200.0:
                pl[id] = C.BNUE[ijo] / (math.exp(HK / C.TEMP[id] * C.FREQ[ijo]) - UN)
            else:
                pl[id] = plm[id]
            plm[id] = pl[id]
    return


# ======================================================================

def angset():
    """sets up angles points and angle-dependent quantities for treating
    the Compton scattering

    对应 tlusty208.f 行 38221–38264（subroutine angset）
    """
    THREE = 3.0                  # parameter(three=3.d0, five=5.d0, zero=0.d0, tr16=3.d0/16.d0)
    FIVE = 5.0
    ZERO = 0.0
    TR16 = 3.0 / 16.0
    # 局部数组 amu0(mmuc), wtmu0(mmuc)
    amu0 = np.zeros(MMUC + 1)
    wtmu0 = np.zeros(MMUC + 1)

    # amu=cos(angle between line of sight and normal to slab) grid and
    # gauss-legendre integration weights for the interval mu=[0,1]
    gauleg(ZERO, UN, amu0, wtmu0, C.nmuc, MMUC)  # GAULEG 不修改标量哑元

    for i in range(1, C.nmuc + 1):
        C.amuc[i] = -amu0[C.nmuc - i + 1]
        C.amuc[i + C.nmuc] = amu0[i]
        C.wtmuc[i] = wtmu0[C.nmuc - i + 1]
        C.wtmuc[i + C.nmuc] = wtmu0[i]
    C.nmuc = 2 * C.nmuc

    for i in range(1, C.nmuc + 1):
        C.amuc1[i] = C.amuc[i] * C.wtmuc[i]
        C.amuc2[i] = C.amuc[i] * C.amuc[i] * C.wtmuc[i]
        C.amuc3[i] = C.amuc[i] * C.amuc[i] * C.amuc[i] * C.wtmuc[i]
        a1 = C.amuc[i]
        a2 = a1 * a1
        a3 = a1 * a2
        for i1 in range(1, C.nmuc + 1):
            b1 = C.amuc[i1]
            b2 = b1 * b1
            b3 = b1 * b2
            trw = TR16 * C.wtmuc[i1]
            C.calph[i, i1] = (THREE * a2 * b2 - a2 - b2 + THREE) * trw
            C.cbeta[i, i1] = (FIVE * (a1 * b1 + a3 * b3) -
                              THREE * (a3 * b1 + a1 * b3)) * trw
            C.cgamm[i, i1] = a1 * b1 * trw
    return


# ======================================================================

def gauleg(x1, x2, x, w, n, m):
    """set up angle points

    对应 tlusty208.f 行 38272–38305（SUBROUTINE GAULEG）
    不修改标量哑元（X1,X2,N,M 只读；X,W 数组就地修改）→ 无返回
    """
    # PARAMETER (EPS=3.D-14,half=0.5d0,pi=3.141592654d0,quart=0.25,un=,two=)
    EPS = 3.0e-14
    pi = 3.141592654
    quart = 0.25
    # half/un/two 与 params 常量 HALF/UN/TWO 等值，直接用后者

    n2 = idiv(n + 1, 2)          # (N+1)/2 整数除法
    xm = HALF * (x2 + x1)
    xl = HALF * (x2 - x1)
    for i in range(1, n2 + 1):
        z = math.cos(pi * (i - quart) / (n + HALF))
        while True:              # 标号 1：牛顿迭代求 Legendre 零点
            p1 = 1.0
            p2 = 0.0
            for j in range(1, n + 1):
                p3 = p2
                p2 = p1
                p1 = ((TWO * j - UN) * z * p2 - (j - UN) * p3) / j
            pp = n * (z * p1 - p2) / (z * z - UN)
            z1 = z
            z = z1 - p1 / pp
            if abs(z - z1) <= EPS:
                break            # 否则 GO TO 1
        x[i] = xm - xl * z
        x[n + 1 - i] = xm + xl * z
        w[i] = TWO * xl / ((UN - z * z) * pp * pp)
        w[n + 1 - i] = w[i]
    return


# ======================================================================

def rte_sc(dtau, st0, rup, rdown, amu0, ri, ali):
    """formal solver of the radiative transfer equation
    for one frequency, angle, and for completely known source function;
    using short characteristics

    input:    dtau - optical depth increments Delta tau
              st0  - total source function
              rup  - intensity at the upper boundary (id=1)
              rdown- intensity at the lower boundary (id=nd)
              amu0 - cosine of angle of propagation (wrt. the normal)
    output:   ri   - radiation intensity

    对应 tlusty208.f 行 38312–38364（subroutine rte_sc）
    不修改标量哑元 → 无返回
    """
    # 局部数组 dtx1/dtx2/dtx0(mdepth)
    dtx1 = np.zeros(MDEPTH + 1)
    dtx2 = np.zeros(MDEPTH + 1)
    dtx0 = np.zeros(MDEPTH + 1)

    for id in range(1, C.ND):            # 1..nd-1
        dtx1[id] = math.exp(-dtau[id])
        dtx2[id] = (UN - dtx1[id]) / dtau[id]
        dtx0[id] = UN - dtx2[id]

    # incoming intensity
    if amu0 < 0:
        id = 1
        ri[id] = rup
        for id in range(1, C.ND):        # 1..nd-1
            ri[id + 1] = ri[id] * dtx1[id] + st0[id] * (dtx2[id] - dtx1[id]) + \
                st0[id + 1] * dtx0[id]
            ali[id + 1] = dtx0[id]
        ali[1] = 0.0
    # outgoing intensity
    else:
        ri[C.ND] = rdown
        for id in range(C.ND - 1, 0, -1):    # nd-1..1
            ri[id] = ri[id + 1] * dtx1[id] + st0[id] * dtx0[id] + \
                st0[id + 1] * (dtx2[id] - dtx1[id])
            ali[id] = dtx0[id]
        ali[C.ND] = 0.0
    return


# ======================================================================

def rtesol(dtau, st0, rup, rdown, amu0, ri, ali):
    """formal solver of the radiative transfer equation
    for one frequency, angle, and for completely known source function;
    by the Discontinuous Finite Element method
    Castor, Dykema, Klein, 1992, ApJ 387, 561.

    对应 tlusty208.f 行 38371–38457（subroutine rtesol）
    不修改标量哑元 → 无返回
    """
    ONE = 1.0                    # parameter (one=1.d0)
    # 局部数组 rim/rip/aim/aip(mdepth)
    rim = np.zeros(MDEPTH + 1)
    rip = np.zeros(MDEPTH + 1)
    aim = np.zeros(MDEPTH + 1)
    aip = np.zeros(MDEPTH + 1)

    # incoming intensity
    if amu0 < 0:
        id = 1
        rip[id] = rup
        dt0 = dtau[id]
        dtaup1 = dt0 + ONE
        dtau2 = dt0 * dt0
        bb = TWO * dtaup1
        cc = dt0 * dtaup1
        aa = dtau2 + bb
        rim[id] = (aa * rip[id] - cc * st0[id] + dt0 * st0[id + 1]) / bb
        for id in range(1, C.ND):        # 1..nd-1
            dt0 = dtau[id]
            dtaup1 = dt0 + ONE
            dtau2 = dt0 * dt0
            bb = TWO * dtaup1
            cc = dt0 * dtaup1
            aa = dtau2 + bb
            rim[id + 1] = (TWO * rim[id] + dt0 * st0[id] + cc * st0[id + 1]) / aa
            rip[id] = (bb * rim[id] + cc * st0[id] - dt0 * st0[id + 1]) / aa
            aim[id + 1] = cc / aa
            aip[id] = (cc + bb * aim[id]) / aa
        for id in range(2, C.ND):        # 2..nd-1
            dtt = UN / (dtau[id - 1] + dtau[id])
            ri[id] = (rim[id] * dtau[id] + rip[id] * dtau[id - 1]) * dtt
            ali[id] = (aim[id] * dtau[id] + aip[id] * dtau[id - 1]) * dtt
        ri[1] = rip[1]
        ri[C.ND] = rim[C.ND]
        ali[1] = aim[1]
        ali[C.ND] = aim[C.ND]
    # outgoing intensity
    else:
        rip[C.ND] = rdown
        id = C.ND - 1
        dt0 = dtau[id]
        dtaup1 = dt0 + ONE
        dtau2 = dt0 * dt0
        bb = TWO * dtaup1
        cc = dt0 * dtaup1
        aa = dtau2 + bb
        rim[id + 1] = (aa * rip[id + 1] - cc * st0[id + 1] + dt0 * st0[id]) / bb
        for id in range(C.ND - 1, 0, -1):    # nd-1..1
            dt0 = dtau[id]
            dtaup1 = dt0 + ONE
            dtau2 = dt0 * dt0
            bb = TWO * dtaup1
            cc = dt0 * dtaup1
            aa = dtau2 + bb
            rim[id] = (TWO * rim[id + 1] + dt0 * st0[id + 1] + cc * st0[id]) / aa
            rip[id + 1] = (bb * rim[id + 1] + cc * st0[id + 1] - dt0 * st0[id]) / aa
            aim[id] = cc / aa
            aip[id + 1] = (cc + bb * aim[id + 1]) / aa
        for id in range(2, C.ND):        # 2..nd-1
            dtt = UN / (dtau[id - 1] + dtau[id])
            ri[id] = (rim[id] * dtau[id - 1] + rip[id] * dtau[id]) * dtt
            ali[id] = (aim[id] * dtau[id - 1] + aip[id] * dtau[id]) * dtt
        ri[1] = rim[1]
        ri[C.ND] = rip[C.ND]
        ali[1] = aim[1]
        ali[C.ND] = aim[C.ND]
    return


# ======================================================================

def rtefe2(dtau, s, rup, rdown, ri):
    """formal solver of the radiative transfer equation
    for one frequency, angle, and for completely known source function;
    original Feautrier (second-order) scheme

    对应 tlusty208.f 行 38463–38537（subroutine rtefe2）
    不修改标量哑元 → 无返回
    """
    ONE = 1.0                    # parameter (one=1.d0)
    # 局部数组 a/b/c/d/f/v/z(mdepth)
    a = np.zeros(MDEPTH + 1)
    b = np.zeros(MDEPTH + 1)
    c = np.zeros(MDEPTH + 1)
    d = np.zeros(MDEPTH + 1)
    f = np.zeros(MDEPTH + 1)
    v = np.zeros(MDEPTH + 1)
    z = np.zeros(MDEPTH + 1)

    # set up the global tridiagonal matrix

    # upper boundary condition
    id = 1
    cc = TWO / dtau[id]
    c[id] = cc / dtau[id]
    b[id] = ONE + cc + c[id]
    a[id] = 0.0
    v[id] = s[id] + cc * rup

    # normal depth points
    for id in range(2, C.ND):            # 2..nd-1
        dtinv = TWO / (dtau[id - 1] + dtau[id])
        a[id] = dtinv / dtau[id - 1]
        c[id] = dtinv / dtau[id]
        b[id] = ONE + a[id] + c[id]
        v[id] = s[id]

    # lower boundary condition
    id = C.ND
    aa = TWO / dtau[id - 1]
    a[id] = aa / dtau[id - 1]
    b[id] = ONE + aa + a[id]
    if rdown == 0.0:
        b[id] = ONE + a[id]
    c[id] = 0.0
    v[id] = s[id] + aa * rdown

    # ---------------------------------------------------
    # solution by elimination
    # 1. forward sweep
    f[1] = (b[1] - c[1]) / c[1]
    d[1] = ONE / (ONE + f[1])
    z[1] = v[1] / b[1]

    # ii) normal depth points
    for id in range(2, C.ND):            # 2..nd-1
        f[id] = (b[id] - a[id] - c[id] + a[id] * f[id - 1] * d[id - 1]) / c[id]
        d[id] = ONE / (ONE + f[id])
        z[id] = (v[id] + a[id] * z[id - 1]) * d[id] / c[id]

    # iii) upper boundary（原文注释如此，实为下边界 id=nd）
    id = C.ND
    z[id] = (v[id] + a[id] * z[id - 1]) / (b[id] - a[id] * d[id - 1])

    # 2. backward elimination
    ri[C.ND] = z[C.ND]
    for id in range(C.ND - 1, 0, -1):    # nd-1..1
        ri[id] = ri[id + 1] * d[id] + z[id]
    return


