#   /moldat/  moltab, irwtab
#   /RYBMTX/  RA(MDEPTH), RB(MDEPTH), RC(MDEPTH), VR(MDEPTH), UA(MDEPTH),
#             UB(MDEPTH), UC(MDEPTH), VA(MDEPTH), VB(MDEPTH), VC(MDEPTH),
#             WR(MDEPTH), WM(MDEPTH,MDEPTH)
#   /imodlc/  imodl0(mlevel)
# 注意：/COMFH1/ 的 C(600,5) 与 commons.py 中已有的 ARRAY1.FOR 无名 COMMON
# "C"(MTOT,MTOT) 重名冲突，本片改用 C.COMFH1_C 访问（见 moleq/russel 内注释）。


# ----------------------------------------------------------------------
# DATA 且隐含 SAVE 的局部变量（会被修改或在调用间保持）提升为模块级
_save_rhoeos_inirea = 0                      # RHOEOS: DATA inirea /0/
_save_moleq_iread = 1                        # moleq:  DATA iread /1/
_save_mpartf_iread = 0                       # mpartf: DATA iread /0/
_save_mpartf_a = np.zeros((7, 4, 93))        # mpartf: SAVE a(6,3,92)
_save_mpartf_am = np.zeros((7, 601))         # mpartf: SAVE am(6,600)
# TODO(port): mpartf 的 irw(600) 不在 SAVE 列表中，但只在首次调用（iread）
# 时赋值、后续调用仍使用——Fortran 静态存储语义，这里按 SAVE 处理
_save_mpartf_irw = np.zeros(601, dtype=np.int64)


def tabini():
    """
    Initialization and reading of the opacity table for thermal processe
    and Rayleigh scattering
    raytab: scattering opacities in cm^2/gm at 5.0872638d14 Hz (sodium D)
    (NOTE: Quantities in rayleigh.tab are in log_e)

    tempvec: array of temperatures
    rhomat: array of densities (gm/cm^3)
    nu:     array of frequencies
    table:  absorptive opacities in cm^2/gm
    (NOTE:  Quantities in absorption.tab are in log_e)

    对应 tlusty208.f 行 44456–44781
    """
    # parameter (mtabto=100,mtabro=100)
    mtabto = 100
    mtabro = 100
    # common/intcff/yint(mfreq),jint(mfreq)   —— 本例程声明但未使用（见文件头说明）
    # common/abntab/...  common/eletab/elecgr(mtabt,mtabr)
    # CHARACTER(len=100) :: DUM
    # real*4 absopa0；dimension 局部数组（1 基索引，维数 +1）
    frlt = np.zeros(MFRTAB + 1)                       # dimension frlt(mfrtab)
    absopa0 = np.zeros((mtabto + 1, mtabro + 1), dtype=np.float32)
    indt = np.zeros(mtabto + 1, dtype=np.int64)
    indr = np.zeros(mtabro + 1, dtype=np.int64)
    tempve0 = np.zeros(101)                           # dimension tempve0(100)
    rhove0 = np.zeros((101, 101))                     # rhove0(100,100)
    elecg0 = np.zeros((101, 101))                     # elecg0(100,100)
    rhov = np.zeros(MTABR + 1)                        # rhov(mtabr)
    nden = np.zeros(MTABT + 1, dtype=np.int64)        # nden(mtabt)
    typa = np.empty(MATOM + 1, dtype=object)          # character*4 typa(matom)
    typa[...] = ''
    optable = ''                                      # character*(80) optable

    def _read53(n):
        """模拟 list-directed READ(53,*) 读 n 个值（可跨行累积；
        行内多余令牌丢弃，与 Fortran 每次 READ 换新记录一致）。"""
        vals = []
        while len(vals) < n:
            vals.extend(read_line(53).replace(',', ' ').split())
        return vals[:n]

    def _uread53(nbytes):
        """读一条 Fortran 无格式顺序记录（ibinop≠0 分支）。
        TODO(port): 假设 4 字节记录标记、默认 INTEGER*4/REAL*4/REAL*8
        布局，与生成该文件的编译器/平台相关。"""
        fh = funits[53]
        fh.read(4)                  # 记录头标记
        data = fh.read(nbytes)
        fh.read(4)                  # 记录尾标记
        if len(data) < nbytes:
            raise EOFError('unit 53: short unformatted record')
        return data

    istept = 1
    istepr = 1
    istepf = 1

    # read(15,*,err=10,end=10) optable,ibinop
    _rdok = True
    try:
        _tok = read_line(15).replace(',', ' ').split()
        optable = _tok[0]
        C.ibinop = int(_tok[1])
    except (EOFError, IndexError, ValueError):
        _rdok = False                       # err=10 / end=10 → 转向标号 10
    # GO TO 20（读成功时跳过标号 10）
    if not _rdok:
        # 标号 10
        optable = './data/absopac.dat'
        # TODO(port): 读失败时 ibinop 在原文中保持原值（未定义则为零初始化）
    # 标号 20
    if C.ibinop == 0:
        # open(53,file=optable,status='old')
        open_unit(53, optable, 'r')
    else:
        # open(53,file=optable,form='unformatted',status='old')
        open_unit(53, optable, 'rb')

    # read(15,*,err=30,end=30) istept,istepr,istepf
    try:
        _tok = read_line(15).replace(',', ' ').split()
        istept = int(_tok[0])
        istepr = int(_tok[1])
        istepf = int(_tok[2])
    except (EOFError, IndexError, ValueError):
        pass                                # err=30 / end=30 → 保持默认值
    # 标号 30

    # 601 format(/' '/' OPACITY TABLE:  READ FROM THE FILE ',a70/' IBINOP=',i2/
    #      ' --------------'/)
    print()
    print(' ')
    print(' OPACITY TABLE:  READ FROM THE FILE ' + '%-70s' % optable[:70])
    print(' IBINOP=%2d' % C.ibinop)
    print(' --------------')
    print()
    if istept > 1 or istepr > 1 or istepf > 1:
        print(' BUT ONLY SELECTED DATA USED')
        print()

    # reading the opacity table in the old mode
    if C.IOPTAB < 0 and C.IOPOLD > 0:
        if C.ibinop == 0:
            numfre0, numtem0, numrh0 = (int(x) for x in _read53(3))
            read_line(53)                   # read(53,*)
            _v = _read53(numtem0)
            for i in range(1, numtem0 + 1):
                tempve0[i] = float(_v[i - 1])
            read_line(53)                   # read(53,*)
            _v = _read53(numrh0)
            for j in range(1, numrh0 + 1):
                rhove0[1, j] = float(_v[j - 1])
        else:
            _a = np.frombuffer(_uread53(12), dtype=np.int32)
            numfre0, numtem0, numrh0 = int(_a[0]), int(_a[1]), int(_a[2])
            _a = np.frombuffer(_uread53(8 * numtem0), dtype=np.float64)
            for i in range(1, numtem0 + 1):
                tempve0[i] = float(_a[i - 1])
            _a = np.frombuffer(_uread53(8 * numrh0), dtype=np.float64)
            for j in range(1, numrh0 + 1):
                rhove0[1, j] = float(_a[j - 1])

    # reading the opacity table in the new  mode
    else:
        io2hmt = 0                          # 原文局部变量 io2hmt（未在任何 COMMON 中）
        C.ih2h2t = 0
        C.ih2het = 0
        C.ioh2ht = 0
        C.iohhet = 0
        if C.ibinop == 0:
            read_line(53)                   # read(53,*)
            read_line(53)                   # read(53,*)
            for iat in range(1, MATOM + 1):
                # read(53,'(a100)') dum
                dum = read_line(53)[:100]
                # read(dum,*,iostat=kst) typa(iat),abunt(iat),abuno(iat)
                try:
                    _t = dum.replace(',', ' ').split()
                    typa[iat] = _t[0][:4]
                    C.abunt[iat] = float(_t[1])
                    C.abuno[iat] = float(_t[2])
                    kst = 0
                except (IndexError, ValueError):
                    kst = 1
                if kst != 0:
                    break                   # GO TO 40
            else:
                read_line(53)               # read(53,*) —— 循环正常结束才执行
            # 标号 40
            read_line(53)                   # read(53,*)
            _v = _read53(2)                 # read(53,*) ifmolt,tmolit
            C.ifmolt = int(_v[0])
            C.tmolit = float(_v[1])
            read_line(53)                   # read(53,*)
            read_line(53)                   # read(53,*)
            # read(53,'(a100)') dum
            dum = read_line(53)[:100]
            # read(dum,*,iostat=kst) iophmt,ioph2t,iophet,iopcht,iopoht,
            #      ioh2mt,ih2h2t,ih2het,ioh2ht,iohhet
            try:
                _t = dum.replace(',', ' ').split()
                C.iophmt = int(_t[0])
                C.ioph2t = int(_t[1])
                C.iophet = int(_t[2])
                C.iopcht = int(_t[3])
                C.iopoht = int(_t[4])
                C.ioh2mt = int(_t[5])
                C.ih2h2t = int(_t[6])
                C.ih2het = int(_t[7])
                C.ioh2ht = int(_t[8])
                C.iohhet = int(_t[9])
                kst = 0
            except (IndexError, ValueError):
                kst = 1
            if kst != 0:
                # read(dum,*) iophmt,ioph2t,iophet,iopcht,iopoht
                try:
                    _t = dum.replace(',', ' ').split()
                    C.iophmt = int(_t[0])
                    C.ioph2t = int(_t[1])
                    C.iophet = int(_t[2])
                    C.iopcht = int(_t[3])
                    C.iopoht = int(_t[4])
                except (IndexError, ValueError):
                    pass    # TODO(port): 原文此处无 iostat，出错会运行时终止
            read_line(53)                   # read(53,*)
            read_line(53)                   # read(53,*)
            numfre0, numtem0, numrh0 = (int(x) for x in _read53(3))
            if numrh0 > 0:
                read_line(53)               # read(53,*)
                _v = _read53(numtem0)
                for i in range(1, numtem0 + 1):
                    tempve0[i] = float(_v[i - 1])
                read_line(53)               # read(53,*)
                _v = _read53(numrh0)
                for j in range(1, numrh0 + 1):
                    rhov[j] = float(_v[j - 1])
                nden[1] = numrh0
                for j in range(1, numrh0 + 1):
                    for i in range(1, numtem0 + 1):
                        rhove0[i, j] = rhov[j]
                for i in range(1, numtem0 + 1):
                    nden[i] = nden[1]
                read_line(53)               # read(53,*)
                # read(53,*) ((elecg0(i,j),j=1,numrh0),i=1,numtem0)
                _v = _read53(numtem0 * numrh0)
                _n = 0
                for i in range(1, numtem0 + 1):
                    for j in range(1, numrh0 + 1):
                        elecg0[i, j] = float(_v[_n])
                        _n += 1
            else:
                _v = _read53(numtem0)
                for i in range(1, numtem0 + 1):
                    nden[i] = int(_v[i - 1])
                read_line(53)               # read(53,*)
                _v = _read53(numtem0)
                for i in range(1, numtem0 + 1):
                    tempve0[i] = float(_v[i - 1])
                read_line(53)               # read(53,*)
                for i in range(1, numtem0 + 1):
                    _v = _read53(nden[i])
                    for j in range(1, nden[i] + 1):
                        rhove0[i, j] = float(_v[j - 1])
                read_line(53)               # read(53,*)
                for i in range(1, numtem0 + 1):
                    _v = _read53(nden[i])
                    for j in range(1, nden[i] + 1):
                        elecg0[i, j] = float(_v[j - 1])
        else:
            for iat in range(1, 93):
                # read(53) typa(iat),abunt(iat),abuno(iat)
                _rec = _uread53(20)         # char*4 + real*8 + real*8
                typa[iat] = _rec[0:4].decode('ascii', 'replace')
                C.abunt[iat] = float(np.frombuffer(_rec[4:12], dtype=np.float64)[0])
                C.abuno[iat] = float(np.frombuffer(_rec[12:20], dtype=np.float64)[0])
            _rec = _uread53(12)             # read(53) ifmolt,tmolit
            C.ifmolt = int(np.frombuffer(_rec[0:4], dtype=np.int32)[0])
            C.tmolit = float(np.frombuffer(_rec[4:12], dtype=np.float64)[0])
            _a = np.frombuffer(_uread53(40), dtype=np.int32)   # 10 个整型
            C.iophmt = int(_a[0])
            C.ioph2t = int(_a[1])
            C.iophet = int(_a[2])
            C.iopcht = int(_a[3])
            C.iopoht = int(_a[4])
            C.ioh2mt = int(_a[5])
            C.ih2h2t = int(_a[6])
            C.ih2het = int(_a[7])
            C.ioh2ht = int(_a[8])
            C.iohhet = int(_a[9])
            _a = np.frombuffer(_uread53(12), dtype=np.int32)
            numfre0, numtem0, numrh0 = int(_a[0]), int(_a[1]), int(_a[2])
            if numrh0 > 0:
                _a = np.frombuffer(_uread53(8 * numtem0), dtype=np.float64)
                for i in range(1, numtem0 + 1):
                    tempve0[i] = float(_a[i - 1])
                _a = np.frombuffer(_uread53(8 * numrh0), dtype=np.float64)
                for j in range(1, numrh0 + 1):
                    rhov[j] = float(_a[j - 1])
                _a = np.frombuffer(_uread53(8 * numtem0 * numrh0), dtype=np.float64)
                _n = 0
                for i in range(1, numtem0 + 1):
                    for j in range(1, numrh0 + 1):
                        elecg0[i, j] = float(_a[_n])
                        _n += 1
                nden[1] = numrh0
                for j in range(1, numrh0 + 1):
                    for i in range(1, numtem0 + 1):
                        rhove0[i, j] = rhov[j]
                for i in range(1, numtem0 + 1):
                    nden[i] = nden[1]
            else:
                _a = np.frombuffer(_uread53(4 * numtem0), dtype=np.int32)
                for i in range(1, numtem0 + 1):
                    nden[i] = int(_a[i - 1])
                _a = np.frombuffer(_uread53(8 * numtem0), dtype=np.float64)
                for i in range(1, numtem0 + 1):
                    tempve0[i] = float(_a[i - 1])
                for i in range(1, numtem0 + 1):
                    _a = np.frombuffer(_uread53(8 * nden[i]), dtype=np.float64)
                    for j in range(1, nden[i] + 1):
                        rhove0[i, j] = float(_a[j - 1])
                for i in range(1, numtem0 + 1):
                    _a = np.frombuffer(_uread53(8 * nden[i]), dtype=np.float64)
                    for j in range(1, nden[i] + 1):
                        elecg0[i, j] = float(_a[j - 1])

    # select only a part of tabular data (if required)
    j = 0
    nrmax = 0                               # Fortran: nrmax=0.（整型变量，值为 0）
    for it in range(1, numtem0 + 1, istept):
        j = j + 1
        C.tempvec[j] = tempve0[it]
        indt[j] = it
        k = 0                               # Fortran: k=0.
        numr = nden[it]
        nrmax = max(nrmax, numr)
        for ir in range(1, numr + 1, istepr):
            k = k + 1
            C.rhomat[j, k] = rhove0[it, ir]
            indr[k] = ir
            C.elecgr[j, k] = elecg0[it, ir]
        C.numrh[j] = k
    C.numtemp = j
    if numrh0 > 0:
        C.numrho = k                        # k 保留循环最后一次的值
    if C.numtemp > MTABT:
        print('number of temperatures in opac.table too large')
        print('numtemp,mtabt = ', C.numtemp, MTABT)
        print('recompile with MTABT.ge.NUMTEMP in BASICS.FOR')
        raise SystemExit                    # stop

    if nrmax > MTABR:
        print('number of densities in opac,table too large')
        print('numrho,mtabr = ', C.numtemp, MTABR)
        print('recompile with MTABR.ge.NUMRHO in BASICS.FOR')
        raise SystemExit                    # stop

    ij = 0
    for k in range(1, numfre0 + 1):
        if imod(k, istepf) == 0:
            ij = ij + 1
    C.numfreq = ij
    if C.numfreq > MFREQC:
        print('number of wavelengths in opac.table too large')
        print('numfreq,mfreqc = ', C.numfreq, MFREQC)
        print('recompile with MFREQC.ge.NUMFREQ in BASICS.FOR')
        raise SystemExit                    # stop

    # 602 format(' original number of frequencies, temperatures',
    #      ' densities:  ',3i7/)
    print(' original number of frequencies, temperatures densities:  '
          '%7d%7d%7d' % (numfre0, numtem0, numrh0))
    print()

    if istept > 1 or istepr > 1 or istepf > 1:
        # 603 format(' modified number of frequencies, temperatures',
        #      ' densities:  ',3i7/)
        print(' modified number of frequencies, temperatures densities:  '
              '%7d%7d%7d' % (C.numfreq, C.numtemp, C.numrho))
        print()

    print('temperatures:')
    # 604 format(10f8.1)
    _vals = ['%8.1f' % math.exp(C.tempvec[i]) for i in range(1, C.numtemp + 1)]
    for _i in range(0, len(_vals), 10):
        print(''.join(_vals[_i:_i + 10]))
    print('densities:')
    for i in range(1, C.numtemp + 1):
        numr = C.numrh[i]
        # 605 format('for T=',f7.1,(1p10e10.2))
        # TODO(port): 未模拟 1P 尺度因子；格式组 (1p10e10.2) 超过 10 个时换行
        _s = 'for T=' + '%7.1f' % math.exp(C.tempvec[i])
        _vals = ['%10.2e' % math.exp(C.rhomat[i, j]) for j in range(1, numr + 1)]
        print(_s + ''.join(_vals[:10]))
        for _i in range(10, len(_vals), 10):
            print(''.join(_vals[_i:_i + 10]))

    # check the consistency (or a lack thereof) the parameters of
    # the opacity table
    #
    # if(ioptab.gt.0.or.iopold.eq.0) call chctab   —— 原文已注释，保留注释

    C.RTAB1 = C.rhomat[1, 1]
    C.RTAB2 = C.rhomat[1, C.numrho]
    C.TTAB1 = C.tempvec[1]
    C.TTAB2 = C.tempvec[C.numtemp]

    if C.ibinop == 0:
        ij = 0
        nden0 = numrh0
        for k in range(1, numfre0 + 1):
            read_line(53)                   # read(53,*)
            read_line(53)                   # read(53,*)
            frta = float(_read53(1)[0])     # read(53,*) frta
            if numrh0 > 0:
                for j in range(1, numrh0 + 1):
                    _v = _read53(numtem0)
                    for i in range(1, numtem0 + 1):
                        absopa0[i, j] = float(_v[i - 1])
            else:
                for i in range(1, numtem0 + 1):
                    nden0 = nden[i]
                    _v = _read53(nden0)
                    for j in range(1, nden0 + 1):
                        absopa0[i, j] = float(_v[j - 1])
            if imod(k, istepf) == 0 and frta < C.frtlim:
                ij = ij + 1
                C.frtab[ij] = frta
                frlt[ij] = math.log10(frta)
                for i in range(1, C.numtemp + 1):
                    numr = C.numrh[i]
                    for j in range(1, numr + 1):
                        C.absopac[i, j, ij] = float(absopa0[indt[i], indr[j]])
        C.numfreq = ij
        close_unit(53)
    else:
        ij = 0
        nden0 = numrh0
        for k in range(1, numfre0 + 1):
            # read(53) frta
            frta = float(np.frombuffer(_uread53(8), dtype=np.float64)[0])
            if numrh0 > 0:
                for j in range(1, numrh0 + 1):
                    _a = np.frombuffer(_uread53(4 * numtem0), dtype=np.float32)
                    for i in range(1, numtem0 + 1):
                        absopa0[i, j] = _a[i - 1]
            else:
                for i in range(1, numtem0 + 1):
                    nden0 = nden[i]
                    # read(53,err=11) (absopa0(i,j),j=1,nden0)
                    try:
                        _a = np.frombuffer(_uread53(4 * nden0), dtype=np.float32)
                        for j in range(1, nden0 + 1):
                            absopa0[i, j] = _a[j - 1]
                    except (EOFError, ValueError):
                        pass                # 标号 11：出错则继续
            if imod(k, istepf) == 0 and frta < C.frtlim:
                ij = ij + 1
                C.frtab[ij] = frta
                frlt[ij] = math.log10(frta)
                for i in range(1, C.numtemp + 1):
                    numr = C.numrh[i]
                    for j in range(1, numr + 1):
                        C.absopac[i, j, ij] = float(absopa0[indt[i], indr[j]])
        C.numfreq = ij

        # write(*,*) 'final NUMFREQ, FREQ(1)',numfreq,freq(1)  —— 原文已注释

        k0 = 1
        # TODO(port): 原文若 FRTAB(1) 即 <= 阈值，则 K0 使用前未定义；此处置 1
        for k in range(1, C.numfreq + 1):
            if C.frtab[k] > 2.997925e13:
                k0 = k
            else:
                for i in range(1, C.numtemp + 1):
                    numr = C.numrh[i]
                    for j in range(1, numr + 1):
                        C.absopac[i, j, k] = C.absopac[i, j, k0]
        close_unit(53)

    C.frtabm = max(C.frtab[1], C.frtab[C.numfreq])
    return


def rayini():
    """
    Initialization and reading of the opacity table for thermal processe
    and Rayleigh scattering
    raytab: scattering opacities in cm^2/gm at 5.0872638d14 Hz (sodium D)
    (NOTE: Quantities in rayleigh.tab are in log_e)

    tempvec: array of temperatures
    rhomat: array of densities (gm/cm^3)
    nu:     array of frequencies
    table:  absorptive opacities in cm^2/gm
    (NOTE:  Quantities in absorption.tab are in log_e)

    对应 tlusty208.f 行 44787–44828
    """
    # read Rayleigh scattering opacity table (if needed)
    numfreq2 = C.numfreq
    if C.IFRAYL < 0:
        # open(52,file='./data/rayleigh.tab',status='old')
        open_unit(52, './data/rayleigh.tab', 'r')

        def _read52(n):
            """list-directed READ(52,*) 读 n 个值（可跨行；行内多余令牌丢弃）。"""
            vals = []
            while len(vals) < n:
                vals.extend(read_line(52).replace(',', ' ').split())
            return vals[:n]

        # read(52,*) numfreq2,numtemp,numrho
        _v = _read52(3)
        numfreq2 = int(_v[0])
        C.numtemp = int(_v[1])
        C.numrho = int(_v[2])
        read_line(52)                       # read(52,*)
        _v = _read52(C.numtemp)             # read(52,*) (tempvec(i),i=1,numtemp)
        for i in range(1, C.numtemp + 1):
            C.tempvec[i] = float(_v[i - 1])
        read_line(52)                       # read(52,*)
        # read(52,*) ((rhomat(i,j),j=1,numrho),i=1,numtemp)
        _v = _read52(C.numtemp * C.numrho)
        _n = 0
        for i in range(1, C.numtemp + 1):
            for j in range(1, C.numrho + 1):
                C.rhomat[i, j] = float(_v[_n])
                _n += 1
        read_line(52)                       # read(52,*)
        for j in range(1, C.numrho + 1):
            # read(52,*) (raytab(i,j),i=1,numtemp)
            _v = _read52(C.numtemp)
            for i in range(1, C.numtemp + 1):
                C.raytab[i, j] = float(_v[i - 1])
        close_unit(52)
        # call rayset —— 无哑元，直接调用
        rayset()
    elif C.IFRAYL > 0:
        # call rayleigh(0,0,0,scr)
        # RAYLEIGH 会修改标量哑元 SCR（仅 MODE≠0 分支）；按约定返回全部标量哑元，
        # 实参 0,0,0 为字面量、对应未被修改的 MODE/IJ/ID，用临时名接收
        scr = 0.0                           # 局部变量，先定义（MODE=0 时不被赋值）
        _mode, _ij, _id, scr = rayleigh(0, 0, 0, scr)
    return


def tabint():
    """
    对应 tlusty208.f 行 44834–44922
    （原文无头部注释；功能：频率表与表列不透明度之间的插值设置）
    """
    absort = np.zeros(MFRTAB + 1)           # dimension absort(mfrtab)

    if C.IOPTAB < 0 and C.IFRSET == 0:

        # if frequencies are exactly tabular
        C.NFREQ = C.numfreq
        C.NFREQC = C.numfreq
        for ij in range(1, C.NFREQ + 1):
            C.FREQ[ij] = C.frtab[ij]
            C.IJFR[ij] = ij
            C.JIK[ij] = ij
            C.IJALI[ij] = 1
        C.W[1] = 0.5 * (C.frtab[1] - C.frtab[2])
        C.W[C.NFREQ] = 0.5 * (C.frtab[C.NFREQ - 1] - C.frtab[C.NFREQ])
        for ij in range(2, C.NFREQ - 1 + 1):
            C.W[ij] = 0.5 * (C.frtab[ij - 1] - C.frtab[ij + 1])

    else:

        # if frequencies are already set

        # set up interpolation coefficients for frequency interpolation
        # by bisection
        fr1 = C.frtab[1]
        fr2 = C.frtab[C.numfreq]
        for ij in range(1, C.NFREQ + 1):
            xint = C.FREQ[ij]
            jl = 0
            ju = C.numfreq + 1
            # 标号 10：二分查找（GO TO 10 → while 循环）
            while ju - jl > 1:
                jm = idiv(ju + jl, 2)       # Fortran 整数除法
                if (fr2 > fr1) == (xint > C.frtab[jm]):   # .EQV.
                    jl = jm
                else:
                    ju = jm
            j = jl
            if j == C.numfreq:
                j = j - 1
            if j == 0:
                j = j + 1
            C.jint[ij] = j
            # /intcff/ 的 yint 规范名为 INTCFF_YINT（见 INLINE_COMMONS.md）
            C.INTCFF_YINT[ij] = UN / math.log10(C.frtab[j + 1] / C.frtab[j])

        for it in range(1, C.numtemp + 1):
            C.numrho = C.numrh[it]
            for ir in range(1, C.numrho + 1):
                for k in range(1, C.numfreq + 1):
                    absort[k] = C.absopac[it, ir, k]
                for ij in range(1, C.NFREQ + 1):
                    j = C.jint[ij]
                    rc = (absort[j + 1] - absort[j]) * C.INTCFF_YINT[ij]
                    opac = rc * math.log10(C.FREQ[ij] / C.frtab[j]) + absort[j]
                    C.absopac[it, ir, ij] = opac

        # reset tabular opacities to zero out of range of FREQ
        for ij in range(1, C.NFREQ + 1):
            if C.FREQ[ij] < fr2 * 0.99 or C.FREQ[ij] > fr1 * 1.01:
                for it in range(1, C.numtemp + 1):
                    C.numrho = C.numrh[it]
                    for ir in range(1, C.numrho + 1):
                        C.absopac[it, ir, ij] = 0.0

    return


