def rayset():
    """
    set up a table of Rayleigh scattering opacity

    对应 tlusty208.f 行 45105–45172
    """
    for id in range(1, C.ND + 1):
        t = C.TEMP[id]
        rho = C.DENS[id]

        if C.numtemp == C.ND:
            opac = C.raytab[id, 1]
            # GO TO 10 → 跳过插值，直接到标号 10
        else:
            tl = math.log(t)
            deltat = ((tl - C.TTAB1) / (C.TTAB2 - C.TTAB1)
                      * float(C.numtemp - 1))
            jt = 1 + int(dint(deltat))      # IDINT → dint，再转 int（向零截断）
            ju = jt + 1
            if jt < 1:
                jt = 1
            if jt > C.numtemp - 1:
                jt = C.numtemp - 1
            t1i = C.tempvec[jt]
            t2i = C.tempvec[jt + 1]
            dti = (tl - t1i) / (t2i - t1i)
            if deltat < 0.0:
                dti = 0.0

            if C.numrho > 1:
                C.RTAB1 = C.rhomat[jt, 1]
                C.RTAB2 = C.rhomat[jt, C.numrho]
                rl = math.log(rho)
                deltar = ((rl - C.RTAB1) / (C.RTAB2 - C.RTAB1)
                          * float(C.numrho - 1))
                jr = 1 + int(dint(deltar))
                if jr < 1:
                    jr = 1
                if jr > C.numrho - 1:
                    jr = C.numrho - 1
                r1i = C.rhomat[jt, jr]
                r2i = C.rhomat[jt, jr + 1]
                dri = (rl - r1i) / (r2i - r1i)
                if deltar < 0.0:
                    dri = 0.0
                opr1 = (C.raytab[jt, jr]
                        + dri * (C.raytab[jt, jr + 1] - C.raytab[jt, jr]))

                C.RTAB1 = C.rhomat[ju, 1]
                C.RTAB2 = C.rhomat[ju, C.numrho]
                rl = math.log(rho)
                deltar = ((rl - C.RTAB1) / (C.RTAB2 - C.RTAB1)
                          * float(C.numrho - 1))
                jr = 1 + int(dint(deltar))
                if jr < 1:
                    jr = 1
                if jr > C.numrho - 1:
                    jr = C.numrho - 1
                r1i = C.rhomat[ju, jr]
                r2i = C.rhomat[ju, jr + 1]
                dri = (rl - r1i) / (r2i - r1i)
                if deltar < 0.0:
                    dri = 0.0
                opr2 = (C.raytab[ju, jr]
                        + dri * (C.raytab[ju, jr + 1] - C.raytab[ju, jr]))

                opac = opr1 + (opr2 - opr1) * dti
            else:
                jr = 1
                opac = (C.raytab[jt, jr]
                        + (C.raytab[ju, jr] - C.raytab[jt, jr]) * dti)
        # 标号 10
        C.raysc[id] = math.exp(opac)
    return


def rayleigh(mode, ij, id, scr):
    """
    对应 tlusty208.f 行 45179–45224
    （原文无头部注释；功能：Rayleigh 散射截面的设置/求值）

    修改标量哑元 SCR（仅 MODE≠0 分支）→ 按约定返回全部标量哑元
    (mode, ij, id, scr)
    """
    # PARAMETER (FRRAY=2.463D15, FRAYHe=5.150E15, FRAYH2=2.922E15,
    #            C18=2.997925D18, CR0=5.799D-13, CR1=1.422D-6, CR2=2.784D0)
    FRRAY = 2.463e15
    FRAYHE = 5.150e15                       # 原 PARAMETER 名 FRAYHe
    FRAYH2 = 2.922e15
    C18 = 2.997925e18
    CR0 = 5.799e-13
    CR1 = 1.422e-6
    CR2 = 2.784e0
    # COMMON/RAYSCT/RCS(MFREQ),RCHE(MFREQ),RCH2(MFREQ) —— 见文件头说明
    # common/eospar/anmol,anato,anion —— 见文件头说明

    if mode == 0:
        for ik in range(1, C.NFREQ + 1):
            frm = min(C.FREQ[ik], FRRAY)
            x = UN / (C18 / frm) ** 2
            C.RCS[ik] = (CR0 + (CR1 + CR2 * x) * x) * x * x
        if C.IRSCHE != 0:
            # TODO(port): 原文下面两行 MIN(FR,FRAYHe) 引用的局部变量 FR 在
            # 本例程中从未赋值（几乎可以肯定是 FREQ(IK) 或 FRM 之误）；
            # 直译保留 FR，此处置 0.0
            fr = 0.0
            for ik in range(1, C.NFREQ + 1):
                x = (C18 / min(fr, FRAYHE)) ** 2
                C.RCHE[ik] = (5.484e-14 / x / x
                              * (1.0 + (2.44e5 + 5.94e10 / (x - 2.90e5)) / x) ** 2)
        if C.IRSCH2 != 0 and C.IFMOL > 0:
            fr = 0.0                        # TODO(port): 同上，原文 FR 未赋值
            for ik in range(1, C.NFREQ + 1):
                x = (C18 / min(fr, FRAYH2)) ** 2
                x2 = 1.0 / x / x
                C.RCH2[ik] = (8.14e-13 + 1.28e-6 / x + 1.61 * x2) * x2
    else:
        scr = C.RCS[ij] * C.anato[1, id]
        if C.IRSCHE != 0:
            scr = scr + C.RCHE[ij] * C.anato[2, id]
        if C.IRSCH2 != 0 and C.IFMOL > 0:
            scr = scr + C.RCH2[ij] * C.anmol[2, id]
    return mode, ij, id, scr


def opctab(fr, ij, id, t, rho, ab, sc, sct, igram):
    """
    opacity for a given temperature and density computed
    by an interpolation of the precalculated opacity table

    This is a simplified routine with all interpolations linear

    Input:   FR  - frequency   (Hz)
             T   - temperature (K)
             RHO - density     (g cm^-3)
     Outout: AB  - absorptive opacity  (per gram)
             SC  - scattering opacity  (per gram)

    对应 tlusty208.f 行 45231–45346

    修改标量哑元 AB、SCT（以及 IGRAM=0 且 ITER>0 时的 AB/SC/SCT 缩放）
    → 按约定返回全部标量哑元 (fr, ij, id, t, rho, ab, sc, sct, igram)
    """
    # parameter (frray0 = 5.0872638d14)
    frray0 = 5.0872638e14

    jf = ij
    frij = fr                             # 局部变量，原文赋值后未再使用

    if C.numtemp == C.ND:
        opac = C.absopac[id, 1, jf]
        # GO TO 10 → 跳过插值，直接到标号 10
    else:
        tl = math.log(t)
        deltat = ((tl - C.TTAB1) / (C.TTAB2 - C.TTAB1)
                  * float(C.numtemp - 1))
        jt = 1 + int(dint(deltat))        # IDINT → dint，再转 int
        ju = jt + 1
        if jt < 1:
            jt = 1
        if jt > C.numtemp - 1:
            jt = C.numtemp - 1
        t1i = C.tempvec[jt]
        t2i = C.tempvec[jt + 1]
        dti = (tl - t1i) / (t2i - t1i)
        if deltat < 0.0:
            dti = 0.0

        if C.numrh[1] != 1:

            # lower temperature
            C.numrho = C.numrh[jt]
            C.RTAB1 = C.rhomat[jt, 1]
            C.RTAB2 = C.rhomat[jt, C.numrho]
            rl = math.log(rho)
            deltar = ((rl - C.RTAB1) / (C.RTAB2 - C.RTAB1)
                      * float(C.numrho - 1))
            jr = 1 + int(dint(deltar))
            if jr < 1:
                jr = 1
            if jr > C.numrho - 1:
                jr = C.numrho - 1
            r1i = C.rhomat[jt, jr]
            r2i = C.rhomat[jt, jr + 1]
            dri = (rl - r1i) / (r2i - r1i)
            if deltar < 0.0:
                dri = 0.0
            opr1 = (C.absopac[jt, jr, jf]
                    + dri * (C.absopac[jt, jr + 1, jf] - C.absopac[jt, jr, jf]))

            # higher temperature
            ju = jt + 1                     # 原文在钳位后重新计算 JU
            C.numrho = C.numrh[ju]
            C.RTAB1 = C.rhomat[ju, 1]
            C.RTAB2 = C.rhomat[ju, C.numrho]
            rl = math.log(rho)
            deltar = ((rl - C.RTAB1) / (C.RTAB2 - C.RTAB1)
                      * float(C.numrho - 1))
            jr = 1 + int(dint(deltar))
            if jr < 1:
                jr = 1
            if jr > C.numrho - 1:
                jr = C.numrho - 1
            r1i = C.rhomat[ju, jr]
            r2i = C.rhomat[ju, jr + 1]
            dri = (rl - r1i) / (r2i - r1i)
            if deltar < 0.0:
                dri = 0.0
            opr2 = (C.absopac[ju, jr, jf]
                    + dri * (C.absopac[ju, jr + 1, jf] - C.absopac[ju, jr, jf]))
            opac = opr1 + (opr2 - opr1) * dti
        else:
            jr = 1
            opac = (C.absopac[jt, jr, jf]
                    + (C.absopac[ju, jr, jf] - C.absopac[jt, jr, jf]) * dti)
    # 标号 10
    opac = math.exp(opac)

    ab = opac

    # ************************************************************
    # scattering
    # ************************************************************
    # 1. Rayleigh scattering
    sct = 0.0
    if C.IFRAYL < 0:
        sct = C.raysc[id] * (C.FREQ[jf] / frray0) ** 4
    elif C.IFRAYL > 0:
        # call rayleigh(1,ij,id,scr)：RAYLEIGH 修改 SCR → 返回全部标量哑元；
        # 实参 1 为字面量、对应未被修改的 MODE，用临时名接收
        scr = 0.0                           # 局部变量，先定义
        _mode, ij, id, scr = rayleigh(1, ij, id, scr)
        sct = scr / C.DENS[id]
    if C.IOPTAB < 0:
        sct = sct + SIGE * C.ELEC[id] / rho
    # sct=sc+sige*elec(id)/dens(id)   —— 原文注释行
    # sct=sc                          —— 原文注释行

    # 2. cloud scattering (not yet implemented)

    if C.ITER <= 0:
        return fr, ij, id, t, rho, ab, sc, sct, igram

    # ab=ab+abscld(id,jf)             —— 原文注释行
    # sct=sct+scacld(id,jf,1)         —— 原文注释行

    if igram == 0:
        ab = ab * rho
        sc = sc * rho
        sct = sct * rho

    return fr, ij, id, t, rho, ab, sc, sct, igram


def opact1(ij):
    """
    Absorption, emission, and scattering coefficients
    at frequency IJ and for all depths

    Input: IJ   opacity and emissivity is calculated for the
                frequency points with index IJ
    Output: ABSO1 -  array of absorption coefficient
            EMIS1 -  array of emission coefficient
            SCAT1 -  array of scattering coefficient

    对应 tlusty208.f 行 45352–45390
    """
    # common/hmolab/anh2(mdepth),anhm(mdepth) —— 本例程声明但未使用（见文件头说明）
    fr = C.FREQ[ij]
    for id in range(1, C.ND + 1):
        t = C.TEMP[id]
        rho = C.DENS[id]
        C.HKT1[id] = HK / t
        C.XKF[id] = math.exp(-C.HKT1[id] * fr)
        C.XKF1[id] = UN - C.XKF[id]
        C.XKFB[id] = C.XKF[id] * C.BNUE[ij]
        plan = C.XKFB[id] / C.XKF1[id]
        # CALL OPCTAB(FR,IJ,ID,T,RHO,AB,SC,SCT,0)
        # OPCTAB 修改标量哑元 AB/SC/SCT → 返回全部标量哑元，调用点解包接收；
        # 实参 0 为字面量、对应未被修改的 IGRAM，用临时名接收
        ab = 0.0
        sc = 0.0
        sct = 0.0                           # Python 需先定义局部变量
        fr, ij, id, t, rho, ab, sc, sct, _igram = opctab(
            fr, ij, id, t, rho, ab, sc, sct, 0)
        if C.IOPTAB < 0:
            C.ABSO1[id] = ab + sct
            C.SCAT1[id] = sct
            C.ABSOT[id] = C.ABSOT[id] + C.ABSO1[id] / C.DENS[id]
        elif C.IOPTAB > 0:
            C.ABSO1[id] = C.ABSO1[id] + ab
        C.EMIS1[id] = C.EMIS1[id] + ab * plan
    return


def opactd(ij):
    """
    Absorption and emission coefficients, and their derivatives

    This procedure is very similar to OPACT1, the only difference is
    the evaluation of derivatives

    Input:
     IJ    - depth index
    Output:
     ABSO1 - array of absorption coefficient
     EMIS1 - array of emission coefficient
     SCAT1 - array of scattering coefficient
     Dxxy  - array of derivatives of xx (=AB for absorption, =EM for
             emission, =SC for scattering) coefficient
             wrt y (=T for temperature, =N for density)

    对应 tlusty208.f 行 45397–45491
    """
    # common/rhoder/drhodt(mdepth)；common/dsctva/dsct1,dscn1；
    # common/hmolab/anh2,anhm —— 见文件头说明（hmolab 本例程未使用）
    # PARAMETER (DELT=1.D-3, DELR=1.D-3)
    DELT = 1.0e-3
    DELR = 1.0e-3

    imodf = 0
    if C.IFRYB > 0:
        imodf = 1
    fr = C.FREQ[ij]
    for id in range(1, C.ND + 1):
        t = C.TEMP[id]
        t1 = t * (UN + DELT)
        rho = C.DENS[id]
        rho1 = rho * (UN + DELR)
        C.XKF[id] = math.exp(-C.HKT1[id] * fr)
        C.XKF1[id] = UN - C.XKF[id]
        C.XKFB[id] = C.XKF[id] * C.BNUE[ij]
        plan = C.XKFB[id] / C.XKF1[id]
        dplan = plan / C.XKF1[id] * C.HKT1[id] * fr / t
        # CALL OPCTAB(...)：OPCTAB 修改 AB/SC/SCT → 解包接收（见 opact1 注释）
        ab = sc = sct = 0.0
        ab1 = sc1 = sct1 = 0.0
        ab2 = sc2 = sct2 = 0.0
        fr, ij, id, t, rho, ab, sc, sct, _igram = opctab(
            fr, ij, id, t, rho, ab, sc, sct, imodf)
        fr, ij, id, t1, rho, ab1, sc1, sct1, _igram = opctab(
            fr, ij, id, t1, rho, ab1, sc1, sct1, imodf)
        fr, ij, id, t, rho1, ab2, sc2, sct2, _igram = opctab(
            fr, ij, id, t, rho1, ab2, sc2, sct2, imodf)
        C.ABSO1[id] = ab + sct
        C.SCAT1[id] = sct
        C.EMIS1[id] = ab * plan
        C.ABSOT[id] = C.ABSO1[id]
        if imodf == 0:
            C.ABSOT[id] = C.ABSO1[id] / C.DENS[id]

        # derivatives w.r.t. temperature
        C.DABT1[id] = (ab1 - ab) / t / DELT
        C.DEMT1[id] = ab * dplan + C.DABT1[id] * plan
        C.dsct1[id] = (sct1 - sct) / t / DELT
        C.DABT1[id] = C.DABT1[id] + C.dsct1[id]
        if C.IFRYB > 0:

            # derivatives w.r.t. density
            C.DABN1[id] = (ab2 - ab) / rho / DELR
            C.DEMN1[id] = C.DABN1[id] * plan
            C.dscn1[id] = (sct2 - sct) / rho / DELR
            C.DABN1[id] = C.DABN1[id] + C.dscn1[id]

            # modify derivatives  in case density is not a state parameter
            if C.INHE <= 0:
                C.DABT1[id] = C.DABT1[id] + C.DABN1[id] * C.drhodt[id]
                C.DEMT1[id] = C.DEMT1[id] + C.DEMN1[id] * C.drhodt[id]
                C.dsct1[id] = C.dsct1[id] + C.dscn1[id] * C.drhodt[id]
                C.DABN1[id] = 0.0
                C.DEMN1[id] = 0.0
                C.dscn1[id] = 0.0

    # store quantities for explicit (linearized) frequencies
    if C.IJEX[ij] <= 0 or C.IFRYB > 0:
        return
    ije = C.IJEX[ij]
    for id in range(1, C.ND + 1):
        C.ABSOEX[ije, id] = C.ABSO1[id]
        C.SCATEX[ije, id] = C.SCAT1[id]
        C.EMISEX[ije, id] = C.EMIS1[id]
        C.DABTEX[ije, id] = C.DABT1[id]
        C.DEMTEX[ije, id] = C.DEMT1[id]
        C.DABNEX[ije, id] = C.DABN1[id]
        C.DEMNEX[ije, id] = C.DEMN1[id]

    return


def settrm():
    """
    reads the equation-of-state tables for the pressure (P)
    and entropy (S), as a function of T and rho;

    stores P(rho,T) and S(rho,t) in arrays PL and SL

    对应 tlusty208.f 行 45497–45580
    """
    # COMMON/THERM/SL(330,100),PL(330,100)；COMMON/TABLTD/...；
    # common/tdedge/...；common/tdflag/JON —— 见文件头说明
    # parameter (RCON=8.31434E7)
    RCON = 8.31434e7

    # open(58,file='./data/stab.dat',status='old')
    # open(59,file='./data/ptab.dat',status='old')
    open_unit(58, './data/stab.dat', 'r')
    open_unit(59, './data/ptab.dat', 'r')

    # READ(58,*) YHEA,INDEX,R1,R2,T1,T2,T12,T22
    _v = []
    while len(_v) < 8:
        _v.extend(read_line(58).replace(',', ' ').split())
    yhea = float(_v[0])                     # 局部变量，原文读后未使用
    C.INDEX = int(_v[1])
    C.R1 = float(_v[2])
    C.R2 = float(_v[3])
    C.T1 = float(_v[4])
    C.T2 = float(_v[5])
    C.T12 = float(_v[6])
    C.T22 = float(_v[7])

    for jr in range(1, C.INDEX + 1):
        for jqs in range(1, 11):
            jl = 1 + (jqs - 1) * 10
            ju = jl + 9
            # READ(58,130) (SL(JR,JQ),JQ=JL,JU)；130 FORMAT(10F8.5)
            _line = read_line(58)
            for jq in range(jl, ju + 1):
                C.SL[jr, jq] = float(_line[8 * (jq - jl):8 * (jq - jl) + 8])

    # READ(59,*) YHEA,INDEX,R1,R2,T1,T2,T12,T22
    _v = []
    while len(_v) < 8:
        _v.extend(read_line(59).replace(',', ' ').split())
    yhea = float(_v[0])
    C.INDEX = int(_v[1])
    C.R1 = float(_v[2])
    C.R2 = float(_v[3])
    C.T1 = float(_v[4])
    C.T2 = float(_v[5])
    C.T12 = float(_v[6])
    C.T22 = float(_v[7])
    for jr in range(1, C.INDEX + 1):
        for jqp in range(1, 11):
            jl = 1 + (jqp - 1) * 10
            ju = jl + 9
            # READ(59,130) (PL(JR,JQ),JQ=JL,JU)；130 FORMAT(10F8.5)
            _line = read_line(59)
            for jq in range(jl, ju + 1):
                C.PL[jr, jq] = float(_line[8 * (jq - jl):8 * (jq - jl) + 8])

    close_unit(58)
    close_unit(59)

    # Edge arrays
    r = 1.5 * 10.0 ** C.R1
    tmin = 1.5 * 10.0 ** C.T1
    tmax = 0.9 * 10.0 ** C.T2
    C.redge = r
    p1 = s1 = p2 = s2 = p0 = s0 = 0.0       # Python 需先定义局部变量
    for i in range(1, 101):
        t = C.T1 + (C.T2 - C.T1) * float(i - 1) / float(99)
        t = 10.0 ** t
        t = min(tmax, max(t, tmin))
        C.tedge[i] = t
        rho = r
        # CALL PRSENT(...)：PRSENT 修改 FP/FS → 返回 (r,t,fp,fs)，解包接收
        _r, t, p1, s1 = prsent(rho * 1.1, t, p1, s1)
        _r, t, p2, s2 = prsent(rho, t * 1.1, p2, s2)
        rho, t, p0, s0 = prsent(rho, t, p0, s0)
        s1 = RCON * s1
        s2 = RCON * s2
        s0 = RCON * s0
        dpdr = (p1 - p0) / (0.1 * rho)
        dpdt = (p2 - p0) / (0.1 * t)
        dsdt = (s2 - s0) / (0.1 * t)
        dsdr = (s1 - s0) / (0.1 * rho)
        den = dpdr * dsdt - dpdt * dsdr
        p = p0
        s = s0 / RCON
        cv = t * dsdt
        cp = t * den / dpdr
        dq = dsdt * p / (den * rho)
        gamma = 1.0 / dq

        C.pedge[i] = p
        C.sedge[i] = s
        C.cvedge[i] = cv
        C.cpedge[i] = cp
        C.gammaedge[i] = gamma
        # 45 format(i4,5e14.5)
        write_line(44, '%4d%14.5e%14.5e%14.5e%14.5e%14.5e'
                   % (i, C.tedge[i], C.cvedge[i], C.cpedge[i],
                      C.sedge[i], C.gammaedge[i]))

    return


def rhoeos(t, p):
    """
    equation of state - determining density from
    temperature and pressure

    Input:   T - temperature (K)
             P - total pressure (cgs)

    对应 tlusty208.f 行 45587–45624

    Fortran FUNCTION：返回密度 rho；不修改标量哑元 T、P。
    """
    global _save_rhoeos_inirea
    # parameter(wmol0=1.67333E-24/2.3)；data inirea /0/（隐含 SAVE，见模块级）
    wmol0 = 1.67333e-24 / 2.3

    # initialize EOS tables
    if _save_rhoeos_inirea == 0:
        # call settrm —— 无哑元，直接调用
        settrm()
        _save_rhoeos_inirea = 1

    an = p / BOLK / t
    rho = an * wmol0

    niteos = 0
    p0 = s0 = p1 = s1 = 0.0                 # Python 需先定义局部变量
    # 标号 10：牛顿迭代（GO TO 10 → while 循环）
    while True:
        niteos = niteos + 1
        # CALL PRSENT(...)：PRSENT 修改 FP/FS → 返回 (r,t,fp,fs)
        rho, t, p0, s0 = prsent(rho, t, p0, s0)
        _r, t, p1, s1 = prsent(rho * 1.01, t, p1, s1)
        dpdr = (p1 - p0) / (0.01 * rho)
        drxx = (p - p0) / dpdr / rho
        if drxx < -0.9:
            drxx = -0.9
        rho = rho * (UN + drxx)
        if not (abs(drxx) > 1.0e-5 and niteos < 20):
            break                           # 不满足 GO TO 10 条件 → 退出循环

    return rho                              # rhoeos = rho


def setdrt():
    """
    对应 tlusty208.f 行 45631–45648
    （原文无头部注释；功能：用 RHOEOS 数值求 d rho / d T，存入 DRHODT）
    """
    # COMMON/RHODER/DRHODT(MDEPTH)；PARAMETER(DDTMIN=0., DDTPLU=0.001)
    DDTMIN = 0.0
    DDTPLU = 0.001

    for id in range(1, C.ND + 1):
        t = C.TEMP[id]
        p = C.PTOTAL[id]
        # RHOEOS 为 FUNCTION，不修改哑元，直接接收函数值
        rho1 = rhoeos(t * (UN - DDTMIN), p)
        rho2 = rhoeos(t * (UN + DDTPLU), p)
        C.drhodt[id] = (rho2 - rho1) / t / (DDTMIN + DDTPLU)
    return


def trmdrt(id, t, p, heatcp, dlrdlt, grdadb, rho):
    """
    Thermodynamic derivatives - based on statew equation and entropy
    tables

    Input:  T     -  temperature
            P     -  gas pressure

    Output: HEATCP - specific heat at constant pressure
            DLRDLT - d(ln rho)/d(ln T)
            GRDADB - adiabatic gradient d(ln T)/d(ln P)_ad
            etdrt

    对应 tlusty208.f 行 45655–45719

    修改标量哑元 HEATCP、DLRDLT、GRDADB、RHO
    → 按约定返回全部标量哑元 (id, t, p, heatcp, dlrdlt, grdadb, rho)
    """
    # COMMON/CC/DPDR,DPDT,DSDT,DSDR,CV,S,GAMMA；COMMON/CONVOUT/... —— 见文件头说明
    # parameter (RCON=8.31434E7)；parameter(wmol0=1.67333E-24/2.3)
    RCON = 8.31434e7
    wmol0 = 1.67333e-24 / 2.3               # 原文定义后未使用

    # numerical evaluation of thermodynamic derivatives
    rho = rhoeos(t, p)                      # RHOEOS 为 FUNCTION，直接接收
    drho = 0.01 * rho
    dt = 0.01 * t
    p0 = s0 = p1 = s1 = p2 = s2 = p3 = s3 = p4 = s4 = 0.0
    # CALL PRSENT(...)：PRSENT 修改 FP/FS → 返回 (r,t,fp,fs)
    rho, t, p0, s0 = prsent(rho, t, p0, s0)
    _r, t, p1, s1 = prsent(rho + drho, t, p1, s1)
    _r, t, p2, s2 = prsent(rho - drho, t, p2, s2)
    _r, t, p3, s3 = prsent(rho, t + dt, p3, s3)
    _r, t, p4, s4 = prsent(rho, t - dt, p4, s4)
    C.DPDR = (p1 - p2) / (2.0 * drho)
    C.DPDT = (p3 - p4) / (2.0 * dt)
    C.DSDR = (s1 - s2) / (2.0 * drho) * RCON
    C.DSDT = (s3 - s4) / (2.0 * dt) * RCON
    den = C.DPDR * C.DSDT - C.DPDT * C.DSDR

    if C.JON == 0:
        heatcv = t * C.DSDT                 # 局部变量（原文未使用）
        heatcp = t * den / C.DPDR
        dq = C.DSDT * p / (den * rho)
        C.GAMMA = 1.0 / dq
        dlrdlt = -rho * C.DPDR / (t * C.DPDT)
        dlrdlt = 1.0 / dlrdlt
        grdadb = -p / (heatcp * rho * t) * dlrdlt
        tdpt = t * C.DPDT                   # 局部变量（原文未使用）
    else:                                   # jon ≠ 0
        heatcv = C.cvedge[C.JON]
        heatcp = C.cpedge[C.JON]
        dlrdlt = -1.0
        grdadb = -p / (heatcp * rho * t) * dlrdlt   # 0.4d0
        C.GAMMA = C.gammaedge[C.JON]

    # 原文无条件重算 grdadb（覆盖上面两个分支的结果）
    grdadb = p / t * (C.DSDR / (C.DSDR * C.DPDT - C.DSDT * C.DPDR))
    C.GRADAD[id] = grdadb
    C.ENT[id] = s0

    return id, t, p, heatcp, dlrdlt, grdadb, rho


def prsent(r, t, fp, fs):
    """
    interpolates pressure and entropy from tables

    对应 tlusty208.f 行 45726–45784

    修改标量哑元 FP、FS → 按约定返回全部标量哑元 (r, t, fp, fs)
    """
    # COMMON/THERM/SL(330,100),PL(330,100)；COMMON/TABLTD/...；
    # common/tdedge/...；common/tdflag/JON —— 见文件头说明
    C.JON = 0
    rl = math.log10(r)
    alpha = C.T1 + (rl - C.R1) / (C.R2 - C.R1) * (C.T12 - C.T1)
    beta = (C.T2 - C.T1
            + ((C.T22 - C.T12) - (C.T2 - C.T1)) * (rl - C.R1) / (C.R2 - C.R1))
    ql = (math.log10(t) - alpha) / beta
    delta = (rl - C.R1) / (C.R2 - C.R1) * float(C.INDEX - 1)
    jr = 1 + int(dint(delta))               # IDINT → dint，再转 int
    jq = 1 + int(dint(99.0 * ql))
    # IF(JR.LT.2) GO TO 300 / IF(JR.GT.(INDEX-1)) GO TO 300 /
    # IF(JQ.LT.2) GO TO 300 / IF(JQ.GT.99) GO TO 300
    # → 四个条件全不满足才做表内插值，否则落到标号 300（off the table）
    if 2 <= jr <= C.INDEX - 1 and 2 <= jq <= 99:
        p = delta - (jr - 1)
        q = 99.0 * ql - (jq - 1)
        # interpolate:
        fs = (0.5 * q * (q - 1.0) * C.SL[jr, jq - 1]
              + 0.5 * p * (p - 1.0) * C.SL[jr - 1, jq]
              + (1.0 + p * q - p * p - q * q) * C.SL[jr, jq]
              + 0.5 * p * (p - 2.0 * q + 1.0) * C.SL[jr + 1, jq]
              + 0.5 * q * (q - 2.0 * p + 1.0) * C.SL[jr, jq + 1]
              + p * q * C.SL[jr + 1, jq + 1])
        fs = 10.0 ** fs

        fp = (0.5 * q * (q - 1.0) * C.PL[jr, jq - 1]
              + 0.5 * p * (p - 1.0) * C.PL[jr - 1, jq]
              + (1.0 + p * q - p * p - q * q) * C.PL[jr, jq]
              + 0.5 * p * (p - 2.0 * q + 1.0) * C.PL[jr + 1, jq]
              + 0.5 * q * (q - 2.0 * p + 1.0) * C.PL[jr, jq + 1]
              + p * q * C.PL[jr + 1, jq + 1])
        fp = 10.0 ** fp
        return r, t, fp, fs

    # off the table
    # 标号 300
    write_line(60, ' Off the table!')       # write(60,*)

    jq = min(98, max(jq, 2))
    C.JON = jq
    fp = C.pedge[jq] * r * t / (C.redge * C.tedge[jq])
    fs = (C.sedge[jq] + 1.0 / (C.gammaedge[jq] - 1.0)
          * math.log(fp / C.pedge[jq] * (C.redge / r) ** C.gammaedge[jq]))
    # write(60,*) JQ, R, T, FP, FS
    write_line(60, '%r %r %r %r %r' % (jq, r, t, fp, fs))

    return r, t, fp, fs


def moleq(id, tt, an, aein, ane, energ, entt, wm, ipri):
    """
    calculation of the equilibrium state of atoms and molecules

    Input:  id    - depth point
            tt    - temperature [K]
            an    - total particle number density
            aein  - initial estimate of the electron density

    Output: 1) parameters transported through formal parameters"
               ane    - electron density
               entt   - entropy
               energ  - internal energy
            2) parameters transported through COMMON blocks
               ELEC(ID)    - electron denity
               DENS(ID)    - mass density
               WMM(ID)     - mean molecular weight
               QADD(ID)    - total charge of non-explicit species
               ABUND(I,ID) - abundances of explicit atoms,
                             counting only atoms and ions
                             (not atoms sequestered in molecules)

    Input data for molecules given in file tsuji.molec

    对应 tlusty208.f 行 45790–46107

    修改标量哑元 ane、energ、entt、wm
    → 按约定返回全部标量哑元 (id, tt, an, aein, ane, energ, entt, wm, ipri)
    """
    global _save_moleq_iread
    # character*128 MOLEC
    # COMMON/COMFH1/... —— 见文件头说明
    # TODO(port): /COMFH1/ 的 C(600,5) 与 commons.py 中 ARRAY1.FOR 无名 COMMON
    # 的 "C"(MTOT,MTOT) 重名冲突，本片一律以 C.COMFH1_C 访问
    # data nmetal/92/ —— 对 COMMON 变量 NMETAL 的 DATA 初始化（非标准用法，
    # 等价于加载时赋值；NMETAL 在程序中不再被修改）
    C.NMETAL = 92
    # DIMENSION 局部数组（1 基索引）
    natomm = np.zeros(6, dtype=np.int64)    # NATOMM(5)
    nelemm = np.zeros(6, dtype=np.int64)    # NELEMM(5)
    emass = np.zeros(101)                   # emass(100)
    uelem = np.zeros(101)                   # uelem(100)
    ull = np.zeros(101)                     # ull(100)
    anden = np.zeros(801)                   # anden(800)
    aelem = np.zeros(101)                   # aelem(100)
    ammol = np.zeros(601)                   # ammol(600)
    cmol = np.empty(601, dtype=object)      # cmol(600)
    cmol[...] = ''
    anat0 = np.zeros(101)                   # anat0(100)
    anio0 = np.zeros(101)                   # anio0(100)
    anmo0 = np.zeros(601)                   # anmo0(600)
    pfmol = np.zeros(601)                   # pfmol(600)
    denso = np.zeros(MDEPTH + 1)            # denso(mdepth)
    eleco = np.zeros(MDEPTH + 1)            # eleco(mdepth)
    wmmo = np.zeros(MDEPTH + 1)             # wmmo(mdepth)
    # TODO(port): 局部变量 nelemi 在原文 aelem(99)=...emass(nelemi)... 处
    # （行 45929）被引用时，其值依赖 Fortran 局部变量的静态保存语义
    # （首次调用时在 iread 块中最后一次赋为 NELEMX(NMETAL)=92）；此处置 0
    nelemi = 0

    # data iread/1/（隐含 SAVE，见模块级 _save_moleq_iread）

    if C.IFMOL == 0:
        return id, tt, an, aein, ane, energ, entt, wm, ipri
    molec = 'data/tsuji.molec_bc2'
    if C.moltab == 0:
        molec = 'data/tsuji.molec_orig'

    econst = 4.342945e-1
    tk = 1.0 / (tt * BOLK)
    pgas = an / tk
    sahcon = 1.87840e20 * tt * math.sqrt(tt)
    ev2erg = 1.6018e-12
    C.NIMAX = 3000
    C.EPS = 0.001
    C.SWITER = 1.0                          # switer=1（实型变量）

    if _save_moleq_iread == 1:

        # ---- data for atoms  ----------------
        for i in range(1, C.NMETAL + 1):
            ia = i
            C.NELEMX[i] = ia
            C.CCOMP[ia] = C.ABNDD[ia, id]
            C.XIP[ia] = C.ENEV[ia, 1]
            C.XIP2[ia] = C.ENEV[ia, 2]
            emass[ia] = C.amas[ia]

        # ---- read molecular data from tsuji.molec ----------------------
        j = 0
        # OPEN(UNIT=26,FILE=MOLEC,STATUS='OLD')
        open_unit(26, molec, 'r')
        while True:
            # 标号 10
            j = j + 1
            try:
                # READ(26,510,END=20) CMOL(J),(C(J,K),K=1,5),MMAX(J),
                #                     (NELEMM(M),NATOMM(M),M=1,4)
                # 510 FORMAT(A8,5E13.5,9I3)
                _line = read_line(26)
            except EOFError:
                break                       # END=20 → 标号 20
            _line = _line.ljust(100)        # 固定格式按列取字段，短行补空格
            cmol[j] = _line[0:8]            # A8
            for k in range(1, 6):           # 5E13.5
                C.COMFH1_C[j, k] = float(_line[8 + 13 * (k - 1):8 + 13 * k])
            _f = _line[73:76]               # I3：MMAX(J)
            C.MMAX[j] = int(_f) if _f.strip() else 0
            for m in range(1, 5):           # 8×I3：(NELEMM(M),NATOMM(M)),M=1,4
                _f = _line[76 + 6 * (m - 1):79 + 6 * (m - 1)]
                nelemm[m] = int(_f) if _f.strip() else 0
                _f = _line[79 + 6 * (m - 1):82 + 6 * (m - 1)]
                natomm[m] = int(_f) if _f.strip() else 0

            # for now, exclude all molecules with 4 or more C atoms
            _skip = False
            for m in range(1, 5):
                if nelemm[m] == 6 and natomm[m] >= 5:
                    j = j - 1
                    _skip = True
                    break                   # GO TO 10（重读下一条记录）
            if _skip:
                continue

            mmaxj = C.MMAX[j]
            if mmaxj > 0:
                for m in range(1, mmaxj + 1):
                    C.NELEM[m, j] = nelemm[m]
                    C.NATO[m, j] = natomm[m]
                continue                    # GO TO 10
            # MMAXJ<=0（终止记录）→ 落到标号 20
            break
        # 标号 20
        C.NMOLEC = j - 1
        close_unit(26)

        for i in range(1, C.NMETAL + 1):
            nelemi = C.NELEMX[i]
            C.P[nelemi] = 1.0e-70
        _save_moleq_iread = 0

    # ---- end of reading atomic and molecular data  ----------------------

    C.P[99] = aein / tk
    pesave = C.P[99]
    C.P[99] = pesave

    thet = 5040.0 / tt
    tem = tt
    pglog = math.log10(pgas)                # 局部变量，原文赋值后未使用
    pg = pgas
    tkln25 = -math.log(tk) * 2.5            # 局部变量，原文赋值后未使用
    tkln15 = math.log(BOLK * tt) * 1.5
    tkev = 5040.0 / tt                      # 局部变量，原文赋值后未使用

    # CALL RUSSEL(TEM,PG)：RUSSEL 不修改标量哑元 TEM/PG，直接调用
    russel(tem, pg)

    pe = C.P[99]
    ane = pe * tk
    pelog = math.log10(pe)
    emass[99] = 5.486e-4
    uelem[99] = 2.0
    aelem[99] = pe * tk / (2.0 * sahcon * emass[nelemi] ** 1.5)
    ull[99] = math.log10(aelem[99])
    C.IDSTD = idiv(C.ND * 2, 3)             # idstd=nd*2/3（Fortran 整数除法）
    entcon = 103.973
    ann = an - ane
    tkk = BOLK * tt * tt

    # ----atoms-----------------------------------------------------------------
    entt = 0.0                              # entt=0
    antt = 0.0
    energ = 0.0
    tmass = 0.0
    u0 = 0.0
    dulog = 0.0                             # Python 需先定义
    for i in range(1, C.NMETAL + 1):
        nelemi = C.NELEMX[i]
        fplog = math.log10(C.FP[nelemi])    # 局部变量，原文赋值后未使用
        anden[i] = (C.P[nelemi] + 1.0e-70) * tk
        tmass = tmass + anden[i] * emass[nelemi]
        # call mpartf(nelemi,1,0,tt,u0,dulog)
        # mpartf 修改标量哑元 u、dulog → 返回全部标量哑元；
        # 实参 1、0 为字面量、对应未被修改的 ion/indmol，用临时名接收
        _jatom, _ion, _indmol, tt, u0, dulog = mpartf(nelemi, 1, 0, tt, u0, dulog)
        uelem[nelemi] = u0
        aelem[nelemi] = anden[i] / (u0 * sahcon * emass[nelemi] ** 1.5)
        ull[nelemi] = math.log10(aelem[nelemi])
        anat0[nelemi] = anden[i]
        if dulog < 0.0:
            dulog = 0.0
        C.entato[nelemi] = (tkln15 - math.log(anden[i]) + math.log(u0)
                            + 1.5 * math.log(emass[nelemi]) + entcon
                            + tkk * dulog)
        anx = anden[i] / ann
        antt = antt + anx
        entt = entt + C.entato[nelemi] * anden[i]
        energ = energ + dulog / tk * anden[i]
    an1 = anden[1]                          # 局部变量，原文赋值后未使用

    # ---- positive ions ---------------------------------------------------------
    u1 = 0.0                                # Python 需先定义
    for i in range(1, C.NMETAL + 1):
        nelemi = C.NELEMX[i]
        plog = math.log10(C.P[nelemi] + 1.0e-70)
        xkplog = math.log10(C.XKP[nelemi] + 1.0e-70)
        pionl = plog + xkplog - pelog
        anden[i + C.NMETAL] = math.exp(pionl / econst) * tk
        tmass = tmass + anden[i + C.NMETAL] * emass[nelemi]
        # call mpartf(nelemi,2,0,tt,u1,dulog) —— 标量哑元约定同上
        _jatom, _ion, _indmol, tt, u1, dulog = mpartf(nelemi, 2, 0, tt, u1, dulog)
        if dulog < 0.0:
            dulog = 0.0
        anio0[nelemi] = anden[i + C.NMETAL]
        C.ention[nelemi] = (tkln15 - math.log(anden[i + C.NMETAL])
                            + math.log(u1)
                            + 1.5 * math.log(emass[nelemi]) + entcon
                            + tkk * dulog)
        anx = anio0[nelemi] / ann
        antt = antt + anx
        entt = entt + C.ention[nelemi] * anio0[nelemi]
        energ = (energ + (C.XIP[nelemi] * 1.6018e-12
                          + dulog / tk) * anio0[nelemi])
        if 2 <= nelemi <= 30:
            x2log = math.log10(C.XK2[nelemi] + 1.0e-70)
            pion2 = pionl + x2log - pelog
            C.anion2[nelemi, id] = math.exp(pion2 / econst) * tk

    # H- (incorrect in the original Tsuji's table)
    jbeg = 1
    if C.moltab == 0:
        j = 1
        anmo0[1] = (1.0353e-16 / tt / math.sqrt(tt) * math.exp(8762.9 / tt)
                    * anat0[1] * ane)
        ammol[1] = emass[1]
        pfmol[1] = 1.0
        C.entmol[1] = (tkln15 - math.log(anmo0[1])
                       + 1.5 * math.log(emass[1]) + entcon)
        anx = anmo0[1] / ann
        antt = antt + anx
        entt = entt + C.entmol[j] * anmo0[1]
        tmass = tmass + emass[1] * anmo0[1]
        jbeg = 2

    # ---- molecules-------------------------------------------------------------
    um = 0.0                                # Python 需先定义
    for j in range(jbeg, C.NMOLEC + 1):
        jm = j + 2 * C.NMETAL
        pmoll = math.log10(C.PPMOL[j] + 1.0e-70)
        anden[jm] = math.exp(pmoll / econst) * tk
        if pmoll < -20.0:
            continue                        # GO TO 100
        umoll = math.log10(anden[jm]) + C.COMFH1_C[j, 2] * thet
        amasm = 0.0
        for jjj in range(1, C.MMAX[j] + 1):
            i = C.NELEM[jjj, j]
            amasm = amasm + C.NATO[jjj, j] * emass[i]
            umoll = umoll - C.NATO[jjj, j] * ull[i]
        ammol[j] = amasm
        tmass = tmass + anden[jm] * amasm
        umoll = math.exp(umoll / econst) / (sahcon * amasm ** 1.5)

        # replace with Irwin data whenever available
        # call mpartf(0,0,j,tt,um,dulog) —— 标量哑元约定同上
        _jatom, _ion, _indmol, tt, um, dulog = mpartf(0, 0, j, tt, um, dulog)
        if um > 0.0:
            umoll = um
        if umoll < 1.0:
            umoll = 1.0

        anmo0[j] = anden[jm]
        pfmol[j] = umoll
        if dulog < 0.0:
            dulog = 0.0
        C.entmol[j] = (tkln15 - math.log(anden[jm]) + math.log(umoll)
                       + 1.5 * math.log(amasm) + entcon + tkk * dulog)
        anx = anden[jm] / ann
        antt = antt + anx
        entt = entt + C.entmol[j] * anden[jm]
        energ = energ + dulog / tk * anden[jm]
        if j == 2:
            energ = energ - 4.476 * ev2erg * anden[jm]
        # if(ipri.gt.0.and.ipmole.gt.0.and.mod(id,10).eq.1.and.j.le.10) ...
        #   —— 原文已注释的诊断输出，保留注释
        # 标号 100

    # electrons
    entel = (tkln15 - math.log(ane) + 1.5 * math.log(emass[99]) + entcon)
    entt = entt + entel * ane
    antt = antt + ane / ann

    # final entropy, density, and mean mnolecular weight
    entt = entt * BOLK
    C.rhoter = tmass * HMASS
    ahtot = anat0[1] + anio0[1] + anmo0[1] + 2.0 * anmo0[2]
    wm = tmass / antt / ann

    if ipri == 0:
        return id, tt, an, aein, ane, energ, entt, wm, ipri

    for i in range(1, C.NMETAL + 1):
        j = C.NELEMX[i]
        C.anato[j, id] = anat0[j]
        C.anion[j, id] = anio0[j]

    for j in range(1, C.NMOLEC + 1):
        C.anmol[j, id] = anmo0[j]

    C.anhm[id] = C.anmol[1, id]
    C.anh2[id] = C.anmol[2, id]

    # save new density, molecular weight, and abundances of
    # atomic species
    denso[id] = C.DENS[id]
    eleco[id] = C.ELEC[id]
    wmmo[id] = C.WMM[id]
    C.DENS[id] = tmass * HMASS
    C.ELEC[id] = ane
    C.WMM[id] = C.DENS[id] / (an - C.ELEC[id])
    C.QADD[id] = 0.0
    for i in range(1, C.NMETAL + 1):
        nelemi = C.NELEMX[i]
        ia = C.iatex[nelemi]
        if ia > 0:
            C.ABUND[ia, id] = ((C.anato[nelemi, id] + C.anion[nelemi, id])
                               * C.WMM[id] / C.DENS[id] * C.YTOT[id])
        else:
            C.QADD[id] = C.QADD[id] + C.anion[nelemi, id]
    if C.IELHM == 0:
        C.QADD[id] = C.QADD[id] - C.anhm[id]

    if ipri == 0:
        return id, tt, an, aein, ane, energ, entt, wm, ipri

    # don't change structure if particle conservation in not solved
    # IF(INPC.eq.0.and.ifryb.eq.0) THEN —— 原文注释掉的条件，实际为下行
    if C.INPC == 0:
        C.DENS[id] = denso[id]
        C.ELEC[id] = eleco[id]
        C.WMM[id] = wmmo[id]

    return id, tt, an, aein, ane, energ, entt, wm, ipri


def russel(tem, pg):
    """
    对应 tlusty208.f 行 46113–46329
    （原文无头部注释；功能：Russell 方程求解分子/原子平衡分压）

    不修改标量哑元 TEM、PG → 隐式返回 None，调用点直接调用
    """
    # COMMON/COMFH1/... —— 见文件头说明（C(600,5) → C.COMFH1_C，见 moleq 注释）
    fx = np.zeros(101)                      # FX(100)
    dfx = np.zeros(101)                     # DFX(100)
    z = np.zeros(101)                       # Z(100)
    prev = np.zeros(101)                    # PREV(100)
    wa = np.zeros(101)                      # WA(100)（原文最大用到 WA(NMETAL+1)=WA(93)）
    uiidu2 = np.zeros(101)                  # UIIDU2(100)

    # ECONST=4.342945E-1 —— 原文注释掉的替代值，保留注释
    econst = 4.3426e-1
    xkcon = 6.667343e-1
    epsdie = 5.0e-5
    t = 5040.4 / tem
    pglog = math.log10(pg)                  # 局部变量，原文赋值后未使用
    tk = 1.0 / (tem * 1.38054e-16)

    # HEH=helium/hydrogen ratio by number
    # HEH=CCOMP(2)/CCOMP(1) —— 原文注释行
    heh = C.YTOT[1] - UN

    # evaluation of log XKP(MOL)
    for j in range(1, C.NMOLEC + 1):
        aplogj = C.COMFH1_C[j, 5]
        for k in range(1, 5):
            km5 = 5 - k
            aplogj = aplogj * t + C.COMFH1_C[j, km5]
        C.APMLOG[j] = aplogj
    C.APMLOG[1] = -math.log10(1.0353e-16 / tem / math.sqrt(tem)
                              * tk * math.exp(8762.9 / tem))
    dhh = ((((0.1196952e-02 * t - 0.2125713e-01) * t + 0.1545253e+00) * t
            - 0.5161452e+01) * t + 0.1277356e+02)
    dhh = math.exp(dhh / econst)

    # evaluation of the ionization constants
    tem25 = tem ** 2 * math.sqrt(tem)
    g0 = g1 = g2 = dulog = 0.0              # Python 需先定义
    for i in range(1, C.NMETAL + 1):
        nelemi = C.NELEMX[i]
        # calculation of the partition functions following Irwin (1981)
        # call mpartf(...)：mpartf 修改标量哑元 u、dulog → 返回全部标量哑元；
        # 实参 1/2/3、0 为字面量、对应未被修改的 ion/indmol，用临时名接收
        _jatom, _ion, _indmol, tem, g0, dulog = mpartf(nelemi, 1, 0, tem, g0, dulog)
        _jatom, _ion, _indmol, tem, g1, dulog = mpartf(nelemi, 2, 0, tem, g1, dulog)
        _jatom, _ion, _indmol, tem, g2, dulog = mpartf(nelemi, 3, 0, tem, g2, dulog)
        C.UIIDUI[nelemi] = g1 / g0 * xkcon
        uiidu2[nelemi] = g2 / g1 * xkcon
        C.UIIDUI[nelemi] = g1 / g0 * xkcon  # 原文重复赋值（直译保留）
        C.XKP[nelemi] = (C.UIIDUI[nelemi] * tem25
                         * math.exp(-C.XIP[nelemi] * t / econst))
        C.XK2[nelemi] = (uiidu2[nelemi] * tem25
                         * math.exp(-C.XIP2[nelemi] * t / econst))
        C.XK2[nelemi] = max(C.XK2[nelemi], 1.0e-70)
    C.XK2[1] = 0.0

    # preliminary value of PH at high temperatures
    hkp = C.XKP[1]
    if t < 0.6:
        pph = math.sqrt(hkp * (pg / (1.0 + heh) + hkp)) - hkp
        ph = pph ** 2 / hkp
    else:
        if pg / dhh <= 0.1:
            ph = pg / (1.0 + heh)
        else:
            ph = 0.5 * (math.sqrt(dhh * (dhh + 4.0 * pg / (1.0 + heh))) - dhh)

    # evaluation of the fictitious pressures of hydrogen
    # PG=PH+PHH+2.0*PPH+HEH*(PH+2.0*PHH+PPH)
    u = (1.0 + 2.0 * heh) / dhh
    q = 1.0 + heh
    r = (2.0 + heh) * math.sqrt(hkp)
    s = -1.0 * pg
    x = math.sqrt(ph)

    # Russell iterations
    iterat = 0
    # 标号 10（GO TO 10 → while 循环）
    while True:
        f = ((u * x ** 2 + q) * x + r) * x + s
        df = 2.0 * (2.0 * u * x ** 2 + q) * x + r
        xr = x - f / df

        if abs((x - xr) / xr) > epsdie:
            iterat = iterat + 1
            if iterat > 50:
                # 710 FORMAT(1H1, ' NOT CONVERGE IN RUSSEL '/// 'TEM=',F9.2,
                #      5X,'PG=',E12.5,5X,'X1=',E12.5,5X,'X2=',E12.5,5X,'PH=',
                #      E12.5/////)
                print()                     # 1H1 换页符以空行近似
                print(' NOT CONVERGE IN RUSSEL ')
                print()
                print()
                print('TEM=%9.2f     PG=%12.5E     X1=%12.5E     X2=%12.5E'
                      '     PH=%12.5E' % (tem, pg, x, xr, ph))
                print()
                print()
                print()
                print()
                # 写完继续向下执行（不再 GO TO 10）→ 跳出循环
            else:
                x = xr
                continue                    # GO TO 10
        break
    ph = xr ** 2
    phh = ph ** 2 / dhh
    pph = math.sqrt(hkp * ph)
    fph = ph + 2.0 * phh + pph
    C.P[100] = pph

    # evaluation of the fictitious pressure of each element
    for i in range(1, C.NMETAL + 1):
        nelemi = C.NELEMX[i]
        C.FP[nelemi] = C.CCOMP[nelemi] * fph

    # check of initialization
    pe = C.P[99]

    # Russell equations
    niterr = 0
    # 标号 20（GO TO 20 → while 循环）
    while True:
        for i in range(1, C.NMETAL + 1):
            nelemi = C.NELEMX[i]
            # FX(NELEMI)=-FP(NELEMI)+P(NELEMI)*(1.0+XKP(NELEMI)/PE)
            # DFX(NELEMI)=1.0+XKP(NELEMI)/PE —— 原文注释行
            dfx[nelemi] = 1.0 + C.XKP[nelemi] / pe * (1.0 + C.XK2[nelemi] / pe)
            fx[nelemi] = -C.FP[nelemi] + C.P[nelemi] * dfx[nelemi]

        spnion = 0.0
        spnplu = 0.0
        for j in range(1, C.NMOLEC + 1):
            mmaxj = C.MMAX[j]
            pmoljl = -C.APMLOG[j]
            for m in range(1, mmaxj + 1):
                nelemj = C.NELEM[m, j]
                natomj = C.NATO[m, j]
                pmoljl = pmoljl + float(natomj) * math.log10(C.P[nelemj])

            pmolj = math.exp(pmoljl / econst)
            for m in range(1, mmaxj + 1):
                nelemj = C.NELEM[m, j]
                natomj = C.NATO[m, j]
                atomj = float(natomj)
                if nelemj == 99:
                    if natomj >= 0:
                        spnion = spnion + pmolj * natomj
                    else:
                        spnplu = spnplu - pmolj * natomj
                for i in range(1, C.NMETAL + 1):
                    nelemi = C.NELEMX[i]
                    if nelemj == nelemi:
                        fx[nelemi] = fx[nelemi] + atomj * pmolj
                        dfx[nelemi] = (dfx[nelemi] + atomj ** 2
                                       * pmolj / C.P[nelemi])
            C.PPMOL[j] = pmolj

        # solution of the Russell equations by Newton-Raphson method
        for i in range(1, C.NMETAL + 1):
            nelemi = C.NELEMX[i]
            wa[i] = math.log10(C.P[nelemi] + 1.0e-70)
        imaxp1 = C.NMETAL + 1
        wa[imaxp1] = math.log10(pe + 1.0e-70)
        deltrs = 0.0
        for i in range(1, C.NMETAL + 1):
            nelemi = C.NELEMX[i]
            prev[nelemi] = C.P[nelemi] - fx[nelemi] / dfx[nelemi]
            prev[nelemi] = abs(prev[nelemi])
            if prev[nelemi] < 1.0e-70:
                prev[nelemi] = 1.0e-70
            z[nelemi] = prev[nelemi] / C.P[nelemi]
            deltrs = deltrs + abs(z[nelemi] - 1.0)
            if C.SWITER > 0.0:
                C.P[nelemi] = (prev[nelemi] + C.P[nelemi]) * 0.5
            else:
                C.P[nelemi] = prev[nelemi]

        # ionization equilibrium
        perev = 0.0
        for i in range(1, C.NMETAL + 1):
            nelemi = C.NELEMX[i]
            perev = perev + C.XKP[nelemi] * C.P[nelemi] * (1.0 + C.XK2[nelemi] / pe)

        perev = math.sqrt(perev / (1.0 + spnion / pe))
        deltrs = deltrs + abs((pe - perev) / pe)
        pe = (perev + pe) * 0.5
        C.P[99] = pe
        if deltrs > C.EPS:
            niterr = niterr + 1
            if niterr <= C.NIMAX:
                continue                    # GO TO 20
            else:
                # 605 FORMAT(1H0,'*DOES NOT CONVERGE AFTER ',I4,' ITERATIONS')
                print()                     # 1H0 → 先空一行
                print('*DOES NOT CONVERGE AFTER %4d ITERATIONS' % C.NIMAX)
                # 写完继续向下执行（RETURN）→ 跳出循环
        break

    return


def mpartf(jatom, ion, indmol, t, u, dulog):
    """
    yields partition functions with polynomial data from
    ref. Irwin, A.W., 1981, ApJ Suppl. 45, 621.
    ln u(temp)=sum(a(i)*(ln(temp))**(i-1)) 1<=a<=6

    Input:
      jatom = element number in periodic table
      ion   = 1 for neutral, 2 for once ionized and 3 for twice ionized
      indmol= index of a molecular specie (Tsuji index)
      temp  = temperature
    Output:
      u     = partf.(linear scale) for iat,ion, or indmol, and temperature t
      dulog = d ln(u)/d ln(T)

    对应 tlusty208.f 行 46337–46474

    修改标量哑元 u、dulog
    → 按约定返回全部标量哑元 (jatom, ion, indmol, t, u, dulog)
    """
    global _save_mpartf_iread
    # real*8 a(6,3,92),aa(6),am(6,600)；save iread,a,am（见模块级 _save_mpartf_*）
    a = _save_mpartf_a
    am = _save_mpartf_am
    irw = _save_mpartf_irw                  # 见模块级 TODO（按 SAVE 处理）
    aa = np.zeros(7)                        # aa(6)
    # dimension indtsu(324),irw(600),igle(28)
    # DATA IGLE/.../（不再修改，函数顶部直接赋值）
    igle = np.zeros(29, dtype=np.int64)
    igle[1:] = [2, 1, 2, 1, 6, 9, 4, 9, 6, 1, 2, 1, 6, 9, 4, 9, 6, 1,
                10, 21, 28, 25, 6, 25, 28, 21, 10, 21]
    # DATA indtsu/.../（不再修改；原文含 120*0 与 136*0 重复段）
    indtsu = np.zeros(325, dtype=np.int64)
    indtsu[1:] = ([2, 5, 12, 4, 8, 7, 6,
                   9, 11, 10, 29, 50, 59, 46, 133, 52, 19,
                   13, 42, 38, 39, 37, 44, 36, 14, 118, 33,
                   3, 16, 57, 32, 49, 60, 54, 41, 107, 304,
                   148, 152, 153, 155, 303, 17, 24, 25, 28, 51,
                   112, 119, 102, 0, 21, 15, 43, 22, 478, 64,
                   47, 65, 414, 61, 191, 62, 109, 40, 66, 214]
                  + [0] * 120 + [30] + [0] * 136)

    # data iread /0/（隐含 SAVE，见模块级 _save_mpartf_iread）

    # read data if first call:
    if _save_mpartf_iread != 1:
        if C.irwtab == 0:
            # open(67,file= './data/irwin_orig.dat',status='old')
            open_unit(67, './data/irwin_orig.dat', 'r')
            nmoli = 66
        else:
            # open(67,file= './data/irwin_bc.dat',status='old')
            open_unit(67, './data/irwin_bc.dat', 'r')
            nmoli = 324
        read_line(67)                       # read(67,*)
        read_line(67)                       # read(67,*)
        for j in range(1, 93):
            for i in range(1, 4):
                if j == 1 and i == 3:
                    continue                # GO TO 10
                sp = float(j) + float(i - 1) / 100.0   # 原文赋值后未使用
                # read(67,*) spec,aa（aa 为 6 个值）
                _v = []
                while len(_v) < 7:
                    _v.extend(read_line(67).replace(',', ' ').split())
                spec = float(_v[0])         # 局部变量，原文读后未使用
                for k in range(1, 7):
                    aa[k] = float(_v[k])
                for k in range(1, 7):
                    a[k, i, j] = aa[k]
                # 标号 10

        read_line(67)                       # read(67,*)
        read_line(67)                       # read(67,*)
        read_line(67)                       # read(67,*)
        for i in range(1, 601):
            irw[i] = 0
        for i in range(1, nmoli + 1):
            # read(67,*) spec,aa
            _v = []
            while len(_v) < 7:
                _v.extend(read_line(67).replace(',', ' ').split())
            spec = float(_v[0])
            for k in range(1, 7):
                aa[k] = float(_v[k])
            indm = indtsu[i]
            if indm > 0:
                irw[indm] = i
                for j in range(1, 7):
                    am[j, indm] = aa[j]
        close_unit(67)
        _save_mpartf_iread = 1

    # evaluation of the partition function
    # stop if T is out of limits of Irwin's tables
    u = 1.0
    dulog = 0.0
    if t < 1000.0:
        raise SystemExit('partf; temp<1000 K')   # stop 'partf; temp<1000 K'
    elif t > 16000.0:
        # stop 'partf; temp>16000 K'  —— 原文已注释
        # write(6,601) t                —— 原文已注释
        # 601 format(' warning! T = ',f12.1,  'larger than 16000.'/) —— 原文已注释
        if indmol == 0:
            if jatom <= 28 and ion <= jatom:
                u = float(igle[jatom - ion + 1])   # 整型 DATA 赋实型变量
        return jatom, ion, indmol, t, u, dulog
    tl = math.log(t)
    u = 0.0

    # atomic species
    if jatom > 0 and ion > 0:
        ulog = (a[1, ion, jatom]
                + tl * (a[2, ion, jatom]
                + tl * (a[3, ion, jatom]
                + tl * (a[4, ion, jatom]
                + tl * (a[5, ion, jatom]
                + tl * (a[6, ion, jatom]))))))
        if jatom == 5 and ion == 3:
            ulog = 1.0
        u = math.exp(ulog)
        dulog = (a[2, ion, jatom]
                 + tl * (a[3, ion, jatom] * 2.0
                 + tl * (a[4, ion, jatom] * 3.0
                 + tl * (a[5, ion, jatom] * 4.0
                 + tl * (a[6, ion, jatom] * 5.0)))))

    # molecular species
    if indmol > 0:
        indm = indmol
        if irw[indm] > 0:
            ulog = (am[1, indm]
                    + tl * (am[2, indm]
                    + tl * (am[3, indm]
                    + tl * (am[4, indm]
                    + tl * (am[5, indm]
                    + tl * (am[6, indm]))))))
            u = math.exp(ulog)
            dulog = (am[2, indm]
                     + tl * (am[3, indm] * 2.0
                     + tl * (am[4, indm] * 3.0
                     + tl * (am[5, indm] * 4.0
                     + tl * (am[6, indm] * 5.0)))))
    return jatom, ion, indmol, t, u, dulog


