def rybsol():
    """
    driver of the complete-linearization solution in the Rybicki
    formalism

    对应 tlusty208.f 行 46635–46836
    """
    # COMMON/RYBMTX/...；common/imodlc/imodl0(mlevel) —— 见文件头说明
    # DIMENSION 局部数组（1 基索引）
    al = np.zeros(MDEPTH + 1)               # AL(MDEPTH)
    au = np.zeros(MDEPTH + 1)               # AU(MDEPTH)
    val = np.zeros(MDEPTH + 1)              # VAL(MDEPTH)
    ucol = np.zeros(MDEPTH + 1)             # UCOL(MDEPTH)
    vau = np.zeros((MDEPTH + 1, MDEPTH + 1))   # VAU(MDEPTH,MDEPTH)
    changt = np.zeros(MDEPTH + 1)           # CHANGT(MDEPTH)
    pop1 = np.zeros(MLEVEL + 1)             # pop1(mlevel)
    babs = np.zeros((MLEVEL + 1, MDEPTH + 1))  # babs(mlevel,mdepth)

    # zeroing needed quantities
    for id in range(1, C.ND + 1):
        C.REIT[id] = 0.0
        C.REIN[id] = 0.0
        C.AREIT[id] = 0.0
        C.AREIN[id] = 0.0
        C.CREIT[id] = 0.0
        C.CREIN[id] = 0.0
        C.REDT[id] = 0.0
        C.REDTM[id] = 0.0
        C.REDTP[id] = 0.0
        C.REDN[id] = 0.0
        C.REDNM[id] = 0.0
        C.REDNP[id] = 0.0
        C.FCOOLI[id] = 0.0
        C.FLFIX[id] = 0.0
        C.FLRD[id] = 0.0
        C.ABROSD[id] = 0.0
        C.SUMDPL[id] = 0.0

    # zero vectors and matrices of the Rybicki formalism
    for id in range(1, C.ND + 1):
        C.RA[id] = 0.0
        C.RB[id] = 0.0
        C.RC[id] = 0.0
        C.UA[id] = 0.0
        C.UB[id] = 0.0
        C.UC[id] = 0.0
        C.VA[id] = 0.0
        C.VB[id] = 0.0
        C.VC[id] = 0.0
        C.VR[id] = 0.0
        C.WR[id] = 0.0
        al[id] = 0.0
        au[id] = 0.0
        val[id] = 0.0
        for id1 in range(1, C.ND + 1):
            C.WM[id1, id] = 0.0
            vau[id1, id] = 0.0

    if C.IOPTAB < -1:
        # call setdrt —— 无哑元，直接调用
        setdrt()

    for ij in range(1, C.NFREQ + 1):
        fr = C.FREQ[ij]                     # 局部变量，原文赋值后未使用
        w0 = C.W0E[ij]                      # 局部变量，原文赋值后未使用
        # IF(IOPTAB.GE.0) THEN / CALL OPACTR(IJ) / ELSE / CALL OPACFD(IJ)
        # —— 原文条件已注释，固定调用 OPACTR
        # 以下被调子程序均不修改标量哑元 IJ（已在 tlusty208.f 中核实定义），
        # 故调用点不解包接收
        opactr(ij)
        # CALL OPACFD(IJ) —— 原文注释行
        rtefr1(ij)
        alifr1(ij)
        rosstd(ij)

        rybmat(ij)
        # CALL TRIDAG(RA,RB,RC,VR,AL,ND)：TRIDAG 不修改标量哑元 N（已核实）
        tridag(C.RA, C.RB, C.RC, C.VR, al, C.ND)
        id = 1
        val[id] = val[id] + C.VB[id] * al[id] + C.VC[id] * al[id + 1]
        for id in range(2, C.ND - 1 + 1):
            val[id] = (val[id] + C.VA[id] * al[id - 1] + C.VB[id] * al[id]
                       + C.VC[id] * al[id + 1])
        id = C.ND
        val[id] = val[id] + C.VA[id] * al[id - 1] + C.VB[id] * al[id]

        for idc in range(1, C.ND + 1):
            for id in range(1, C.ND + 1):
                ucol[id] = 0.0
            ucol[idc] = C.UB[idc]
            if idc > 1:
                ucol[idc - 1] = C.UC[idc - 1]
            if idc < C.ND:
                ucol[idc + 1] = C.UA[idc + 1]
            # CALL TRIDAG(RA,RB,RC,UCOL,AU,ND)
            tridag(C.RA, C.RB, C.RC, ucol, au, C.ND)
            id = 1
            vau[id, idc] = (vau[id, idc] + C.VB[id] * au[id]
                            + C.VC[id] * au[id + 1])
            for id in range(2, C.ND - 1 + 1):
                vau[id, idc] = (vau[id, idc]
                                + C.VA[id] * au[id - 1] + C.VB[id] * au[id]
                                + C.VC[id] * au[id + 1])
            id = C.ND
            vau[id, idc] = (vau[id, idc] + C.VA[id] * au[id - 1]
                            + C.VB[id] * au[id])

    for id in range(1, C.ND + 1):
        C.ABROSD[id] = C.SUMDPL[id] / C.ABROSD[id]
        C.FCOOL[id] = (C.REINT[id] * C.FCOOLI[id] * C.DENS[id]
                       - C.REDIF[id] * C.FLFIX[id])
    if C.IOPTAB < 0:
        rosstd(0)

    # final evaluation of matrices and the global inversion
    # call rybene —— 无哑元，直接调用
    rybene()

    for id in range(1, 71, 34):
        # 603 format('rybene ',8x,i4,1p4e11.3)
        # TODO(port): 未模拟 1P 尺度因子
        print('rybene         %4d%11.3e%11.3e%11.3e'
              % (id, C.WM[id, id], C.WM[id, id + 1], C.WR[id]))
    for id in range(1, C.ND + 1):
        for idc in range(1, C.ND + 1):
            C.WM[id, idc] = C.WM[id, idc] - vau[id, idc]
        C.WR[id] = C.WR[id] - val[id]
    # CALL LINEQS(WM,WR,CHANGT,ND,MDEPTH)：LINEQS 不修改标量哑元 N、NR（已核实）
    lineqs(C.WM, C.WR, changt, C.ND, MDEPTH)

    if (not C.LTE) and C.IFRYB > 1:
        C.LTE = True
        iflev0 = C.IFLEV
        C.IFLEV = 1
        for i in range(1, C.NLEVEL + 1):
            C.imodl[i] = C.imodl0[i]
        # call levset —— 无哑元，直接调用
        levset()
        for id in range(1, C.ND + 1):
            # call steqeq(id,pop1,0)：STEQEQ 不修改标量哑元 ID、MODE（已核实）
            steqeq(id, pop1, 0)
            for i in range(1, C.NLEVEL + 1):
                babs[i, id] = UN
                if pop1[i] > 0.0:
                    babs[i, id] = C.POPUL[i, id] / pop1[i]
        C.LTE = False
        C.IFLEV = iflev0
        for i in range(1, C.NLEVEL + 1):
            C.imodl[i] = C.imodl0[i]
        levset()

    if (not C.LTE) and C.IFRYB > 2:
        for ij in range(1, C.NFREQ + 1):
            opactr(ij)
            rtefr1(ij)
            alifr1(ij)
            rosstd(ij)
            rybmat(ij)
            id = 1
            C.WR[id] = (C.VR[id] - C.UB[id] * changt[id]
                        - C.UC[id] * changt[id + 1])
            for id in range(2, C.ND - 1 + 1):
                C.WR[id] = (C.VR[id] - C.UA[id] * changt[id - 1]
                            - C.UB[id] * changt[id]
                            - C.UC[id] * changt[id + 1])
            id = C.ND
            C.WR[id] = (C.VR[id] - C.UA[id] * changt[id - 1]
                        - C.UB[id] * changt[id])
            # CALL TRIDAG(RA,RB,RC,WR,AL,ND)
            tridag(C.RA, C.RB, C.RC, C.WR, al, C.ND)
            C.RAD[ij, id] = C.RAD1[id] + al[id]

    # call rybchn(changt)：CHANGT 为数组哑元，按引用共享
    rybchn(changt)

    if (not C.LTE) and C.IFRYB > 1:
        C.LTE = True
        iflev0 = C.IFLEV
        C.IFLEV = 1
        for i in range(1, C.NLEVEL + 1):
            C.imodl[i] = C.imodl0[i]
        levset()
        for id in range(1, C.ND + 1):
            # call steqeq(id,pop1,0)
            steqeq(id, pop1, 0)
            for i in range(1, C.NLEVEL + 1):
                C.POPUL[i, id] = pop1[i] * babs[i, id]
        C.LTE = False
        C.IFLEV = iflev0
        for i in range(1, C.NLEVEL + 1):
            C.imodl[i] = C.imodl0[i]
        levset()

    return


def rybmat(ij):
    """
    evaluation of the complete-linearization matrices in the Rybicki
    formalism

    对应 tlusty208.f 行 46841–47230
    """
    # COMMON/RYBMTX/...；common/dsctva/dsct1,dscn1 —— 见文件头说明
    # PARAMETER (SIXTH=UN/6.D0, THIRD=UN/3.D0, TWOTHR=TWO/3.D0)
    SIXTH = UN / 6.0
    THIRD = UN / 3.0
    TWOTHR = TWO / 3.0
    # TODO(port): 局部变量 icentr 在全程序中从未声明（不在任何 COMMON 中）
    # 也未赋值——Fortran 下为未初始化局部量（通常实际为 0）；此处置 0
    icentr = 0
    # TODO(port): 局部变量 a2 在 IDISK≠0 分支（行 47092）被引用时，
    # 其值是前面正常深度点循环最后一次迭代的留存（Fortran 静态语义）；
    # 若循环未执行则未定义，此处置 0.0
    a2 = 0.0

    ijt = C.IJFR[ij]

    # ==============================================================
    # 1. components corresponding to the radiative transfer equation
    # ==============================================================

    # -----------------------------------
    # ID = 1  -  upper boundary condition
    id = 1
    ddm = (C.DM[id + 1] - C.DM[id]) * HALF
    dtm = UN / ((C.ABSO1[id] + C.ABSO1[id + 1]) * ddm)
    dtm2 = dtm * dtm
    alf = dtm * ddm
    fd = TWO * C.FH[ij]
    exti = C.EXTRAD[ij]
    bet = (exti - fd * C.RAD1[id]) * dtm
    gam = (C.FAK1[id] * C.RAD1[id] - C.FAK1[id + 1] * C.RAD1[id + 1]) * TWO * dtm2
    s0 = (C.EMIS1[id] + C.SCAT1[id] * C.RAD1[id]) / C.ABSO1[id]
    c1 = alf * (TWO * gam - bet)
    b1 = c1 - s0 / C.ABSO1[id]
    unq = UN + TWO * dtm * C.Q0[ij]
    # unq=un —— 原文注释行
    C.RB[id] = (-(UN + dtm * (fd + TWO * C.FAK1[id] * dtm))
                + C.SCAT1[id] / C.ABSO1[id] * unq)
    C.RC[id] = TWO * C.FAK1[id + 1] * dtm2
    C.VR[id] = gam - bet + C.RAD1[id] - s0 * unq
    C.UB[id] = (b1 * C.DABT1[id] + (C.DEMT1[id]
                + C.dsct1[id] * C.RAD1[id]) / C.ABSO1[id] * unq
                - C.EMIS1[id] / C.ABSO1[id] ** 2 * C.DABT1[id] * TWO * dtm * C.Q0[ij]
                + dtm * s0 * (C.UU0[ij] * C.DM[1] * C.DABT1[id]
                - TWO * C.Q0[ij] * dtm * ddm * C.DABT1[id]))
    C.UC[id] = (c1 * C.DABT1[id + 1]
                - TWO * dtm * C.Q0[ij] * s0 * dtm * ddm * C.DABT1[id + 1])

    if C.IUBC > 0:
        corf = HALF / dtm
        C.RB[id] = C.RB[id] * corf
        C.RC[id] = C.RC[id] * corf
        C.VR[id] = C.VR[id] * corf
        c1 = (gam - C.RAD1[id] + s0) * corf * alf
        b1 = c1 - corf * s0 / C.ABSO1[id]
        C.UB[id] = (b1 * C.DABT1[id] + (C.DEMT1[id]
                    + C.dsct1[id] * C.RAD1[id]) / C.ABSO1[id] * corf)
        C.UC[id] = c1 * C.DABT1[id + 1]

    # ----------------------------------
    # 1 < ID < ND  -  normal depth point
    for id in range(2, C.ND - 1 + 1):
        ddm = (C.DM[id] - C.DM[id - 1]) * HALF
        ddp = (C.DM[id + 1] - C.DM[id]) * HALF
        dzm = C.ABSO1[id] + C.ABSO1[id - 1]
        dzp = C.ABSO1[id] + C.ABSO1[id + 1]
        dtaup = dzp * ddp
        dtaum = dzm * ddm
        dtau0 = HALF * (dtaup + dtaum)
        frd = C.FAK1[id] * C.RAD1[id]
        alf1 = (frd - C.FAK1[id + 1] * C.RAD1[id + 1]) / dtaup / dtau0
        gam1 = (frd - C.FAK1[id - 1] * C.RAD1[id - 1]) / dtaum / dtau0
        bet1 = alf1 + gam1
        x1 = HALF * bet1 / dtau0
        a1 = (gam1 + x1 * dtaum) / dzm
        c1 = (alf1 + x1 * dtaup) / dzp
        b1 = a1 + c1
        bs = UN
        chielm = C.SCAT1[id - 1]
        chiel0 = C.SCAT1[id]
        chielp = C.SCAT1[id + 1]
        s0 = (C.EMIS1[id] + chiel0 * C.RAD1[id]) / C.ABSO1[id]
        as_ = 0.0                           # AS（Python 关键字 as，加下划线）
        cs = 0.0
        a2 = 0.0
        c2 = 0.0
        a3 = 0.0
        c3 = 0.0
        bet2 = 0.0
        sm = 0.0
        sp = 0.0
        # IF(MOD(ISPLIN,3).EQ.0) GO TO 60 → 条件成立时跳过下面整块到标号 60
        if imod(C.ISPLIN, 3) != 0:
            sm = (C.EMIS1[id - 1] + C.RAD1[id - 1] * chielm) / C.ABSO1[id - 1]
            sp = (C.EMIS1[id + 1] + C.RAD1[id + 1] * chielp) / C.ABSO1[id + 1]
            if C.ISPLIN == 1:

                # spline collocation (ISPLIN=1)
                as_ = dtaum / dtau0 * SIXTH
                cs = dtaup / dtau0 * SIXTH
                bs = 0.666666666666667
                alf2 = as_ * (C.RAD1[id - 1] - sm)
                gam2 = cs * (C.RAD1[id + 1] - sp)
                bet2 = alf2 + gam2
                x = HALF * bet2 / dtau0
                a2 = (gam2 - x * dtaum) / dzm
                c2 = (alf2 - x * dtaup) / dzp
            else:

                # Hermitian method (ISPLIN=2)
                as_ = dtaup * dtaup / dtaum / dtau0
                cs = dtaum * dtaum / dtaup / dtau0
                al3 = (C.RAD1[id + 1] - sp - C.RAD1[id] + s0) * SIXTH
                ga3 = (C.RAD1[id - 1] - sm - C.RAD1[id] + s0) * SIXTH
                av = al3 * cs
                cv = ga3 * as_
                as_ = (UN - HALF * as_) * SIXTH
                cs = (UN - HALF * cs) * SIXTH
                bs = UN - as_ - cs
                x = (av + cv) / dtau0 / 4.0
                a2 = (x * dtaum + HALF * cv - av) / dzm
                c2 = (x * dtaup + HALF * av - cv) / dzp
                bet2 = as_ * (C.RAD1[id - 1] - sm) + cs * (C.RAD1[id + 1] - sp)

            # auxiliary quantities
            b1 = b1 - (a2 + c2)
            a1 = a1 - a2
            c1 = c1 - c2
            a2 = as_ / C.ABSO1[id - 1]
            c2 = cs / C.ABSO1[id + 1]
            a3 = a2 * sm
            c3 = c2 * sp

        # 标号 60
        b2 = bs / C.ABSO1[id]
        b3 = b2 * s0
        a1 = a1 - a3
        b1 = b1 - b3
        c1 = c1 - c3

        # *** elements of the matrices
        C.RA[id] = (C.FAK1[id - 1] / dtaum / dtau0
                    - as_ * (UN - chielm / C.ABSO1[id - 1]))
        C.RB[id] = (-C.FAK1[id] / dtau0 * (UN / dtaup + UN / dtaum)
                    - bs * (UN - chiel0 / C.ABSO1[id]))
        C.RC[id] = (C.FAK1[id + 1] / dtaup / dtau0
                    - cs * (UN - chielp / C.ABSO1[id + 1]))
        C.VR[id] = bet1 + bet2 + bs * (C.RAD1[id] - s0)
        C.UA[id] = (a1 * C.DABT1[id - 1]
                    + a2 * (C.DEMT1[id - 1] + C.dsct1[id - 1] * C.RAD1[id - 1]))
        C.UB[id] = (b1 * C.DABT1[id]
                    + b2 * (C.DEMT1[id] + C.dsct1[id] * C.RAD1[id]))
        C.UC[id] = (c1 * C.DABT1[id + 1]
                    + c2 * (C.DEMT1[id + 1] + C.dsct1[id + 1] * C.RAD1[id + 1]))

    # ----------------------------------
    # ID=ND  -  lower boundary condition
    id = C.ND
    ddm = HALF * (C.DM[id] - C.DM[id - 1])
    t0 = C.TEMP[id]
    tm = C.TEMP[id - 1]
    if C.IBC > 0 and C.IBC < 4 and C.IDISK == 0:
        dtm = UN / ((C.ABSO1[id - 1] + C.ABSO1[id]) * ddm)
        dtm2 = dtm * dtm
        fd = TWO * C.FHD[ijt]
        fr = C.FREQ[ijt]
        fr15 = fr * 1.0e-15
        bnu = BN * fr15 * fr15 * fr15
        x0 = HK * fr / t0
        xm = HK * fr / tm
        pland = bnu / (math.exp(x0) - UN)
        planm = bnu / (math.exp(xm) - UN)
        dpldt0 = pland / (UN - math.exp(-x0)) * x0 / t0
        dpldtm = planm / (UN - math.exp(-xm)) * xm / tm
        dplan = (pland - planm) * dtm       # 局部变量，原文赋值后未使用
        alf = dtm * ddm
        bet = (pland - fd * C.RAD1[id]) * dtm
        gam = ((C.FAK1[id] * C.RAD1[id] - C.FAK1[id - 1] * C.RAD1[id - 1]
                - THIRD * (pland - planm)) * TWO * dtm2)
        s0 = (C.EMIS1[id] + C.SCAT1[id] * C.RAD1[id]) / C.ABSO1[id]
        a1 = alf * (TWO * gam - bet)
        b1 = a1 - s0 / C.ABSO1[id]
        C.RA[id] = TWO * C.FAK1[id - 1] * dtm2
        C.RB[id] = (-(UN + dtm * (fd + TWO * C.FAK1[id] * dtm))
                    + C.SCAT1[id] / C.ABSO1[id])
        C.VR[id] = gam - bet + C.RAD1[id] - s0
        C.UA[id] = (b1 * C.DABT1[id - 1]
                    + (C.DEMT1[id - 1]
                    + C.dsct1[id - 1] * C.RAD1[id - 1]) / C.ABSO1[id - 1]
                    - dpldtm * dtm2 * TWOTHR)
        C.UB[id] = (b1 * C.DABT1[id] + (C.DEMT1[id]
                    + C.dsct1[id] * C.RAD1[id]) / C.ABSO1[id]
                    + dpldt0 * dtm * (UN + TWOTHR * dtm))

        if C.IFRYB > 0:
            dtm = UN / ((C.ABSO1[id - 1] + C.ABSO1[id]) * ddm)
            fr = C.FREQ[ijt]
            fr15 = fr * 1.0e-15
            bnu = BN * fr15 * fr15 * fr15
            x0 = HK * fr / t0
            xm = HK * fr / tm
            pland = bnu / (math.exp(x0) - UN)
            planm = bnu / (math.exp(xm) - UN)
            dpldt0 = pland / (UN - math.exp(-x0)) * x0 / t0
            dpldtm = planm / (UN - math.exp(-xm)) * xm / tm
            gam = ((C.FAK1[id] * C.RAD1[id] - C.FAK1[id - 1] * C.RAD1[id - 1]
                    - THIRD * (pland - planm)) * dtm)
            s0 = (C.EMIS1[id] + C.SCAT1[id] * C.RAD1[id]) / C.ABSO1[id]
            bs = HALF / dtm
            bet = bs * (C.RAD1[id] - s0)
            a1 = (gam - bet) * dtm * ddm
            b1 = a1 - bs * s0 / C.ABSO1[id]
            C.RA[id] = C.FAK1[id - 1] * dtm
            C.RB[id] = (-C.FAK1[id] * dtm - bs * (UN - C.SCAT1[id] / C.ABSO1[id])
                        - C.FHD[ijt])
            C.VR[id] = gam + bet - HALF * pland + C.FHD[ijt] * C.RAD1[id]
            C.UA[id] = a1 * C.DABT1[id - 1] - dpldtm * dtm * THIRD
            C.UB[id] = (b1 * C.DABT1[id]
                        + bs * (C.DEMT1[id] + C.dsct1[id] * C.RAD1[id]) / C.ABSO1[id]
                        + (HALF + THIRD * dtm) * dpldt0)

    else:

        # for disks -
        # lower b.c. expresses just I(taumax,-mu,nu)=I(taumax,+mu,nu)
        dzm = C.ABSO1[id] + C.ABSO1[id - 1]
        frd = C.FAK1[id] * C.RAD1[id] - C.FAK1[id - 1] * C.RAD1[id - 1]
        dtaum = dzm * ddm
        gam1 = frd / dtaum
        a1 = gam1 / dzm
        as_ = 0.0
        bs = dtaum * HALF
        s0 = (C.EMIS1[id] + C.SCAT1[id] * C.RAD1[id]) / C.ABSO1[id]
        gam2 = bs * (C.RAD1[id] - s0)
        x1 = gam2 / dzm
        a1 = a1 - x1
        b2 = bs / C.ABSO1[id]
        b1 = a1 - b2 * s0
        C.RA[id] = (C.FAK1[id - 1] / dtaum
                    - as_ * (UN - C.SCAT1[id - 1] / C.ABSO1[id - 1]))
        C.RB[id] = (-C.FAK1[id] / dtaum
                    - bs * (UN - C.SCAT1[id] / C.ABSO1[id]))
        C.UA[id] = (a1 * C.DABT1[id - 1]
                    + a2 * (C.DEMT1[id - 1] + C.dsct1[id - 1] * C.RAD1[id - 1]))
        C.UB[id] = (b1 * C.DABT1[id]
                    + b2 * (C.DEMT1[id] + C.dsct1[id] * C.RAD1[id]))
        C.VR[id] = gam1 + gam2

    # =====================================================
    # components corresponding to the radiative equilibrium
    # =====================================================
    for id in range(1, C.ND + 1):

        # *********     integral equation part
        if C.REINT[id] > 0.0:
            heat = C.ABSO1[id] - C.SCAT1[id]
            dheat = (C.DABT1[id] - C.dsct1[id]) * C.RAD1[id]
            wdr = C.W[ij] * C.DENS[id] * C.REINT[id]
            C.VB[id] = heat * wdr
            C.WM[id, id] = C.WM[id, id] + (dheat - C.DEMT1[id]) * wdr
            C.WR[id] = C.WR[id] - (heat * C.RAD1[id] - C.EMIS1[id]) * wdr

    # *********     differential equation part
    id = 1
    if C.REDIF[id] > 0.0:
        wf = C.W[ij] * C.FH[ijt] * C.REDIF[id]
        C.VB[id] = C.VB[id] + wf
        C.WR[id] = C.WR[id] - wf * C.RAD1[id]

    # original variant with 1st-order mid-point differences
    if icentr == 0:
        nd1 = C.ND
        if C.ilbc != 0:
            nd1 = C.ND - 1
        for id in range(2, nd1 + 1):
            if C.REDIF[id] > 0.0:
                ddm = (C.DM[id] - C.DM[id - 1]) * HALF
                omeg0 = C.ABSO1[id]
                omegm = C.ABSO1[id - 1]
                dtaum = (omeg0 + omegm) * ddm
                frd = C.FAK1[id] * C.RAD1[id] - C.FAK1[id - 1] * C.RAD1[id - 1]
                gamr = frd / dtaum * C.REDIF[id]
                a1 = gamr / (omeg0 + omegm)
                C.VA[id] = -C.W[ij] * C.FAK1[id - 1] / dtaum * C.REDIF[id]
                C.VB[id] = C.VB[id] + C.W[ij] * C.FAK1[id] / dtaum * C.REDIF[id]
                C.WM[id, id - 1] = C.WM[id, id - 1] - a1 * C.W[ij] * C.DABT1[id - 1]
                C.WM[id, id] = C.WM[id, id] - a1 * C.W[ij] * C.DABT1[id]
                C.WR[id] = C.WR[id] - C.W[ij] * gamr

        if C.ilbc > 0:
            id = C.ND
            if C.REDIF[id] > 0.0:
                ddm = (C.DM[id] - C.DM[id - 1]) * HALF
                dtaum = (C.ABSO1[id] + C.ABSO1[id - 1]) * ddm * 3.0
                fr = C.FREQ[ijt]
                fr15 = fr * 1.0e-15
                bnu = BN * fr15 * fr15 * fr15
                x0 = HK * fr / C.TEMP[id]
                xm = HK * fr / C.TEMP[id - 1]
                pland = bnu / (math.exp(x0) - UN)
                planm = bnu / (math.exp(xm) - UN)
                dpldt0 = pland / (UN - math.exp(-x0)) * x0 / C.TEMP[id]
                dpldtm = planm / (UN - math.exp(-xm)) * xm / C.TEMP[id - 1]
                flx = (pland - planm) / dtaum * C.REDIF[id]
                a1 = flx / (C.ABSO1[id] + C.ABSO1[id - 1])
                C.WM[id, id - 1] = (C.WM[id, id - 1]
                                    + C.W[ij] * (dpldtm - a1 * C.DABT1[id - 1]))
                C.WM[id, id] = (C.WM[id, id]
                                + C.W[ij] * (dpldt0 - a1 * C.DABT1[id]))
                C.WR[id] = C.WR[id] - C.W[ij] * flx

    # centered difference variant
    else:
        for id in range(2, C.ND - 1 + 1):
            if C.REDIF[id] > 0.0:
                wwr = C.W[ij] * C.REDIF[id]
                ddm = HALF * (C.DM[id] - C.DM[id - 1])
                ddp = HALF * (C.DM[id + 1] - C.DM[id])
                dtm = (C.ABSO1[id - 1] + C.ABSO1[id]) * ddm
                dtp = (C.ABSO1[id + 1] + C.ABSO1[id]) * ddp
                dt0 = dtm + dtp
                frm = C.FAK1[id] * C.RAD1[id] - C.FAK1[id - 1] * C.RAD1[id - 1]
                frp = C.FAK1[id + 1] * C.RAD1[id + 1] - C.FAK1[id] * C.RAD1[id]
                alp = dtp / dtm / dt0
                gam = dtm / dtp / dt0
                flx = alp * frm + gam * frp

                # matrix elements
                C.VA[id] = -wwr * C.FAK1[id - 1] * alp
                C.VB[id] = C.VB[id] + wwr * C.FAK1[id] * (alp - gam)
                C.VC[id] = wwr * C.FAK1[id + 1] * gam

                dmtm = ddm / (dtm * dtm)
                dmtp = ddp / (dtp * dtp)
                rm = dtm / dt0
                rp = dtp / dt0
                C.WM[id, id - 1] = (C.WM[id, id - 1] + wwr * C.DABT1[id - 1] * dmtm
                                    * (rm * rm * frp - (UN + rm) * frm))
                # TODO(port): 原文下行第二项括号不对称
                # （(dmtm*rm*rm-dmtp*rm*(un+rp)*frp)，frp 在括号内），直译保留
                C.WM[id, id] = (C.WM[id, id] + wwr * C.DABT1[id]
                                * ((dmtp * rp * rp - dmtm * rp * (UN + rm)) * frm
                                + (dmtm * rm * rm - dmtp * rm * (UN + rp) * frp)))
                C.WR[id] = C.WR[id] - wwr * flx

        id = C.ND
        if C.REDIF[id] > 0.0:
            ddm = (C.DM[id] - C.DM[id - 1]) * HALF
            dtaum = (C.ABSO1[id] + C.ABSO1[id - 1]) * ddm
            frd = C.FAK1[id] * C.RAD1[id] - C.FAK1[id - 1] * C.RAD1[id - 1]
            flx = frd / dtaum * C.REDIF[id]
            a1 = flx / (C.ABSO1[id] + C.ABSO1[id - 1])
            C.VA[id] = -C.W[ij] * C.FAK1[id - 1] / dtaum * C.REDIF[id]
            C.VB[id] = C.VB[id] + C.W[ij] * C.FAK1[id] / dtaum * C.REDIF[id]
            C.WM[id, id - 1] = C.WM[id, id - 1] - a1 * C.W[ij] * C.DABT1[id - 1]
            C.WM[id, id] = C.WM[id, id] - a1 * C.W[ij] * C.DABT1[id]
            C.WR[id] = C.WR[id] - C.W[ij] * flx

    if C.NRETC > 0:
        for id in range(1, C.NRETC + 1):
            C.WR[id] = 0.0
            C.VB[id] = 0.0
            C.VA[id] = 0.0
            C.WM[id, id] = 1.0
            if id > 1:
                C.WM[id, id - 1] = 0.0
    return


