    if t >= 9000.0:
        return sbfch
    if n < 20:
        return sbfch
    if n >= 105:
        return sbfch
    it = int((t - 1000.0) * twhui + 1.0)
    if it < 1:
        it = 1
    tn = float(it) * twhu + 800.0
    part = partcha[it] + (partcha[it + 1] - partcha[it]) * (t - tn) * twhui

    # interpolate to obtain cross-section
    it = int((t - 2000.0) * fihui + 1.0)
    if it < 1:
        it = 1
    tn = float(it) * fihu + 1500.0
    chop = (math.exp((_save_sbfch_crosscht[it]
                     + (_save_sbfch_crosscht[it + 1] - _save_sbfch_crosscht[it])
                     * (t - tn) * fihui) * tenl) * part)
    # TODO(port): 原代码把最终结果赋给 CHOP 而不是函数名 SBFCH（48713 行），
    # 因此函数实际恒返回 0；疑为原代码 bug，直译保留（chop 算后未用）。
    return sbfch


