def h2minus(t, anh2, ane, fr, oph2m):
    """
    H- free-free opacity

    K L Bell 1980 J. Phys. B: At. Mol. Phys. 13 1859, Table 1
    The first column is theta=5040/T(K)
    The first row are names for each row corresponding to lambda (angstroms)
    The last row for 10.0 is linearly extrapolated
    The units of everything else is 10^26 cm4/dyn-1

    对应 tlusty208.f 行 49669–49768

    修改标量哑元 OPH2M → 按约定返回全部标量哑元 (t, anh2, ane, fr, oph2m)。
    """
    # dimension FFthet(9),FFlamb(18),FFkapp(18,9) —— DATA 初始化且不再修改
    ffthet = [  # DATA
        0.5, 0.8, 1.0, 1.2, 1.6, 2.0, 2.8, 3.6,
        10.0
        ]
    fflamb = [  # DATA
        151883., 113913., 91130., 60753., 45565., 36452., 30377., 22783.,
        18226., 15188., 11391., 9113., 7594., 6509., 5696., 5063.,
        4142., 3505.
        ]
    ffkapp_flat = [  # DATA
        7.16e+01, 4.03e+01, 2.58e+01, 1.15e+01, 6.47e+00, 4.15e+00, 2.89e+00, 1.63e+00,
        1.05e+00, 7.36e-01, 4.20e-01, 2.73e-01, 1.92e-01, 1.43e-01, 1.10e-01, 8.70e-02,
        5.84e-02, 4.17e-02, 9.23e+01, 5.20e+01, 3.33e+01, 1.48e+01, 8.37e+00, 5.38e+00,
        3.76e+00, 2.14e+00, 1.39e+00, 9.75e-01, 5.64e-01, 3.71e-01, 2.64e-01, 1.98e-01,
        1.54e-01, 1.24e-01, 8.43e-02, 6.10e-02, 1.01e+02, 5.70e+01, 3.65e+01, 1.63e+01,
        9.20e+00, 5.92e+00, 4.14e+00, 2.36e+00, 1.54e+00, 1.09e+00, 6.35e-01, 4.22e-01,
        3.03e-01, 2.30e-01, 1.80e-01, 1.46e-01, 1.01e-01, 7.34e-02, 1.08e+02, 6.08e+01,
        3.90e+01, 1.74e+01, 9.84e+00, 6.35e+00, 4.44e+00, 2.55e+00, 1.66e+00, 1.18e+00,
        6.97e-01, 4.67e-01, 3.39e-01, 2.59e-01, 2.06e-01, 1.67e-01, 1.17e-01, 8.59e-02,
        1.18e+02, 6.65e+01, 4.27e+01, 1.91e+01, 1.08e+01, 6.99e+00, 4.91e+00, 2.84e+00,
        1.87e+00, 1.34e+00, 8.06e-01, 5.52e-01, 4.08e-01, 3.17e-01, 2.55e-01, 2.10e-01,
        1.49e-01, 1.11e-01, 1.26e+02, 7.08e+01, 4.54e+01, 2.04e+01, 1.16e+01, 7.50e+00,
        5.28e+00, 3.07e+00, 2.04e+00, 1.48e+00, 9.09e-01, 6.33e-01, 4.76e-01, 3.75e-01,
        3.05e-01, 2.53e-01, 1.82e-01, 1.37e-01, 1.38e+02, 7.76e+01, 4.98e+01, 2.24e+01,
        1.28e+01, 8.32e+00, 5.90e+00, 3.49e+00, 2.36e+00, 1.74e+00, 1.11e+00, 7.97e-01,
        6.13e-01, 4.92e-01, 4.06e-01, 3.39e-01, 2.49e-01, 1.87e-01, 1.47e+02, 8.30e+01,
        5.33e+01, 2.40e+01, 1.38e+01, 9.02e+00, 6.44e+00, 3.90e+00, 2.68e+00, 2.01e+00,
        1.32e+00, 9.63e-01, 7.51e-01, 6.09e-01, 5.07e-01, 4.27e-01, 3.16e-01, 2.40e-01,
        2.19e+02, 1.26e+02, 8.13e+01, 3.68e+01, 2.18e+01, 1.46e+01, 1.08e+01, 7.18e+00,
        5.24e+00, 4.17e+00, 3.00e+00, 2.29e+00, 1.86e+00, 1.55e+00, 1.32e+00, 1.13e+00,
        8.52e-01, 6.64e-01
        ]
    nthet = 9                                     # data nthet /9/
    nlamb = 18                                    # data nlamb /18/
    # 转为 1 基索引（索引 0 不用）
    ffthet = [0.0] + ffthet
    fflamb = [0.0] + fflamb
    ffkapp = np.zeros((19, 10))
    ffkapp[1:, 1:] = np.array(ffkapp_flat, dtype=float).reshape(
        18, 9, order='F')
    # TODO(port): 原代码 49749 行 `else if (i.eq.0 .or. i.eq.nlines)` 引用了
    # 未声明的变量 nlines（本例程中无此 PARAMETER，疑为 nlamb 之笔误；
    # 其余 cia_* 例程均有 parameter(nlines=...)）。直译时取 nlines=0，
    # 使 i.eq.nlines 在 i>=1 时恒为假。
    nlines = 0

    # locate position in temperature array
    theta = 5040.0 / t

    nthet, theta, j, _nxdim = locate(ffthet, nthet, theta, 0, nthet)
    if j == 0:
        print()
        # write(*,'(a,f6.0,a)') 'Error: requested temperature is outside
        # the ranges' —— 格式中 f6.0 无对应实参，Fortran 只输出前导字符串
        print('Error: requested temperature is outside the ranges')
        print('h2minus:Stop')
        print()
        raise SystemExit                            # STOP
    flamb = 2.997925e18 / fr
    # locate position in wavelength array
    nlamb, flamb, i, _nxdim = locate(fflamb, nlamb, flamb, 0, nlamb)

    # linearly interpolate in frequency and temperature
    if j == nthet:
        # hold values constant if off high temperature end of table
        y1 = ffkapp[i, j]
        y2 = ffkapp[i + 1, j]
        tt = (flamb - fflamb[i]) / (fflamb[i + 1] - fflamb[i])
        fkappa = (1.0 - tt) * y1 + tt * y2
    elif i == 0 or i == nlines:
        # set values to 0 if off frequency table
        fkappa = 0.0
    else:
        # interpolate linearly within table
        y1 = ffkapp[i, j]
        y2 = ffkapp[i + 1, j]
        y3 = ffkapp[i + 1, j + 1]
        y4 = ffkapp[i, j + 1]

        tt = (flamb - fflamb[i]) / (fflamb[i + 1] - fflamb[i])
        uu = (theta - ffthet[j]) / (ffthet[j + 1] - ffthet[j])

        fkappa = ((1.0 - tt) * (1.0 - uu) * y1 + tt * (1.0 - uu) * y2
                  + tt * uu * y3 + (1.0 - tt) * uu * y4)
    pe = ane * BOLK * t
    oph2m = anh2 * 1.0e-26 * pe * fkappa
    return t, anh2, ane, fr, oph2m


def prnt():
    """
    （原代码无头部注释；诊断打印例程，全部 WRITE 已被原作者注释掉）

    对应 tlusty208.f 行 49775–49847
    """
    ipop = [0, 98, 99, 100, 115]                    # data ipop /98,99,100,115/

    for id in range(1, C.ND + 1, 69):
        hkt = HK / C.TEMP[id]
        ane = C.ELEC[id]
        sabolf(id)
        # do k=1,4  （原代码注释掉）
        for k in range(3, 4):                       # do k=3,3
            ii = ipop[k] - 3
            iat = C.IATM[ii]
            ie = C.IEL[ii]
            psum = 0.0
            psuu = 0.0
            for j in range(C.N0A[iat], C.NKA[iat] + 1):
                psum = psum + C.POPUL[j, id]
                if C.ILK[j] > 0:
                    psuu = (psuu + C.USUM[C.ILK[j]] * C.ELEC[id]
                            * C.POPUL[j, id])
            bb = C.DENS[id] / C.WMM[id] / C.YTOT[id] * C.ABUND[iat, id]
            rin = 0.0
            rou = 0.0
            # write(63,601) id,ii,psum,bb,popul(ii,id)  （原代码注释掉）
            for jj in range(C.NFIRST[ie], ii):
                itr = C.ITRA[jj, ii]
                ru = C.RRU[itr, id] * C.wop[ii, id]
                cu = C.COLRAT[itr, id] * C.wop[ii, id]
                if ii <= C.NLAST[ie]:
                    rd = (C.RRD[itr, id] * C.G[jj] / C.G[ii]
                          * math.exp(hkt * C.FR0[itr]) * C.wop[jj, id])
                else:
                    rd = C.RRD[itr, id] * C.SBF[jj] * ane * C.wop[jj, id]
                cd = C.COLTAR[itr, id] * C.wop[jj, id]
                # write(63,602) jj,itr,popul(jj,id),ru,cu,rd,cd  （注释掉）
                rin = rin + (ru + cu) * C.POPUL[jj, id]
                rou = rou + (rd + cd) * C.POPUL[ii, id]

            for jj in range(ii + 1, C.NNEXT[ie] + 1):
                itr = C.ITRA[ii, jj]
                ru = C.RRU[itr, id] * C.wop[jj, id]
                cu = C.COLRAT[itr, id] * C.wop[jj, id]
                if jj <= C.NLAST[ie]:
                    rd = (C.RRD[itr, id] * C.G[ii] / C.G[jj]
                          * math.exp(hkt * C.FR0[itr]) * C.wop[ii, id])
                else:
                    rd = C.RRD[itr, id] * C.SBF[ii] * ane * C.wop[ii, id]
                cd = C.COLTAR[itr, id] * C.wop[ii, id]
                # write(63,602) jj,itr,popul(jj,id),rd,cd,ru,cu  （注释掉）
                rou = rou + (ru + cu) * C.POPUL[ii, id]
                rin = rin + (rd + cd) * C.POPUL[jj, id]

            # write(63,603) id,ii,rou,rin,(rou-rin)/rin  （原代码注释掉）
        # write(63,*)  （原代码注释掉）
    # write(63,*) '=============================='  （原代码注释掉）
    # write(63,*)
    # 601 format('id,ii',2i4,1p4e12.4)
    # 602 format('   jj    ',i4,i5,1p5e12.4)
    # 603 format('iitot',2i4,1p3e12.4/)
    return


def rechck():
    """
    check of radiative equilibrium - integral version

    对应 tlusty208.f 行 49853–49887
    """
    abt = np.zeros(MDEPTH + 1)
    emt = np.zeros(MDEPTH + 1)

    for id in range(1, C.ND + 1):
        abt[id] = 0.0
        emt[id] = 0.0

    for ij in range(1, C.NFREQ + 1):
        opacf1(ij)
        rtefr1(ij)
        for id in range(1, C.ND + 1):
            abt[id] = (abt[id] + (C.ABSO1[id] - C.SCAT1[id])
                       * C.RAD1[id] * C.W[ij])
            emt[id] = emt[id] + C.EMIS1[id] * C.W[ij]

    # 600 format(/' id     dm         T     int(kappa*J)  int(emis)   rel'/)
    write_line(17, '')
    write_line(17, ' id     dm         T     int(kappa*J)  int(emis)   rel')
    write_line(17, '')
    for id in range(1, C.ND + 1):
        re = (abt[id] - emt[id]) / emt[id]
        # 601 format(i4,1pe11.3,0pf10.1,2x,1p3e13.5)
        write_line(17, '%4d%11.3e%10.1f  %13.5e%13.5e%13.5e'
                   % (id, C.DM[id], C.TEMP[id], abt[id], emt[id], re))
    return


# LYMLIN：INIP 为 DATA 且被修改（隐含 SAVE）→ 模块级；XKIJL/FIJL/WL0L/FR0L/
# F00/DOP0/PJ/ABTR/EMTR/FID/AD0/DIV0/DBET0/BETAD0 只在 INIP==1 时填一次、
# 之后每次调用都要用 → 必须跨调用保持，提升为模块级。
_save_lymlin_inip = 1                             # DATA INIP/1/
_save_lymlin_xkijl = np.zeros(31)                 # XKIJL(30)
_save_lymlin_fijl = np.zeros(31)                  # FIJL(30)
_save_lymlin_wl0l = np.zeros(31)                  # WL0L(30)
_save_lymlin_fr0l = np.zeros(31)                  # FR0L(30)
_save_lymlin_f00 = np.zeros(MDEPTH + 1)           # F00(MDEPTH)
_save_lymlin_dop0 = np.zeros(MDEPTH + 1)          # DOP0(MDEPTH)
_save_lymlin_pj = np.zeros((31, MDEPTH + 1))      # PJ(30,MDEPTH)
_save_lymlin_abtr = np.zeros((31, MDEPTH + 1))    # ABTR(30,MDEPTH)
_save_lymlin_emtr = np.zeros((31, MDEPTH + 1))    # EMTR(30,MDEPTH)
_save_lymlin_fid = np.zeros((31, MDEPTH + 1))     # FID(30,MDEPTH)
_save_lymlin_ad0 = np.zeros((31, MDEPTH + 1))     # AD0(30,MDEPTH)
_save_lymlin_div0 = np.zeros((31, MDEPTH + 1))    # DIV0(30,MDEPTH)
_save_lymlin_dbet0 = np.zeros((31, MDEPTH + 1))   # DBET0(30,MDEPTH)
_save_lymlin_betad0 = np.zeros((31, MDEPTH + 1))  # BETAD0(30,MDEPTH)


def lymlin(ij):
    """
    opacity and emissibvity in first 30 Lyman lines

    对应 tlusty208.f 行 49893–50007
    """
    global _save_lymlin_inip
    sixth = 1.0 / 6.0                               # PARAMETER（算后未用）
    ttw = 2.0 / 3.0
    os0 = 0.02654
    cpp = 4.1412e-16
    cpj = 157803.0
    c00 = 1.25e-9
    c18 = 2.997925e18
    mlevl = 30                                      # PARAMETER (MLEVL=30)
    ablym = np.zeros(MDEPTH + 1)
    emlym = np.zeros(MDEPTH + 1)

    if C.IELH == 0:
        return

    fr = C.FREQ[ij]
    if fr > 3.28805e15 or fr < 1.5e15:
        return

    if _save_lymlin_inip == 1:
        n0h = C.NFIRST[C.IELH]
        n1h = C.NLAST[C.IELH]
        nkh = C.NNEXT[C.IELH]
        nlh = n1h - n0h
        xii = 1.0
        for j in range(2, 31):
            # STARK0 修改标量哑元 XKIJ,WL0,FIJ → 返回全部标量哑元；
            # 字面量实参 1 用弃元接收；XKIJ0/WL00/FIJ0 为纯输出，传入 0.0
            _i, _j, _izz, xkij0, wl00, fij0 = stark0(1, j, 1, 0.0, 0.0, 0.0)
            _save_lymlin_xkijl[j] = xkij0
            _save_lymlin_fijl[j] = fij0
            _save_lymlin_wl0l[j] = wl00
            _save_lymlin_fr0l[j] = c18 / _save_lymlin_wl0l[j]
        for id in range(1, C.ND + 1):
            t = C.TEMP[id]
            t1 = 1.0 / t
            sqt = math.sqrt(t)
            ane = C.ELEC[id]
            anp = C.POPUL[nkh, id]
            _save_lymlin_f00[id] = c00 * ane ** ttw
            _save_lymlin_dop0[id] = (1.0e8
                                     * math.sqrt(1.65e8 * t + C.VTURB[id]))

            p0 = cpp * ane * anp * t1 / sqt
            p1 = C.POPUL[n0h, id]
            for j in range(2, 31):
                x = j * j
                jj = n0h + j - 1
                xjj = 1.0 / jj
                if j <= nlh:
                    _save_lymlin_pj[j, id] = C.POPUL[jj, id]
                else:
                    _save_lymlin_pj[j, id] = (p0 * math.exp(cpj / (x * t))
                                              * x * C.WNHINT[j, id])
                _save_lymlin_abtr[j, id] = p1 * C.WNHINT[j, id]
                _save_lymlin_emtr[j, id] = (
                    _save_lymlin_pj[j, id] * xjj
                    * math.exp(cpj * (xii - xjj) * t1))

                fxk = _save_lymlin_f00[id] * _save_lymlin_xkijl[j]
                # DBETA/BETAD/ADH/DIVH 是 MODELQ.FOR /STRAUX/ 的 COMMON 量
                C.DBETA = (_save_lymlin_wl0l[j] * _save_lymlin_wl0l[j]
                           / (c18 * fxk))
                _save_lymlin_fid[j, id] = (os0 * _save_lymlin_fijl[j]
                                           * C.DBETA)
                dop = _save_lymlin_dop0[id] / _save_lymlin_wl0l[j]
                C.BETAD = dop * C.DBETA
                divstr(1)                           # 输出 COMMON 量 ADH,DIVH
                _save_lymlin_ad0[j, id] = C.ADH
                _save_lymlin_div0[j, id] = C.DIVH
                _save_lymlin_dbet0[j, id] = C.DBETA
                _save_lymlin_betad0[j, id] = C.BETAD
        _save_lymlin_inip = 0

    fr = C.FREQ[ij]
    wl = c18 / fr
    f15 = fr * 1.0e-15
    for id in range(1, C.ND + 1):
        ablym[id] = 0.0
        emlym[id] = 0.0
        for j in range(2, 31):
            beta = _save_lymlin_dbet0[j, id] * abs(fr - _save_lymlin_fr0l[j])
            C.BETAD = _save_lymlin_betad0[j, id]
            C.ADH = _save_lymlin_ad0[j, id]
            C.DIVH = _save_lymlin_div0[j, id]
            sg = starka(beta, TWO) * _save_lymlin_fid[j, id]
            ablym[id] = ablym[id] + sg * _save_lymlin_abtr[j, id]
            emlym[id] = emlym[id] + sg * _save_lymlin_emtr[j, id]
            # if(wl.gt.1120.0.and.wl.lt.1120.3.and.id.eq.50)  （原代码注释掉）
            #   write(6,600) j,fr,fr0l(j),abs(fr-fr0l(j)),
            #   dbet0(j,id),beta,fid(j,id),sg,abtr(j,id),
            #   emtr(j,id),sg*abtr(j,id),ablym(id)
            # if(wl.gt.1120.0.and.wl.lt.1120.3.and.id.eq.50)
            #   write(6,600) j,fid(j,id),dbet0(j,id),wl0l(j),xkijl(j),
            #   dop0(id),fijl(j)
            # 600 format('lymsig',i4,1p11e11.3)
        xkt = math.exp(-4.79928e-11 * fr / C.TEMP[id])
        xkb = xkt * 1.4743e-2 * f15 * f15 * f15
        ablym[id] = ablym[id] - xkt * emlym[id]
        emlym[id] = xkb * emlym[id]
        C.ABSO1[id] = C.ABSO1[id] + ablym[id]
        C.EMIS1[id] = C.EMIS1[id] + emlym[id]
        # if(wl.gt.1120.0.and.wl.lt.1120.3)  （原代码注释掉）
        #   write(6,601) ij,wl,ablym(50),emlym(50),xkt,xkb
        # 601 format('lymlin',i6,f10.3,1p4e11.3)
    return


